          dum2(i,j,k) = q3d(i,j,k,nqv)/rslf(prs(i,j,k),dum1(i,j,k))
        enddo
        enddo
        enddo

        call getavg3d(dum2,icrs,savg,ir,rr,navg,area,ruh,rvh)
