        call write3d(icrs,savg,arecs,arecw,nvar,varname,vardesc,varunit,vargrid)

      ENDIF

  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      doit = .true.

      dorturb:  &
      if( doit )then
        IF( cm1setup.eq.4 )THEN

      !c-c-c-c-c-c-c-c-c-c

          nvar = nvar+1
