        call getavg3d(qdiag(ibdq,jbdq,kbdq,qd_vti),icrs,savg,ir,rr,navg,area,ruh,rvh)
        call write3d(icrs,savg,arecs,arecw,nvar,varname,vardesc,varunit,vargrid)

      ENDIF

