        nvar = nvar+1
        varname(nvar) = 'effs'
        vardesc(nvar) = 'effs'
        varunit(nvar) = 'm'

        call getavg3d(effs(ibr,jbr,kbr),icrs,savg,ir,rr,navg,area,ruh,rvh)
        call write3d(icrs,savg,arecs,arecw,nvar,varname,vardesc,varunit,vargrid)

      ENDIF

