    subroutine getmin3d(s,icrs,savg,ir,rr,navg,area,ruh,rvh)
    use input
    use constants , only : grads_undef
#ifdef MPI
    use mpi
#endif
    implicit none

    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: s
    integer, intent(in) :: icrs
    double precision, dimension(icrs,nk+1) :: savg
    integer, intent(in), dimension(ib:ie,jb:je) :: ir
    real, intent(in), dimension(ib:ie,jb:je) :: rr
    integer, intent(in), dimension(icrs) :: navg
    double precision, intent(in), dimension(icrs) :: area
    real, intent(in), dimension(ib:ie) :: ruh
    real, intent(in), dimension(jb:je) :: rvh

    integer :: i,j,k

    savg = 1.0e30

    do k=1,nk+1
    do j=1,nj
    do i=1,ni
      if( ir(i,j).ge.1 .and. ir(i,j).le.icrs )then
        savg(ir(i,j),k) = min( savg(ir(i,j),k) , s(i,j,k) )
      endif
    enddo
    enddo
    enddo

#ifdef MPI
    call MPI_ALLREDUCE(MPI_IN_PLACE,savg,icrs*(nk+1),MPI_DOUBLE_PRECISION,MPI_MIN,MPI_COMM_WORLD,ierr)
#endif

    do k=1,nk+1
    do i=1,icrs
      if( navg(i).eq.0 )then
        savg(i,k) = grads_undef
      endif
    enddo
    enddo

    end subroutine getmin3d


    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


    subroutine getfrac3d(s,icrs,savg2d,savg,ir,rr,navg,area,ruh,rvh,op)
    use input
    use constants , only : grads_undef
#ifdef MPI
    use mpi
#endif
    implicit none

    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: s
    integer, intent(in) :: icrs
    double precision, dimension(icrs) :: savg2d
    double precision, dimension(icrs,nk+1) :: savg
    integer, intent(in), dimension(ib:ie,jb:je) :: ir
    real, intent(in), dimension(ib:ie,jb:je) :: rr
    integer, intent(in), dimension(icrs) :: navg
    double precision, intent(in), dimension(icrs) :: area
    real, intent(in), dimension(ib:ie) :: ruh
    real, intent(in), dimension(jb:je) :: rvh
    integer, intent(in) :: op     !  1 = use values >= 0
                                  !  2 = use values < 0

    integer :: i,j,k

    savg2d = 0.0
    savg = 0.0

    do j=1,nj
    do i=1,ni
      if( ir(i,j).ge.1 .and. ir(i,j).le.icrs )then
        savg2d(ir(i,j)) = savg2d(ir(i,j)) + dx*dy*ruh(i)*rvh(j)
      endif
    enddo
    enddo

    do k=1,nk+1
    do j=1,nj
    do i=1,ni
      if( ir(i,j).ge.1 .and. ir(i,j).le.icrs )then
      if( op.eq.1 .and. s(i,j,k).ge.0.0 )then
        savg(ir(i,j),k) = savg(ir(i,j),k) + dx*dy*ruh(i)*rvh(j)
      endif
      if( op.eq.2 .and. s(i,j,k).lt.0.0 )then
        savg(ir(i,j),k) = savg(ir(i,j),k) + dx*dy*ruh(i)*rvh(j)
      endif
      endif
    enddo
    enddo
    enddo

#ifdef MPI
    call MPI_ALLREDUCE(MPI_IN_PLACE,savg2d,icrs     ,MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,ierr)
    call MPI_ALLREDUCE(MPI_IN_PLACE,savg,icrs*(nk+1),MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,ierr)
#endif

    do k=1,nk+1
    do i=1,icrs
      if( navg(i).eq.0 )then
        savg(i,k) = grads_undef
      else
        savg(i,k) = savg(i,k)/max(1.0e-20,savg2d(i))
      endif
    enddo
    enddo

    end subroutine getfrac3d


    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


    subroutine write2d(icrs,savg2d,arecs,arecw,nvar,varname,vardesc,varunit,vargrid)
    use input
#ifdef NETCDF
    use writeout_nc_module, only : disp_err
    use netcdf
#endif
    implicit none

    integer, intent(in) :: icrs
    double precision, intent(in), dimension(icrs) :: savg2d
    integer, intent(inout) :: arecs,arecw,nvar
    character(len=80), intent(in), dimension(varmax) :: varname,vardesc,varunit
    character(len=1), intent(in), dimension(varmax) :: vargrid

    integer :: i,varid,status
    real, dimension(1,1,1,1) :: var
      
  if( output_format.eq.1 .or. ( output_format.eq.2 .and. wloop.eq.2 ) )then

    if( myid.eq.0 )then

      print *,nvar,trim(varname(nvar))

      if( output_format.eq.1 )then

        ! grads-format file:

        ! note:  all 2d vars go into scalar output file
        write(fnums,rec=arecs) (sngl(savg2d(i)),i=1,icrs)
        arecs = arecs+1

#ifdef NETCDF
      elseif( output_format.eq.2 )then

        status = nf90_inq_varid(ncid,trim(varname(nvar)),varid)
        if(status.ne.nf90_noerr)then
          print *,'  Error in write3d, varname = ',varname(nvar)
          print *,nf90_strerror(status)
          call stopcm1
        endif

        do i=1,icrs
          var = savg2d(i)
          call disp_err( nf90_put_var(ncid,varid,var,(/i,1,1/),(/1,1,1/)) , .true. )
        enddo
#endif

      endif

    endif

  endif

    end subroutine write2d


    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


    subroutine write3d(icrs,savg,arecs,arecw,nvar,varname,vardesc,varunit,vargrid)
    use input
#ifdef NETCDF
    use writeout_nc_module, only : disp_err
    use netcdf
#endif
    implicit none

    integer, intent(in) :: icrs
    double precision, intent(in), dimension(icrs,nk+1) :: savg
    integer, intent(inout) :: arecs,arecw,nvar
    character(len=80), intent(in), dimension(varmax) :: varname,vardesc,varunit
    character(len=1), intent(in), dimension(varmax) :: vargrid

    integer :: i,k,kmax,varid,status
    real, dimension(1,1,1,1) :: var
      
  if( output_format.eq.1 .or. ( output_format.eq.2 .and. wloop.eq.2 ) )then

    if( myid.eq.0 )then

      print *,nvar,vargrid(nvar),' ',trim(varname(nvar))

      if( output_format.eq.1 )then
        ! grads-format file:

      if( vargrid(nvar).eq.'s' )then
        do k=1,nk
          write(fnums,rec=arecs) (sngl(savg(i,k)),i=1,icrs)
          arecs = arecs+1
        enddo
      elseif( vargrid(nvar).eq.'w' )then
        do k=1,nk+1
          write(fnumw,rec=arecw) (sngl(savg(i,k)),i=1,icrs)
          arecw = arecw+1
        enddo
      else
        print *,' 67833 '
        call stopcm1
      endif

#ifdef NETCDF
      elseif( output_format.eq.2 )then

        status = nf90_inq_varid(ncid,trim(varname(nvar)),varid)
        if(status.ne.nf90_noerr)then
          print *,'  Error in write3d, varname = ',varname(nvar)
          print *,nf90_strerror(status)
          call stopcm1
        endif

        if( vargrid(nvar).eq.'s' )then
          kmax = nk
        elseif( vargrid(nvar).eq.'w' )then
          kmax = nk+1
        else
          print *,'  67844 '
        endif

        do k=1,kmax
        do i=1,icrs
          var = savg(i,k)
          call disp_err( nf90_put_var(ncid,varid,var,(/i,1,k,1/),(/1,1,1,1/)) , .true. )
        enddo
        enddo
#endif
      endif

    endif

  endif


    end subroutine write3d


    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


    subroutine getcenter(nstep,mtime,rddr,xh,yh,zh,xfref,yfref,ugr,utmp,vgr,vtmp,pp3d,  &
                         nwritea,icenter,jcenter,xcenter,ycenter,domainlocx,domainlocy)
    use input
    use constants
#ifdef NETCDF
      use writeout_nc_module, only : writecenter_nc
#endif
#ifdef MPI
      use comm_module
      use mpi
#endif
    implicit none

      !----------------------------------------------------------------
      !     center-finding code:
      ! (note: for axisymmetric simulations, this code isn't used)
      !----------------------------------------------------------------

      integer, intent(in) :: nstep
      double precision, intent(in) :: mtime
      real, intent(in) :: rddr
      real, intent(in), dimension(ib:ie) :: xh
      real, intent(in), dimension(jb:je) :: yh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: zh
      real, intent(in), dimension(1-ngxy:nx+ngxy+1) :: xfref
      real, intent(in), dimension(1-ngxy:ny+ngxy+1) :: yfref
      real, intent(in   ), dimension(ib:ie+1,jb:je,kb:ke) :: ugr
      real, intent(inout), dimension(ib:ie+1,jb:je,kb:ke) :: utmp
      real, intent(in   ), dimension(ib:ie,jb:je+1,kb:ke) :: vgr
      real, intent(inout), dimension(ib:ie,jb:je+1,kb:ke) :: vtmp
      real, intent(in),    dimension(ib:ie,jb:je,kb:ke) :: pp3d
      integer, intent(inout) :: nwritea,icenter,jcenter
      real, intent(inout) :: xcenter,ycenter
      double precision, intent(in) :: domainlocx,domainlocy

    integer :: i,j,k,ii,jj,ir,proc,jfoo,arecs,arecw,irec1,nr,kmax,nloop
    integer :: ictest,jctest,imin,imax,jmin,jmax,ninc
    real :: rr,vmax,mostmax,mostx,mosty,mostr,mostz,rmax,zmax,u,v,angle
    real :: xctest,yctest

    integer :: ipmin,jpmin
    real :: ppmin

    logical, parameter :: doit = .true.

#ifdef MPI
    integer status(MPI_STATUS_SIZE)
#endif

      integer, parameter :: centertype  =  1    ! 1 = gridpoint that produces the 
                                                !     maximum azimuthally averaged 
                                                !     tangential velocity
                                                ! 
                                                ! 2 = minimum perturbation pressure
                                                !     at lowest model level
                                                ! 

             ! assume rmw <= rcrit
             ! assume zmw <= zcrit
      real, parameter :: rcrit = 150000.0       ! max possible rmw (m)
      real, parameter :: zcrit =   4000.0       ! max possible zmw (m)
                                                ! (Note:  code uses last known location 
                                                !  of storm center as a starting point)

      real, parameter :: search_radius  =  30000.0   ! to reduce cost, search only within 
                                                     ! this radius (m) from previous known 
                                                     ! position

      integer, dimension(:), allocatable :: navg
      double precision, dimension(:), allocatable :: ravg
      double precision, dimension(:,:), allocatable :: davg
#ifdef MPI
      integer :: loc
      real, dimension(2) :: valmin
#endif

      integer, parameter :: nvars = 10

!-----------------------------------------------------------------------

  docenter:  IF(doit)THEN

    if(myid.eq.0) print *,'  Entering getcenter .... '


  centype:  &
  IF( centertype.eq.1 .or. centertype.eq.2 )THEN


    !
    ! 180620: For centype = 1 (max azim-avg tang. vel.):
    !          two-pass approach.  1st pass finds min surface pressure
    !                              2nd pass finds point with maximum azimth. avg. V
    !  (added to account for fast moving storms)
    !

    !c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c
    ! Pass 1:  find min surface pressure

#ifdef MPI
      call comm_2d_corner(pp3d(ib,jb,1))
#endif

      ppmin = 1.0e30

      do j=1,nj+1
      do i=1,ni+1
        if( pp3d(i,j,1).lt.ppmin )then
          ! nondim. pressure, lowest model level, vorticity points:
          ppmin = 0.25*( (pp3d(i-1,j-1,1)+pp3d(i  ,j  ,1)) &
                        +(pp3d(i-1,j  ,1)+pp3d(i  ,j-1,1)) )
          ipmin = i
          jpmin = j
        endif
      enddo
      enddo

#ifdef MPI
      valmin(1) = ppmin
      valmin(2) = myid
      call mpi_allreduce(mpi_in_place,valmin,1,MPI_2REAL,MPI_MINLOC,MPI_COMM_WORLD,ierr)

      ppmin = valmin(1)
      loc = nint(valmin(2))
      ipmin = ipmin + (myi1-1)
      jpmin = jpmin + (myj1-1)
      call MPI_BCAST(ipmin,1,MPI_INTEGER,loc,MPI_COMM_WORLD,ierr)
      call MPI_BCAST(jpmin,1,MPI_INTEGER,loc,MPI_COMM_WORLD,ierr)
#endif

      if( myid.eq.0 )then
      print *,'  myid,ppmin,ipmin,jpmin = ',myid,ppmin,ipmin,jpmin
      print *,'    xfref,yfref = ',xfref(ipmin),yfref(jpmin)
      endif

      xcenter = xfref(ipmin)
      ycenter = yfref(jpmin)

      icenter = ipmin
      jcenter = jpmin

    !c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c
    ! Pass 2:  find point with max azimuthally averaged tangential velocity


      nr = int( rcrit*rddr + 1 )

      kmax = 0
      do while( zh(1,1,kmax).le.zcrit .and. kmax.lt.nk )
        kmax = kmax+1
      enddo

    ! print xc,yc from last time:
    if(myid.eq.0) print *,'  Previous values: '
    if(myid.eq.0) print *,'    xcenter,ycenter = ',xcenter,ycenter
    if(myid.eq.0) print *,'    icenter,jcenter = ',icenter,jcenter
    if(myid.eq.0) print *,'  nr,kmax           = ',nr,kmax

    allocate( navg(nr) )
    navg = 0
    allocate( ravg(nr) )
    ravg = 0
    allocate( davg(nr,kmax) )
    davg = 0.0

!$omp parallel do default(shared)  &
!$omp private(i,j,k)
    do k=1,kmax
    do j=1,nj
    do i=1,ni
      utmp(i,j,k) = 0.5*( ugr(i,j,k) + ugr(i+1,j,k) )
      vtmp(i,j,k) = 0.5*( vgr(i,j,k) + vgr(i,j+1,k) )
    enddo
    enddo
    enddo

      mostmax = 0.0
      mostx = 0.0
      mosty = 0.0
      mostr = 0.0
      mostz = 0.0
      ictest = nx/2 + 1
      jctest = ny/2 + 1

    ct2:  &
    IF( centertype.eq.2 )THEN

      imin = icenter
      imax = icenter

      jmin = jcenter
      jmax = jcenter

      ninc  =  1

    ELSE  ct2


      imin = 1
      imax = nx

      do i=(nx+1),1,-1
        if( -(xfref(i)-xcenter).le.search_radius ) imin = i
      enddo

      do i=1,nx+1
        if(  (xfref(i)-xcenter).le.search_radius ) imax = i
      enddo

      jmin = 1
      jmax = ny

      do j=(ny+1),1,-1
        if( -(yfref(j)-ycenter).le.search_radius ) jmin = j
      enddo

      do j=1,ny+1
        if(  (yfref(j)-ycenter).le.search_radius ) jmax = j
      enddo

      ! to reduce cost, skip some grid points:
      !   (set ninc=1 to search every gridpoint)
      !   (set ninc=2 to search every other gridpoint)
      !   (set ninc=3 to search every third gridpoint)
      ninc  =  2
!!!      ninc  =  4

!    if( nstep.eq.0 )then
!      ! search entire domain:
!      imin = 1
!      imax = nx
!      jmin = 1
!      jmax = ny
!      ! use double the increment, to reduce cost
!      ninc = ninc*2
!    endif

    ENDIF  ct2

    if(myid.eq.0)then
      print *,'    search box: '
      print *,'      imin,imax,ninc = ',imin,imax,ninc
      print *,'      jmin,jmax,ninc = ',jmin,jmax,ninc
      print *,'      xmin,xmax,diff = ',xfref(imin),xfref(imax),xfref(imax)-xfref(imin)
      print *,'      ymin,ymax,diff = ',yfref(jmin),yfref(jmax),yfref(jmax)-yfref(jmin)
    endif

!    if( imin.lt.1 .or. imax.gt.nx .or.  &
!        jmin.lt.1 .or. jmax.gt.ny )then
!      print *
!      print *,'  too close to lateral boundary in subroutine getcenter '
!      print *
!      print *,'  56091 '
!      call stopcm1
!    endif

      jloop:  do jj=jmin,jmax,ninc
      iloop:  do ii=imin,imax,ninc
        navg = 0
        ravg = 0
        davg = 0.0
        xctest = xfref(ii)
        yctest = yfref(jj)
        if( nstep.eq.0 )then
          ! search entire domain:
          xcenter = xfref(ii)
          ycenter = yfref(jj)
        endif
        checkit: IF( sqrt( (xfref(ii)-xcenter)**2 + (yfref(jj)-ycenter)**2 ) .le. search_radius )THEN
          ! Calculate azim-avg vt:
          do j=1,nj
          do i=1,ni
            rr = sqrt( (xh(i)-xctest)**2 + (yh(j)-yctest)**2 )
            if( rr.lt.rcrit )then
              ir = 1 + int( rr*rddr )
              navg(ir)=navg(ir)+1
              if( abs(rr).lt.1.0e-4 )then
                u=0.0
                v=0.0
              else
                if( (xh(i)-xctest).ge.0.0 )then
                  angle =      asin( (yh(j)-yctest)/rr )
                else
                  angle = pi - asin( (yh(j)-yctest)/rr )
                endif
                do k=1,kmax
                  v=vtmp(i,j,k)*cos(angle)-utmp(i,j,k)*sin(angle)
                  davg(ir,k)=davg(ir,k)+v
                enddo
              endif
            endif
          enddo
          enddo
!-----------------------------------------------------------------------
!  communicate:
#ifdef MPI
        if( myid.eq.0 )then
          call MPI_REDUCE(mpi_in_place,davg,nr*kmax,mpi_double_precision,mpi_sum,0,mpi_comm_world,ierr)
          call MPI_REDUCE(mpi_in_place,navg,nr     ,mpi_integer         ,mpi_sum,0,mpi_comm_world,ierr)
        else
          call MPI_REDUCE(  davg      ,davg,nr*kmax,mpi_double_precision,mpi_sum,0,mpi_comm_world,ierr)
          call MPI_REDUCE(  navg      ,navg,nr     ,mpi_integer         ,mpi_sum,0,mpi_comm_world,ierr)
        endif
#endif
!-----------------------------------------------------------------------
        IF(myid.eq.0)THEN
          ! Search for maximum value for this center point:
          vmax = 0.0
          do i=1,nr
            ravg(i) = 1.0/dble(max(1,navg(i)))
          enddo
          do k=1,kmax
          do i=1,nr
            davg(i,k) = davg(i,k)*ravg(i)
            if( davg(i,k).gt.vmax )then
              vmax = davg(i,k)
              rmax = (i-1)*ddr + 0.5*ddr
              zmax = zh(1,1,k)
            endif
          enddo
          enddo
          if( vmax.gt.mostmax )then
            mostmax = vmax
            mostx = xctest
            mosty = yctest
            mostr = rmax
            mostz = zmax
            ictest = ii
            jctest = jj
          endif
        ENDIF
        ENDIF  checkit
      enddo  iloop
      enddo  jloop

      IF(myid.eq.0)THEN
        xcenter = mostx
        ycenter = mosty
        icenter = ictest
        jcenter = jctest
      ENDIF

  ELSE

    print *,'  87235:  unknown valye of centertype '
    call stopcm1

  ENDIF  centype

    if(myid.eq.0) print *,'  New values: '
    if(myid.eq.0) print *,'    xcenter,ycenter = ',xcenter,ycenter
    if(myid.eq.0) print *,'    icenter,jcenter = ',icenter,jcenter
    if(myid.eq.0) print *,'    vmax,rmax,zmax  = ',mostmax,mostr,mostz


  ELSE  docenter

    ! just use center of domain:
    icenter = nx/2 + 1
    jcenter = ny/2 + 1
    xcenter = minx + 0.5*(maxx-minx)
    ycenter = miny + 0.5*(maxy-miny)

  ENDIF  docenter


!-----------------------------------------------------------------------
!  more comms:

#ifdef MPI
    call MPI_BCAST(icenter,1,MPI_INTEGER,0,MPI_COMM_WORLD,ierr)
    call MPI_BCAST(jcenter,1,MPI_INTEGER,0,MPI_COMM_WORLD,ierr)
    call MPI_BCAST(xcenter,1,MPI_REAL,0,MPI_COMM_WORLD,ierr)
    call MPI_BCAST(ycenter,1,MPI_REAL,0,MPI_COMM_WORLD,ierr)
#endif

!-----------------------------------------------------------------------

  myid0:  &
  IF(myid.eq.0)THEN

    of1:  &
    IF( output_format.eq.1 )THEN
      ! grads format:

      print *,'  writing azimavg stats file'

        irec1 = 1 + nvars*(nwritea-1)

        do i=1,maxstring
          string(i:i) = ' '
        enddo

        string = 'cm1out_azimavg_stats.dat'
        print *,string
        open(unit=67,file=string,form='unformatted',access='direct',recl=4,status='unknown')

        write(67,rec=irec1) sngl(mtime)
        irec1=irec1+1
        write(67,rec=irec1) float(icenter)
        irec1=irec1+1
        write(67,rec=irec1) float(jcenter)
        irec1=irec1+1
        write(67,rec=irec1) xcenter
        irec1=irec1+1
        write(67,rec=irec1) ycenter
        irec1=irec1+1
        write(67,rec=irec1) mostmax
        irec1=irec1+1
        write(67,rec=irec1) mostr
        irec1=irec1+1
        write(67,rec=irec1) mostz
        irec1=irec1+1
        write(67,rec=irec1) sngl(domainlocx)
        irec1=irec1+1
        write(67,rec=irec1) sngl(domainlocy)
        irec1=irec1+1

        close(unit=67)


    !------------------------
    !  GrADS descriptor file:

      do i=1,maxstring
        string(i:i) = ' '
      enddo
      string = 'cm1out_azimavg_stats.ctl'
      open(unit=50,file=string,status='unknown')
      string = 'cm1out_azimavg_stats.dat'
      write(50,231) string
231   format('dset ^',a)
      write(50,202) trim(cm1version)
      write(50,203) grads_undef
      write(50,204)
      write(50,205)
      write(50,206)
      write(50,207) nwritea
      write(50,208) nvars
      write(50,209) 'mtime       ','model time (seconds since beginning of simulation)'
      write(50,209) 'icenter     ','i value of center point                           '
      write(50,209) 'jcenter     ','j value of center point                           '
      write(50,209) 'xcenter     ','x (m) value of center point                       '
      write(50,209) 'ycenter     ','y (m) value of center point                       '
      write(50,209) 'vmax        ','max azimuthally averaged tangential velocity (m/s)'
      write(50,209) 'rmax        ','radius of Vmax (m)                                '
      write(50,209) 'zmax        ','height (m ASL) of Vmax                            '
      write(50,209) 'domainlocx  ','x location of (center of) domain (m)              '
      write(50,209) 'domainlocy  ','y location of (center of) domain (m)              '
      write(50,210)
      close(unit=50)
202   format('title stats and info for CM1 azimuthally averaged output; using version ',a,'; time is generic, see variable mtime for actual times')
203   format('undef ',f10.1)
204   format('xdef 1 linear 0.0 1.0')
205   format('ydef 1 linear 0.0 1.0')
206   format('zdef 1 linear 0.0 1.0')
207   format('tdef ',i10,' linear 00:00Z01JAN0001 1YR')
208   format('vars ',i4)
209   format(a12,' 0 99 ',a50)
210   format('endvars')

!-----------------------------------------------------------------------

#ifdef NETCDF
    ELSEIF( output_format.eq.2 )THEN  of1
      ! netcdf format:

    ! 210203: bug fix
      call       writecenter_nc(nwritea,ncid,mtime,icenter,jcenter,xcenter,ycenter,mostmax,mostr,mostz)

!-----------------------------------------------------------------------
#endif

    ENDIF  of1

  ENDIF  myid0

!-----------------------------------------------------------------------

    deallocate( navg )
    deallocate( ravg )
    deallocate( davg )

    if(myid.eq.0) print *,'  .... leaving getcenter '

    return
    end subroutine getcenter


    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine getpsmth(xh,yh,sigma,pp3d,dum1,xfref,yfref,icenter,jcenter,xcenter,ycenter,psmth)

      use input
      use constants
      use bc_module
#ifdef MPI
      use comm_module
      use mpi
#endif
      implicit none

      real, intent(in), dimension(ib:ie) :: xh
      real, intent(in), dimension(jb:je) :: yh
      real, intent(in), dimension(kb:ke) :: sigma
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: pp3d
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum1
      real, intent(in), dimension(1-ngxy:nx+ngxy+1) :: xfref
      real, intent(in), dimension(1-ngxy:ny+ngxy+1) :: yfref
      integer, intent(inout) :: icenter,jcenter
      real, intent(inout) :: xcenter,ycenter
      real, intent(inout), dimension(ib:ie,jb:je) :: psmth

      integer :: i,j,k,n,ipmin,jpmin,kval
      real :: rmin,minval,zref
      real, dimension(cmp,jmp) :: west,newwest,east,neweast
      real, dimension(imp,cmp) :: south,newsouth,north,newnorth
      integer, dimension(8) :: reqs

#ifdef MPI
      integer :: loc
      real, dimension(2) :: valmin
#endif

    !---------------------------------------

    ! 210228: specify level to use
    ! (default is surface)

      zref = 0.0    ! level (ASL) to use

      minval = 1.0e30

      if( zref.gt.smeps )then
        do k=1,nk
          if( abs(sigma(k)-zref).lt.minval )then
            minval = abs(sigma(k)-zref)
            kval = k
          endif
        enddo
      else
        kval = 1
      endif

!!!      kval = nint(var2)

      if(myid.eq.0) print *,'  kval,zval = ',kval,sigma(kval)

    !---------------------------------------

      do j=1,nj
      do i=1,ni
        dum1(i,j,1) = pp3d(i,j,kval)
      enddo
      enddo

      ! by default, run del^2 diffusion 100 times:
      do n=1,100

        call bc2d(dum1(ib,jb,1))
#ifdef MPI
        call comm_2d_start(dum1(ib,jb,1),west,newwest,east,neweast,   &
                                         south,newsouth,north,newnorth,reqs)
        call comm_2dew_end(dum1(ib,jb,1),west,newwest,east,neweast,reqs)
        call comm_2dns_end(dum1(ib,jb,1),south,newsouth,north,newnorth,reqs)
        call bcs2_2d(dum1(ib,jb,1))
        call comm_2d_corner(dum1(ib,jb,1))
#endif

        do j=1,nj
        do i=1,ni
          dum1(i,j,2) = 0.11111111*( dum1(i,j,1) + (                 &
                              ( (dum1(i+1,j  ,1)+dum1(i-1,j  ,1))    &
                               +(dum1(i  ,j+1,1)+dum1(i  ,j-1,1)) )  &
                             +( (dum1(i+1,j+1,1)+dum1(i-1,j+1,1))    &
                               +(dum1(i+1,j-1,1)+dum1(i-1,j-1,1)) ) ) )
        enddo
        enddo

        do j=1,nj
        do i=1,ni
          dum1(i,j,1) = dum1(i,j,2)
          psmth(i,j) = dum1(i,j,2)
        enddo
        enddo

      enddo

        call bc2d(dum1(ib,jb,1))
#ifdef MPI
        call comm_2d_start(dum1(ib,jb,1),west,newwest,east,neweast,   &
                                         south,newsouth,north,newnorth,reqs)
        call comm_2dew_end(dum1(ib,jb,1),west,newwest,east,neweast,reqs)
        call comm_2dns_end(dum1(ib,jb,1),south,newsouth,north,newnorth,reqs)
        call bcs2_2d(dum1(ib,jb,1))
        call comm_2d_corner(dum1(ib,jb,1))
#endif

    !---------------------------------------
    !  interpolate to zeta points, and find min value:

      do j=1,nj+1
      do i=1,ni+1
        dum1(i,j,2) = 0.25*( (dum1(i,j,1)+dum1(i-1,j-1,1)) &
                            +(dum1(i-1,j,1)+dum1(i,j-1,1)) )
      enddo
      enddo

      rmin = 1.0e30

      do j=1,nj
      do i=1,ni
        if( dum1(i,j,2).lt.rmin )then
          rmin = dum1(i,j,2)
          ipmin = i
          jpmin = j
        endif
      enddo
      enddo

#ifdef MPI
      valmin(1) = rmin
      valmin(2) = myid
      call mpi_allreduce(mpi_in_place,valmin,1,MPI_2REAL,MPI_MINLOC,MPI_COMM_WORLD,ierr)

      rmin = valmin(1)
      loc = nint(valmin(2))
      ipmin = ipmin + (myi-1)*ni
      jpmin = jpmin + (myj-1)*nj
      call MPI_BCAST(ipmin,1,MPI_INTEGER,loc,MPI_COMM_WORLD,ierr)
      call MPI_BCAST(jpmin,1,MPI_INTEGER,loc,MPI_COMM_WORLD,ierr)
#endif

      if( myid.eq.0 )then
      print *,'  myid,rmin,ipmin,jpmin = ',myid,rmin,ipmin,jpmin
      print *,'    xf,yf = ',xfref(ipmin),yfref(jpmin)
      endif

      xcenter = xfref(ipmin)
      ycenter = yfref(jpmin)

      icenter = ipmin
      jcenter = jpmin

      end subroutine getpsmth


    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine getpcent(xh,yh,xfref,yfref,pp3d,icenter,jcenter,xcenter,ycenter,psmth)

      use input
      use constants
      use bc_module
#ifdef MPI
      use comm_module
      use mpi
#endif
      implicit none

      real, intent(in), dimension(ib:ie) :: xh
      real, intent(in), dimension(jb:je) :: yh
      real, intent(in), dimension(1-ngxy:nx+ngxy+1) :: xfref
      real, intent(in), dimension(1-ngxy:ny+ngxy+1) :: yfref
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: pp3d
      integer, intent(inout) :: icenter,jcenter
      real, intent(inout) :: xcenter,ycenter
      real, intent(in), dimension(ib:ie,jb:je) :: psmth

      integer :: i,j
      real :: ppmin,ppmax,pcent,pminx,pmaxx,pminy,pmaxy
      real :: aa,minval
      double precision :: cx,cy,ca

      integer, parameter :: type = 2    ! 1 = center of pcent
                                        ! 2 = centroid of pcent

      real, parameter :: radmax = 300000.0   ! max radius (m) over which pcent is calculated
                                             ! (for type=2 only)

  !---------------------------------------------------------------------

      ppmin =  1.0e30
      ppmax = -1.0e30

      do j=1,nj
      do i=1,ni
        ppmin = min(ppmin,pp3d(i,j,1))
        ppmax = max(ppmax,pp3d(i,j,1))
      enddo
      enddo

#ifdef MPI
      call MPI_ALLREDUCE(mpi_in_place,ppmin,1,MPI_REAL,MPI_MIN,MPI_COMM_WORLD,ierr)
      call MPI_ALLREDUCE(mpi_in_place,ppmax,1,MPI_REAL,MPI_MAX,MPI_COMM_WORLD,ierr)
#endif

      pcent = 0.5*(ppmin+ppmax)

  !---------------------------------------------------------------------

    IF( type.eq.1 )THEN

      pminx =  1.0e30
      pmaxx = -1.0e30

      pminy =  1.0e30
      pmaxy = -1.0e30

      do j=1,nj
      do i=1,ni
        if( pp3d(i,j,1).lt.pcent )then
          pminx = min(pminx,xh(i))
          pmaxx = max(pmaxx,xh(i))
          pminy = min(pminy,yh(j))
          pmaxy = max(pmaxy,yh(j))
        endif
      enddo
      enddo

#ifdef MPI
      call MPI_ALLREDUCE(mpi_in_place,pminx,1,MPI_REAL,MPI_MIN,MPI_COMM_WORLD,ierr)
      call MPI_ALLREDUCE(mpi_in_place,pmaxx,1,MPI_REAL,MPI_MAX,MPI_COMM_WORLD,ierr)
      call MPI_ALLREDUCE(mpi_in_place,pminy,1,MPI_REAL,MPI_MIN,MPI_COMM_WORLD,ierr)
      call MPI_ALLREDUCE(mpi_in_place,pmaxy,1,MPI_REAL,MPI_MAX,MPI_COMM_WORLD,ierr)
#endif

      xcenter = 0.5*(pminx+pmaxx)
      ycenter = 0.5*(pminy+pmaxy)

    ENDIF

  !---------------------------------------------------------------------

    IF( type.eq.2 )THEN

      if(myid.eq.0) print *,'  ... centroid ... '

!!!      do j=1,nj
!!!      do i=1,ni
!!!        out2d(i,j,1) = 0.0
!!!      enddo
!!!      enddo

      ca = 0.0
      cx = 0.0
      cy = 0.0

      do j=1,nj
      do i=1,ni
!!!        if( pp3d(i,j,1).lt.pcent )then
        if( sqrt( (xh(i)-centerx)**2 + (yh(j)-centery)**2 ) .lt. radmax )then
!!!          aa = (dx*ruh(i))*(dy*rvh(j))
          aa = psmth(i,j)
          ca = ca + aa
          cx = cx + aa*xh(i)
          cy = cy + aa*yh(j)
!!!          out2d(i,j,1) = 1.0
        endif
      enddo
      enddo

#ifdef MPI
      call MPI_ALLREDUCE(mpi_in_place,ca,1,MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,ierr)
      call MPI_ALLREDUCE(mpi_in_place,cx,1,MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,ierr)
      call MPI_ALLREDUCE(mpi_in_place,cy,1,MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,ierr)
#endif

      if( abs(ca).gt.smeps )then
        cx = cx/ca
        cy = cy/ca
      else
        stop 19999
        cx = centerx
        cy = centery
      endif

      minval =  1.0e30
      do i=1,nx+1
        if( abs(xfref(i)-cx).lt.minval )then
          minval = abs(xfref(i)-cx)
          icenter = i
        endif
      enddo

      minval =  1.0e30
      do j=1,ny+1
        if( abs(yfref(j)-cy).lt.minval )then
          minval = abs(yfref(j)-cy)
          jcenter = j
        endif
      enddo

      if(myid.eq.0)then
        print *,'  cx,cy = ',cx,cy
        print *,'  xf,yf = ',xfref(icenter),yfref(jcenter)
        print *,'  i,j   = ',icenter,jcenter
      endif

      xcenter = cx
      ycenter = cy

    ENDIF

  !---------------------------------------------------------------------

      end subroutine getpcent


    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine change_uvmove(u0,ua,u3d,v0,va,v3d,oldumove,oldvmove)
      use input
#ifdef MPI
      use mpi
#endif
      implicit none

      real, intent(inout), dimension(ib:ie+1,jb:je,kb:ke) :: u0,ua,u3d
      real, intent(inout), dimension(ib:ie,jb:je+1,kb:ke) :: v0,va,v3d
      real, intent(in) :: oldumove,oldvmove

      integer :: i,j,k

      do k=1,nk
        do j=jb,je
        do i=ib,ie+1
          u0(i,j,k) = u0(i,j,k) + (oldumove-umove)
          ua(i,j,k) = ua(i,j,k) + (oldumove-umove)
          u3d(i,j,k) = u3d(i,j,k) + (oldumove-umove)
        enddo
        enddo
        do j=jb,je+1
        do i=ib,ie
          v0(i,j,k) = v0(i,j,k) + (oldvmove-vmove)
          va(i,j,k) = va(i,j,k) + (oldvmove-vmove)
          v3d(i,j,k) = v3d(i,j,k) + (oldvmove-vmove)
        enddo
        enddo
      enddo

      end subroutine change_uvmove


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine update_adapt_move(nstep,mtime,xh,yh,xfref,yfref,ug,vg,psmth,     &
                                   dum1,pp3d,u0,ua,u3d,v0,va,v3d,mvrec,nwritemv,  &
                                   icenter,jcenter,xcenter,ycenter,               &
                                   domainlocx,domainlocy)
      use input
      use constants
#ifdef NETCDF
      use writeout_nc_module, only : writemove_nc
#endif
      implicit none

      integer, intent(in) :: nstep
      double precision, intent(in) :: mtime
      real, intent(in), dimension(ib:ie) :: xh
      real, intent(in), dimension(jb:je) :: yh
      real, intent(in), dimension(1-ngxy:nx+ngxy+1) :: xfref
      real, intent(in), dimension(1-ngxy:ny+ngxy+1) :: yfref
      real, intent(inout), dimension(kb:ke) :: ug,vg
      real, intent(inout), dimension(ib:ie,jb:je) :: psmth
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum1,pp3d
      real, intent(inout), dimension(ib:ie+1,jb:je,kb:ke) :: u0,ua,u3d
      real, intent(inout), dimension(ib:ie,jb:je+1,kb:ke) :: v0,va,v3d
      integer, intent(inout) :: mvrec
      integer, intent(in)    :: nwritemv
      integer, intent(inout) :: icenter,jcenter
      real, intent(inout) :: xcenter,ycenter
      double precision, intent(in) :: domainlocx,domainlocy

      integer :: k
      real :: oldumove,oldvmove,term2

      !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
      !cc   Adaptive domain-moving option for TCs  ccccccccccccccccccccccccccc
      !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

        ! Experimental (seems to work well, though)
        !
        ! Uses a smoothed field of pressure at the lowest model level to determine
        ! the position of a TC.

        ! skip if this is first time step
        if( nstep.ge.1 )then

          ! 220313: NOTE: moved getpsmth and getpcent to cm1.F

          ! attempt to move toward center of domain by next adaptmove time:
          oldumove = umove
          oldvmove = vmove

          ! 220313: increased timescale from 1.0 to 1.5 times adapt_move_frq
!!!          umove = -(centerx-xcenter)/(1.5*adapt_move_frq)
!!!          vmove = -(centery-ycenter)/(1.5*adapt_move_frq)

          term2 = 0.5

          umove = oldumove -term2*(centerx-xcenter)/(adapt_move_frq)  &
                           +(1.0-term2)*(umovem2-umovem1)

          vmove = oldvmove -term2*(centery-ycenter)/(adapt_move_frq)  &
                           +(1.0-term2)*(vmovem2-vmovem1)

          umovem2 = umovem1
          vmovem2 = vmovem1

          umovem1 = oldumove
          vmovem1 = oldvmove

          if( myid.eq.0 ) print *,'  adjusting umove,vmove:',umove,vmove

          call change_uvmove(u0,ua,u3d,v0,va,v3d,oldumove,oldvmove)

            do k=1,nk
              ug(k) = ug(k) + (oldumove-umove)
              vg(k) = vg(k) + (oldvmove-vmove)
            enddo

        endif

  !-------------------------------------------------------
  ! writeout:

    mid0:  &
    IF( myid.eq.0 )THEN

      of2:  &
      IF( output_format.eq.1 )THEN

          open(unit=82,file='cm1out_move.dat',form='unformatted',access='direct',recl=4)

          write(82,rec=mvrec) sngl(mtime)
          mvrec = mvrec+1
          write(82,rec=mvrec) xcenter
          mvrec = mvrec+1
          write(82,rec=mvrec) ycenter
          mvrec = mvrec+1
          write(82,rec=mvrec) real(icenter)
          mvrec = mvrec+1
          write(82,rec=mvrec) real(jcenter)
          mvrec = mvrec+1
          write(82,rec=mvrec) umove
          mvrec = mvrec+1
          write(82,rec=mvrec) vmove
          mvrec = mvrec+1
          write(82,rec=mvrec) sngl(domainlocx)
          mvrec = mvrec+1
          write(82,rec=mvrec) sngl(domainlocy)
          mvrec = mvrec+1

          close(unit=82)

          open(unit=50,file='cm1out_move.ctl',status='unknown')
          write(50,231)
231       format('dset ^cm1out_move.dat')
          write(50,202) trim(cm1version)
          write(50,203) grads_undef
          write(50,204)
          write(50,205)
          write(50,206)
          write(50,207) nwritemv
          write(50,208) 9
          write(50,209) 'mtime       ','model time (seconds since beginning of simulation)'
          write(50,209) 'xcenter     ','x (m) value of center point                       '
          write(50,209) 'ycenter     ','y (m) value of center point                       '
          write(50,209) 'icenter     ','i value of center point                           '
          write(50,209) 'jcenter     ','j value of center point                           '
          write(50,209) 'umove       ','umove (m/s)                                       '
          write(50,209) 'vmove       ','vmove (m/s)                                       '
          write(50,209) 'domainlocx  ','x location of (center of) domain (m)              '
          write(50,209) 'domainlocy  ','y location of (center of) domain (m)              '
          write(50,210)
          close(unit=50)
202       format('title CM1 adaptive move info, using version ',a,'; time is generic, see variable mtime for actual times')
203       format('undef ',f10.1)
204       format('xdef 1 linear 0.0 1.0')
205       format('ydef 1 linear 0.0 1.0')
206       format('zdef 1 linear 0.0 1.0')
207       format('tdef ',i10,' linear 00:00Z01JAN0001 1YR')
208       format('vars ',i4)
209       format(a12,' 0 99 ',a50)
210       format('endvars')


#ifdef NETCDF
      ELSEIF( output_format.eq.2 )THEN  of2

        call     writemove_nc(nwritemv,ncid,mtime,icenter,jcenter,xcenter,ycenter,umove ,vmove )

#endif
      ENDIF  of2

    ENDIF  mid0

      end subroutine update_adapt_move


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine getrangle(xh,yh,xcenter,ycenter, ir, rr, angle,icrs,crref,xhref,xfref)
      use input
      use constants
      implicit none

      real, intent(in), dimension(ib:ie) :: xh
      real, intent(in), dimension(jb:je) :: yh
      real, intent(inout) :: xcenter,ycenter
      integer, intent(inout), dimension(ib:ie,jb:je) :: ir
      real, intent(inout), dimension(ib:ie,jb:je) :: rr,angle
      integer, intent(in) :: icrs
      real, intent(in), dimension(icrs) :: crref
      real, intent(in), dimension(1-ngxy:nx+ngxy+1) :: xhref,xfref

      integer :: i,j,nn,ii,iimin
      real :: xsave,ysave,rddr,rrtmp
      real :: diff,diffmin

      xsave = xcenter
      ysave = ycenter

      ir = 0
      rr = 1.0e30
      angle = 0.0
      rddr = 1.0/ddr

    do nn = 1 , 1

      if( nn.eq.1 )then
        xcenter = xsave
        ycenter = ysave
      endif
      if( nn.eq.2 )then
        xcenter = xsave + (maxx-minx)
        ycenter = ysave + (maxy-miny)
      endif
      if( nn.eq.3 )then
        xcenter = xsave - (maxx-minx)
        ycenter = ysave - (maxy-miny)
      endif
      if( nn.eq.4 )then
        xcenter = xsave + (maxx-minx)
        ycenter = ysave - (maxy-miny)
      endif
      if( nn.eq.5 )then
        xcenter = xsave - (maxx-minx)
        ycenter = ysave + (maxy-miny)
      endif
      if( nn.eq.6 )then
        xcenter = xsave + (maxx-minx)
        ycenter = ysave
      endif
      if( nn.eq.7 )then
        xcenter = xsave - (maxx-minx)
        ycenter = ysave
      endif
      if( nn.eq.8 )then
        xcenter = xsave
        ycenter = ysave + (maxy-miny)
      endif
      if( nn.eq.9 )then
        xcenter = xsave
        ycenter = ysave - (maxy-miny)
      endif

      do j=1,nj
      do i=1,ni
        rrtmp = sqrt( (xh(i)-xcenter)**2 + (yh(j)-ycenter)**2 )
        if( rrtmp.lt.rr(i,j) )then
          rr(i,j) = rrtmp
          if( (xh(i)-xcenter).ge.0.0 )then
            angle(i,j) =      asin( (yh(j)-ycenter)/max(smeps,rr(i,j)) )
          else
            angle(i,j) = pi - asin( (yh(j)-ycenter)/max(smeps,rr(i,j)) )
          endif
        endif
      enddo
      enddo

    enddo

      xcenter = xsave
      ycenter = ysave

      do j=1,nj
      do i=1,ni
        rrtmp = sqrt( (xh(i)-xcenter)**2 + (yh(j)-ycenter)**2 )
        diffmin = 1.0e30
        do ii=1,icrs
          diff = rrtmp-crref(ii)
          if( abs(diff).lt.diffmin )then
            diffmin = abs(diff)
            iimin = ii
          endif
        enddo
!!!        ir(i,j) = iimin
        if( rr(i,j).lt.xfref(nx/2+icrs+1) )   ir(i,j) = iimin
      enddo
      enddo

      end subroutine getrangle


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


  END MODULE azimavg_module
base.F/         1744672191  3193  100   100644  103157    `
  MODULE base_module

  implicit none

  private
  public :: base

  CONTAINS

!-----------------------------------------------------------------------------
!
!  subroutine BASE:  Specify base-state arrays for CM1. 
!
!    Note:   The base state in CM1 is assumed to be in hydrostatic balance.
!            See "The governing equations for CM1" for more details:
!               http://www2.mmm.ucar.edu/people/bryan/cm1/cm1_equations.pdf
!
!    Note:  The variables psurf, tsurf, and qsurf refer to very-near-surface 
!           ATMOSPHERIC conditions (not land/ocean surface conditions).
!           They are used primarily for diagnostics purposes, such as for 
!           calculation of surface-based CAPE and CIN.
!
!-----------------------------------------------------------------------------

      subroutine base(zh,mh,rmh,c1,c2,zf,mf,rho0s,pi0s,prs0s,rth0s,         &
                      wprof,ufrc,vfrc,thfrc,qvfrc,ug,vg,dvdr,               &
                      uavg,vavg,thavg,pavg,qavg,ulspg,vlspg,                &
                      pi0,prs0,rho0,thv0,th0,rth0,qv0,u0,v0,thrd,           &
                      qc0,qi0,rr0,rf0,rrf0,t0  ,rh0 ,                       &
                      reqs_u,reqs_v,reqs_s,nw1,nw2,ne1,ne2,sw1,sw2,se1,se2, &
                      n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,              &
                      uw31,uw32,ue31,ue32,us31,us32,un31,un32,              &
                      vw31,vw32,ve31,ve32,vs31,vs32,vn31,vn32,              &
                      sw31,sw32,se31,se32,ss31,ss32,sn31,sn32)
      use input
      use constants
      use bc_module
      use comm_module
      use goddard_module, only : T0K,T00K,RT0
      use cm1libs , only : rslf,rsif
      use getcape_module
#ifdef MPI
      use mpi
#endif
      implicit none

      real, dimension(ib:ie,jb:je,kb:ke) :: zh,mh,rmh,c1,c2
      real, dimension(ib:ie,jb:je,kb:ke+1) :: zf,mf
      real, dimension(ib:ie,jb:je) :: rho0s,pi0s,prs0s,rth0s

      real, intent(inout), dimension(kb:ke) :: wprof,ufrc,vfrc,thfrc,qvfrc,ug,vg,dvdr,  &
                                               uavg,vavg,thavg,pavg
      real, intent(inout), dimension(kb:ke,numq) :: qavg
      real, intent(inout), dimension(kb:ke) :: ulspg,vlspg
      real, dimension(ib:ie,jb:je,kb:ke) :: pi0,prs0,rho0,thv0,th0,rth0,qv0
      real, dimension(ib:ie,jb:je,kb:ke) :: qc0,qi0,rr0,rf0,rrf0
      real, dimension(ib:ie,jb:je,kb:ke) :: t0,rh0
      real, dimension(ib:ie+1,jb:je,kb:ke) :: u0
      real, dimension(ib:ie,jb:je+1,kb:ke) :: v0
      real, intent(inout), dimension(ibb2:ibe2,jbb2:jbe2,kbb2:kbe2) :: thrd
      integer, intent(inout), dimension(rmp) :: reqs_u,reqs_v,reqs_s
      real, intent(inout), dimension(kmt) :: nw1,nw2,ne1,ne2,sw1,sw2,se1,se2
      real, intent(inout), dimension(cmp,cmp,kmt+1) :: n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2
      real, intent(inout), dimension(cmp,jmp,kmp) :: uw31,uw32,ue31,ue32
      real, intent(inout), dimension(imp+1,cmp,kmp) :: us31,us32,un31,un32
      real, intent(inout), dimension(cmp,jmp+1,kmp) :: vw31,vw32,ve31,ve32
      real, intent(inout), dimension(imp,cmp,kmp) :: vs31,vs32,vn31,vn32
      real, intent(inout), dimension(cmp,jmp,kmp) :: sw31,sw32,se31,se32
      real, intent(inout), dimension(imp,cmp,kmp) :: ss31,ss32,sn31,sn32

!-----------------------------------------------------------------------

      integer i,j,k,m,n,nn,irec,niter,nsnd,kbot,ktop,tflag,nmax
      real zu,zv
      real z_trop,th_trop,th_sfc,t_trop,prs_sfc,qv_pbl,pi_sfc,t_sfc,rh_sfc,rh_pbl
      real qv_sfc,thv_sfc,psurf,tsurf,qsurf,thsurf,thvsurf
      real tlast,ql2,thbar,qvbar,tlcl
      real ns,ns1,ns2,ns3,zl1,zl2,zsfc
      real qcval,qtval,p_sfc,ql_sfc,thn,thlast,qtm,qtp,tavg,lhv,     &
           qvavg,qlavg,qtavg,desdt,gamma,tp,delz,pim,thvm,qvm,qlm,   &
           tm,pm,thm,drdt,prsavg,qvl,qvi,fliq,fice,cpml,qim
      real thex,es,qvs,aaa
      real udep,uconst1,uconst2
      real udep1,udep2,umax1,umax2,vmax1,angle,a1,a2,wsp
      real tmp,ql,t1,t2,pitmp
      real hs,lapse
      real alpha,umax,nm,dudz,dvdz,rinum
      real, dimension(:), allocatable :: zsnd,thsnd,qvsnd,usnd,vsnd,   &
                                         thvsnd,pisnd,psnd,tsnd,rhsnd
      real, dimension(:), allocatable :: thinterp,qvinterp,uinterp,vinterp, &
                                         pinterp,tinterp,rhinterp
      integer :: kk,kup,kdn
      real :: interp_frac

      integer :: flag,ttype
      real :: pisfc,the_sfc,thv1,thv2,pi1,pi2,p2,theq,qt_sfc

      real :: ztrop,zmix,qv_mix,zmin,dtheta,thv_trop,qv_trop,pi_trop,p_trop,rhexp
      real :: depth_layer_01,depth_layer_02,shear_layer_01,shear_layer_02
      real :: du,dv

      real, dimension(:), allocatable :: pfoo,tfoo,qvfoo
      real :: cape,cin,zlcl,zlfc,zel,psource,tsource,thsource,qvsource

      integer :: k1,k2
      real :: lr1,lr2,ths1
      real :: tem
      logical :: dothis
      real :: wsp10,cd,znt,ust,wspr,gam,wsp1,wsp2,wtop,wref,radsfc,qvsfc,thsfc
      real :: uval,vval,vmax,wmin
      real :: z1,z2,z3,z4,z5,z6,z7,z8,z9
      real :: th1,th2,th3,th4,th5,th6,th7,th8,th9
      real :: qv1,qv2,qv3,qv4,qv5,qv6,qv7,qv8,qv9
      real :: pilast,thvlast,zlast,qt,thl,z_inv,th0last,lwp
      real :: qsfc,zq1,zq2,tv0,tsfc,tvsfc,psfc,lr,tvtrop,ptrop
      real :: rhval

!------------------------------------------------------------------

      if(dowr) write(outfile,*) 'Inside BASE'

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cc  Start definition of base state sounding (isnd opton)  cccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      psurf = 0.0
      tsurf = 0.0
      qsurf = 0.0

!-----------------------------------------------------------------------
!  isnd = 1
!  Dry adiabatic base state

      IF(isnd.eq.1)THEN

        ! Set these two variables for dry adiabatic sounding

        th_sfc   =   300.0   ! Potential temperature of atmosphere (K)
        pi_sfc   =   1.0     ! Exner function at surface

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          th0(i,j,k)=th_sfc
          pi0(i,j,k)=pi_sfc-g*zh(i,j,k)/(cp*th_sfc)
          prs0(i,j,k)=p00*(pi0(i,j,k)**cpdrd)
        enddo
        enddo
        enddo

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          qv0(i,j,k)=0.0
          rh0(i,j,k)=0.0
        enddo
        enddo
        enddo

        thsurf = th_sfc
        psurf = p00*(pi_sfc**cpdrd)
        tsurf = thsurf*((psurf*rp00)**rovcp)
        qsurf = 0.0

!-----------------------------------------------------------------------
!  isnd = 2
!  Dry isothermal base state
            
      ELSEIF(isnd.eq.2)THEN
          
        ! Set these two variables for dry isothermal sounding

        t_sfc    =   250.0    ! Temperature of atmosphere (K)
        prs_sfc  =   p00      ! Pressure at surface (Pa)


        hs=rd*t_sfc/g        ! scale height of atmosphere

        do k=kb,ke
        do j=jb,je
        do i=ib,ie

          ! calculate pressure field
          prs0(i,j,k)=prs_sfc*EXP(-zh(i,j,k)/hs)

          ! using the pressure field, calculate the exner pressure
          pi0(i,j,k)=(prs0(i,j,k)/p00)**(rd/cp)

          ! using exner pressure, determine the potential temperature
          th0(i,j,k)=t_sfc/pi0(i,j,k)

        enddo
        enddo
        enddo

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          qv0(i,j,k)=0.0
          rh0(i,j,k)=0.0
        enddo
        enddo
        enddo

        psurf = prs_sfc
        tsurf = t_sfc
        qsurf = 0.0


!-----------------------------------------------------------------------
!  isnd = 3
!  Dry, constant dT/dz sounding.
!  Lapse rate of 0.0065  =  standard dry atmosphere.

      ELSEIF(isnd.eq.3)THEN

        ! Set these three variables for dry constant lapse rate sounding

        th_sfc   =  300.0     ! theta at surface (K)
        prs_sfc  =  p00       ! pressure at surface (Pa)
        lapse    =  0.0065    ! dT/dz (K m^-1)

        do k=kb,ke
        do j=jb,je
        do i=ib,ie

          ! Calculate the temperature using the specified lapse rate.
          t0(i,j,k)=th_sfc-lapse*zh(i,j,k)

          ! Calculate the pressure from the temperature field.
          prs0(i,j,k)=p00*(t0(i,j,k)/th_sfc)**(g/(lapse*rd))

          ! Calculate the exner pressure from the pressure field.
          pi0(i,j,k)=(prs0(i,j,k)/p00)**(rd/cp)

          ! Calculate the theta field from temperature and the 
          ! specified lapse rate.
          th0(i,j,k)=th_sfc*(t0(i,j,k)/th_sfc)**(1-g/(lapse*cp))

        enddo
        enddo
        enddo

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          qv0(i,j,k)=0.0
          rh0(i,j,k)=0.0
        enddo
        enddo
        enddo

        psurf = prs_sfc
        tsurf = th_sfc*((psurf*rp00)**rovcp)
        qsurf = 0.0


!------------------------------------------------------------------
!  isnd = 4
!  Saturated, neutrally-stable sounding for moist benchmark simulation.
!  reference:  Bryan and Fritsch, 2002, MWR, 130, 2917-2928.

      ELSEIF(isnd.eq.4)THEN

        ! these two parameters define the sounding

        thec_mb   =   320.0     ! wet equivalent potential temp (K)
        qt_mb     =   0.020     ! total water mixing ratio (unitless)


        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  Saturated, neutrally-stable sounding'
        if(dowr) write(outfile,*) '    thec,qt=',thec_mb,qt_mb
        if(dowr) write(outfile,*)

        prs_sfc = 100000.0

      do j=jb,je
      do i=ib,ie

        !! First guesses at lowest model level
        prs0(i,j,1)=prs_sfc
        qv1=qt_mb
        tmp=thec_mb
        tlast=tmp

        do n=1,20
          thbar=(tmp*(p00/prs0(i,j,1))**(rd/cp))*(1.0+qv1*reps)/(1.0+qt_mb)
          pi0(i,j,1)=1.0-g*zh(i,j,1)/(cp*thbar)
          prs0(i,j,1)=p00*(pi0(i,j,1)**(cpdrd))
          qv1=rslf(prs0(i,j,1),tmp)
          tmp=thec_mb*((prs0(i,j,1)/(1.0+qv1/eps)/p00)**(rd/(cp+cpl*qt_mb)))  &
             /exp((lv1-lv2*tmp)*qv1/(tmp*(cp+cpl*qt_mb)))
          tmp=tlast+0.3*(tmp-tlast)
          tlast=tmp
        enddo
 
        t0(i,j,1)=tmp
        th0(i,j,1)=tmp/pi0(i,j,1)
        rh0(i,j,1)=1.0
        qv0(i,j,1)=rslf(prs0(i,j,1),tmp)
        t1=tmp
        qv1=qv0(i,j,1)
        th1=th0(i,j,1)

        do k=2,nk
          tlast=th1
          t2=t1
          qv2=qv1
          th2=th1
          n=0
          pi0(i,j,k)=pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*th2)
100       continue
            n=n+1
            th2=tlast
            t2=th2*pi0(i,j,k)
            thbar=0.5*( th1*(1.0+qv1*reps)/(1.0+qt_mb)    &
                       +th2*(1.0+qv2*reps)/(1.0+qt_mb) )
            pi0(i,j,k)=pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*thbar)
            prs0(i,j,k)=p00*(pi0(i,j,k)**(cpdrd))
            qv2=rslf(prs0(i,j,k),t2)
            t2=thec_mb*((prs0(i,j,k)/(1.0+qv2/eps)/p00)**(rd/(cp+cpl*qt_mb))) &
             /exp((lv1-lv2*t2)*qv2/(t2*(cp+cpl*qt_mb)))
            th2=t2/pi0(i,j,k)

            if(n.gt.50.and.dowr) write(outfile,*) n,th2
            if(abs(th2-tlast).gt.0.0001 .and. n.lt.100)then
              tlast=tlast+0.3*(th2-tlast)
              go to 100
            elseif(n.ge.100)then
              if(dowr) write(outfile,*) '  stuck in loop!'
              call stopcm1
            endif
 
          t0(i,j,k)=t2
          th0(i,j,k)=th2
          qv0(i,j,k)=rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k))
          rh0(i,j,k)=1.0
 
          th1=th2
          qv1=qv2
          t1=t2
 
        enddo

        do k=1,nk
          qc0(i,j,k)=qt_mb-qv0(i,j,k)
        enddo

      enddo
      enddo

        psurf = prs_sfc
        tsurf = cgs1*t0(1,1,1)+cgs2*t0(1,1,2)+cgs3*t0(1,1,3)
        qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)


!-----------------------------------------------------------------------
!  isnd = 5
!  Weisman-Klemp analytic sounding.
!  reference:  Weisman and Klemp, 1982, MWR, 110, 504-520.

      ELSEIF(isnd.eq.5)THEN

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  WK sounding'

!  variables related to Weisman-Klemp analytic sounding
        z_trop   = 12000.0      ! height of tropopause (m)
        th_trop  = 343.0        ! theta at tropopause (K)
        t_trop   = 213.0        ! temp at tropopause (K)
        th_sfc   = 300.0        ! theta at surface (K)
        prs_sfc  = 100000.0     ! pressure at surface (Pa)
        qv_pbl   = 0.014        ! constant value of mixing ratio in PBL

!--------------

        pi_sfc  = (prs_sfc/p00)**(rd/cp)
        qv_sfc  = rslf(prs_sfc,th_sfc*pi_sfc)
        thv_sfc = th_sfc*(1.0+qv_sfc*reps)/(1.0+qv_sfc)

      do j=jb,je
      do i=ib,ie

        do k=kb,ke
          rh0(i,j,k)=0.0
        enddo

        do k=1,nk
          if(zh(i,j,k).lt.z_trop)then
            th0(i,j,k)=th_sfc+(th_trop-th_sfc)*((zh(i,j,k)/z_trop)**1.25)
            if(imoist.eq.1) rh0(i,j,k)=1.0-0.75*((zh(i,j,k)/z_trop)**1.25)
          else
            th0(i,j,k)=th_trop*exp((g/(t_trop*cp))*(zh(i,j,k)-z_trop))
            if(imoist.eq.1) rh0(i,j,k)=0.25
          endif
        enddo

        th0(i,j,0)=th0(i,j,1)
        th0(i,j,nk+1)=th0(i,j,nk)


!  Get pressure, temperature, and mixing ratio using hydrostatic eqt.

        do k=kb,ke
          qv0(i,j,k)=0.0
        enddo

        do n=1,20
! virtual potential temperature
          do k=kb,ke
            thv0(i,j,k)=th0(i,j,k)*(1.0+reps*qv0(i,j,k))/(1.0+qv0(i,j,k))
          enddo

          pi0(i,j,1)=pi_sfc-g*zh(i,j,1)/(cp*0.5*(thv_sfc+thv0(i,j,1)))
          do k=2,nk
            pi0(i,j,k)=pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(thv0(i,j,k)+thv0(i,j,k-1)))
          enddo

! pressure
          do k=1,nk
            prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
          enddo

! mixing ratio
          do k=1,nk
            qv0(i,j,k)=rh0(i,j,k)*rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k))
            if(qv0(i,j,k).gt.qv_pbl) qv0(i,j,k)=qv_pbl
          enddo

        enddo

        do k=1,nk
          rh0(i,j,k)=qv0(i,j,k)/(rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k)))
        enddo

      enddo
      enddo

        psurf = prs_sfc
        tsurf = th_sfc*((psurf*rp00)**rovcp)
      IF( imoist.eq.1 )THEN
        if( qv0(1,1,1).lt.qv_pbl )then
          qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)
        else
          qsurf = qv_pbl
        endif
      ELSE
        qsurf = 0.0
      ENDIF

!------------------------------------------------------------------
!  isnd = 6

      ELSEIF(isnd.eq.6)THEN

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) ' isnd = 6 code has been removed (for now)'
        if(dowr) write(outfile,*)
        call stopcm1

!------------------------------------------------------------------
!  isnd = 7
!  Read base-state sounding from an external text file.
!  Assumes file name = "input_sounding"
!  NOTE:  for isnd=7, iwnd is ignored.
!
!  The format is the same as that for the WRF Model.
!
!  One-line header containing:   sfc pres (mb)    sfc theta (K)    sfc qv (g/kg)
!   
!   (Note1: here, "sfc" refers to near-surface atmospheric conditions. 
!    Technically, this should be z = 0, but in practice is obtained from the   
!    standard reporting height of 2 m AGL/ASL from observations)
!   (Note2: land-surface temperature and/or sea-surface temperature (SST) are 
!    specified elsewhere: see tsk0 in namelist.input and/or tsk array in 
!    init_surface.F)
!
! Then, the following lines are:   z (m)    theta (K)   qv (g/kg)    u (m/s)    v (m/s)
!
!   (Note3: # of levels is arbitrary)
!
!     Index:   sfc    =  surface (technically z=0, but typically from 2 m AGL/ASL obs)
!              z      =  height AGL/ASL
!              pres   =  pressure
!              theta  =  potential temperature
!              qv     =  mixing ratio
!              u      =  west-east component of velocity
!              v      =  south-north component of velocity
!
! Note4:  For final line of input_sounding file, z (m) must be greater than the model top
!         (which is nz * dz when stretch_z=0, or ztop when stretch_z=1,  etc)
!

      ELSEIF( isnd.eq.7 .or. isnd.eq.17 )then

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) ' Reading sounding from external file, input_sounding'
        if(dowr) write(outfile,*)

        nmax = 1000000  !should be enough!

        allocate(   zsnd(nmax) )
        zsnd = 0.0
        allocate(  thsnd(nmax) )
        thsnd = 0.0
        allocate(  qvsnd(nmax) )
        qvsnd = 0.0
        allocate(   usnd(nmax) )
        usnd = 0.0
        allocate(   vsnd(nmax) )
        vsnd = 0.0
        allocate( thvsnd(nmax) )
        thvsnd = 0.0
        allocate(  pisnd(nmax) )
        pisnd = 0.0
        allocate(   psnd(nmax) )
        psnd = 0.0
        allocate(   tsnd(nmax) )
        tsnd = 0.0
        allocate(  rhsnd(nmax) )
        rhsnd = 0.0

        allocate( thinterp(nk) )
        thinterp = 0.0
        allocate( qvinterp(nk) )
        qvinterp = 0.0
        allocate(  uinterp(nk) )
        uinterp = 0.0
        allocate(  vinterp(nk) )
        vinterp = 0.0
        allocate(  pinterp(nk) )
        pinterp = 0.0
        allocate(  tinterp(nk) )
        tinterp = 0.0
        allocate( rhinterp(nk) )
        rhinterp = 0.0

      prc0:  &
      IF( myid.eq.0 )THEN
        ! only processor 0 does this:

        open(unit=40,file='input_sounding',status='old',err=9009)

        ! read surface parameters:
        read(40,*,err=9008) p_sfc, th_sfc, qv_sfc
        if(dowr) write(outfile,*) ' p_sfc, th_sfc, qv_sfc = ',p_sfc, th_sfc, qv_sfc

        ! now, read entire sounding until end of file is discovered
        nsnd=1
        do k=1,nmax
          if( isnd.eq.7 )then
            read(40,*,end=445,err=9008) zsnd(k+1),thsnd(k+1),qvsnd(k+1),usnd(k+1),vsnd(k+1)
          elseif( isnd.eq.17 )then
            read(40,*,end=445,err=9008) zsnd(k+1),thsnd(k+1),qvsnd(k+1)
          else
            print *,'  23985 '
            call stopcm1
          endif
          ! put qv in g/g
          qvsnd(k+1) = qvsnd(k+1)/1000.0
          nsnd=nsnd+1
        enddo
445     continue
        if(dowr) write(outfile,*) '  Found ',nsnd,'  levels (including surface)'
        if(dowr) write(outfile,*)
        close(unit=40)

        if( nsnd.le.2 )then
          print *
          print *,'  There is only one u,v level.  At least two u,v levels are needed. '
          print *
          print *,'  ..... stopping cm1 ..... '
          print *
          call stopcm1
        endif

      ENDIF  prc0

#ifdef MPI
        call MPI_BCAST(nsnd    ,  1 ,MPI_INTEGER,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(p_sfc   ,  1 ,MPI_REAL   ,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(th_sfc  ,  1 ,MPI_REAL   ,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(qv_sfc  ,  1 ,MPI_REAL   ,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(zsnd(1) ,nsnd,MPI_REAL   ,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(thsnd(1),nsnd,MPI_REAL   ,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(qvsnd(1),nsnd,MPI_REAL   ,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(usnd(1) ,nsnd,MPI_REAL   ,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(vsnd(1) ,nsnd,MPI_REAL   ,0,MPI_COMM_WORLD,ierr)
#endif

        if(imoist.eq.0) qv_sfc = 0.0

        p_sfc = p_sfc * 100.0
        ! put qv in g/g
        qv_sfc = qv_sfc / 1000.0
        pi_sfc  = (p_sfc/p00)**(rd/cp)
        thv_sfc = th_sfc*(1.0+qv_sfc*reps)/(1.0+qv_sfc)

        psurf  = p_sfc
        thsurf = th_sfc
        tsurf  = th_sfc * pi_sfc
        qsurf  = qv_sfc

        zsnd(1) = 0.0
        thsnd(1) = th_sfc
        qvsnd(1) = qv_sfc

        if(imoist.eq.0) qvsnd = 0.0

      if( isnd.eq.7 )then
        ! dont remember where this formulation comes from:
!!!        usnd(1) = 1.75*usnd(2)-usnd(3)+0.25*usnd(4)
!!!        vsnd(1) = 1.75*vsnd(2)-vsnd(3)+0.25*vsnd(4)

        ! 190324:  use simple extrapolation
        usnd(1) = usnd(2) - (zsnd(2)-zsnd(1))*(usnd(3)-usnd(2))/(zsnd(3)-zsnd(2))
        vsnd(1) = vsnd(2) - (zsnd(2)-zsnd(1))*(vsnd(3)-vsnd(2))/(zsnd(3)-zsnd(2))
      endif

!--------------------------------------------------------------------
!  Added by GHB, 061021:
!  Get thv and prs. Check if qv is too small; if so, set rh to 0.1%
!  (This code has no effect on the sounding if qv > 1e-12 everywere)
        do k=1,nsnd
          thvsnd(k)=thsnd(k)*(1.0+reps*qvsnd(k))/(1.0+qvsnd(k))
        enddo
        pisnd(1)=pi_sfc
        do k=2,nsnd
          pisnd(k)=pisnd(k-1)-g*(zsnd(k)-zsnd(k-1))   &
                               /(cp*0.5*(thvsnd(k)+thvsnd(k-1)))
        enddo
        do k=1,nsnd
          psnd(k)=p00*(pisnd(k)**(cp/rd))
          tsnd(k)=thsnd(k)*pisnd(k)
        enddo
      if(imoist.eq.1)then
        do k=1,nsnd
          if(qvsnd(k).lt.1.0e-12)then
            if(dowr) write(outfile,*) '  Qv is too small.  Setting rh to 0.01%.  k,zsnd=',k,zsnd(k)
            qvsnd(k)=0.0001*rslf(psnd(k),thsnd(k)*pisnd(k))
          endif
          rhsnd(k)=qvsnd(k)/rslf(psnd(k),tsnd(k))
        enddo
      endif
!--------------------------------------------------------------------

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) ' Data from input_sounding file: '
        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '    k,z,th,qv:'
        do k=1,nsnd
          if(dowr) write(outfile,*) k,zsnd(k),thsnd(k),1000.0*qvsnd(k)
        enddo
        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '    k,z,u,v:'
        do k=1,nsnd
          if(dowr) write(outfile,*) k,zsnd(k),usnd(k),vsnd(k)
        enddo
        if(dowr) write(outfile,*)

! check to make sure sounding levels span computational grid (WICKER)
!!!        061011, GHB:  Commented this out ... we'll use the surface info.
!!!        if (zsnd(1) .gt. zh(1,1,1)) then
!!!          write(*,*) 'zmin of sounding > zmin of grid!'
!!!          write(*,*) 'zmin of sounding = ',zsnd(1)
!!!          write(*,*) 'zmin of grid = ',zh(1,1,1)
!!!          call stopcm1
!!!        endif

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) 'interpolating sounding to grid: '
        if(dowr) write(outfile,*)

      DO j=jb,je
      DO i=ib,ie

        if (zsnd(nsnd) .lt. zh(i,j,nk)) then
          if(dowr) write(outfile,*) 'zmax of sounding < zmax of grid!'
          if(dowr) write(outfile,*) 'zmax of sounding = ',zsnd(nsnd)
          if(dowr) write(outfile,*) 'zmax of grid  = ',zh(i,j,nk)
          call stopcm1
        endif

        DO k=1,nk

            kk = 1
            do while( zsnd(kk) .lt. zh(i,j,k) )
              kk = kk+1
            enddo
            kdn = kk-1
            kup = kk

            zu=0.5*(zh(max(ib,i-1),j,k)+zh(i,j,k))
            interp_frac = (   zu        - zsnd(kdn) )   &
                        / ( zsnd( kup ) - zsnd(kdn) )
            uinterp(k) =  usnd(kdn) + ( usnd(kup)- usnd(kdn))*interp_frac

            zv=0.5*(zh(i,max(jb,j-1),k)+zh(i,j,k))
            interp_frac = (   zv        - zsnd(kdn) )   &
                        / ( zsnd( kup ) - zsnd(kdn) )
            vinterp(k) =  vsnd(kdn) + ( vsnd(kup)- vsnd(kdn))*interp_frac

!!!            ! if this is first grid point, utilize surface values of th,qv:
!!!            if( k.eq.1 ) kdn = 1

            interp_frac = (   zh(i,j,k) - zsnd(kdn) )   &
                        / ( zsnd( kup ) - zsnd(kdn) )
            thinterp(k) = thsnd(kdn) + (thsnd(kup)-thsnd(kdn))*interp_frac
            qvinterp(k) = qvsnd(kdn) + (qvsnd(kup)-qvsnd(kdn))*interp_frac
             pinterp(k) =  psnd(kdn) + ( psnd(kup)- psnd(kdn))*interp_frac
             tinterp(k) =  tsnd(kdn) + ( tsnd(kup)- tsnd(kdn))*interp_frac
            rhinterp(k) = rhsnd(kdn) + (rhsnd(kup)-rhsnd(kdn))*interp_frac

            if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) '       ',zsnd(kdn),zh(i,j,k),zsnd(kup),interp_frac

        ENDDO
        if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*)

        do k=1,nk
           u0(i,j,k) =  uinterp(k)
           v0(i,j,k) =  vinterp(k)
          qv0(i,j,k) = qvinterp(k)
          th0(i,j,k) = thinterp(k)
         prs0(i,j,k) =  pinterp(k)
           t0(i,j,k) =  tinterp(k)
          rh0(i,j,k) = rhinterp(k)
        enddo

        ! get pi0 and prs0 from thv0, using hydrostatic equation

        do k=1,nk
          ! get qv from linear interpolation of rh:
          qv0(i,j,k) = rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
        enddo

        do k=1,nk
          thv0(i,j,k)=th0(i,j,k)*(1.0+reps*qv0(i,j,k))/(1.0+qv0(i,j,k))
        enddo

        pi0(i,j,1)=pi_sfc-g*zh(i,j,1)/(cp*0.5*(thv_sfc+thv0(i,j,1)))
        do k=2,nk
          pi0(i,j,k)=pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))   &
                                   /(cp*0.5*(thv0(i,j,k)+thv0(i,j,k-1)))
        enddo

        do k=1,nk
          prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
        enddo

        ! rh, just in case we want/need it later

      if(imoist.eq.1)then
        do k=1,nk
          rh0(i,j,k)=qv0(i,j,k)/(rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k)))
        enddo
      endif

      ENDDO    ! enddo for i loop
      ENDDO    ! enddo for j loop


        ! deallocate temporary 1D arrays
        deallocate(   zsnd )
        deallocate(  thsnd )
        deallocate(  qvsnd )
        deallocate(   usnd )
        deallocate(   vsnd )
        deallocate( thvsnd )
        deallocate(  pisnd )
        deallocate(   psnd )
        deallocate(   tsnd )
        deallocate(  rhsnd )
        deallocate( thinterp )
        deallocate( qvinterp )
        deallocate(  uinterp )
        deallocate(  vinterp )
        deallocate(  pinterp )
        deallocate(  tinterp )
        deallocate( rhinterp )


!-----------------------------------------------------------------------
!  isnd = 8
!  Dry, constant d(theta)/dz sounding

      ELSEIF(isnd.eq.8)THEN

        ! Set these three variables for dry, constant d(theta)/dz sounding

        th_sfc   =  300.0     ! theta at surface (K)
        pi_sfc   =    1.0     ! Exner function at surface
        lapse    = -0.0030581 ! potential temperature lapse rate (K/m)

        rhval = 0.0

        IF( testcase.eq.6 .or. testcase.eq.10 )THEN
          !  hurricane boundary layer (Bryan et al, 2017, BLM)
          lapse  =  0.005
        ENDIF
        IF( testcase.eq.10 )THEN
          rhval = 0.90
        ENDIF
        IF( testcase.eq.15 )THEN
          lapse = 0.005
          rhval = 0.80
        ENDIF


        do k=kb,ke
        do j=jb,je
        do i=ib,ie

          ! Calculate theta using the specified lapse rate.
          th0(i,j,k)=th_sfc+lapse*zh(i,j,k)

          ! Calculate pi from theta
          pi0(i,j,k)=pi_sfc-(g/(cp*lapse))*alog(th0(i,j,k)/th_sfc)

          ! Calculate pressure from pi
          prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))

          ! Calculate temperature from theta and pi
          t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)

          rh0(i,j,k) = rhval
          qv0(i,j,k) = rhval*rslf(prs0(i,j,k),t0(i,j,k))

        enddo
        enddo
        enddo

        thsurf = th_sfc
        psurf = p00*(pi_sfc**(cp/rd))
        tsurf = th_sfc * pi_sfc
        qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)

!------------------------------------------------------------------
!  isnd = 9
!  Constant Brunt-Vaisala frequency

      ELSEIF(isnd.eq.9)then

        ns1 =  0.0001
        ns2 =  0.0000

        zl1 = 40000.0

      do j=jb,je
      do i=ib,ie
        th_sfc   =  288.00
        pi_sfc   =    1.0
        !-----
        thsurf = th_sfc
        psurf = p00*(pi_sfc**(cp/rd))
        tsurf = th_sfc * pi_sfc
        !-----
        if(zh(i,j,1).lt.zl1)then
          zsfc = 0.0
          ns   = ns1
        else
          if(abs(ns1).lt.1.0e-6)then
            pi_sfc=pi_sfc-g*zl1/(cp*th_sfc)
          else
            pi_sfc=pi_sfc+g*g/(cp*ns1*th_sfc)*(exp(-ns1*zl1/g)-1.0)
            th_sfc=th_sfc*exp(ns1*zl1/g)
          endif
          zsfc = zl1
          ns   = ns2
        endif
        do k=1,nk
          qv0(i,j,k)=0.0
          qc0(i,j,k)=0.0
          rh0(i,j,k)=0.0
          if(abs(ns).lt.1.0e-6)then
            thv0(i,j,k)=th_sfc
            pi0(i,j,k)=pi_sfc-g*(zh(i,j,k)-zsfc)/(cp*th_sfc)
          else
            thv0(i,j,k)=th_sfc*exp(ns*(zh(i,j,k)-zsfc)/g)
            pi0(i,j,k)=pi_sfc+g*g/(cp*ns*th_sfc)   &
                           *(exp(-ns*(zh(i,j,k)-zsfc)/g)-1.0)
          endif
          prs0(i,j,k)=p00*(pi0(i,j,k)**cpdrd)
          th0(i,j,k)=thv0(i,j,k)
          do n=1,20
            t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
            qv0(i,j,k)=rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
            th0(i,j,k)=thv0(i,j,k)*(1.0+qv0(i,j,k)+qc0(i,j,k))/(1.0+reps*qv0(i,j,k))
!!!            if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) k,n,th0(i,j,k),qv0(i,j,k)
          enddo
          if(zh(i,j,k+1).gt.zl1.and.zsfc.lt.1.0)then
            if(abs(ns1).lt.1.0e-6)then
              pi_sfc=pi_sfc-g*zl1/(cp*th_sfc)
            else
              pi_sfc=pi_sfc+g*g/(cp*ns1*th_sfc)*(exp(-ns1*zl1/g)-1.0)
              th_sfc=th_sfc*exp(ns1*zl1/g)
            endif
            zsfc=zl1
            ns=ns2
          endif
        enddo

      enddo
      enddo

        qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)

!------------------------------------------------------------------
!  isnd = 10
!  Moist, constant Brunt-Vaisala frequency
!    (assuming reversible moist microphysics)

      ELSEIF(isnd.eq.10)then

        if(dowr) write(outfile,*) '  isnd = 10'

        qcval    =   0.005
        qtval    =   0.00000

        ns1 =  0.0
        ns2 =  4.0e-4

        zl1 = 111700.0

      do k=kb,ke
      do j=jb,je
      do i=ib,ie
        ! DEFINE RH here:  saturated (RH = 100%) is assumed by default
        rh0(i,j,k)=1.0
        qc0(i,j,k)=qcval
      enddo
      enddo
      enddo

      if(dowr) write(outfile,*)
      do j=jb,je
      do i=ib,ie
        th_sfc   =  288.0
        pi_sfc   =    1.0
        !-----
        thsurf = th_sfc
        psurf = p00*(pi_sfc**(cp/rd))
        tsurf = th_sfc * pi_sfc
        !-----
        ns=ns1
        p_sfc=p00*(pi_sfc**(cp/rd))
        t_sfc=th_sfc*pi_sfc
        qv_sfc=rh0(i,j,1)*rslf(p_sfc,t_sfc)
        ql_sfc=qcval
!!!        ql_sfc=qtval-qv_sfc
        thv_sfc=th_sfc*(1.0+reps*qv_sfc)/(1.0+qv_sfc+ql_sfc)
        thn=th_sfc
        thlast=thn
      !---------- do k=1 first ----------!
        k=1
        n=1
        qv0(i,j,k)=qv_sfc
        qc0(i,j,k)=ql_sfc
 571      continue
          th0(i,j,k)=thn
          thv0(i,j,k)=th0(i,j,k)*(1.0+reps*qv0(i,j,k))   &
                                /(1.0+qv0(i,j,k)+qc0(i,j,k))
          pi0(i,j,k)=pi_sfc-g*zh(i,j,k)/(cp*0.5*(thv0(i,j,k)+thv_sfc))
          prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
          t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
          qvs=rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
          qv0(i,j,k)=qvs
          qc0(i,j,k)=qcval
!!!          qc0(i,j,k)=qtval-qv0(i,j,k)
          qtm=qv_sfc+ql_sfc
          qtp=qv0(i,j,k)+qc0(i,j,k)
          tavg=0.5*( t0(i,j,k)+t_sfc )
          lhv=lv1-lv2*tavg
          qvavg=0.5*( qv_sfc + qv0(i,j,k) )
          qlavg=0.5*( ql_sfc + qc0(i,j,k) )
          qtavg=qvavg+qlavg
          desdt=17.67*(273.15-29.65)/((tavg-29.65)**2)
          drdt=17.67*(273.15-29.65)*qvavg/((tavg-29.65)**2)
        if(eqtset.eq.2)then
          gamma=g*(1.0+qtavg)*(1.0+lhv*qvavg/rd/tavg)   &
               /( cp+cpv*qvavg+cpl*qlavg          &
                 +lhv*drdt )
        else
          gamma=g*(1.0+qtavg)*(rd/(rd+rv*qvavg)+lhv*qvavg/rd/tavg)   &
               /( cp+lhv*(1.0+qvavg*reps)*qvavg*desdt )
        endif
          tp=t_sfc*exp( zh(i,j,k)*(                     &
                ((ns/g)+alog((1.0+qtp)/(1.0+qtm))/zh(i,j,k))  &
                   /(1.0+tavg*drdt/(eps+qvavg))-gamma/tavg                  &
                                                      ) )
          thn=tp/pi0(i,j,k)

          n=n+1

          if(n.gt.180.and.dowr) write(outfile,*) n,thn
          if(abs(thn-thlast).gt.0.0001 .and. n.lt.200)then
            thn=thlast+0.3*(thn-thlast)
            thlast=thn
            go to 571
          elseif(n.ge.200)then
            if(dowr) write(outfile,*) '  stuck in loop (111)!'
            call stopcm1
          endif

        th0(i,j,k)=thn
        prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
        t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
        qvs=rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
        qv0(i,j,k)=qvs
        qc0(i,j,k)=qcval
!!!        qc0(i,j,k)=qtval-qv0(i,j,k)
        if(qc0(i,j,1).lt.0.0)then
          print *,'  calling stopcm1 (222) '
          call stopcm1
        endif
        if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) k,n,th0(i,j,k),prs0(i,j,k)
      !---------- done with k=1, do all other levels ----------!
        qvs=qv0(i,j,1)
        ns=ns1
        do k=2,nk
        tflag=0
        do niter=1,2
        if(tflag.lt.2)then
          if(zh(i,j,k).gt.zl1.and.ns.eq.ns1.and.tflag.eq.0.and.zh(i,j,k-1).lt.zl1)then
            tflag=1
            delz=zl1-zh(i,j,k-1)
            pim=pi0(i,j,k-1)
            thm=th0(i,j,k-1)
            thvm=thv0(i,j,k-1)
            qtm=qv0(i,j,k-1)+qc0(i,j,k-1)+qi0(i,j,k-1)
            qvm=qv0(i,j,k-1)
            qlm=qc0(i,j,k-1)
            qim=qi0(i,j,k-1)
            tm=t0(i,j,k-1)
            pm=prs0(i,j,k-1)
          elseif(tflag.eq.1)then
            tflag=0
            ns=ns2
            delz=zh(i,j,k)-zl1
            pim=pi0(i,j,k)
            thm=th0(i,j,k)
            thvm=thv0(i,j,k)
            qtm=qv0(i,j,k)+qc0(i,j,k)+qi0(i,j,k)
            qvm=qv0(i,j,k)
            qlm=qc0(i,j,k)
            qim=qi0(i,j,k)
            tm=t0(i,j,k)
            pm=prs0(i,j,k)
          else
            tflag=2
            delz=zh(i,j,k)-zh(i,j,k-1)
            pim=pi0(i,j,k-1)
            thm=th0(i,j,k-1)
            thvm=thv0(i,j,k-1)
            qtm=qv0(i,j,k-1)+qc0(i,j,k-1)+qi0(i,j,k-1)
            qvm=qv0(i,j,k-1)
            qlm=qc0(i,j,k-1)
            qim=qi0(i,j,k-1)
            tm=t0(i,j,k-1)
            pm=prs0(i,j,k-1)
          endif
!!!          t0(i,j,k)=tm
          th0(i,j,k)=thm
          qv0(i,j,k)=qvm
          qc0(i,j,k)=qlm
          qi0(i,j,k)=qim
          thv0(i,j,k)=thvm
!!!          thlast=tm*pim
          thlast=thm
          n=0
          thn=thlast
          thlast=thn
 572      continue
            th0(i,j,k)=thn
            thv0(i,j,k)=th0(i,j,k)*(1.0+reps*qv0(i,j,k))   &
                                  /(1.0+qv0(i,j,k)+qc0(i,j,k)+qi0(i,j,k))
            pi0(i,j,k)=pim-g*delz/(cp*0.5*(thv0(i,j,k)+thvm))
            prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
            t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
          if(iice.eq.0)then
            qvs=rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
            qv0(i,j,k)=qvs
            qc0(i,j,k)=qcval
!!!            qc0(i,j,k)=qtval-qv0(i,j,k)
            qtp=qv0(i,j,k)+qc0(i,j,k)
            prsavg=0.5*(prs0(i,j,k-1)+prs0(i,j,k))
            tavg=0.5*( t0(i,j,k)+tm )
            qvavg=rh0(i,j,k)*rslf(prsavg,tavg)
            qlavg=0.5*( qlm + qc0(i,j,k) )
            qtavg=0.5*( qtm + qtp )
            drdt=17.67*(273.15-29.65)*qvavg/((tavg-29.65)**2)
            lhv=lv1-lv2*tavg
            cpml=cp+cpv*qvavg+cpl*qlavg
          else
            qvl=rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
            qvi=rh0(i,j,k)*rsif(prs0(i,j,k),t0(i,j,k))
            fliq=max(min((t0(i,j,k)-t00k)*rt0,1.0),0.0)
            fice=1.0-fliq
            qvs=fliq*qvl+fice*qvi
            qv0(i,j,k)=qvs
            qc0(i,j,k)=fliq*qcval
            qi0(i,j,k)=fice*qcval
            qtp=qv0(i,j,k)+qc0(i,j,k)+qi0(i,j,k)
            prsavg=0.5*(prs0(i,j,k-1)+prs0(i,j,k))
            tavg=0.5*( t0(i,j,k)+tm )
            qvl=rh0(i,j,k)*rslf(prsavg,tavg)
            qvi=rh0(i,j,k)*rsif(prsavg,tavg)
            fliq=max(min((tavg-t00k)*rt0,1.0),0.0)
            fice=1.0-fliq
            qvavg=fliq*qvl+fice*qvi
            qlavg=0.5*( qlm + qc0(i,j,k) )
            qtavg=0.5*( qtm + qtp )
            drdt=fliq*17.67*(273.15-29.65)*qvl/((tavg-29.65)**2)    &
                +fice*21.8745584*(273.15-7.66)*qvi/((tavg-7.66)**2)
            if(tavg.gt.t00k.and.tavg.lt.t0k)then
              drdt=drdt+(qvl-qvi)*rt0
            endif
            lhv=fliq*(lv1-lv2*tavg)+fice*(ls1-ls2*tavg)
            cpml=cp+cpv*qvavg+cpl*qlavg+cpi*(qtavg-qlavg-qvavg)
          endif
          if(eqtset.eq.2)then
            gamma=g*(1.0+qtavg)*(1.0+lhv*qvavg/rd/tavg)   &
                 /( cpml+lhv*drdt )
          else
            gamma=g*(1.0+qtavg)*(rd/(rd+rv*qvavg)+lhv*qvavg/rd/tavg)   &
                 /( cp+lhv*(1.0+qvavg*reps)*qvavg*desdt )
          endif
            tp=tm*exp( delz*(                                 &
                  ((ns/g)+alog((1.0+qtp)/(1.0+qtm))/delz)     &
                     /(1.0+tavg*drdt/(eps+qvavg))-gamma/tavg  &
                                                        ) )
            thn=tp/pi0(i,j,k)

            n=n+1

            if(n.gt.180.and.dowr) write(outfile,*) n,tp,tm,delz
            if(abs(thn-thlast).gt.0.0001 .and. n.lt.200)then
              thn=thlast+0.3*(thn-thlast)
              thlast=thn
              go to 572
            elseif(n.ge.200)then
              if(dowr) write(outfile,*) '  stuck in loop (333)!'
              call stopcm1
            endif

          t0(i,j,k)=tp
          th0(i,j,k)=thn
          prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
          t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
          if(iice.eq.0)then
            qvs=rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
            qv0(i,j,k)=qvs
            fliq = 1.0
            fice = 0.0
          else
            qvl=rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
            qvi=rh0(i,j,k)*rsif(prs0(i,j,k),t0(i,j,k))
            fliq=max(min((t0(i,j,k)-t00k)*rt0,1.0),0.0)
            fice=1.0-fliq
            qvs=fliq*qvl+fice*qvi
            qv0(i,j,k)=qvs
            qc0(i,j,k)=fliq*qcval
            qi0(i,j,k)=fice*qcval
          endif
          if(qc0(i,j,1).lt.0.0)then
            print *,'  calling stopcm1 (444) '
            call stopcm1
          endif
!!!          if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) k,n,zh(i,j,k),th0(i,j,k),prs0(i,j,k)
          if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) k,n,t0(i,j,k),fliq,fice
        endif
        enddo  ! enddo for iteration loop
        enddo  ! enddo for k loop

      enddo  ! enddo for i loop
      enddo  ! enddo for j loop
      if(dowr) write(outfile,*)

        qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)

!------------------------------------------------------------------
!  constant theta-e, saturated
!  Reference:  Bryan and Rotunno, 2009, JAS, v10, pp. 3042-3060

      ELSEIF(isnd.eq.11)THEN

        IF(imoist.eq.0)THEN
          if(dowr) write(outfile,*)
          if(dowr) write(outfile,*) '  isnd=11 requires imoist=1'
          if(dowr) write(outfile,*)
          if(dowr) write(outfile,*) '  stopping model ...'
          if(dowr) write(outfile,*)
          call stopcm1
        ENDIF

        zl1 = 15000.0    ! tropopause height

        ttype =  2    ! 1 = reversible
                      ! 2 = pseudoadiabatic

        psurf = 101510.0    ! surface pressure (Pa)

      DO j=jb,je
      DO i=ib,ie

        ! use psurf:
        pi_sfc   =  (psurf*rp00)**rovcp
        ! use tsk from namelist.input, make 3 K cooler:
        th_sfc   =  ( tsk0 - 3.0 )/pi_sfc

        !-----
        thsurf = th_sfc
        tsurf = th_sfc * pi_sfc
        !-----

        t_sfc=th_sfc*pi_sfc
        p_sfc=p00*(pi_sfc**(cp/rd))
        qv_sfc=rslf(p_sfc,t_sfc)
        qt_sfc=qv_sfc
        thv_sfc=th_sfc*(1.0+reps*qv_sfc)/(1.0+qv_sfc)

        the_sfc=getthe(ttype,p_sfc,t_sfc,qv_sfc,qt_sfc)
        if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) '  p_sfc,t_sfc,qv_sfc = ',p_sfc,t_sfc,qv_sfc
        if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) '  the_sfc,qt_sfc = ',the_sfc,qt_sfc

        th_sfc=0.0
        qv_sfc=0.0
        call revthe(ttype,the_sfc,p_sfc,qt_sfc,t_sfc,qv_sfc)
        if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) '  p_sfc,t_sfc,qv_sfc = ',p_sfc,t_sfc,qv_sfc

        pi1=pi_sfc
        z1=0.0
        t1=t_sfc
        thv1=thv_sfc
        thv2=thv1
        flag=0

        do k=1,nk

          z2=zh(i,j,k)
          t2=t1
          tlast=0.0
          n=0

        if(z2.le.zl1)then
          ! troposphere
          theq=the_sfc
          ! iterate:
          do while( abs(t2-tlast).gt.0.0001 )
            tlast=t2
            n=n+1
            pi2=pi1-g*(z2-z1)/(cp*0.5*(thv1+thv2))
            p2=p00*(pi2**(cp/rd))
            call revthe(ttype,theq,p2,qt_sfc,t2,qv2)
            th2=t2/pi2
            if(ttype.eq.1)then
              ql2=qt_sfc-qv2
            elseif(ttype.eq.2)then
              ql2=0.0
            endif
            thv2=th2*(1.0+reps*qv2)/(1.0+qv2+ql2)
          enddo
        else
          ! stratosphere
          ns=4.0e-4
          if(flag.eq.0)then
            ! first time in this section ... get sfc params
            !-------------------
            z2=zl1
            t2=t1
            tlast=0.0
            n=0
            theq=the_sfc
            do while( abs(t2-tlast).gt.0.0001 )
              tlast=t2
              n=n+1
              pi2=pi1-g*(z2-z1)/(cp*0.5*(thv1+thv2))
              p2=p00*(pi2**(cp/rd))
              call revthe(ttype,theq,p2,qt_sfc,t2,qv2)
              th2=t2/pi2
              if(ttype.eq.1)then
                ql2=qt_sfc-qv2
              elseif(ttype.eq.2)then
                ql2=0.0
              endif
              thv2=th2*(1.0+reps*qv2)/(1.0+qv2+ql2)
            enddo
            flag=1
            th_sfc=thv2
            pi_sfc=pi2
            zsfc=z2
            !-------------------
            z2=zh(i,j,k)
            t2=t1
            tlast=0.0
            n=0
          endif
          if(abs(ns).lt.1.0e-6)then
            thv2=th_sfc
            pi2=pi_sfc-g*(z2-zsfc)/(cp*th_sfc)
          else
            thv2=th_sfc*exp(ns*(z2-zsfc)/g)
            pi2=pi_sfc+g*g/(cp*ns*th_sfc)   &
                           *(exp(-ns*(z2-zsfc)/g)-1.0)
          endif
          p2=p00*(pi2**cpdrd)
          th2=thv2
          do n=1,20
            t2=th2*pi2
            qv2=rslf(p2,t2)
            if(ttype.eq.1)then
              ql2=qt_sfc-qv2
            elseif(ttype.eq.2)then
              ql2=0.0
            endif
            th2=thv2*(1.0+qv2+ql2)/(1.0+reps*qv2)
          enddo
        endif
!!!          if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) n,p2,th2

          t1=t2
          thv1=thv2
          z1=z2
          pi1=pi2

          pi0(i,j,k)=pi2
          prs0(i,j,k)=p2
          t0(i,j,k)=t2
          th0(i,j,k)=th2
          thv0(i,j,k)=thv2
          rh0(i,j,k)=1.0
          qv0(i,j,k)=qv2
          qc0(i,j,k)=ql2

        enddo

      ENDDO
      ENDDO

        qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)

!------------------------------------------------------------------
!  PBL simulation:  assumed dry

      ELSEIF(isnd.eq.12)THEN

        pi_sfc = 1.0
        th_sfc = 300.0
        zl1    = 960.0
        lapse  = 0.010

        pisfc = pi_sfc-g*zl1/(cp*th_sfc)

        do k=1,nk
        do j=jb,je
        do i=ib,ie
          IF(zh(i,j,k).le.zl1)THEN
            th0(i,j,k) = th_sfc
            pi0(i,j,k)=pi_sfc-g*zh(i,j,k)/(cp*th_sfc)
          ELSE
            th0(i,j,k) = th_sfc+lapse*(zh(i,j,k)-zl1)
            pi0(i,j,k)=pisfc-(g/(cp*lapse))*alog(th0(i,j,k)/th_sfc)
          ENDIF
          prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
          t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
          rh0(i,j,k)=0.0
          qv0(i,j,k)=0.0
          if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) k,zh(i,j,k),th0(i,j,k),prs0(i,j,k)
        enddo
        enddo
        enddo

!------------------------------------------------------------------
!  from Klemp (2011)

      ELSEIF(isnd.eq.13)then

        ns1 =  0.0001
        ns2 =  0.0004
        ns3 =  0.0001

        zl1 =  2000.0
        zl2 =  3000.0

      do j=jb,je
      do i=ib,ie
        th_sfc   =  288.00
        pi_sfc   =    1.0
        !-----
        thsurf = th_sfc
        psurf = p00*(pi_sfc**(cp/rd))
        tsurf = th_sfc * pi_sfc
        !-----
        if(zh(i,j,1).lt.zl1)then
          zsfc = 0.0
          ns   = ns1
        else
          if(abs(ns1).lt.1.0e-6)then
            pi_sfc=pi_sfc-g*zl1/(cp*th_sfc)
          else
            pi_sfc=pi_sfc+g*g/(cp*ns1*th_sfc)*(exp(-ns1*zl1/g)-1.0)
            th_sfc=th_sfc*exp(ns1*zl1/g)
          endif
          zsfc = zl1
          ns   = ns2
        endif
        do k=1,nk
          if(abs(ns).lt.1.0e-6)then
            th0(i,j,k)=th_sfc
            pi0(i,j,k)=pi_sfc-g*(zh(i,j,k)-zsfc)/(cp*th_sfc)
          else
            th0(i,j,k)=th_sfc*exp(ns*(zh(i,j,k)-zsfc)/g)
            pi0(i,j,k)=pi_sfc+g*g/(cp*ns*th_sfc)   &
                           *(exp(-ns*(zh(i,j,k)-zsfc)/g)-1.0)
          endif
          prs0(i,j,k)=p00*(pi0(i,j,k)**cpdrd)
          thv0(i,j,k)=th0(i,j,k)
          qv0(i,j,k)=0.0
          rh0(i,j,k)=0.0
          t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
          if(zh(i,j,k+1).gt.zl1.and.zsfc.lt.1.0)then
            if(abs(ns1).lt.1.0e-6)then
              pi_sfc=pi_sfc-g*zl1/(cp*th_sfc)
            else
              pi_sfc=pi_sfc+g*g/(cp*ns1*th_sfc)*(exp(-ns1*zl1/g)-1.0)
              th_sfc=th_sfc*exp(ns1*zl1/g)
            endif
            zsfc=zl1
            ns=ns2
          elseif(zh(i,j,k+1).gt.zl2.and.zsfc.lt.zl2)then
            if(abs(ns1).lt.1.0e-6)then
              pi_sfc=pi_sfc-g*(zl2-zl1)/(cp*th_sfc)
            else
              pi_sfc=pi_sfc+g*g/(cp*ns2*th_sfc)*(exp(-ns2*(zl2-zl1)/g)-1.0)
              th_sfc=th_sfc*exp(ns2*(zl2-zl1)/g)
            endif
            zsfc=zl2
            ns=ns3
          endif
        enddo

      enddo
      enddo

!------------------------------------------------------------------
!  Convective boundary layer  (Sullivan and Patton, 2011, JAS)

      ELSEIF(isnd.eq.14)THEN

        pi_sfc = 1.0
        th_sfc = 300.0

        lr1 =  0.08       ! lapse rate within inversion
        lr2 =  0.003      ! lapse rate above inversion

        zl1 =   974.0     ! bottom of inversion
        zl2 =  1074.0     ! top of inversion

        do k=1,nk
        do j=jb,je
        do i=ib,ie
          IF(zh(i,j,k).le.zl1)THEN
            th0(i,j,k) = th_sfc
            pi0(i,j,k) = pi_sfc-g*zh(i,j,k)/(cp*th_sfc)
          ELSEIF(zh(i,j,k).le.zl2)THEN
            th0(i,j,k) = th_sfc + (zh(i,j,k)-zl1)*lr1
            pi0(i,j,k) = pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(th0(i,j,k)+th0(i,j,k-1)))
          ELSE
            th0(i,j,k) = th_sfc + (zl2-zl1)*lr1 + (zh(i,j,k)-zl2)*lr2
            pi0(i,j,k) = pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(th0(i,j,k)+th0(i,j,k-1)))
          ENDIF
          prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
          t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
          thv0(i,j,k)=th0(i,j,k)
          rh0(i,j,k)=0.0
          qv0(i,j,k)=0.0
          if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) k,zh(i,j,k),th0(i,j,k),prs0(i,j,k)
        enddo
        enddo
        enddo

!------------------------------------------------------------------
! isnd = 15
      
      ! base state for the simulation of DYCOMS-II RF01,
      ! nonprecipitating stratocumulus (Stevens et al, 2005, MWR)            

      ! and DYCOMS-II RF02
      ! drizzling stratocumulus (Ackerman et al, 2009, MWR)

      ELSEIF( isnd.eq.15 )THEN

        if( testcase.lt.4 .or. testcase.gt.5 )then
          if( myid.eq.0 )then
            print *
            print *,'  isnd       = ',isnd
            print *,'  testcase = ',testcase
            print *
            print *,'  testcase must be 4 or 5 for this case '
            print *
            print *,'   stopping model .... '
            print *
            print *
          endif
#ifdef MPI
          call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif
          call stopcm1
        endif
         
        do j = 1,nj
        do i = 1,ni

          if( testcase .eq. 4 )then
            th_sfc  =  289.0                   ! surface (air) potential temperature (K)
            qv_sfc  =  0.009                   ! surface mixing ratio (kg/kg)
            prs_sfc = 101780.0                 ! surface pressure (Pa)
            z_inv   =  840.0                   ! base of the inversion (m)
          elseif( testcase .eq. 5 )then
            th_sfc  =  288.3                   ! surface (air) potential temperature (K)
            qv_sfc  =  0.00945                 ! surface mixing ratio (kg/kg)
            prs_sfc = 101780.0                 ! surface pressure (Pa)
            z_inv   =  795.0                   ! base of the inversion (m)
          endif

          pi_sfc  = (prs_sfc/p00)**(rd/cp)                 ! Exner function at surface
          thv_sfc = th_sfc*(1.0+qv_sfc*reps)/(1.0+qv_sfc)  ! surface density potential temperature (K)

          thvlast = thv_sfc
          th0last = th_sfc
          zlast = 0.0
          pilast = pi_sfc

          if( myid.eq.0 .and. i.eq.1 .and. j.eq.1 ) print *,'  pi_sfc,z_inv = ',pi_sfc,z_inv

          kloop1:  do k = 1,nk

            if( zh(i,j,k) .le. z_inv )then
              thl = th_sfc
              qt = qv_sfc
            else
              if( testcase .eq. 4 )then
                thl = 297.5 + (zh(i,j,k)-z_inv)**(1.0/3.0)
                qt = 0.0015
                ! convert specific humidity to mixing ratio:
                qt = qt/(1.0-qt)
              elseif( testcase .eq. 5 )then
                thl = 295.0 + (zh(i,j,k)-z_inv)**(1.0/3.0)
                qt = 0.001*( 5.0-3.0*(1.0-exp((z_inv-zh(i,j,k))/500.0)) )
              endif
            endif

            if( myid.eq.0 .and. i.eq.1 .and. j.eq.1 ) print *
            if( myid.eq.0 .and. i.eq.1 .and. j.eq.1 ) print *,'  k,zh = ',k,zh(i,j,k)
            if( myid.eq.0 .and. i.eq.1 .and. j.eq.1 ) print *,'  pi0,th0,qc0:'

            ! first guess:
            thlast = 0.0
            th0(i,j,k) = thl
            qv0(i,j,k) = qt
            qc0(i,j,k) = 0.0
            n = 0

            ! iterate:
            do while( abs(th0(i,j,k)-thlast).ge.0.0001 )

              thlast = th0(i,j,k)
              thv0(i,j,k) = th0(i,j,k)*(1.0+reps*qv0(i,j,k))/(1.0+qv0(i,j,k)+qc0(i,j,k))
              pi0(i,j,k) = pilast - g*(zh(i,j,k)-zlast)/(cp*0.5*(thvlast+thv0(i,j,k)))
              prs0(i,j,k) = p00*(pi0(i,j,k)**(cp/rd))
              t0(i,j,k) = th0(i,j,k)*pi0(i,j,k)
              qvs = rslf( prs0(i,j,k) , t0(i,j,k) )
              if( qt .lt. qvs )then
                qv0(i,j,k) = qt
                qc0(i,j,k) = 0.0
                th0(i,j,k) = thl
              else
                qv0(i,j,k) = qvs
                qc0(i,j,k) = qt-qvs
                th0(i,j,k) = thl/(1.0-xlv*qc0(i,j,k)/(cp*t0(i,j,k)))
              endif

              th0(i,j,k) = thlast + 0.3*(th0(i,j,k)-thlast)

              n = n+1
              if( myid.eq.0 .and. i.eq.1 .and. j.eq.1 ) print *,n,pi0(i,j,k),th0(i,j,k),qc0(i,j,k)
              if( n.gt.100.0 ) stop 1111

            enddo

            t0(i,j,k) = th0(i,j,k)*pi0(i,j,k)
            rho0(i,j,k) = prs0(i,j,k)/(rd*t0(i,j,k)*(1.0+qv0(i,j,k)*reps))

            thvlast = thv0(i,j,k)
            th0last = th0(i,j,k)
            pilast = pi0(i,j,k)
            zlast = zh(i,j,k)

          enddo  kloop1

        enddo
        enddo
 
        psurf = prs_sfc
        qsurf = qv_sfc
        tsurf = th_sfc * pi_sfc

        lwp = 0.0
        do k=1,nk
          lwp = lwp + rho0(1,1,k)*qc0(1,1,k)*dz*rmh(1,1,k)
        enddo

        if( myid.eq.0 ) print *
        if( myid.eq.0 ) print *,'  lwp = ',lwp
        if( myid.eq.0 ) print *
 

!------------------------------------------------------------------
!   Moeng and Sullivan (1994, JAS) PBL

      ELSEIF(isnd.eq.18)THEN

        pi_sfc = 1.0
        th_sfc = 300.0

        delz = 60.0

        lr1 =  8.0/delz   ! lapse rate within inversion
        lr2 =  0.003      ! lapse rate above inversion

        zl1 =   465.0 - delz/2.0   ! bottom of inversion
        zl2 =   465.0 + delz/2.0   ! top of inversion

        do k=1,nk
        do j=jb,je
        do i=ib,ie
          IF(zh(i,j,k).le.zl1)THEN
            th0(i,j,k) = th_sfc
            pi0(i,j,k) = pi_sfc-g*zh(i,j,k)/(cp*th_sfc)
          ELSEIF(zh(i,j,k).le.zl2)THEN
            th0(i,j,k) = th_sfc + (zh(i,j,k)-zl1)*lr1
            pi0(i,j,k) = pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(th0(i,j,k)+th0(i,j,k-1)))
          ELSE
            th0(i,j,k) = th_sfc + (zl2-zl1)*lr1 + (zh(i,j,k)-zl2)*lr2
            pi0(i,j,k) = pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(th0(i,j,k)+th0(i,j,k-1)))
          ENDIF
          prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
          t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
          thv0(i,j,k)=th0(i,j,k)
          rh0(i,j,k)=0.0
          qv0(i,j,k)=0.0
          if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) k,zh(i,j,k),th0(i,j,k),prs0(i,j,k)
        enddo
        enddo
        enddo

!------------------------------------------------------------------
!   Siebesma et al (2003, JAS) shallow Cu case:

      ELSEIF(isnd.eq.19)THEN

        ! (m)
        z1   =     0.0
        z2   =   520.0
        z3   =  1480.0
        z4   =  2000.0
        z5   =  3000.0

        ! (K)
        th1  =   298.7
        th2  =   298.7
        th3  =   302.4
        th4  =   308.2
        th5  =   311.85

        ! specific humidity (convert to mixing ratio below)
        ! (g/g)
        qv1  =  0.0170
        qv2  =  0.0163
        qv3  =  0.0107
        qv4  =  0.0042
        qv5  =  0.0030

        prs_sfc  =  101500.0   ! (Pa)

      IF( testcase.eq.11 )THEN
        ! SAS convective PBL:
        ! (m)
        z1   =     0.0
        z2   =   352.5
        z3   =   442.5
        z4   =  3000.0
        z5   = 20000.0

        ! (K)
        th1  =   296.6
        th2  =   296.6
        th3  =   298.1
        th4  =   th3 + 0.003*(z4-z3)
        th5  =   th3 + 0.003*(z5-z3)

        ! specific humidity (convert to mixing ratio below)
        ! (g/g)
        qv1  =  11.8e-3
        qv2  =  11.8e-3
        qv3  =   7.8e-3
        qv4  =  qv3 - 0.004e-3*(z4-z3)
        qv5  =  qv3 - 0.004e-3*(z5-z3)

        prs_sfc  =  100000.0   ! (Pa)
      ENDIF

        pi_sfc   =  (prs_sfc*rp00)**(rovcp)
        thv_sfc  = th1*(1.0+reps*qv1)/(1.0+qv1)

        do j=1,nj
        do i=1,ni

          do k=kb,ke
            if(     zh(i,j,k).le.z2 )then
              th0(i,j,k) = th1+(th2-th1)*(zh(i,j,k)-z1)/(z2-z1)
              qv0(i,j,k) = qv1+(qv2-qv1)*(zh(i,j,k)-z1)/(z2-z1)
            elseif( zh(i,j,k).le.z3 )then
              th0(i,j,k) = th2+(th3-th2)*(zh(i,j,k)-z2)/(z3-z2)
              qv0(i,j,k) = qv2+(qv3-qv2)*(zh(i,j,k)-z2)/(z3-z2)
            elseif( zh(i,j,k).le.z4 )then
              th0(i,j,k) = th3+(th4-th3)*(zh(i,j,k)-z3)/(z4-z3)
              qv0(i,j,k) = qv3+(qv4-qv3)*(zh(i,j,k)-z3)/(z4-z3)
            elseif( zh(i,j,k).le.z5 )then
              th0(i,j,k) = th4+(th5-th4)*(zh(i,j,k)-z4)/(z5-z4)
              qv0(i,j,k) = qv4+(qv5-qv4)*(zh(i,j,k)-z4)/(z5-z4)
            endif
            ! convert specific humidity to mixing ratio:
            qv0(i,j,k) = max( 0.0 , qv0(i,j,k)/(1.0-qv0(i,j,k)) )
            thv0(i,j,k) = th0(i,j,k)*(1.0+reps*qv0(i,j,k))/(1.0+qv0(i,j,k))
          enddo

          pi0(i,j,1) = pi_sfc-g*zh(i,j,1)/(cp*0.5*(thv_sfc+thv0(i,j,1)))
          do k=2,nk
            pi0(i,j,k) = pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(thv0(i,j,k)+thv0(i,j,k-1)))
          enddo

          do k=1,nk
            prs0(i,j,k) = p00*(pi0(i,j,k)**(cp/rd))
            rh0(i,j,k) = qv0(i,j,k)/(rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k)))
          enddo

      enddo
      enddo


        psurf = prs_sfc
        tsurf = th1*((psurf*rp00)**rovcp)
      IF( imoist.eq.1 )THEN
        if( qv0(1,1,1).lt.qv1 )then
          qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)
        else
          qsurf = qv1
        endif
      ELSE
        qsurf = 0.0
      ENDIF

!------------------------------------------------------------------
!   RICO, precipitating shallow Cu  (VanZanten et al 2011, JAMES)

      ELSEIF(isnd.eq.20)THEN

        ! (m)
        z1   =     0.0
        z2   =   740.0
        z3   =  3260.0
        z4   =  4000.0

        ! (K)
        th1  =   297.9
        th2  =   297.9
        th3  =   312.6644
        th4  =   317.0

        ! specific humidity (convert to mixing ratio below)
        ! (g/g)
        qv1  =  0.0160
        qv2  =  0.0138
        qv3  =  0.0024
        qv4  =  0.0018

        ! (Pa)
        prs_sfc  =  101540.0

        pi_sfc   =  (prs_sfc*rp00)**(rovcp)
        thv_sfc  = th1*(1.0+reps*qv1)/(1.0+qv1)

        do j=1,nj
        do i=1,ni

          do k=kb,ke
            if(     zh(i,j,k).le.z2 )then
              th0(i,j,k) = th1+(th2-th1)*(zh(i,j,k)-z1)/(z2-z1)
              qv0(i,j,k) = qv1+(qv2-qv1)*(zh(i,j,k)-z1)/(z2-z1)
            elseif( zh(i,j,k).le.z3 )then
              th0(i,j,k) = th2+(th3-th2)*(zh(i,j,k)-z2)/(z3-z2)
              qv0(i,j,k) = qv2+(qv3-qv2)*(zh(i,j,k)-z2)/(z3-z2)
            elseif( zh(i,j,k).le.z4 )then
              th0(i,j,k) = th3+(th4-th3)*(zh(i,j,k)-z3)/(z4-z3)
              qv0(i,j,k) = qv3+(qv4-qv3)*(zh(i,j,k)-z3)/(z4-z3)
            endif
            ! convert specific humidity to mixing ratio:
            qv0(i,j,k) = qv0(i,j,k)/(1.0-qv0(i,j,k))
            thv0(i,j,k) = th0(i,j,k)*(1.0+reps*qv0(i,j,k))/(1.0+qv0(i,j,k))
          enddo

          pi0(i,j,1) = pi_sfc-g*zh(i,j,1)/(cp*0.5*(thv_sfc+thv0(i,j,1)))
          do k=2,nk
            pi0(i,j,k) = pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(thv0(i,j,k)+thv0(i,j,k-1)))
          enddo

          do k=1,nk
            prs0(i,j,k) = p00*(pi0(i,j,k)**(cp/rd))
            rh0(i,j,k) = qv0(i,j,k)/(rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k)))
          enddo

      enddo
      enddo


        psurf = prs_sfc
        tsurf = th1*((psurf*rp00)**rovcp)
      IF( imoist.eq.1 )THEN
        if( qv0(1,1,1).lt.qv1 )then
          qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)
        else
          qsurf = qv1
        endif
      ELSE
        qsurf = 0.0
      ENDIF

!------------------------------------------------------------------
!   RCEMIP  (Wing et al. 2018, GMD)

      ELSEIF(isnd.eq.21)THEN

        ztrop = 15000.0

        qsfc = 0.01865
        qt = 10.0**(-11)
        zq1 = 4000.0
        zq2 = 7500.0

        tsfc = tsk0           ! set air temperature equal to SST 
        tvsfc = tsfc*(1.0+0.608*qsfc)

        psfc = 101480.0
        pisfc = (psfc/p00)**(rd/cp)

        lr = 0.0067

        tvtrop = tvsfc - lr*ztrop
        ptrop = psfc*(tvtrop/tvsfc)**(g/(rd*lr))

        th_sfc = tsfc/pisfc
        qv_sfc = qsfc/(1.0-qsfc)
        thv_sfc = th_sfc*(1.0+reps*qv_sfc)/(1.0+qv_sfc)

        if(dowr) write(outfile,*) '  tvsfc,ptrop = ',tvsfc,ptrop

        do j=jb,je
        do i=ib,ie

          do k=1,nk
            if( zh(i,j,k).lt.ztrop )then
              qv0(i,j,k) = qsfc*exp(-zh(i,j,k)/zq1)*exp(-(zh(i,j,k)/zq2)**2)
              tv0 = tvsfc - lr*zh(i,j,k)
              prs0(i,j,k) = psfc*( ((tvsfc-lr*zh(i,j,k))/tvsfc)**(g/(rd*lr)) )
            else
              qv0(i,j,k) = qt
              tv0 = tvtrop
              prs0(i,j,k) = ptrop*exp( -(g*(zh(i,j,k)-ztrop)/(rd*tvtrop)) )
            endif
            t0(i,j,k) = tv0/(1.0+0.608*qv0(i,j,k))
            if(dowr.and.i.eq.1.and.j.eq.1) write(outfile,*) k,zh(i,j,k),qv0(i,j,k),t0(i,j,k),prs0(i,j,k)
            pi0(i,j,k) = (prs0(i,j,k)*rp00)**rovcp
            th0(i,j,k) = t0(i,j,k)/pi0(i,j,k)
            ! convert specific humidity to mixing ratio:
            qv0(i,j,k) = qv0(i,j,k)/(1.0-qv0(i,j,k))
            thv0(i,j,k) = th0(i,j,k)*(1.0+reps*qv0(i,j,k))/(1.0+qv0(i,j,k))
          enddo

        enddo
        enddo

!------------------------------------------------------------------
!   stable boundary layer test case (Beare et al. 2006, BLM, pg 247)

      ELSEIF( isnd.eq.22 )THEN

        pi_sfc = 1.0
        th_sfc = 265.0
        zl1 = 100.0
        lr1 = 0.01

        do k=1,nk
        do j=jb,je
        do i=ib,ie
          IF(zh(i,j,k).le.zl1)THEN
            th0(i,j,k) = th_sfc
            pi0(i,j,k) = pi_sfc-g*zh(i,j,k)/(cp*th_sfc)
          ELSE
            th0(i,j,k) = th_sfc + (zh(i,j,k)-zl1)*lr1
            pi0(i,j,k) = pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(th0(i,j,k)+th0(i,j,k-1)))
          ENDIF
          prs0(i,j,k)=p00*(pi0(i,j,k)**(cp/rd))
          t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
          thv0(i,j,k)=th0(i,j,k)
          rh0(i,j,k)=0.0
          qv0(i,j,k)=rh0(i,j,k)*rslf(prs0(i,j,k),t0(i,j,k))
          if(i.eq.1.and.j.eq.1.and.dowr) write(outfile,*) k,zh(i,j,k),th0(i,j,k),prs0(i,j,k)
        enddo
        enddo
        enddo

!------------------------------------------------------------------
!   Diurnal cycle of shallow cumulus (Brown et al, 2002, QJRMS)

      ELSEIF( isnd.eq.23 )THEN

        pi_sfc = 1.0
        th_sfc = 299.0
        qv_sfc = 0.0152

        ! (m)
        z1   =     0.0
        z2   =    50.0
        z3   =   350.0
        z4   =   650.0
        z5   =   700.0
        z6   =  1300.0
        z7   =  2500.0
        z8   =  5500.0

        ! (K)
        th1  =   299.0
        th2  =   301.5
        th3  =   302.5
        th4  =   303.53
        th5  =   303.7
        th6  =   307.13
        th7  =   314.0
        th8  =   343.2

        ! specific humidity (convert to mixing ratio below)
        ! (g/g)
        qv1  =  0.0152
        qv2  =  0.01517
        qv3  =  0.01498
        qv4  =  0.0148
        qv5  =  0.0147
        qv6  =  0.0135
        qv7  =  0.003
        qv8  =  0.003

        prs_sfc  = 97000.0

        pi_sfc   =  (prs_sfc*rp00)**(rovcp)
        thv_sfc  = th1*(1.0+reps*qv1)/(1.0+qv1)

        z9 = 10000.0
        th9 = th8+(z9-z8)*(th8-th7)/(z8-z7)
        qv9 = qv8+(z9-z8)*(qv8-qv7)/(z8-z7)

        do j=1,nj
        do i=1,ni

          do k=kb,ke
            if(     zh(i,j,k).le.z2 )then
              th0(i,j,k) = th1+(th2-th1)*(zh(i,j,k)-z1)/(z2-z1)
              qv0(i,j,k) = qv1+(qv2-qv1)*(zh(i,j,k)-z1)/(z2-z1)
            elseif( zh(i,j,k).le.z3 )then
              th0(i,j,k) = th2+(th3-th2)*(zh(i,j,k)-z2)/(z3-z2)
              qv0(i,j,k) = qv2+(qv3-qv2)*(zh(i,j,k)-z2)/(z3-z2)
            elseif( zh(i,j,k).le.z4 )then
              th0(i,j,k) = th3+(th4-th3)*(zh(i,j,k)-z3)/(z4-z3)
              qv0(i,j,k) = qv3+(qv4-qv3)*(zh(i,j,k)-z3)/(z4-z3)
            elseif( zh(i,j,k).le.z5 )then
              th0(i,j,k) = th4+(th5-th4)*(zh(i,j,k)-z4)/(z5-z4)
              qv0(i,j,k) = qv4+(qv5-qv4)*(zh(i,j,k)-z4)/(z5-z4)
            elseif( zh(i,j,k).le.z6 )then
              th0(i,j,k) = th5+(th6-th5)*(zh(i,j,k)-z5)/(z6-z5)
              qv0(i,j,k) = qv5+(qv6-qv5)*(zh(i,j,k)-z5)/(z6-z5)
            elseif( zh(i,j,k).le.z7 )then
              th0(i,j,k) = th6+(th7-th6)*(zh(i,j,k)-z6)/(z7-z6)
              qv0(i,j,k) = qv6+(qv7-qv6)*(zh(i,j,k)-z6)/(z7-z6)
            elseif( zh(i,j,k).le.z8 )then
              th0(i,j,k) = th7+(th8-th7)*(zh(i,j,k)-z7)/(z8-z7)
              qv0(i,j,k) = qv7+(qv8-qv7)*(zh(i,j,k)-z7)/(z8-z7)
            elseif( zh(i,j,k).le.z9 )then
              th0(i,j,k) = th8+(th9-th8)*(zh(i,j,k)-z8)/(z9-z8)
              qv0(i,j,k) = qv8+(qv9-qv8)*(zh(i,j,k)-z8)/(z9-z8)
            endif
            ! convert specific humidity to mixing ratio:
            qv0(i,j,k) = qv0(i,j,k)/(1.0-qv0(i,j,k))
            thv0(i,j,k) = th0(i,j,k)*(1.0+reps*qv0(i,j,k))/(1.0+qv0(i,j,k))
          enddo

          pi0(i,j,1) = pi_sfc-g*zh(i,j,1)/(cp*0.5*(thv_sfc+thv0(i,j,1)))
          do k=2,nk
            pi0(i,j,k) = pi0(i,j,k-1)-g*(zh(i,j,k)-zh(i,j,k-1))/(cp*0.5*(thv0(i,j,k)+thv0(i,j,k-1)))
          enddo

          do k=1,nk
            prs0(i,j,k) = p00*(pi0(i,j,k)**(cp/rd))
            rh0(i,j,k) = qv0(i,j,k)/(rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k)))
          enddo

      enddo
      enddo


        psurf = prs_sfc
        tsurf = th1*((psurf*rp00)**rovcp)
      IF( imoist.eq.1 )THEN
        if( qv0(1,1,1).lt.qv1 )then
          qsurf = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)
        else
          qsurf = qv1
        endif
      ELSE
        qsurf = 0.0
      ENDIF

!------------------------------------------------------------------

      ENDIF

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cc  End definition of base state sounding (isnd opton)  cccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


!------------------------------------------------------------------
!  fill in ghost cells

      call bcs(pi0)
      call bcs(prs0)
      call bcs(th0)
      call bcs(qv0)
      call bcs(qc0)
      call bcs(qi0)
      call bcs(rh0)

#ifdef MPI
      nf=0
      nu=0
      nv=0
      nw=0
      call comm_all_s( pi0,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,  &
                           n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,reqs_s)
      call comm_all_s(prs0,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,  &
                           n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,reqs_s)
      call comm_all_s( th0,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,  &
                           n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,reqs_s)
      call comm_all_s( qv0,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,  &
                           n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,reqs_s)
      call comm_all_s( qc0,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,  &
                           n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,reqs_s)
      call comm_all_s( qi0,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,  &
                           n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,reqs_s)
      call comm_all_s( rh0,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,  &
                           n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,reqs_s)
#endif

      call extrapbcs(pi0)
      call extrapbcs(prs0)
      call extrapbcs(th0)
      call extrapbcs(qv0)
      call extrapbcs(qc0)
      call extrapbcs(qi0)
      call extrapbcs(rh0)

    do j=jb,je
    do i=ib,ie

!------------------------------------------------------------------
!  check thv0
!  Assumes th0, qv0 are accurate

      if(imoist.eq.1)then
        do k=kb,ke
          thv0(i,j,k)=th0(i,j,k)*(1.0+reps*qv0(i,j,k))/(1.0+qv0(i,j,k)+qc0(i,j,k)+qi0(i,j,k))
        enddo
      else
        do k=kb,ke
          qv0(i,j,k)=0.0
          rh0(i,j,k)=0.0
          thv0(i,j,k)=th0(i,j,k)
        enddo
      endif

!----------------------------
!  calculate pressure, density, and temperature

      do k=kb,ke
        prs0(i,j,k)=p00*(pi0(i,j,k)**cpdrd)
        rho0(i,j,k)=prs0(i,j,k)/(rd*th0(i,j,k)*pi0(i,j,k)*(1.0+qv0(i,j,k)*reps))
        t0(i,j,k)=th0(i,j,k)*pi0(i,j,k)
      enddo

!----------------------------
!  This reduces errors associated with buoyancy term
!  (seems kind of redundant ... but it works)

      !  This qv0 must match specification of qva array in 
      !  the INIT3D subroutine
      !  (i.e., identical bit-for-bit calculation)

!    IF(imoist.eq.1)THEN
!      do k=kb,ke
!        qv0(i,j,k)=rh0(i,j,k)*rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k))
!      enddo
!    ENDIF


      !  This thv0 must exactly match the manner in which thv
      !  is calculated in the SOLVE subroutine
      !  (i.e., identical bit-for-bit calculation)

      do k=kb,ke
        if(imoist.eq.1)then
          thv0(i,j,k)=(th0(i,j,k)+0.0)*(1.0+reps*max(0.0,qv0(i,j,k)))  &
                                      /(1.0+max(0.0,qv0(i,j,k))+max(0.0,qc0(i,j,k)+qi0(i,j,k)))
        else
          thv0(i,j,k)=th0(i,j,k)
        endif
      enddo

    enddo
    enddo

      call bcs(rho0)
#ifdef MPI
      call comm_all_s(rho0,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,  &
                           n3w1,n3w2,n3e1,n3e2,s3w1,s3w2,s3e1,s3e2,reqs_s)
#endif
      call extrapbcs(rho0)

      IF( psolver.eq.5 .or. psolver.eq.6 )THEN   
        ! incompressible or compressible-Boussinesq:  set rho0 to a constant

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          rho0(i,j,k) = 1.0
        enddo
        enddo
        enddo

      ENDIF

      do k=kb,ke
      do j=jb,je
      do i=ib,ie
        rr0(i,j,k)=1.0/rho0(i,j,k)
      enddo
      enddo
      enddo

      do k=2,nk
      do j=jb,je
      do i=ib,ie
        rf0(i,j,k)=c1(i,j,k)*rho0(i,j,k-1)+c2(i,j,k)*rho0(i,j,k)
      enddo
      enddo
      enddo

      do j=jb,je
      do i=ib,ie
        ! cm1r17, 2nd-order extrapolation:
        rf0(i,j,1) = cgs1*rho0(i,j,1)+cgs2*rho0(i,j,2)+cgs3*rho0(i,j,3)
        rf0(i,j,0)=rf0(i,j,1)
        rho0s(i,j) = rf0(i,j,1)
        ! cm1r17, 2nd-order extrapolation:
        rf0(i,j,nk+1) = cgt1*rho0(i,j,nk)+cgt2*rho0(i,j,nk-1)+cgt3*rho0(i,j,nk-2)
      enddo
      enddo

      do k=kb,ke
      do j=jb,je
      do i=ib,ie
        rrf0(i,j,k)=1.0/rf0(i,j,k)
      enddo
      enddo
      enddo

!        i = 1
!        j = 1
!        print *
!        print *,'  nk = ',nk
!        k = 1
!        print *,k,rf0(i,j,k)
!      do k=2,nk+1
!        print *,k,rf0(i,j,k),rf0(i,j,k)-rf0(i,j,k-1)
!      enddo
!        print *
!      stop 11111

!-----------------------------------------------------------------------
!  values at surface:

      ! Get surface p/T/q (for surface models and for CAPE calculation):

      IF( psurf.ge.tsmall .and. tsurf.ge.tsmall .and. (.not.terrain_flag) )THEN
        ! this section of code only if no terrain
#ifdef MPI
        call MPI_BCAST(psurf,1,MPI_REAL,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(tsurf,1,MPI_REAL,0,MPI_COMM_WORLD,ierr)
        call MPI_BCAST(qsurf,1,MPI_REAL,0,MPI_COMM_WORLD,ierr)
#endif
        thsurf = tsurf/( (psurf*rp00)**rovcp )
        do j=jb,je
        do i=ib,ie
          prs0s(i,j) = psurf
          pi0s(i,j) = (psurf*rp00)**rovcp
          rth0s(i,j) = thsurf**(-1)
        enddo
        enddo
      ELSE
        do j=jb,je
        do i=ib,ie
          thsurf = cgs1*th0(i,j,1)+cgs2*th0(i,j,2)+cgs3*th0(i,j,3)
           qsurf = cgs1*qv0(i,j,1)+cgs2*qv0(i,j,2)+cgs3*qv0(i,j,3)
          thvsurf = thsurf*(1.0+qsurf*reps)/(1.0+qsurf)
          ! use hydrostatic equation:
          pi0s(i,j) = pi0(i,j,1)+zh(i,j,1)*g/(cp*0.5*(thvsurf+thv0(i,j,1)))
          prs0s(i,j) = p00*( pi0s(i,j)**(cp/rd) )
          rth0s(i,j) = thsurf**(-1)
        enddo
        enddo
      ENDIF

      i = 1
      j = 1
      if( psurf.lt.tsmall ) psurf = prs0s(i,j)
      if( tsurf.le.tsmall ) tsurf = cgs1*t0(i,j,1)+cgs2*t0(i,j,2)+cgs3*t0(i,j,3)
      if( qsurf.le.tsmall ) qsurf = cgs1*qv0(i,j,1)+cgs2*qv0(i,j,2)+cgs3*qv0(i,j,3)
      thsurf = tsurf/( (psurf*rp00)**rovcp )


!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cc  Start definition of base state wind (iwnd option)  ccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


!-----------------------------------------------------------------------
!  Get wind profiles  ...  assume zero wind to start

!--------------------------
! 061012:
! Ignore this section if isnd = 7;  in that case, wind profile has
! already been retrieved from the input_sounding file
!--------------------------

    IF(isnd.ne.7)THEN

      do k=1,nk
      do j=1,nj
      do i=1,ni+1
        u0(i,j,k)= 0.0
      enddo
      enddo
      enddo

      do k=1,nk
      do j=1,nj+1
      do i=1,ni
        v0(i,j,k)= 0.0
      enddo
      enddo
      enddo

!-----------------------------------------------------------------------
!  iwnd = 1
!  RKW-type wind profile
!  reference: Rotunno, Klemp, and Weisman, 1988, JAS, 463-485.

      if(iwnd.eq.1)then

        udep1   =     0.0    ! height of bottom of shear layer (m)
        udep2   =  2500.0    ! height of top of shear layer (m)
        uconst1 =     0.0    ! u at bottom of shear layer
        uconst2 =    10.0    ! u at top of shear layer

        do k=1,nk
        do j=0,nj+1
        do i=0,ni+2
          zu=0.5*(zh(i-1,j,k)+zh(i,j,k))
          if(zu.lt.udep1)then
            u0(i,j,k)=uconst1
          elseif(zu.gt.udep1 .and. zu.lt.udep2)then
            u0(i,j,k)=(uconst2-uconst1)*(zu-udep1)/(udep2-udep1)+uconst1
          else
            u0(i,j,k)=uconst2
          endif
        enddo
        enddo
        enddo

        do k=1,nk
        do j=0,nj+2
        do i=0,ni+1
          zv=0.5*(zh(i,j-1,k)+zh(i,j,k))
          v0(i,j,k)=0.0
        enddo
        enddo
        enddo

!-----------------------------------------------------------------------
!  iwnd = 2
!  Weisman-Klemp type supercell profile

      elseif(iwnd.eq.2)then

        udep1=2000.0
        udep2=6000.0
        umax1=7.0
        umax2=31.0

        do k=1,nk
        do j=1,nj
        do i=1,ni+1
          zu=0.5*(zh(i-1,j,k)+zh(i,j,k))
          if(zu.le.udep1)THEN
            ANGLE=90.0*(zu/udep1)*(pi/180.0)
            u0(i,j,k)=umax1-umax1*cos(ANGLE)
          elseif(zu.gt.udep1 .and. zu.le.udep2)THEN
            u0(i,j,k)=umax1+(zu-udep1)*(umax2-umax1)/(udep2-udep1)
          ELSE
            u0(i,j,k)=umax2
          ENDIF
        enddo
        enddo
        enddo

        vmax1=umax1

        do k=1,nk
        do j=1,nj+1
        do i=1,ni
          zv=0.5*(zh(i,j-1,k)+zh(i,j,k))
          if(zv.le.udep1)THEN
            ANGLE=90.0*(zv/udep1)*(pi/180.0)
            v0(i,j,k)=vmax1*SIN(ANGLE)
          elseif(zv.gt.udep1 .and. zv.le.udep2)THEN
            v0(i,j,k)=vmax1
          ELSE
            v0(i,j,k)=vmax1
          ENDIF
        enddo
        enddo
        enddo

!-----------------------------------------------------------------------
!  iwnd = 3
!  Mulit-cell type profile (?)

      elseif(iwnd.eq.3)then

        udep1=0.0
        udep2=7500.0
        umax1=-40.0/pi
        umax2=40.0/pi+40.0

        do k=1,nk
        do j=1,nj
        do i=1,ni+1
          zu=0.5*(zh(i-1,j,k)+zh(i,j,k))
          if(zu.le.udep2)then
            u0(i,j,k)=umax1+(zu-udep1)*(umax2-umax1)/(udep2-udep1)
          else
            u0(i,j,k)=umax2
          endif
        enddo
        enddo
        enddo

        do k=1,nk
        do j=1,nj+1
        do i=1,ni
          zv=0.5*(zh(i,j-1,k)+zh(i,j,k))
          v0(i,j,k)=40.0/pi
        enddo
        enddo
        enddo

!-----------------------------------------------------------------------
!  iwnd = 4
!  Multi-cell
!  reference:  Weisman and Klemp, 1982, MWR, 110, 504-520.

      elseif(iwnd.eq.4)then

        umax1=35.0

        do k=1,nk
        do j=1,nj
        do i=1,ni+1
          u0(i,j,k)=umax1*tanh(0.5*(zh(i-1,j,k)+zh(i,j,k))/3000.0)
        enddo
        enddo
        enddo

        do k=1,nk
        do j=1,nj+1
        do i=1,ni
          zv=0.5*(zh(i,j-1,k)+zh(i,j,k))
          v0(i,j,k)=0.
        enddo
        enddo
        enddo

!-----------------------------------------------------------------------
!  iwnd = 5
!  reference:  Dornbrack et al., 2005, Atmos. Sci. Let., 6, 118-122

      elseif(iwnd.eq.5)then

        umax  =   15.0
        udep1 = 4000.0
        udep2 = 6000.0

        do k=1,nk
        do j=1,nj
        do i=1,ni+1
          zu=0.5*(zh(i-1,j,k)+zh(i,j,k))
          if(zu.lt.udep1)then
            u0(i,j,k) = umax
          elseif(zu.lt.udep2)then
            alpha=0.25*pi*(1.0+cos(pi*(zu-udep1)/(udep2-udep1)))
            u0(i,j,k) = umax*sin(alpha)
          else
            u0(i,j,k) = 0.0
          endif
        enddo
        enddo
        enddo

        do k=1,nk
        do j=1,nj+1
        do i=1,ni
          zv=0.5*(zh(i,j-1,k)+zh(i,j,k))
          if(zv.lt.udep1)then
            v0(i,j,k) = 0.0
          elseif(zv.lt.udep2)then
            alpha=0.25*pi*(1.0+cos(pi*(zv-udep1)/(udep2-udep1)))
            v0(i,j,k) = umax*cos(alpha)
          else
            v0(i,j,k) = umax
          endif
        enddo
        enddo
        enddo

!-----------------------------------------------------------------------
!  iwnd = 6
!  constant wind

      ELSEIF(iwnd.eq.6)THEN

        if( testcase.eq.1 )then
          ! Sullivan and Patton (2011, JAS)
          uval = 1.0
          vval = 0.0
        elseif( testcase.eq.2 )then
          ! Moeng and Sullivan (1994, JAS)
          uval = 15.0
          vval =  0.0
        elseif( testcase.eq.4 )then
          ! nonprecipitating stratocumulus case (Stevens et al. MWR 2005)            
          uval =  7.0
          vval = -5.5
        elseif( testcase.eq.9 )then
          ! stable boundary layer (Beare et al. 2006, BLM)
          uval =  8.0
          vval =  0.0
        elseif( testcase.eq.11 )then
          ! SAS
          uval =  2.0
          vval =  0.0
        elseif( testcase.eq.12 )then
          ! Martinuzzi and Tropea (1993) wind tunnel
          uval = 20.0
          vval =  0.0
        elseif( testcase.eq.14 )then
          ! shallow Cu over land (Brown et al. 2002)
          uval = 10.0
          vval =  0.0
        else
          ! default:
          uval = 10.0
          vval =  0.0
        endif

        do k=kb,ke
        do j=jb,je
        do i=ib,ie+1
          u0(i,j,k) = uval
        enddo
        enddo
        enddo

        do k=kb,ke
        do j=jb,je+1
        do i=ib,ie
          v0(i,j,k) = vval
        enddo
        enddo
        enddo


!-----------------------------------------------------------------------
!  iwnd = 8
!  Wind speed decreasing with height
!  Simple hurricane boundary layer (Bryan et al 2017, BLM)

      ELSEIF(iwnd.eq.8)THEN

!!!        vmax = 40.0        ! this is now set in namelist.input
                              ! (see hurr_vg in param21 section)

        ! velocity in cylindrical coords:
        do k=1,nk

!!!          ! linearly decreasing with height:
!!!          ug(k) = 0.0
!!!          vg(k) = hurr_vg * max( 0.0 , (1.0-zh(1,1,k)/18000.0) )

          ! constant with height:
          ug(k) = 0.0
          vg(k) = hurr_vg

        enddo

        ! convert to Cartesian components:
        do k=1,nk
        do j=0,nj+2
        do i=0,ni+2
          u0(i,j,k) = - vg(k) * sin(-hurr_angle)
          v0(i,j,k) =   vg(k) * cos(-hurr_angle)
        enddo
        enddo
        enddo

!-----------------------------------------------------------------------
!  iwnd = 9
!  Siebesma et al (2003, JAS) shallow Cu case:

      ELSEIF(iwnd.eq.9)THEN

        udep1   =   700.0    ! height of bottom of shear layer (m)
        udep2   =  3000.0    ! height of top of shear layer (m)
        uconst1 =    -8.75   ! u at bottom of shear layer
        uconst2 =    -4.61   ! u at top of shear layer

        do k=1,nk

          do j=0,nj+1
          do i=0,ni+2
            zu=0.5*(zh(i-1,j,k)+zh(i,j,k))
            if(zu.le.udep1)then
              u0(i,j,k)=uconst1
            elseif(zu.gt.udep1 .and. zu.lt.udep2)then
              u0(i,j,k)=(uconst2-uconst1)*(zu-udep1)/(udep2-udep1)+uconst1
            else
              u0(i,j,k)=uconst2
            endif
          enddo
          enddo

          do j=0,nj+2
          do i=0,ni+1
            zv=0.5*(zh(i,j-1,k)+zh(i,j,k))
            v0(i,j,k)=0.0
          enddo
          enddo

        enddo


!-----------------------------------------------------------------------
!  iwnd = 10
!  Ackerman et al (2009, MWR) drizzling Sc case

      ELSEIF(iwnd.eq.10)THEN

        do k=1,nk

          do j=0,nj+1
          do i=0,ni+2
            zu=0.5*(zh(i-1,j,k)+zh(i,j,k))
            u0(i,j,k) =  3.0 + 4.3*zu/1000.0
          enddo
          enddo

          do j=0,nj+2
          do i=0,ni+1
            zv=0.5*(zh(i,j-1,k)+zh(i,j,k))
            v0(i,j,k) = -9.0 + 5.6*zv/1000.0
          enddo
          enddo

        enddo

!-----------------------------------------------------------------------
!  iwnd = 11
!   RICO, precipitating shallow Cu  (VanZanten et al 2011, JAMES)

      ELSEIF(iwnd.eq.11)THEN

        udep1   =      0.0   ! height of bottom of shear layer (m)
        udep2   =   4000.0   ! height of top of shear layer (m)
        uconst1 =     -9.9   ! u at bottom of shear layer
        uconst2 =     -1.9   ! u at top of shear layer

        do k=1,nk

          do j=0,nj+1
          do i=0,ni+2
            zu=0.5*(zh(i-1,j,k)+zh(i,j,k))
            if(zu.le.udep1)then
              u0(i,j,k)=uconst1
            elseif(zu.gt.udep1 .and. zu.lt.udep2)then
              u0(i,j,k)=(uconst2-uconst1)*(zu-udep1)/(udep2-udep1)+uconst1
            else
              u0(i,j,k)=uconst2
            endif
          enddo
          enddo

          do j=0,nj+2
          do i=0,ni+1
            zv=0.5*(zh(i,j-1,k)+zh(i,j,k))
            v0(i,j,k) = -3.8
          enddo
          enddo

        enddo

!-----------------------------------------------------------------------

      ENDIF    ! endif for iwnd options

    ENDIF   ! endif for isnd=7 check


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


!-----------------------------------------------------------------------
!  subtract off umove and vmove (if applicable)

      if(imove.eq.1)then
        do k=1,nk
        do j=1,nj+1
        do i=1,ni+1
          u0(i,j,k)=u0(i,j,k)-umove
          v0(i,j,k)=v0(i,j,k)-vmove
        enddo
        enddo
        enddo
      else
        umove=0.0
        vmove=0.0
      endif

!-----------------------------------------------------------------------
!  Fill in ghost cells

      call bcu(u0)
      call bcv(v0)

      !--------
#ifdef MPI
      call comm_3u_start(u0,uw31,uw32,ue31,ue32,   &
                            us31,us32,un31,un32,reqs_u)
      call comm_3u_end(u0,uw31,uw32,ue31,ue32,   &
                          us31,us32,un31,un32,reqs_u)
      call getcorneru3(u0,n3w1(1,1,1),n3w2(1,1,1),n3e1(1,1,1),n3e2(1,1,1),  &
                          s3w1(1,1,1),s3w2(1,1,1),s3e1(1,1,1),s3e2(1,1,1))
      call bcu2(u0)
#endif
!$omp parallel do default(shared)   &
!$omp private(i,j)
      do j=jb,je
      do i=ib,ie+1
        u0(i,j,0)    = cgs1*u0(i,j,1)+cgs2*u0(i,j,2)+cgs3*u0(i,j,3)
        u0(i,j,nk+1) = cgt1*u0(i,j,nk)+cgt2*u0(i,j,nk-1)+cgt3*u0(i,j,nk-2)
      enddo
      enddo
      !--------
#ifdef MPI
      call comm_3v_start(v0,vw31,vw32,ve31,ve32,   &
                            vs31,vs32,vn31,vn32,reqs_v)
      call comm_3v_end(v0,vw31,vw32,ve31,ve32,   &
                          vs31,vs32,vn31,vn32,reqs_v)
      call getcornerv3(v0,n3w1(1,1,1),n3w2(1,1,1),n3e1(1,1,1),n3e2(1,1,1),  &
                          s3w1(1,1,1),s3w2(1,1,1),s3e1(1,1,1),s3e2(1,1,1))
      call bcv2(v0)
#endif
!$omp parallel do default(shared)   &
!$omp private(i,j)
      do j=jb,je+1
      do i=ib,ie
        v0(i,j,0)    = cgs1*v0(i,j,1)+cgs2*v0(i,j,2)+cgs3*v0(i,j,3)
        v0(i,j,nk+1) = cgt1*v0(i,j,nk)+cgt2*v0(i,j,nk-1)+cgt3*v0(i,j,nk-2)
      enddo
      enddo
      !--------

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cc  End definition of base state wind (iwnd option)  ccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc



!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!
!  forcing tendencies and settings for certain configurations:
!
    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase .eq. 3 )THEN

      ! shallow Cu case  (Siebesma et al, 2003, JAS)

      if( myid.eq.0 ) print *
      if( myid.eq.0 ) print *,'  k,zf,w:'

      wmin  =  -0.0065
      z1    =   1500.0
      z2    =   2100.0

      do k=1,nk
        ! note:  wprof is on w levels (ie, full levels).   Use zf.
        if( zf(1,1,k).le.z1 )then
          wprof(k) = 0.0 + ( wmin - 0.0 )*(zf(1,1,k)-0.0)/(z1-0.0)
        elseif( zf(1,1,k).le.z2 )then
          wprof(k) = wmin + ( 0.0 - wmin )*(zf(1,1,k)-z1)/(z2-z1)
        else
          wprof(k) = 0.0
        endif
        if( myid.eq.0 ) print *,k,zf(1,1,k),wprof(k)
      enddo
 
      radsfc = -2.0 /( 3600.0 * 24.0 )
      z1     =  1500.0
      z2     =  2100.0

      do k=1,nk
        if( zh(1,1,k).le.z1 )then
          thfrc(k) = radsfc
        elseif( zh(1,1,k).le.z2 )then
          thfrc(k) = radsfc + ( 0.0 - radsfc )*(zh(1,1,k)-z1)/(z2-z1)
        else
          thfrc(k) = 0.0
        endif
      enddo

      if( myid.eq.0 ) print *
      if( myid.eq.0 ) print *,'  k,zh,thfrc,qvfrc '

      qvsfc  =  -1.2e-8
      z1     =   300.0
      z2     =   500.0

      do k=1,nk
        if( zh(1,1,k).le.z1 )then
          qvfrc(k) = -1.2e-8
        elseif( zh(1,1,k).le.z2 )then
          qvfrc(k) = qvsfc + ( 0.0 - qvsfc )*(zh(1,1,k)-z1)/(z2-z1)
        else
          qvfrc(k) = 0.0
        endif
        if( myid.eq.0 ) print *,k,zh(1,1,k),thfrc(k)*3600.0*24.0,qvfrc(k)
      enddo


      if( myid.eq.0 ) print *
      if( myid.eq.0 ) print *,'  k,ug,vg '
      do k=1,nk
        ug(k) = -10.0 + 0.0018 * zh(1,1,k)
        vg(k) =   0.0
      enddo
      if( myid.eq.0 ) print *

    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase .eq. 4 )THEN

      ! nonprecipitating stratoCu (Stevens et al, 2005, MWR)

      do k=2,nk
        ! note:  wprof is on w levels (ie, full levels):   Use zf.
        wprof(k) = -3.75e-6 * zf(1,1,k)
      enddo

    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase .eq. 5 )THEN

      ! drizzling stratoCu (Ackerman et al, 2009, MWR)

      do k=2,nk
        ! note:  wprof is on w levels (ie, full levels):   Use zf.
        wprof(k) = -3.75e-6 * zf(1,1,k)
      enddo

    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase.eq.6 .or. testcase.eq.10 .or. testcase.eq.15 )THEN

      ! hurricane boundary layer (Bryan et al, 2017, BLM)

!!!      hurr_rad = 40000.0      ! radius from center of hurricane (m) 
                                 ! (cm1r21.0: now set this in namelist.input)

      wmin  =   -0.01    ! value of w at z = z1
!!!      wmin  =   var1     ! value of w at z = z1
      z1    =  1000.0    ! level of min w
      z2    =  4000.0    ! level where w = 0

      do k=1,nk

        ! radial gradient of tangential velocity (defined on scalar levels)
!!!        dvdr(k) = -0.00085*max(0.0,1.0-zh(1,1,k)/18000.0)
        ! set this in namelist.input:
        ! hurr_vgpl is the power law of the gradient wind
        dvdr(k) = hurr_vgpl * ( vg(k) / hurr_rad )

        ! subsidence (defined on w levels)
        if( zf(1,1,k).le.z1 )then
          wprof(k) = 0.0 + ( wmin - 0.0 )*(zf(1,1,k)-0.0)/(z1-0.0)
        elseif( zf(1,1,k).le.z2 )then
          wprof(k) = wmin + ( 0.0 - wmin )*(zf(1,1,k)-z1)/(z2-z1)
        else
          wprof(k) = 0.0
        endif

      enddo

      if( dowr ) write(outfile,*)
      if( dowr ) write(outfile,*) '  hurr_rad (m) = ',hurr_rad
      if( dowr ) write(outfile,*)
      if( dowr ) write(outfile,*) '      zh(m),vg(m/s),dvdr(1/s),n = '
      do k=1,nk
        if( dowr ) write(outfile,*) zh(1,1,k),vg(k),dvdr(k),-dvdr(k)*hurr_rad/max(1.0e-12,vg(k))
      enddo
      if( dowr ) write(outfile,*)

    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase .eq. 7 )THEN

      !   RICO, precipitating shallow Cu  
      !   (VanZanten et al 2011, JAMES)

      if( myid.eq.0 ) print *
      if( myid.eq.0 ) print *,'  k,zf,w:'

      wmin  =  -0.005
      z1    =   2260.0

      do k=1,nk
        ! note:  wprof is on w levels (ie, full levels).   Use zf.
        if( zf(1,1,k).le.z1 )then
          wprof(k) = 0.0 + ( wmin - 0.0 )*(zf(1,1,k)-0.0)/(z1-0.0)
        else
          wprof(k) = wmin
        endif
        if( myid.eq.0 ) print *,k,zf(1,1,k),wprof(k)
      enddo
 
      thsfc  = -2.5 /( 3600.0 * 24.0 )

      do k=1,nk
        thfrc(k) = thsfc
      enddo

      if( myid.eq.0 ) print *
      if( myid.eq.0 ) print *,'  k,zh,thfrc,qvfrc '

      qv1    =    -1.0 / 1000.0 / ( 3600.0 * 24.0 )
      qv2    =  0.3456 / 1000.0 / ( 3600.0 * 24.0 )
      z1     =  2980.0

      do k=1,nk
        ! humidity tendency:
        if( zh(1,1,k).le.z1 )then
          qvfrc(k) = qv1 + ( qv2 - qv1 )*(zh(1,1,k)-0.0)/(z1-0.0)
        else
          qvfrc(k) = qv2
        endif
        if( myid.eq.0 ) print *,k,zh(1,1,k),thfrc(k)*3600.0*24.0,qvfrc(k)
      enddo


      if( myid.eq.0 ) print *
      if( myid.eq.0 ) print *,'  k,ug,vg '
      do k=1,nk
        ug(k) = u0(1,1,k)
        vg(k) = v0(1,1,k)
      enddo
      if( myid.eq.0 ) print *

    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase .eq. 9 .or. testcase.eq.14 )THEN


    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase.eq.11 )THEN
      ! SAS NCAR PBL intercomparison

!!!      ug = 2.0
!!!      vg = 0.0
      ug = u0(1,1,1)+umove
      vg = v0(1,1,1)+vmove

      do k=2,nk
        ! note:  wprof is on w levels (ie, full levels):   Use zf.
        wprof(k) = -9.0e-6 * zf(1,1,k)
      enddo

      ufrc = 0.0
      vfrc = 0.0
!!!      thfrc = 6.4e-4
!!!      qvfrc = 1.5e-4 / 2.5e6

      thfrc = 0.0
      qvfrc = 0.0
      wprof = 0.0

    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase.eq.12 )THEN

      ! Martinuzzi and Tropea (1993, JFE) wind tunnel case:

        ulspg = 36.0
        vlspg = 0.0

    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    IF( testcase.eq.13 )THEN

      ! UF Boundary Layer Wind Tunnel case:

      ! BLWT:
      if( isnd.ne.7 )then
        u0 = 18.0
        v0 =  0.0
        ug = 18.0
        vg =  0.0
      endif
      ulspg = 0.000545
      vlspg = 0.0

    ENDIF

    !-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-!

    do k=kb,ke
      ug(k) = ug(k) - umove
      vg(k) = vg(k) - vmove
    enddo


    ! boundary conditions:
    wprof(1) = 0.0
    wprof(nk+1) = 0.0


    if( lspgrad.eq.4 )then
    if( myid.eq.0 )then
      print *
      print *,'  zh,ulspg,vlspg = '
      do k=1,nk
        print *,k,zh(1,1,k),ulspg(k),vlspg(k)
      enddo
      print *
    endif
    endif

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      do k=1,nk
        thavg(k) = th0(1,1,k)
        pavg(k) = prs0(1,1,k)
      enddo

      if( imoist.eq.1 )then
        do k=1,nk
          qavg(k,nqv) = qv0(1,1,k)
        enddo
      endif


!---------------------------------------------------------------------

!  Print out base state

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,101)
      if(dowr) write(outfile,102)
      do k=1,nk
        if(dowr) write(outfile,103) k,zh(1,1,k),prs0(1,1,k),pi0(1,1,k),rho0(1,1,k)
      enddo
      if(dowr) write(outfile,*)

101   format(7x,'k      zh (m)    prs0 (Pa)        pi0        rho0 (kg/m^3)')
102   format(4x,'---------------------------------------------------------------------')
103   format(4x,i4,4x,f8.2,4x,f9.2,4x,f10.7,4x,f10.7)

!-----

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,104)
      if(dowr) write(outfile,102)
      do k=1,nk
        if(dowr) write(outfile,105) k,zh(1,1,k),th0(1,1,k),thv0(1,1,k),t0(1,1,k)
      enddo
      if(dowr) write(outfile,*)

104   format(7x,'k      zh (m)    th0 (K)     thv0 (K)     t0 (K) ')
105   format(4x,i4,4x,f8.2,4x,f8.4,4x,f8.4,4x,f8.4)

!-----

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,114)
      if(dowr) write(outfile,102)
      do k=2,nk
        if(dowr) write(outfile,115) k,zf(1,1,k),  &
                   -1000*(t0(1,1,k)-t0(1,1,k-1))*rdz*mf(1,1,k),  &
                    1.0e4*g*alog(thv0(1,1,k)/thv0(1,1,k-1))*rdz*mf(1,1,k)
      enddo
      if(dowr) write(outfile,*)

114   format(7x,'k      zf (m)     l.r. (K/km)     N^2')
115   format(4x,i4,4x,f8.2,4x,f10.4,4x,f8.4)

!-----
! Ri check ... warn user if Ri < 0.25, but do not stop model
! 061021: added N^2 check ... stop model if N^2 < 0

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,*) '  Richardson number:  NOTE!!!  Ri should be > 0.25 for most applications!'
      if(dowr) write(outfile,*)
      do k=2,nk
        nm = g*alog(thv0(1,1,k)/thv0(1,1,k-1))*rdz*mf(1,1,k)
        if(nm .lt. -1.0e-12)then
          if(dowr) write(outfile,*)
          if(dowr) write(outfile,*) '  k,zf,N^2:',k,zf(1,1,k),nm
          if(dowr) write(outfile,*)
          if(dowr) write(outfile,*) ' Warning.  N^2 (Brunt-Vaisala frequency squared) is less than zero!'
          if(dowr) write(outfile,*) ' This is really, really not recommended for the base state.'
!!!          if(dowr) write(outfile,*) ' Stopping model ....'
          if(dowr) write(outfile,*)
!!!          call stopcm1
        endif
        dudz = (u0(1,1,k)-u0(1,1,k-1))*rdz*mf(1,1,k)
        dvdz = (v0(1,1,k)-v0(1,1,k-1))*rdz*mf(1,1,k)
        rinum = nm/(1.0e-12+dudz*dudz+dvdz*dvdz)
        if(rinum.gt.0.25)then
          if(dowr) write(outfile,*) '  k,zf,Ri:',k,zf(1,1,k),rinum
        else
          if(dowr) write(outfile,*) '  k,zf,Ri:',k,zf(1,1,k),rinum,'<---- NOTE!  Ri < 0.25'
        endif
      enddo
      if(dowr) write(outfile,*)

!-----

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,106)
      if(dowr) write(outfile,102)
      do k=1,nk
        if(rh0(1,1,k).gt.0.999 .or. rh0(1,1,k).lt.0.0001 .or. imoist.eq.0)then
          tlcl=t0(1,1,k)
        else
          tlcl=55.0+(2840./(3.5*alog(t0(1,1,k))-    &
                   alog(0.01*prs0(1,1,k)*qv0(1,1,k)/(0.622+qv0(1,1,k)))-4.805))
        endif
        if(dowr) write(outfile,107) k,zh(1,1,k),                                 &
            th0(1,1,k)*exp((3376./tlcl-2.54)*qv0(1,1,k)*(1.0+0.81*qv0(1,1,k))),  &
            rh0(1,1,k),qv0(1,1,k)
      enddo
      if(dowr) write(outfile,*)

106   format(7x,'k      zh (m)      theta-e (K)       rh0          qv0 ')
107   format(4x,i4,4x,f8.2,4x,4x,f8.4,4x,f9.6,4x,f9.6)

!-----

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,126)
      if(dowr) write(outfile,102)
      do k=1,nk
        if(rh0(1,1,k).gt.0.999 .or. rh0(1,1,k).lt.0.0001 .or. imoist.eq.0)then
          tlcl=t0(1,1,k)
        else
          tlcl=55.0+(2840./(3.5*alog(t0(1,1,k))-    &
                   alog(0.01*prs0(1,1,k)*qv0(1,1,k)/(0.622+qv0(1,1,k)))-4.805))
        endif
        if(dowr) write(outfile,127) k,zh(1,1,k),qc0(1,1,k),qi0(1,1,k)
      enddo
      if(dowr) write(outfile,*)

126   format(7x,'k      zh (m)        qc0          qi0')
127   format(4x,i4,4x,f8.2,4x,f9.6,4x,f9.6)

!------------------------------------------------------------------
!  Get CAPE,CIN,etc:

  IF(imoist.eq.1)THEN

    allocate(  pfoo(nk+1) )
    allocate(  tfoo(nk+1) )
    allocate( qvfoo(nk+1) )

    pfoo(1) = psurf * 0.01
    tfoo(1) = tsurf - 273.15
   qvfoo(1) = max( qsurf , 1.0e-20 )

    do k=1,nk
      pfoo(k+1) = 0.01*prs0(1,1,k)
      tfoo(k+1) = t0(1,1,k) - 273.15
      qvfoo(k+1) = max( qv0(1,1,k) , 1.0e-20 )
    enddo

    if(dowr) write(outfile,*)
    if(dowr) write(outfile,*) '  Thermodynamic properties of base-state sounding:'
  IF(terrain_flag)THEN
    if(dowr) write(outfile,*) '    (for lower-left corner of domain:  i=1,j=1)  '
  ENDIF
    if(dowr) write(outfile,*)
    do n=1,3
      call getcape( n , nk+1 , pfoo , tfoo , qvfoo , cape , cin ,   &
                    zlcl, zlfc, zel , psource , tsource , qvsource )
      if(n.eq.1)then
        if(dowr) write(outfile,*) '    for surface parcel:'
      elseif(n.eq.2)then
        if(dowr) write(outfile,*) '    for most-unstable parcel:'
      elseif(n.eq.3)then
        if(dowr) write(outfile,*) '    for mixed-layer parcel:'
      endif
      if(dowr) write(outfile,116) 0.01*psource,tsource,1000.0*qvsource
      if(dowr) write(outfile,118) zlcl,zlfc,zel
      if(dowr) write(outfile,117) cape,cin
116   format('        source p(mb),T(K),qv(g/kg) = ',3(4x,f6.1))
118   format('        LCL,LFC,EL (m AGL)         = ',3(3x,f7.1))
117   format('        CAPE,CIN (J/kg)            = ',2(4x,f6.1))
      if(dowr) write(outfile,*)
    enddo
    if(dowr) write(outfile,*)

    deallocate(  pfoo )
    deallocate(  tfoo )
    deallocate( qvfoo )

  ENDIF

!------------------------------------------------------------------

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,108)
      if(dowr) write(outfile,102)
      do k=1,nk
        if(dowr) write(outfile,109) k,zh(1,1,k),u0(1,1,k),v0(1,1,k)
      enddo
      if(dowr) write(outfile,*)

108   format(7x,'k      zh (m)     u0 (m/s)     v0 (m/s)')
109   format(4x,i4,4x,f8.2,4x,f9.4,4x,f9.4)

!------------------------------------------------------------------

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          rth0(i,j,k)=1.0/th0(i,j,k)
        enddo
        enddo
        enddo

        do k=kbb2,kbe2
        do j=jbb2,jbe2
        do i=ibb2,ibe2
          thrd(i,j,k)=th0(i,j,k)
        enddo
        enddo
        enddo

!------------------------------------------------------------------

      pmin = 1.0e30

      do k=1,nk
      do j=1,nj
      do i=1,ni
        pmin = min( pmin , prs0(i,j,k) )
      enddo
      enddo
      enddo

#ifdef MPI
      call MPI_ALLREDUCE(mpi_in_place,pmin,1,MPI_REAL,MPI_MIN,MPI_COMM_WORLD,ierr)
#endif

!--------------------------------------------------------------

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,*) '  pmin = ',pmin
      if(dowr) write(outfile,*)
      if(dowr) write(outfile,*) '  psurf,tsurf  = ',psurf,tsurf
      if(dowr) write(outfile,*) '  qsurf,thsurf = ',qsurf,thsurf
      if(dowr) write(outfile,*)

      dothis = .false.
      IF( dothis )THEN
      IF( myid.eq.0 )THEN

        open(unit=21,file='input_sounding_grid')
        i = 1
        j = 1
        write(21,123) 0.01*psurf,thsurf,1000.0*qsurf
123     format(2x,f11.4,2x,f11.4,2x,f10.6)
124     format(2x,f11.4,2x,f11.4,2x,f10.6,2x,f11.4,2x,f11.4)
        do k=1,nk
          write(21,124) zh(i,j,k),th0(i,j,k),1000.0*qv0(i,j,k),u0(i,j,k),v0(i,j,k)
        enddo
          write(21,124) cgt1*zh(i,j,nk)+cgt2*zh(i,j,nk-1)+cgt3*zh(i,j,nk-2),     &
                        cgt1*th0(i,j,nk)+cgt2*th0(i,j,nk-1)+cgt3*th0(i,j,nk-2),  &
                1000.0*(cgt1*qv0(i,j,nk)+cgt2*qv0(i,j,nk-1)+cgt3*qv0(i,j,nk-2)), &
                        cgt1*u0(i,j,nk)+cgt2*u0(i,j,nk-1)+cgt3*u0(i,j,nk-2),     &
                        cgt1*v0(i,j,nk)+cgt2*v0(i,j,nk-1)+cgt3*v0(i,j,nk-2)
        close(unit=21)

      ENDIF
      ENDIF

!--------------------------------------------------------------

      dothis = .false.
      IF( dothis )THEN
      IF( myid.eq.0 )THEN

        open(unit=21,file='lsnudge_0001.dat')
        write(21,*) '*  Header:   lsnudge_time1 (s)   lsnudge_time2 (s)'
        write(21,*) '                    0.0                1.0e30 '
        write(21,*) '*  Profile.   Note: values will be ignored if nudging for that variable is off.'
        write(21,*) '*    z (m)   theta (K)    qv (g/kg)  u (m/s, grnd-reltv) v (m/s, grnd-reltv)'
        i = 1
        j = 1
!!!        write(21,123) 0.01*psurf,thsurf,1000.0*qsurf
        do k=1,nk
          write(21,124) zh(i,j,k),th0(i,j,k),1000.0*qv0(i,j,k),u0(i,j,k),v0(i,j,k)
        enddo
          write(21,124) cgt1*zh(i,j,nk)+cgt2*zh(i,j,nk-1)+cgt3*zh(i,j,nk-2),     &
                        cgt1*th0(i,j,nk)+cgt2*th0(i,j,nk-1)+cgt3*th0(i,j,nk-2),  &
                1000.0*(cgt1*qv0(i,j,nk)+cgt2*qv0(i,j,nk-1)+cgt3*qv0(i,j,nk-2)), &
                        cgt1*u0(i,j,nk)+cgt2*u0(i,j,nk-1)+cgt3*u0(i,j,nk-2),     &
                        cgt1*v0(i,j,nk)+cgt2*v0(i,j,nk-1)+cgt3*v0(i,j,nk-2)
        close(unit=21)

      ENDIF
      ENDIF

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      base_pbot = cgs1*prs0(1,1,1)+cgs2*prs0(1,1,2)+cgs3*prs0(1,1,3)
      base_ptop = cgt1*prs0(1,1,nk)+cgt2*prs0(1,1,nk-1)+cgt3*prs0(1,1,nk-2)

      base_pibot = cgs1*pi0(1,1,1)+cgs2*pi0(1,1,2)+cgs3*pi0(1,1,3)
      base_pitop = cgt1*pi0(1,1,nk)+cgt2*pi0(1,1,nk-1)+cgt3*pi0(1,1,nk-2)

      base_tbot = cgs1*t0(1,1,1)+cgs2*t0(1,1,2)+cgs3*t0(1,1,3)
      base_ttop = cgt1*t0(1,1,nk)+cgt2*t0(1,1,nk-1)+cgt3*t0(1,1,nk-2)

      base_thbot = cgs1*th0(1,1,1)+cgs2*th0(1,1,2)+cgs3*th0(1,1,3)
      base_thtop = cgt1*th0(1,1,nk)+cgt2*th0(1,1,nk-1)+cgt3*th0(1,1,nk-2)

      base_qvbot = cgs1*qv0(1,1,1)+cgs2*qv0(1,1,2)+cgs3*qv0(1,1,3)
      base_qvtop = cgt1*qv0(1,1,nk)+cgt2*qv0(1,1,nk-1)+cgt3*qv0(1,1,nk-2)

      if( myid.eq.0 )then
        print *
        print *,'  base_pbot, base_ptop  = ',base_pbot,base_ptop
        print *,'  base_pibot,base_pitop = ',base_pibot,base_pitop
        print *,'  base_tbot, base_ttop  = ',base_tbot,base_ttop
        print *,'  base_thbot,base_thtop = ',base_thbot,base_thtop
        print *,'  base_qvbot,base_qvtop = ',base_qvbot,base_qvtop
        print *
      endif

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      if(dowr) write(outfile,*) 'Leaving BASE'

      return

    !--------------------------------------------------------------

9008  print *
      print *,'  9008: error reading input_sounding file '
      print *,'    ... stopping cm1 ... '
      print *
      call stopcm1

9009  print *
      print *,'  9009: error opening input_sounding file '
      print *,'    ... stopping cm1 ... '
      print *
      call stopcm1

    !--------------------------------------------------------------

      return
      end subroutine base

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    real function getthe(ttype,p,t,qv,qt)
    use constants
    implicit none
    integer ttype
    real p,t,qv,qt

    ! Assumes air is saturated

    real :: pd,cpm,lhv

    getthe = 0.0

  IF(ttype.eq.1)THEN
    pd=p/(1.0+reps*qv)
    cpm=cp+cpl*qt
    lhv=lv1-lv2*t
    getthe=t*((p00/pd)**(rd/cpm))*exp(lhv*qv/(cpm*t))
  ELSEIF(ttype.eq.2)THEN
    getthe=t*( (p00/p)**(0.2854*(1.0-0.28*qv)) )   &
            *exp( ((3376.0/t)-2.54)*qv*(1.0+0.81*qv) )
  ENDIF
    end function getthe

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    subroutine revthe(ttype,the,p,qt,t,qv)
    use constants
    use cm1libs , only : rslf
    implicit none
    integer ttype
    real the,p,qt,rh,t,qv

    ! Assumes air is saturated
    ! Input:   the,p,qt  (t is first guess value upon input)
    ! Output:  t,qv

    integer n
    real tlast,tinc,pd,cpm,lhv,thx,diff

    n=1
    tlast=t
    tinc=0.0
250 continue
      t=tlast+tinc
      qv=rslf(p,t)
    IF(ttype.eq.1)THEN
      pd=p/(1.0+reps*qv)
      cpm=cp+cpl*qt
      lhv=lv1-lv2*t
      thx=t*((p00/pd)**(rd/cpm))*exp(lhv*qv/(cpm*t))
    ELSEIF(ttype.eq.2)THEN
      thx=t*( (p00/p)**(0.2854*(1.0-0.28*qv)) )   &
           *exp( ((3376.0/t)-2.54)*qv*(1.0+0.81*qv) )
    ENDIF

      diff=the-thx
      if(n.ge.40) print *,n,p,the,thx
      if(abs(diff).gt.0.0001 .and. n.lt.50)then
        n=n+1
        tinc=0.30*diff
        tlast=t
        if(abs(tinc).ge.0.0001) go to 250
      elseif(n.ge.50)then
        print *,'n exceeded 50!'
        print *,'n=',n
        print *,'  1222 '
        call stopcm1
      endif

    return
    end subroutine revthe

  END MODULE base_module

bc.F/           1744672191  3193  100   100644  64802     `
  MODULE bc_module

  implicit none

  CONTAINS

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine bc2d(s)
      use input
      implicit none

      real, dimension(ib:ie,jb:je) :: s

      integer i,j

!-----------------------------------------------------------------------
!  west boundary condition

#ifndef MPI
      if(wbc.eq.1)then
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=jb,je
        do i=1,ngxy
          s(1-i,j)=s(ni+1-i,j)
        enddo
        enddo
      elseif(wbc.eq.2)then
#else
      if(ibw.eq.1.and.wbc.eq.2)then
#endif
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=jb,je
        do i=1-ngxy,0
          s(i,j)=s(1,j)
        enddo
        enddo
#ifdef MPI
      elseif(ibw.eq.1.and.(wbc.eq.3.or.wbc.eq.4))then
#else
      elseif(wbc.eq.3.or.wbc.eq.4)then
#endif
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=jb,je
        do i=1,ngxy
          s(1-i,j)=s(i,j)
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  east boundary condition

#ifndef MPI
      if(ebc.eq.1)then
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=jb,je
        do i=1,ngxy
          s(ni+i,j)=s(i,j)
        enddo
        enddo
      elseif(ebc.eq.2)then
#else
      if(ibe.eq.1.and.ebc.eq.2)then
#endif
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=jb,je
        do i=ni+1,ni+ngxy
          s(i,j)=s(ni,j)
        enddo
        enddo
#ifdef MPI
      elseif(ibe.eq.1.and.(ebc.eq.3.or.ebc.eq.4))then
#else
      elseif(ebc.eq.3.or.ebc.eq.4)then
#endif
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=jb,je
        do i=1,ngxy
          s(ni+i,j)=s(ni+1-i,j)
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  south boundary condition

#ifndef MPI
      if(sbc.eq.1)then
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=1,ngxy
        do i=ib,ie
          s(i,1-j)=s(i,nj+1-j)
        enddo
        enddo
      elseif(sbc.eq.2)then
#else
      if(ibs.eq.1.and.sbc.eq.2)then
#endif
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=1-ngxy,0
        do i=ib,ie
          s(i,j)=s(i,1)
        enddo
        enddo
#ifdef MPI
      elseif(ibs.eq.1.and.(sbc.eq.3.or.sbc.eq.4))then
#else
      elseif(sbc.eq.3.or.sbc.eq.4)then
#endif
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=1,ngxy
        do i=ib,ie
          s(i,1-j)=s(i,j)
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  north boundary condition

#ifndef MPI
      if(nbc.eq.1)then
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=1,ngxy
        do i=ib,ie
          s(i,nj+j)=s(i,j)
        enddo
        enddo
      elseif(nbc.eq.2)then
#else
      if(ibn.eq.1.and.nbc.eq.2)then
#endif
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=nj+1,nj+ngxy
        do i=ib,ie
          s(i,j)=s(i,nj)
        enddo
        enddo
#ifdef MPI
      elseif(ibn.eq.1.and.(nbc.eq.3.or.nbc.eq.4))then
#else
      elseif(nbc.eq.3.or.nbc.eq.4)then
#endif
!$omp parallel do default(shared)  &
!$omp private(i,j)
        do j=1,ngxy
        do i=ib,ie
          s(i,nj+j)=s(i,nj+1-j)
        enddo
        enddo
      endif

!-----------------------------------------------------------------------

      if(timestats.ge.1) time_bc=time_bc+mytime()

      end subroutine bc2d


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine bcs(s)
      use input
      implicit none

      real, dimension(ib:ie,jb:je,kb:ke) :: s

      integer i,j,k

!-----------------------------------------------------------------------
!  west boundary condition

#ifndef MPI
      if(wbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=jb,je
        do i=1,ngxy
          s(1-i,j,k)=s(ni+1-i,j,k)
        enddo
        enddo
        enddo
      elseif(wbc.eq.2)then
#else
      if(ibw.eq.1.and.wbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+1
        do i=1-ngxy,0
          s(i,j,k)=s(1,j,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibw.eq.1.and.(wbc.eq.3.or.wbc.eq.4))then
#else
      elseif(wbc.eq.3.or.wbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+1
        do i=1,ngxy
          s(1-i,j,k)=s(i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  east boundary condition

#ifndef MPI
      if(ebc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=jb,je
        do i=1,ngxy
          s(ni+i,j,k)=s(i,j,k)
        enddo
        enddo
        enddo
      elseif(ebc.eq.2)then
#else
      if(ibe.eq.1.and.ebc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+1
        do i=ni+1,ni+ngxy
          s(i,j,k)=s(ni,j,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibe.eq.1.and.(ebc.eq.3.or.ebc.eq.4))then
#else
      elseif(ebc.eq.3.or.ebc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+1
        do i=1,ngxy
          s(ni+i,j,k)=s(ni+1-i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  south boundary condition

#ifndef MPI
      if(sbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=ib,ie
          s(i,1-j,k)=s(i,nj+1-j,k)
        enddo
        enddo
        enddo
      elseif(sbc.eq.2)then
#else
      if(ibs.eq.1.and.sbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1-ngxy,0
        do i=0,ni+1
          s(i,j,k)=s(i,1,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibs.eq.1.and.(sbc.eq.3.or.sbc.eq.4))then
#else
      elseif(sbc.eq.3.or.sbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=0,ni+1
          s(i,1-j,k)=s(i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  north boundary condition

#ifndef MPI
      if(nbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=ib,ie
          s(i,nj+j,k)=s(i,j,k)
        enddo
        enddo
        enddo
      elseif(nbc.eq.2)then
#else
      if(ibn.eq.1.and.nbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=nj+1,nj+ngxy
        do i=0,ni+1
          s(i,j,k)=s(i,nj,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibn.eq.1.and.(nbc.eq.3.or.nbc.eq.4))then
#else
      elseif(nbc.eq.3.or.nbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=0,ni+1
          s(i,nj+j,k)=s(i,nj+1-j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------

      if(timestats.ge.1) time_bc=time_bc+mytime()

      end subroutine bcs


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine bcp(p)
      use input
      implicit none

      real, dimension(ib:ie,jb:je,kb:ke) :: p

      integer i,j,k

!-----------------------------------------------------------------------
!  west boundary condition

#ifndef MPI
      if(wbc.eq.1)then
        !$omp parallel do default(shared) private(j,k)
        do k=1,nk
        do j=0,nj+1
          p(0,j,k)=p(ni,j,k)
        enddo
        enddo
      elseif(wbc.eq.2)then
#else
      if(ibw.eq.1.and.wbc.eq.2)then
#endif
        !$omp parallel do default(shared) private(j,k)
        do k=1,nk
        do j=0,nj+1
          p(0,j,k)=p(1,j,k)
        enddo
        enddo
#ifdef MPI
      elseif(ibw.eq.1.and.(wbc.eq.3.or.wbc.eq.4))then
#else
      elseif(wbc.eq.3.or.wbc.eq.4)then
#endif
        !$omp parallel do default(shared) private(j,k)
        do k=1,nk
        do j=0,nj+1
          p(0,j,k)=p(1,j,k)
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  east boundary condition

#ifndef MPI
      if(ebc.eq.1)then
        !$omp parallel do default(shared) private(j,k)
        do k=1,nk
        do j=0,nj+1
          p(ni+1,j,k)=p(1,j,k)
        enddo
        enddo
      elseif(ebc.eq.2)then
#else
      if(ibe.eq.1.and.ebc.eq.2)then
#endif
        !$omp parallel do default(shared) private(j,k)
        do k=1,nk
        do j=0,nj+1
          p(ni+1,j,k)=p(ni,j,k)
        enddo
        enddo
#ifdef MPI
      elseif(ibe.eq.1.and.(ebc.eq.3.or.ebc.eq.4))then
#else
      elseif(ebc.eq.3.or.ebc.eq.4)then
#endif
        !$omp parallel do default(shared) private(j,k)
        do k=1,nk
        do j=0,nj+1
          p(ni+1,j,k)=p(ni,j,k)
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  south boundary condition

#ifndef MPI
      if(sbc.eq.1)then
        !$omp parallel do default(shared) private(i,k)
        do k=1,nk
        do i=0,ni+1
          p(i,0,k)=p(i,nj,k)
        enddo
        enddo
      elseif(sbc.eq.2)then
#else
      if(ibs.eq.1.and.sbc.eq.2)then
#endif
        !$omp parallel do default(shared) private(i,k)
        do k=1,nk
        do i=0,ni+1
          p(i,0,k)=p(i,1,k)
        enddo
        enddo
#ifdef MPI
      elseif(ibs.eq.1.and.(sbc.eq.3.or.sbc.eq.4))then
#else
      elseif(sbc.eq.3.or.sbc.eq.4)then
#endif
        !$omp parallel do default(shared) private(i,k)
        do k=1,nk
        do i=0,ni+1
          p(i,0,k)=p(i,1,k)
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  north boundary condition

#ifndef MPI
      if(nbc.eq.1)then
        !$omp parallel do default(shared) private(i,k)
        do k=1,nk
        do i=0,ni+1
          p(i,nj+1,k)=p(i,1,k)
        enddo
        enddo
      elseif(nbc.eq.2)then
#else
      if(ibn.eq.1.and.nbc.eq.2)then
#endif
        !$omp parallel do default(shared) private(i,k)
        do k=1,nk
        do i=0,ni+1
          p(i,nj+1,k)=p(i,nj,k)
        enddo
        enddo
#ifdef MPI
      elseif(ibn.eq.1.and.(nbc.eq.3.or.nbc.eq.4))then
#else
      elseif(nbc.eq.3.or.nbc.eq.4)then
#endif
        !$omp parallel do default(shared) private(i,k)
        do k=1,nk
        do i=0,ni+1
          p(i,nj+1,k)=p(i,nj,k)
        enddo
        enddo
      endif

!-----------------------------------------------------------------------

      if(timestats.ge.1) time_bc=time_bc+mytime()

      end subroutine bcp


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine bcu(u)
      use input
      implicit none

      real, dimension(ib:ie+1,jb:je,kb:ke) :: u

      integer i,j,k  

!-----------------------------------------------------------------------
!  west boundary condition

#ifndef MPI
      if(wbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=jb,je
        do i=1,ngxy
          u(1-i,j,k)=u(ni+1-i,j,k)
        enddo
        enddo
        enddo
      elseif(wbc.eq.2)then
#else
      if(ibw.eq.1.and.wbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+1
        do i=1-ngxy,0
          u(i,j,k)=u(1,j,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibw.eq.1.and.(wbc.eq.3.or.wbc.eq.4))then
#else
      elseif(wbc.eq.3.or.wbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+1
          u(1,j,k)=0.
        do i=1,ngxy
          u(1-i,j,k)=-u(1+i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  east boundary condition

#ifndef MPI
      if(ebc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=jb,je
        do i=1,ngxy
          u(ni+1+i,j,k)=u(1+i,j,k)
        enddo
        enddo
        enddo
      elseif(ebc.eq.2)then
#else
      if(ibe.eq.1.and.ebc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+1
        do i=ni+2,ni+1+ngxy
          u(i,j,k)=u(ni+1,j,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibe.eq.1.and.(ebc.eq.3.or.ebc.eq.4))then
#else
      elseif(ebc.eq.3.or.ebc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+1
          u(ni+1,j,k)=0.0
        do i=1,ngxy
          u(ni+1+i,j,k)=-u(ni+1-i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  south boundary condition

#ifndef MPI
      if(sbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=ib,ie+1
          u(i,1-j,k)=u(i,nj+1-j,k)
        enddo
        enddo
        enddo
      elseif(sbc.eq.2)then
#else
      if(ibs.eq.1.and.sbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1-ngxy,0
        do i=0,ni+2
          u(i,j,k)=u(i,1,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibs.eq.1.and.(sbc.eq.3.or.sbc.eq.4))then
#else
      elseif(sbc.eq.3.or.sbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=0,ni+2
          u(i,1-j,k)=u(i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  north boundary condition

#ifndef MPI
      if(nbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=ib,ie+1
          u(i,nj+j,k)=u(i,j,k)
        enddo
        enddo
        enddo
      elseif(nbc.eq.2)then
#else
      if(ibn.eq.1.and.nbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=nj+1,nj+ngxy
        do i=0,ni+2
          u(i,j,k)=u(i,nj,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibn.eq.1.and.(nbc.eq.3.or.nbc.eq.4))then
#else
      elseif(nbc.eq.3.or.nbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=0,ni+2
          u(i,nj+j,k)=u(i,nj+1-j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------

      if(timestats.ge.1) time_bc=time_bc+mytime()
 
      end subroutine bcu


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine bcv(v)
      use input
      implicit none

      real, dimension(ib:ie,jb:je+1,kb:ke) :: v
 
      integer i,j,k

!-----------------------------------------------------------------------
!  south boundary condition

#ifndef MPI
      if(sbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=ib,ie
          v(i,1-j,k)=v(i,nj+1-j,k)
        enddo
        enddo
        enddo
      elseif(sbc.eq.2)then
#else
      if(ibs.eq.1.and.sbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1-ngxy,0
        do i=0,ni+1
          v(i,j,k)=v(i,1,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibs.eq.1.and.(sbc.eq.3.or.sbc.eq.4))then
#else
      elseif(sbc.eq.3.or.sbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=0,ni+1
          v(i,1-j,k)=-v(i,j+1,k)
        enddo
        enddo
        do i=0,ni+1
          v(i,   1,k)=0.
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  north boundary condition

      IF(axisymm.eq.1)THEN
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do i=ib,ie
          v(i,2,k)=v(i,1,k)
        enddo
        enddo
      ENDIF

#ifndef MPI
      if(nbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=ib,ie
          v(i,nj+1+j,k)=v(i,1+j,k)
        enddo
        enddo
        enddo
      elseif(nbc.eq.2)then
#else
      if(ibn.eq.1.and.nbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=nj+2,nj+1+ngxy
        do i=0,ni+1
          v(i,j,k)=v(i,nj+1,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibn.eq.1.and.(nbc.eq.3.or.nbc.eq.4))then
#else
      elseif(nbc.eq.3.or.nbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,ngxy
        do i=0,ni+1
          v(i,nj+1+j,k)=-v(i,nj+1-j,k)
        enddo
        enddo
        do i=0,ni+1
          v(i,nj+1,k)=0.
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  west boundary condition

#ifndef MPI
      if(wbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=jb,je+1
        do i=1,ngxy
          v(1-i,j,k)=v(ni+1-i,j,k)
        enddo
        enddo
        enddo
      elseif(wbc.eq.2)then
#else
      if(ibw.eq.1.and.wbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+2
        do i=1-ngxy,0
          v(i,j,k)=v(1,j,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibw.eq.1.and.(wbc.eq.3.or.wbc.eq.4))then
#else
      elseif(wbc.eq.3.or.wbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+2
        do i=1,ngxy
          v(1-i,j,k)=v(i,j,k)
        enddo
        enddo
        enddo
      endif

      IF(axisymm.eq.1)THEN
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+2
        do i=1,ngxy
          v(1-i,j,k) = -v(i,j,k)
        enddo
        enddo
        enddo
      ENDIF

!-----------------------------------------------------------------------
!  east boundary condition

#ifndef MPI
      if(ebc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=jb,je+1
        do i=1,ngxy
          v(ni+i,j,k)=v(i,j,k)
        enddo
        enddo
        enddo
      elseif(ebc.eq.2)then
#else
      if(ibe.eq.1.and.ebc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+2
        do i=ni+1,ni+ngxy
          v(i,j,k)=v(ni,j,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibe.eq.1.and.(ebc.eq.3.or.ebc.eq.4))then
#else
      elseif(ebc.eq.3.or.ebc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=0,nj+2
        do i=1,ngxy
          v(ni+i,j,k)=v(ni+1-i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------

      if(timestats.ge.1) time_bc=time_bc+mytime()
 
      end subroutine bcv


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine bcw(w,flag)
      use input
      implicit none

      real, dimension(ib:ie,jb:je,kb:ke+1) :: w
      integer flag
 
      integer i,j,k

!-----------------------------------------------------------------------
!  west boundary condition
 
#ifndef MPI
      if(wbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=jb,je
        do i=1,ngxy
          w(1-i,j,k)=w(ni+1-i,j,k)
        enddo
        enddo
        enddo
      elseif(wbc.eq.2)then
#else
      if(ibw.eq.1.and.wbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=0,nj+1
        do i=1-ngxy,0
          w(i,j,k)=w(1,j,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibw.eq.1.and.(wbc.eq.3.or.wbc.eq.4))then
#else
      elseif(wbc.eq.3.or.wbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=0,nj+1
        do i=1,ngxy
          w(1-i,j,k)=w(i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  east boundary condition

#ifndef MPI
      if(ebc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=jb,je
        do i=1,ngxy
          w(ni+i,j,k)=w(i,j,k)
        enddo
        enddo
        enddo
      elseif(ebc.eq.2)then
#else
      if(ibe.eq.1.and.ebc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=0,nj+1
        do i=ni+1,ni+ngxy
          w(i,j,k)=w(ni,j,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibe.eq.1.and.(ebc.eq.3.or.ebc.eq.4))then
#else
      elseif(ebc.eq.3.or.ebc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=0,nj+1
        do i=1,ngxy
          w(ni+i,j,k)=w(ni+1-i,j,k)
        enddo
        enddo
        enddo 
      endif

!-----------------------------------------------------------------------
!  south boundary condition

#ifndef MPI
      if(sbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=1,ngxy
        do i=ib,ie
          w(i,1-j,k)=w(i,nj+1-j,k)
        enddo
        enddo
        enddo
      elseif(sbc.eq.2)then
#else
      if(ibs.eq.1.and.sbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=1-ngxy,0
        do i=0,ni+1
          w(i,j,k)=w(i,1,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibs.eq.1.and.(sbc.eq.3.or.sbc.eq.4))then
#else
      elseif(sbc.eq.3.or.sbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=1,ngxy
        do i=0,ni+1
          w(i,1-j,k)=w(i,j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  north boundary condition

#ifndef MPI
      if(nbc.eq.1)then
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=1,ngxy
        do i=ib,ie
          w(i,nj+j,k)=w(i,j,k)
        enddo
        enddo
        enddo
      elseif(nbc.eq.2)then
#else
      if(ibn.eq.1.and.nbc.eq.2)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=nj+1,nj+ngxy
        do i=0,ni+1
          w(i,j,k)=w(i,nj,k)
        enddo
        enddo
        enddo
#ifdef MPI
      elseif(ibn.eq.1.and.(nbc.eq.3.or.nbc.eq.4))then
#else
      elseif(nbc.eq.3.or.nbc.eq.4)then
#endif
        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=2,nk
        do j=1,ngxy
        do i=0,ni+1
          w(i,nj+j,k)=w(i,nj+1-j,k)
        enddo
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  top/bottom boundary condition

    IF(flag.eq.1)THEN

      !$omp parallel do default(shared)  &
      !$omp private(i,j)
      do j=0,nj+1
      do i=0,ni+1
        w(i,j, 1)=0.0
        w(i,j,nk+1)=0.0
      enddo
      enddo

    ENDIF

!-----------------------------------------------------------------------

      if(timestats.ge.1) time_bc=time_bc+mytime()
 
      end subroutine bcw


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine bcwsfc(gz,dzdx,dzdy,u,v,w)
      use input
      implicit none

      real, intent(in), dimension(itb:ite,jtb:jte) :: gz
      real, intent(in), dimension(itb:ite,jtb:jte) :: dzdx,dzdy
      real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: u
      real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: v
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: w

      integer :: i,j

!-----------------------------------------------------------------------

!$omp parallel do default(shared)  &
!$omp private(i,j)
      do j=0,nj+1
      do i=0,ni+1
        w(i,j,1) = 0.5*( ( u(i,j,1)+u(i+1,j,1) )*dzdx(i,j) &
                        +( v(i,j,1)+v(i,j+1,1) )*dzdy(i,j) )*gz(i,j)
      enddo
      enddo

!-----------------------------------------------------------------------

      if(timestats.ge.1) time_bc=time_bc+mytime()

      end subroutine bcwsfc


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine extrapbcs(s)
      use input
      implicit none

      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: s

      integer :: i,j

      ! cm1r18 extrapolation formulation:
      ! assumes zh(0) is same as zf(1), and zh(nk+1) is same as zf(nk+1)

!$omp parallel do default(shared)   &
!$omp private(i,j)
      do j=jb,je
      do i=ib,ie
        s(i,j,0)    = cgs1*s(i,j,1)+cgs2*s(i,j,2)+cgs3*s(i,j,3)
        s(i,j,nk+1) = cgt1*s(i,j,nk)+cgt2*s(i,j,nk-1)+cgt3*s(i,j,nk-2)
      enddo
      enddo

      end subroutine extrapbcs


#ifdef MPI
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine bcs2(s)
      use input
