      allocate(   zf(ib:ie,jb:je,kb:ke+1) )
      zf = 0.0

      allocate( dtu(ib:ie,jb:je) )
      dtu = 1.0
      allocate( dtu0(ib:ie,jb:je) )
      dtu0 = 1.0
      allocate( dtv(ib:ie,jb:je) )
      dtv = 1.0
      allocate( dtv0(ib:ie,jb:je) )
      dtv0 = 1.0

!------
! allocate the MPI arrays

#ifdef MPI
      imp = max(1,ni)
      jmp = max(1,nj)
      kmp = max(2,nk)
      kmt = max(2,nk+1)
      rmp = 8
      cmp = ngxy
#else
      imp = 1
      jmp = 1
      kmp = 2
      kmt = 2
      rmp = 1
      cmp = 1
#endif

      allocate( reqs_u(rmp) )
      reqs_u = 0
