      allocate( p2e1(jmp,kmp) )
      p2e1 = 0.0
      allocate( p2e2(jmp,kmp) )
      p2e2 = 0.0
      allocate( p2s1(imp,kmp) )
      p2s1 = 0.0
      allocate( p2s2(imp,kmp) )
      p2s2 = 0.0
      allocate( p2n1(imp,kmp) )
