      allocate( p3w1(jmp,kmp) )
      p3w1 = 0.0
      allocate( p3w2(jmp,kmp) )
      p3w2 = 0.0
      allocate( p3e1(jmp,kmp) )
      p3e1 = 0.0
      allocate( p3e2(jmp,kmp) )
      p3e2 = 0.0
      allocate( p3s1(imp,kmp) )
