      subroutine satadj_ice(nrk,dt,tcond,tevac,ruh,rvh,rmh,pi0,th0,   &
                            rho,rr,pp3d,prs,th3d,                  &
                            qv3d,qc3d,qr3d,                        &
                            qi3d,qs3d,qg3d)
      use input
      use constants
    use cm1libs , only : rslf,rsif
#ifdef MPI
      use mpi
#endif
      implicit none

      integer nrk
      real, intent(in) :: dt
      double precision :: tcond,tevac
      real, dimension(ib:ie) :: ruh
      real, dimension(jb:je) :: rvh
      real, dimension(ib:ie,jb:je,kb:ke) :: rmh,pi0,th0
      real, dimension(ib:ie,jb:je,kb:ke) :: rho,rr,pp3d,prs,th3d
      real, dimension(ibm:iem,jbm:jem,kbm:kem) :: qv3d,qc3d,qr3d
      real, dimension(ibi:iei,jbi:jei,kbi:kei) :: qi3d,qs3d,qg3d

      integer :: i,j,k,n,nmax,omax,iflag
      real :: tnew,pnew,qvs,qvnew,qcnew,qinew,cvml,rm,lhv,lhs
      real :: fliq,fice,tem,tlast,dqv,qsw,qsi,cnd,dep,term1,term2
      real :: converge,t1,t2,dum,rdt
      double precision :: tem6
      double precision, dimension(nk) :: bud1,bud2
      logical :: doit

!--------------------------------------------------------------------
!  iterative sat adj.

    nmax=0
    iflag=0

    IF(eqtset.eq.2)THEN

      if(nrk.eq.4)then
!!!        converge=0.0005
        converge=2.0*tsmall
      else
!!!        converge=0.01
        converge=20.0*tsmall
      endif

      rdt = 1.0/dt

!$omp parallel do default(shared)  &
!$omp private(i,j,k,n,tnew,pnew,qvs,qvnew,qcnew,qinew,cvml,rm,   &
!$omp lhv,lhs,fliq,fice,tem,tlast,dqv,qsw,qsi,cnd,dep,term1,term2,      &
!$omp t1,t2,dum,doit)
      do k=1,nk
      bud1(k)=0.0d0
      bud2(k)=0.0d0
      do j=1,nj
      do i=1,ni

        tnew=(th0(i,j,k)+th3d(i,j,k))*(pi0(i,j,k)+pp3d(i,j,k))
        fliq=max(min((tnew-t00k)*rt0,1.0),0.0)
        fice=1.0-fliq
        qsw=0.0
        if(tnew.gt.t00k)then
          qsw=fliq*rslf(prs(i,j,k),tnew)
        endif
        qsi=0.0
        if(tnew.lt.t0k)then
          qsi=fice*rsif(prs(i,j,k),tnew)
        endif
        qvs=qsw+qsi

        IF(qc3d(i,j,k).gt.1.0e-12 .or. qi3d(i,j,k).gt.1.0e-12     &
           .or. qv3d(i,j,k).gt.qvs)THEN

          qvnew=qv3d(i,j,k)
          qcnew=qc3d(i,j,k)
          qinew=qi3d(i,j,k)

          tem=cpl*(qc3d(i,j,k)+qr3d(i,j,k))               &
             +cpi*(qi3d(i,j,k)+qs3d(i,j,k)+qg3d(i,j,k))
          cvml=cv+cvv*qv3d(i,j,k)+tem
          lhv=lv1-lv2*tnew
          lhs=ls1-ls2*tnew

          t1=1.0/cvml
          t2=rv*tnew/cvml

          n=0
          tlast=tnew
          doit=.true.

          do while( doit )
            n=n+1
            term1=0.0
            if(tnew.gt.t00k)then
              term1=qsw*(fliq*C409/((tnew-C358)**2))
            endif
            term2=0.0
            if(tnew.lt.t0k)then
              term2=qsi*(fice*C580/((tnew-C76)**2))
            endif
            dqv=(qvs-qvnew)/(1.0+((lhv*fliq+lhs*fice)*t1-t2)*(term1+term2) )
            dqv=min(dqv,qcnew+qinew)
            if( (dqv*qcnew.gt.0.0.and.qinew.eq.0.0) .or.   &
                (dqv*qinew.gt.0.0.and.qcnew.eq.0.0) )then
              fliq=qcnew/(qcnew+qinew)
              fice=1.0-fliq
            endif
            if(  (qvnew+dqv).lt.1.0e-20 ) dqv=1.0e-20-qvnew
            cnd=min(fliq*dqv,qcnew)
            dep=min(fice*dqv,qinew)
            dqv=cnd+dep

            qvnew=qvnew+dqv
            qcnew=max(qcnew-cnd,0.0)
            qinew=max(qinew-dep,0.0)

            tnew=tnew-( (lhv*cnd+lhs*dep)*t1 - dqv*t2 )
            pnew=rho(i,j,k)*(rd+rv*qvnew)*tnew

            doit = .false.
            if( abs(tnew-tlast).gt.converge )then
              tlast=tnew
              fliq=max(min((tnew-t00k)*rt0,1.0),0.0)
              fice=1.0-fliq
              qsw=0.0
              if(tnew.gt.t00k)then
                qsw=fliq*rslf(prs(i,j,k),tnew)
              endif
              qsi=0.0
              if(tnew.lt.t0k)then
                qsi=fice*rsif(prs(i,j,k),tnew)
              endif
              qvs=qsw+qsi
              doit = .true.
            endif

            if(n.gt.50) print *,'  satadj_ice:',myid,n,tnew,pnew
            if(n.eq.100)then
              print *,'  infinite loop!'
              print *,'  i,j,k=',i,j,k
              iflag=1
              doit=.false.
            endif

          enddo

          dum=ruh(i)*rvh(j)*rmh(i,j,k)

          bud1(k)=bud1(k)+rr(i,j,k)*max(qcnew-qc3d(i,j,k),0.0)*dum
          bud1(k)=bud1(k)+rr(i,j,k)*max(qinew-qi3d(i,j,k),0.0)*dum
          bud2(k)=bud2(k)-rr(i,j,k)*min(qcnew-qc3d(i,j,k),0.0)*dum
          bud2(k)=bud2(k)-rr(i,j,k)*min(qinew-qi3d(i,j,k),0.0)*dum
          
          prs(i,j,k) = pnew
          pp3d(i,j,k) = (pnew*rp00)**rovcp - pi0(i,j,k)
          th3d(i,j,k) = tnew/(pi0(i,j,k)+pp3d(i,j,k))-th0(i,j,k)
          qc3d(i,j,k)=qcnew
          qv3d(i,j,k)=qvnew
          qi3d(i,j,k)=qinew
          
          nmax=max(n,nmax)

        ENDIF

      enddo
      enddo
      enddo

    ELSE

      nmax=1

!$omp parallel do default(shared)  &
!$omp private(i,j,k,qvnew,qcnew,qinew,tnew,fliq,fice,qvs,lhv,lhs,dqv,   &
!$omp qsw,qsi,cnd,dep,term1,term2,dum,rm)
      do k=1,nk
      bud1(k)=0.0d0
      bud2(k)=0.0d0
      do j=1,nj
      do i=1,ni

        qvnew=qv3d(i,j,k)
        qcnew=qc3d(i,j,k)
        qinew=qi3d(i,j,k)
        tnew=(th0(i,j,k)+th3d(i,j,k))*(pi0(i,j,k)+pp3d(i,j,k))
        fliq=max(min((tnew-t00k)*rt0,1.0),0.0)
        fice=1.0-fliq
        qsw=0.0
        term1=0.0
        if(tnew.gt.t00k)then
          qsw=fliq*rslf(prs(i,j,k),tnew)
          term1=qsw*(fliq*C409/((tnew-C358)**2))
        endif
        qsi=0.0
        term2=0.0
        if(tnew.lt.t0k)then
          qsi=fice*rsif(prs(i,j,k),tnew)
          term2=qsi*(fice*C580/((tnew-C76)**2))
        endif
        qvs=qsw+qsi
        lhv=lv1-lv2*tnew
        lhs=ls1-ls2*tnew
        dqv=(qvs-qvnew)/(1.0+(lhv*fliq+lhs*fice)*(term1+term2)*rcp)
        dqv=min(dqv,qcnew+qinew)
        if( (dqv*qcnew.gt.0.0.and.qinew.eq.0.0) .or.   &
            (dqv*qinew.gt.0.0.and.qcnew.eq.0.0) )then
          fliq=qcnew/(qcnew+qinew)
          fice=qinew/(qcnew+qinew)
        endif
        if(  (qvnew+dqv).lt.1.0e-20 ) dqv=1.0e-20-qvnew
        cnd=min(fliq*dqv,qcnew)
        dep=min(fice*dqv,qinew)

        qvnew=qvnew+cnd+dep
        qcnew=qcnew-cnd
        qinew=qinew-dep

        dum=ruh(i)*rvh(j)*rmh(i,j,k)

        bud1(k)=bud1(k)+rr(i,j,k)*max(qcnew-qc3d(i,j,k),0.0)*dum
        bud1(k)=bud1(k)+rr(i,j,k)*max(qinew-qi3d(i,j,k),0.0)*dum
        bud2(k)=bud2(k)-rr(i,j,k)*min(qcnew-qc3d(i,j,k),0.0)*dum
        bud2(k)=bud2(k)-rr(i,j,k)*min(qinew-qi3d(i,j,k),0.0)*dum

        th3d(i,j,k)=th3d(i,j,k)-( (lhv*cnd+lhs*dep)   &
                                 /(cp*(pi0(i,j,k)+pp3d(i,j,k))) )
        qc3d(i,j,k)=qcnew
        qv3d(i,j,k)=qvnew
        qi3d(i,j,k)=qinew
        rho(i,j,k)=prs(i,j,k)   &
           /(rd*(th0(i,j,k)+th3d(i,j,k))*(pi0(i,j,k)+pp3d(i,j,k))*(1.0+qvnew*reps))

      enddo
      enddo
      enddo

    ENDIF

    IF(nrk.ge.nrkmax)THEN
      tem6=dx*dy*dz
      do k=1,nk
        tcond=tcond+bud1(k)*tem6
      enddo

      do k=1,nk
        tevac=tevac+bud2(k)*tem6
      enddo
    ENDIF

!!!#ifdef MPI
!!!      omax=0
!!!      call MPI_REDUCE(nmax,omax,1,MPI_INTEGER,MPI_MAX,0,MPI_COMM_WORLD,ierr)
!!!      nmax=omax
!!!#endif
!!!

      if(iflag.ne.0)then
        print *
        print *,' Convergence cannot be reached in satadj_ice subroutine.'
        print *
        print *,' This may be a problem with the algorithm in satadj_ice.'
        print *,' However, the model may have became unstable somewhere'
        print *,' else and the symptoms first appeared here.'
        print *
        print *,' Try decreasing the timestep.'
        print *
        print *,'  ... stopping cm1 ... '
        print *
        call stopcm1
      endif

      if(timestats.ge.1) time_satadj=time_satadj+mytime()

      END subroutine satadj_ice


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine goddard(dt,tauto,taccr,tevar,ruh,rvh,rmh,pi0,th0,   &
                         rhod,rr,prs,pp3d,th3d,                   &
                         qv3d,qc3d,qr3d,vtr,                      &
                         qi3d,vti,qs3d,vts,                       &
                         qg3d,vtg)
      use input
      use constants
      implicit none

      real :: dt
      double precision :: tauto,taccr,tevar
      real, dimension(ib:ie) :: ruh
      real, dimension(jb:je) :: rvh
      real, dimension(ib:ie,jb:je,kb:ke) :: rmh,pi0,th0
      real, dimension(ib:ie,jb:je,kb:ke) :: rhod,rr,prs,pp3d,th3d,qv3d,qc3d,   &
                                            qr3d,vtr,qi3d,vti,qs3d,vts,qg3d,vtg

!----------------------------------------------------------------------------
!                                                                       
!***********************************************************************
!     LIN ET AL (83) ICE PHASE MICROPHYSICAL PROCESSES                 *
!     MODIFIED AND CODED BY GODDARD CUMULUS ENSEMBLE MODELING GROUP    *
!     TAO, SIMPSON AND MCCUMBER`S SATURATION TECHNIQUE (MWR, 1989)     *
!     TAO AND SIMPSON (JAS, 1989; TAO, 1993),                          *
!     BRAUN AND TAO (MWR, 2000), BRAUN ET AL. (JAM, 2001, submitted)   *
!                                                                      *
!     D2T - LEAPFROG TIME STEP (S)                                     *
!     DPT - DEVIATION POTENTIAL TEMPERATURE FIELD (K)                  *
!     DQV - DEVIATION WATER VAPOR FIELD (G/G)                          *
!     QCL - CLOUD WATER FIELD (G/G)                                    *
!     QRN - RAIN FIELD (G/G)                                           *
!     QCI - CLOUD ICE FIELD (G/G)                                      *
!     QCS - SNOW FIELD (G/G)                                           *
!     QCG - HAIL FIELD (G/G)                                           *
!     RHO - AIR DENSITY (G/CM3)                                        *
!     TA1 - BASE AIR POTENTIAL TEMPERATURE AT THE LEVEL (K)            *
!     QA1 - BASE WATER VAPOR AT THE LEVEL (G/G)                        *
!     P0 - AIR PRESSURE (UB=1.E-3MB)                                   *
!     PI - EXNER FUNCTION (P/1000.E3)**R/CP                            *
!                                                                      *
!     MIX: DIMENSION IN X-DIRECTION                                    *
!     MKX: DIMENSION IN Z-DIRECTION                                    *
!     NOTE: PHYSICAL DOMAIN EXTENDS FROM K=1 TO K=MKX-1                *
!           AND I=2 TO I=MIX-1                                         *
!     C.G.S UNITS                                                      *
!                                                                      *
!     THIS ICE SCHEME HAS BEEN IMPLEMENTED INTO                        *
!     ARPS (CAPS - V. WONG, M. XUE, K. DROEGEMEIER) - 1993             *
!     GODDARD`S SCHLENSINGER MODEL (SIMPSON ET AL., 1991)              *
!     CHEN`S MODEL (C. CHEN) - 1992                                    *
!     GMASS (BIAK ET AL., 1992)                                        *
!     MM5V1 (LIU ET AL., 1994)                                         *
!                                                                      *
!     RECENT CHANGES (6.25.01) BY SCOTT BRAUN INCLUDE                  *
!       * OPTION TO CHOOSE HAIL OR GRAUPEL AS THIRD ICE CATEGORY       *
!	* OPTION OF SATURATION ADJUSTMENT SCHEMES                      *      
!	* NEW FORMULATION OF PSFI                                      *      
!	* REDUCED COLLECTION EFFICIENCIES (EGS) FOR COLLECTION OF SNOW *      
!	  BY GRAUPEL                                                   *      
!	* MODIFICATIONS TO PIDEP, PINT INCLUDING NEW COEFFICIENTS FOR  *      
!	  THE FLETCHER EQ., A LIMIT OF 1 CM**-3 FOR THE NUMBER         *      
!         CONCENTRATION OF ICE NUCLEI, INCLUSION OF A PISUB TERM       *
!	* ELIMINATED THE PGAUT TERM                                    *      
!***********************************************************************
!                                                                       
!     THE FOLLOWINGS ARE LOCALLY USED VARIABLES                         
!                                                                       
      real d2t,VFR,VFS,VFG
      real RHO,P0,PPI,rho0
      integer i,j,k
      real COL,DEP,RGMP,DD,DD1,QVS,DM,RSUB1,WGACR,CND,RQ,             &
       ERN,SCV,TCA,DWV,ZR,VR,ZS,VS,ZG,VG,EGS,ESI,                     &
       QSI,SSI,QSW,SSW,PIHOM,PIDW,PIMLT,PSAUT,PSACI,PSACW,QSACW,      &
       PRACI,PIACR,PRAUT,PRACW,PSFW,PSFI,DGACS,DGACW,DGACI,DGACR,     &
       PGACS,WGACS,QGACW,WGACI,QGACR,PGWET,PGAUT,PRACS,PSACR,QSACR,   &
       PGFR,PSMLT,PGMLT,PSDEP,PSSUB,PGSUB,PINT,PIDEP,PISUB,           &
       PT,QV,QC,QR,QI,QS,QG,TAIR,TAIRC,PR,PS,PG,PRN,                  &
       PSN,DLT1,DLT2,DLT3,RTAIR,DDA,DDB,Y1,Y2,Y3,Y4,Y5,FV

      integer index,IT
      real cmin,cmin1,vgcr,vgcf,r3456,        &
           a2,ee1,ee2,a1,r7r,r8r,del,r11rt,nci
      real tem1,tem2,tem3,tem4
      real rrho,rp0,rpi
      real ene1,ene2,lhv,lhs,lhf
      real tem5,rdt,temp,f1,f2,r1,dum1,cpml,cvml,rm,dum

      double precision :: tem6
      double precision, dimension(nk) :: bud1,bud2,bud3

      parameter(cmin=1.e-14)
      parameter(cmin1=1.e-12)
      parameter(r1=1.0/1.0e-9)

      tem5=.5/(SQRT(AMI100)-SQRT(AMI40))
      d2t=dt
      rdt=1.0/D2T

!     ******   TWO CLASS WATER AND THREE CLASS OF ICE-PHASE    *********


!$omp parallel do default(shared)  &
!$omp private(i,j,k,VFR,VFS,VFG,RHO,P0,PPI,rho0,COL,DEP,RGMP,DD,DD1,QVS,    &
!$omp DM,RSUB1,WGACR,CND,RQ,ERN,SCV,TCA,DWV,ZR,VR,ZS,VS,ZG,VG,EGS,ESI,QSI,  &
!$omp SSI,QSW,SSW,PIHOM,PIDW,PIMLT,PSAUT,PSACI,PSACW,QSACW,PRACI,PIACR,     &
!$omp PRAUT,PRACW,PSFW,PSFI,DGACS,DGACW,DGACI,DGACR,PGACS,WGACS,QGACW,      &
!$omp WGACI,QGACR,PGWET,PGAUT,PRACS,PSACR,QSACR,PGFR,PSMLT,PGMLT,PSDEP,     &
!$omp PSSUB,PGSUB,PINT,PIDEP,PISUB,PT,QV,QC,QR,QI,QS,QG,TAIR,TAIRC,PR,PS,   &
!$omp PG,PRN,PSN,DLT1,DLT2,DLT3,RTAIR,DDA,DDB,Y1,Y2,Y3,Y4,Y5,FV,index,IT,   &
!$omp vgcr,vgcf,r3456,a2,ee1,ee2,a1,r7r,r8r,del,r11rt,nci,tem1,tem2,tem3,   &
!$omp tem4,rrho,rp0,rpi,ene1,ene2,lhv,lhs,lhf,temp,f1,f2,dum1,cpml,cvml,    &
!$omp rm,dum)
      DO k=1,nk
      bud1(k)=0.0d0
      bud2(k)=0.0d0
      bud3(k)=0.0d0
      DO j=1,nj
      DO i=1,ni
          rho0=1.0e-3*rhod(i,j,1)

          vtr(i,j,k)=0.0
          vts(i,j,k)=0.0
          vtg(i,j,k)=0.0

        IT=1                                                           
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!C    ******************************************************************
          fv=rho0                                               
          RHO=1.0e-3*rhod(i,j,k)
          PPI=pi0(i,j,k)+pp3d(i,j,k)
          P0=10.0*prs(i,j,k)
          PT=th3d(i,j,k)
          QV=QV3D(I,J,K)
          QC=QC3D(I,J,K)
          QR=QR3D(I,J,K)
          QI=QI3D(I,J,K)
          QS=QS3D(I,J,K)
          QG=QG3D(I,J,K)
          QV=max(QV,cmin1)
          IF(QC.LT.cmin)  QC=0.0                                  
          IF(QR.LT.cmin)  QR=0.0                                  
          IF(QI.LT.cmin)  QI=0.0                                  
          IF(QS.LT.cmin)  QS=0.0                                  
          IF(QG.LT.cmin)  QG=0.0                                  
          TAIR=(th0(i,j,k)+PT)*PPI                                     
          TAIRC=TAIR-T0K                                          
!----------------------------------------------------
!  variables added to improve performance
          tem1=1.0/(sqrt(sqrt(rho)))
          tem2=sqrt(FV/RHO)
          tem3=1.0/(sqrt(rho))
          tem4=sqrt(sqrt(FV/RHO))
          rrho=1.0/rho
          rp0=1.0/p0
          rpi=1.0/ppi
!----------------------------------------------------
!  variables for new equation set
          if(eqtset.eq.2)then
            dum1=cpl*(qc+qr)+cpi*(qi+qs+qg)
            cvml=cv+cvv*qv+dum1
            cpml=cp+cpv*qv+dum1
            rm=rd+rv*qv
            ene1=cv/(cp*cvml*ppi)
            ene2=(th0(i,j,k)+pt)*(rv/cvml)*(1.0-rovcp*cpml/rm)
          else
            ene1=1.0/(cp*ppi)
            ene2=0.0
          endif
          lhv=lv1-lv2*tair
          lhs=ls1-ls2*tair
          lhf=lhs-lhv
!----------------------------------------------------
!     ***   COMPUTE ZR,ZS,ZG,VR,VS,VG      *****************************
          ZR=1.E5*ZRC*tem1
          ZS=1.E5*ZSC*tem1
          ZG=1.E5*ZGC*tem1
          VR=0.0                                                     
          VS=0.0                                                     
          VG=0.0                                                     
          IF(QR.GT.cmin)THEN                                         
            DD=RHO*QR                                          
            Y1=sqrt(sqrt(DD))
            ZR=ZRC/Y1                                             
            temp=r1*min(50.0e-6,max(0.0,DD))
            index=int(temp)
            f1=pwr2(index)
            f2=pwr2(index+1)
            VR=VRC*tem2*(f1+(f2-f1)*(temp-index))
          ENDIF                                                         
          IF(QS.GT.cmin)THEN                                         
            DD=RHO*QS                                          
            Y1=sqrt(sqrt(DD))
            ZS=ZSC/Y1                                             
!!!            VS=VSC*tem2*sqrt(sqrt(y1))
            VS=VSC*tem2*DD**BSQ
          ENDIF                                                         
          if (qg .gt. cmin) then                                     
            dd=rho*qg                                         
            y1=sqrt(sqrt(dd))
            zg=zgc/y1                                             
            if (ihail .eq. 1) then                                      
              vgcr=vgc*tem3
              vg=vgcr*sqrt(y1)
            else                                                        
              vgcf=vgc*tem2
              vg=vgcf*exp(alog(dd)*bgq)
            endif                                                       
          endif                                                         
          VFR=VR                                                
          VFS=VS                                                
          VFG=VG                                                
!     ******************************************************************
!     ***   Y1 : DYNAMIC VISCOSITY OF AIR (U)                           
!     ***   DWV : DIFFUSIVITY OF WATER VAPOR IN AIR (PI)                
!     ***   TCA : THERMAL CONDUCTIVITY OF AIR (KA)                      
!     ***   Y2 : KINETIC VISCOSITY (V)                                  
          Y1=C149*TAIR*sqrt(TAIR)/(TAIR+120.)
          temp=min(150.0,max(0.0,TAIR-173.15))
          index=int(temp)
          f1=pwr81(index)
          f2=pwr81(index+1)
          DWV=C879*rp0*TAIR*(f1+(f2-f1)*(temp-index))
          TCA=C141*Y1                                             
          SCV=exp(alog(RHO/(Y1*DWV**2))*.1666667)
!*  1 * PSAUT : AUTOCONVERSION OF QI TO QS                        ***1**
!*  3 * PSACI : ACCRETION OF QI TO QS                             ***3**
!*  4 * PSACW : ACCRETION OF QC BY QS (RIMING) (QSACW FOR PSMLT)  ***4**
!*  5 * PRACI : ACCRETION OF QI BY QR                             ***5**
!*  6 * PIACR : ACCRETION OF QR OR QG BY QI                       ***6**
          PSAUT=0.0                                                  
          PSACI=0.0                                                  
          PRACI=0.0                                                  
          PIACR=0.0                                                  
          PSACW=0.0                                                  
          QSACW=0.0                                                  
          PRAUT=0.0                                                  
          PRACW=0.0                                                  
          r3456=tem2
!!!          DD=1.0/(sqrt(sqrt(ZS))*ZS**3)
          DD=1.0/ZS**BS3
          IF( (QI.GT.CMIN) .or. (QC.GT.CMIN) )THEN
            temp=exp(alog(ZR)*(-BW3))
          ENDIF
          IF(QI.GT.CMIN) THEN                                        
           IF(TAIR.LT.T0K)THEN                                       
             ESI=EXP(.025*TAIRC)                                  
             PSAUT=MAX(RN1*ESI*(QI-BND1),0.0)                
             PSACI=RN3*R3456*.1*QI*DD                          
             PRACI=RN5*R3456*QI*temp
             PIACR=RN6*R3456*QI*exp(alog(ZR)*(-BW6))
           ENDIF                                                        
          ENDIF                                                         
          IF(QC.GT.CMIN) THEN                                        
            IF(TAIR.LT.T0K)THEN                                      
              PSACW=RN4*R3456*QC*DD                            
            ELSE                                                        
              QSACW=RN4*R3456*QC*DD                            
            ENDIF                                                       
!* 21 * PRAUT : AUTOCONVERSION OF QC TO QR                        **21**
!* 22 * PRACW : ACCRETION OF QC BY QR                             **22**
           PRACW=RN22*tem2*QC*temp
           IF(iautoc.eq.1)THEN
             Y1=QC-BND3                                             
             IF(Y1.GT.cmin)THEN                                        
               PRAUT=RHO*Y1*Y1/(1.2E-4+RN21/Y1)            
             ENDIF                                                        
           ENDIF
          ENDIF                                                         
!* 12 * PSFW : BERGERON PROCESSES FOR QS (KOENING, 1971)          **12**
!* 13 * PSFI : BERGERON PROCESSES FOR QI                          **13**
!* 32 * PIDEP : DEPOSITION OF QI                                  **32**
          PSFW=0.0                                                   
          PSFI=0.0                                                   
          PIDEP=0.0                                                  
          PISUB=0.0                                                  
          IF(TAIR.LT.T0K.AND.QI.GT.cmin)THEN                      
            Y1=MAX(MIN(TAIRC,-1.),-31.)                       
            IT=INT(ABS(Y1))                                       
            Y1=RN12A(IT)                                          
            Y2=RN12B(IT)                                          
            PSFW=MAX(D2T*Y1*(RN12*RHO*QC)*QI,0.0)      
            RTAIR=1./(TAIR-C76)                                   
            Y2=EXP(C218-C580*RTAIR)                               
            QSI=C380*rp0*Y2                                   
            ESI=C610*Y2                                           
            SSI=QV/QSI-1.                                
            NCI=MIN(RN25*EXP(BETA*TAIRC),1.)                       
            DM=QV-QSI                                      
            RSUB1=C580*ASC*QSI*RTAIR*RTAIR                  
            Y3=1./TAIR                                            
            DD=Y3*(RN30A*Y3-RN30B)+RN30C*TAIR/ESI        
            Y1=206.18*SSI/DD                                   
            DEP=DM/(1.+RSUB1)*rdt
            PIDEP=Y1*SQRT(NCI*QI*rrho)                       
            IF(DM.GT.cmin) THEN                                      
               a2=1.                                                    
               if(pidep.gt.dep .and. pidep .gt. cmin) then     
                  a2=dep/pidep                                    
                  pidep=dep                                       
               endif                                                    
               PSFI=a2*QI*Y1*tem5
            ELSEIF(DM.LT.-cmin) THEN                                 
               PISUB=MAX(-QI*rdt,PIDEP)                      
               PISUB=MIN(-PISUB,-DM*rdt)                     
               PIDEP=0.                                              
               PSFI=0.                                               
            ELSE                                                        
               PISUB=0.                                              
               PIDEP=0.                                              
               PSFI=0.                                               
            ENDIF                                                       
          ENDIF                                                         
!TTT***** QG=QG+MIN(PGDRY,PGWET)                                        
!*  9 * PGACS : ACCRETION OF QS BY QG (DGACS,WGACS: DRY AND WET)  ***9**
!* 14 * DGACW : ACCRETION OF QC BY QG (QGACW FOR PGMLT)           **14**
!* 16 * DGACR : ACCRETION OF QR TO QG (QGACR FOR PGMLT)           **16**
          DGACS=0.0                                                  
          WGACS=0.0                                                  
          DGACW=0.0                                                  
          DGACR=0.0                                                  
          PGACS=0.0                                                  
          QGACW=0.0                                                  
          QGACR=0.0                                                  
          DGACI=0.0                                                  
          WGACI=0.0                                                  
          PGWET=0.0                                                  
        IF(QG.GT.CMIN)THEN                                           
                                                                        
          IF(QC+QR.LT.1.e-4) THEN
             EE1=.01
          ELSE
             EE1=1.
          ENDIF
          EE2=0.09                                                      
          EGS=EE1*EXP(EE2*TAIRC)                                  
          IF(TAIR.GE.T0K)EGS=1.0                                  
          Y1=ABS(VG-VS)                                        
          Y2=ZS*ZG                                             
          Y3=5./Y2                                                
          Y4=.08*Y3*Y3                                         
          Y5=.05*Y3*Y4                                         
          DD=Y1*(Y3/ZS**5+Y4/ZS**3+Y5/ZS)       
          PGACS=RN9*rrho*EGS*DD                              
          DGACS=PGACS                                             
          WGACS=RN9*rrho*DD                                     
          IF(IHAIL.EQ.1) THEN                                           
             Y1=1.0/(sqrt(ZG)*ZG**3)
             DGACW=MAX(RN14*QC*Y1*tem3,0.0)          
          ELSE                                                          
             Y1=exp(alog(ZG)*(-BG3))
             DGACW=MAX(RN14*QC*Y1*R3456,0.0)                 
          ENDIF                                                         
          QGACW=DGACW                                             
          Y1=ABS(VG-VR)                                        
          Y2=ZR*ZG                                             
          Y3=5./Y2                                                
          Y4=.08*Y3*Y3                                         
          Y5=.05*Y3*Y4                                         
          DD=Y1*(Y3/ZR**5+Y4/ZR**3+Y5/ZR)*RN16   &
                *rrho                                                  
          DGACR=MAX(DD,0.0)                                     
          QGACR=DGACR                                             
          IF(TAIR.GE.T0K)THEN                                        
            DGACS=0.0                                                
            WGACS=0.0                                                
            DGACW=0.0                                                
            DGACR=0.0                                                
          ELSE                                                          
            PGACS=0.0                                                
            QGACW=0.0                                                
            QGACR=0.0                                                
          ENDIF                                                         
!*******PGDRY : DGACW+DGACI+DGACR+DGACS                           ******
!* 15 * DGACI : ACCRETION OF QI BY QG (WGACI FOR WET GROWTH)      **15**
!* 17 * PGWET : WET GROWTH OF QG                                  **17**
          IF(TAIR.LT.T0K.AND.TAIR.GT.T0K-40.)THEN                 
            IF(IHAIL.EQ.1) THEN                                         
               Y1=QI/(sqrt(ZG)*ZG**3)
               DGACI=Y1*RN15*tem3
               WGACI=Y1*RN15A*tem3
            ELSE                                                        
               Y1=QI/ZG**BG3                                      
               DGACI=Y1*RN15*R3456                                
               WGACI=Y1*RN15A*R3456                               
            ENDIF                                                       
            Y1=1./(ALF+RN17C*TAIRC)                               
            IF(IHAIL.EQ.1) THEN                                         
               Y3=.78/ZG**2+SCV*RN17A*tem1*exp(alog(ZG)*(-BGH5))
            ELSE                                                        
               Y3=.78/ZG**2+SCV*RN17A*tem4*exp(alog(ZG)*(-BGH5))
            ENDIF                                                       
            Y4=RHO*ALV*DWV*(C380*rp0-QV)-TCA*   &
                  TAIRC                                              
            DD=Y1*(Y4*Y3*RN17*rrho+(WGACI+WGACS)*(   &
                  ALF+RN17B*TAIRC))                                  
            PGWET=MAX(DD,0.0)                                   
          ENDIF                                                         
        ENDIF                                                           
!********   HANDLING THE NEGATIVE CLOUD WATER (QC)    ******************
!********   HANDLING THE NEGATIVE CLOUD ICE (QI)      ******************
!********   DIFFERENT FROM LIN ET AL                  ******************
           y1=qc*rdt
          psacw=MIN(y1, psacw)                               
          praut=MIN(y1, praut)                               
          pracw=MIN(y1, pracw)                               
          psfw= MIN(y1, psfw)                                
          dgacw=MIN(y1, dgacw)                               
          qsacw=MIN(y1, qsacw)                               
          qgacw=MIN(y1, qgacw)                               
                                                                        
          Y1=(PSACW+PRAUT+PRACW+PSFW+DGACW+QSACW+   &
                QGACW)*D2T                                           
          QC=QC-Y1                                             
                                                                        
          IF(QC.LT.0.0) THEN                                         
             a1=1.                                                      
              if (y1 .ne. 0.0) A1=QC/Y1+1.                     
            PSACW=PSACW*A1                                        
            PRAUT=PRAUT*A1                                        
            PRACW=PRACW*A1                                        
            PSFW=PSFW*A1                                          
            DGACW=DGACW*A1                                        
            QSACW=QSACW*A1                                        
            QGACW=QGACW*A1                                        
            QC=0.0                                                   
          ENDIF                                                         

          dum=ruh(i)*rvh(j)*rmh(i,j,k)

          bud1(k)=bud1(k)+rr(i,j,k)*PRAUT*dum
          bud2(k)=bud2(k)+rr(i,j,k)*PRACW*dum

!                                                                       
!******** SHED PROCESS (WGACR=PGWET-DGACW-WGACI-WGACS)                  
!     CALCULATIONS OF THIS TERM HAS BEEN MOVED TO THIS LOCATION TO      
!     ACCOUNT FOR RESCALING OF THE DGACW TERM ABOVE. ALTHOUGH RESCALING 
!     OF THE PGWET, WGACI AND WGACS TERMS OCCURS BELOW, THESE CHANGES   
!     ARE EXPECTED TO BE LESS THAN THAT ASSOCIATED WITH DGACW. THIS CALC
!     IS NOT DONE AFTER RESCALING OF ALL TERMS SINCE WGACR IS NEEDED BEL
!     FOR RAIN AND WGACI AND DGACI ARE NEEDED FOR ICE.                  
          WGACR=PGWET-DGACW-WGACI-WGACS                  
          Y2=DGACW+DGACI+DGACR+DGACS                     
          IF(PGWET.GE.Y2)THEN                                     
            WGACR=0.0                                                
            WGACI=0.0                                                
            WGACS=0.0                                                
          ELSE                                                          
            DGACR=0.0                                                
            DGACI=0.0                                                
            DGACS=0.0                                                
          ENDIF                                                         
                                                                        
            y1=qi*rdt
           psaut=MIN(y1, psaut)                              
           psaci=MIN(y1, psaci)                              
           praci=MIN(y1, praci)                              
           psfi= MIN(y1, psfi)                               
           dgaci=MIN(y1, dgaci)                              
           wgaci=MIN(y1, wgaci)                              

          Y1=(PSAUT+PSACI+PRACI+PSFI+DGACI+WGACI   &
                +PISUB)*D2T                                          

           qi=qi-y1+PIDEP*D2T                               
           if(qi.lt.0.0) then                                        
               a2=1.                                                    
                if (y1 .ne. 0.0) a2=qi/y1+1.                   
            psaut=psaut*a2                                        
            psaci=psaci*a2                                        
            praci=praci*a2                                        
            psfi=psfi*a2                                          
            dgaci=dgaci*a2                                        
            wgaci=wgaci*a2                                        
            pisub=pisub*a2                                        
            qi=0.0                                                   
           endif                                                        
!                                                                       
          DLT3=0.0                                                   
          DLT2=0.0                                                   
          IF(TAIR.LT.T0K)THEN                                        
            IF(QR.LT.1.E-4)THEN                                      
              DLT3=1.0                                               
              DLT2=1.0                                               
            ENDIF                                                       
            IF(QS.GE.1.E-4)DLT2=0.0                               
          ENDIF                                                         
          PR=(QSACW+PRAUT+PRACW+QGACW)*D2T               
          PS=(PSAUT+PSACI+PSACW+PSFW+PSFI+DLT3*    &
                PRACI)*D2T                                           
          PG=((1.-DLT3)*PRACI+DGACI+WGACI+DGACW)*D2T  
!*  7 * PRACS : ACCRETION OF QS BY QR                             ***7**
!*  8 * PSACR : ACCRETION OF QR BY QS (QSACR FOR PSMLT)           ***8**
            PRACS=0.0                                                
            PSACR=0.0                                                
            QSACR=0.0                                                
            PGFR=0.0                                                 
            PGAUT=0.0                                                
        IF(QR.GT.CMIN)THEN                                           
          Y1=ABS(VR-VS)                                        
          Y2=ZR*ZS                                             
          Y3=5./Y2                                                
          Y4=.08*Y3*Y3                                         
          Y5=.05*Y3*Y4                                         
          R7R=RN7*rrho                                                
          PRACS=R7R*Y1*(Y3/ZS**5+Y4/ZS**3+Y5/ZS)
          R8R=RN8*rrho                                                
          PSACR=R8R*Y1*(Y3/ZR**5+Y4/ZR**3+Y5/ZR)
          QSACR=PSACR                                             
          IF(TAIR.GE.T0K)THEN                                        
            PRACS=0.0                                                
            PSACR=0.0                                                
          ELSE                                                          
            QSACR=0.0                                                
          ENDIF                                                         
!*  2 * PGAUT : AUTOCONVERSION OF QS TO QG                        ***2**
!* 18 * PGFR  : FREEZING OF QR TO QG                              **18**
          IF(TAIR.LT.T0K)THEN                                        
!           Y1=EXP(.09*TAIRC)                                     
!           if (ihail .eq. 1) PGAUT=MAX(RN2*Y1*(QS-BND2),0.0)
            Y2=EXP(RN18A*(T0K-TAIR))                              
            PGFR=MAX((Y2-1.)*RN18*rrho/ZR**7,0.0)       
          ENDIF                                                         
        ENDIF                                                           
!********   HANDLING THE NEGATIVE RAIN WATER (QR)    *******************
!********   HANDLING THE NEGATIVE SNOW (QS)          *******************
!********   DIFFERENT FROM LIN ET AL                 *******************
          y1=qr*rdt
          Y2=-QG*rdt
         piacr=MIN(y1, piacr)                                
         dgacr=MIN(y1, dgacr)                                
         wgacr=MIN(y1, wgacr)                                
         wgacr=MAX(y2, wgacr)                                
         psacr=MIN(y1, psacr)                                
         pgfr= MIN(y1, pgfr)                                 

         del=0.                                                         
         IF(WGACR.LT.0.) del=1.                                      
          Y1=(PIACR+DGACR+(1.-del)*WGACR+PSACR+          &
                  PGFR)*D2T                                          
          qr=qr+pr-y1-del*WGACR*D2T                      
                                                                        
          if(qr.lt.0.0) then                                         
            a1=1.0                                                      
             if(y1 .ne. 0.) a1=qr/y1+1.                        
            piacr=piacr*a1                                        
            dgacr=dgacr*a1                                        
            if(wgacr.gt.0) wgacr=wgacr*a1                      
            pgfr=pgfr*a1                                          
            psacr=psacr*a1                                        
            qr=0.0                                                   
          endif                                                         

          PRN=D2T*((1.-DLT3)*PIACR+DGACR+WGACR+(1.-      &
                 DLT2)*PSACR+PGFR)                             
          PS=PS+D2T*(DLT3*PIACR+DLT2*PSACR)           

           y1=qs*rdt
          pgacs=MIN(y1, pgacs)                               
          dgacs=MIN(y1, dgacs)                               
          wgacs=MIN(y1, wgacs)                               
          pgaut=MIN(y1, pgaut)                               
          pracs=MIN(y1, pracs)                               

          PRACS=(1.-DLT2)*PRACS                                
          PSN=D2T*(PGACS+DGACS+WGACS+PGAUT+PRACS)     
          QS=QS+PS-PSN                                      
          if(qs .lt. 0.0) then                                       
            a2=1.                                                       
              if(psn .ne. 0.) a2=qs/psn+1.                     
            pgacs=pgacs*a2                                        
            dgacs=dgacs*a2                                        
            wgacs=wgacs*a2                                        
            pgaut=pgaut*a2                                        
            pracs=pracs*a2                                        
            psn=psn*a2                                            
            qs=0.0                                                   
          endif                                                         
          Y2=D2T*(PSACW+PSFW+DGACW+PIACR+DGACR+       &
                WGACR+PSACR+PGFR)                              
          PT=PT+lhf*ene1*Y2                                   
          QG=QG+PG+PRN+PSN                               
!* 11 * PSMLT : MELTING OF QS                                     **11**
!* 19 * PGMLT : MELTING OF QG TO QR                               **19**
          PSMLT=0.0                                                  
          PGMLT=0.0                                                  
          TAIR=(th0(i,j,k)+PT)*PPI                                     
          r3456=tem2
          IF(TAIR.GE.T0K .AND. (QS+QG).GT.CMIN) THEN           
            TAIRC=TAIR-T0K                                        
            Y1=TCA*TAIRC-RHO*ALV*DWV    &
                       *(C380*rp0-QV)
            Y2=.78/ZS**2+RN101*tem4*SCV    &
                 *exp(alog(ZS)*(-BSH5))
            R11RT=RN11*D2T*rrho                                       
            DD=R11RT*Y1*Y2+R11AT*TAIRC*(QSACW+QSACR)  
            PSMLT=MAX(0.0,MIN(DD,QS))                      
            IF(IHAIL.EQ.1) THEN                                         
               Y3=.78/ZG**2+SCV*RN19A*tem1*exp(alog(ZG)*(-BGH5))
            ELSE                                                        
               Y3=.78/ZG**2+SCV*RN19A*tem4*exp(alog(ZG)*(-BGH5))
            ENDIF                                                       
            DD1=Y1*Y3*RN19*D2T*rrho+R19BT*TAIRC*(QGACW   &
                   +QGACR)                                            
            PGMLT=MAX(0.0,MIN(DD1,QG))                     
            PT=PT-lhf*ene1*(PSMLT+PGMLT)
            QR=QR+PSMLT+PGMLT                               
            QS=QS-PSMLT                                        
            QG=QG-PGMLT                                        
          ENDIF                                                         
!* 24 * PIHOM : HOMOGENEOUS FREEZING OF QC TO QI (T < T00K)    **24**   
!* 25 * PIDW : DEPOSITION GROWTH OF QC TO QI ( T0K < T <= T00K)**25**   
!* 26 * PIMLT : MELTING OF QI TO QC (T >= T0K)                 **26**   
          IF(QC.LE.cmin)QC=0.0                                    
          IF(QI.LE.cmin)QI=0.0                                    
          PIHOM=0.                                                   
          PIMLT=0.                                                   
          TAIR=(th0(i,j,k)+PT)*PPI                                     
          IF((TAIR-T00K).LE.0.) PIHOM=QC                       
          IF((TAIR-T0K) .GE.0.) PIMLT=QI                       
          PIDW=0.0                                                   
          IF(TAIR.LT.T0K.AND.TAIR.GT.T00K.AND.QC.GT.CMIN)THEN  
            TAIRC=TAIR-T0K                                        
            Y1=MAX(MIN(TAIRC,-1.),-31.)                       
            Y2=RN25A(INT(ABS(Y1)))                                
            Y3=MIN(RN25*EXP(BETA*TAIRC),1.)                     
            PIDW=MIN(Y2*Y3*D2T*rrho,QC)                 
          ENDIF                                                         
          Y1=PIHOM-PIMLT+PIDW                               
          PT=PT+lhf*ene1*Y1    &
                     +(lhs*ene1-ene2)*(PIDEP-PISUB)*D2T
          QV=QV-(PIDEP-PISUB)*D2T                           
          QC=QC-Y1                                             
          QI=QI+Y1                                             
!* 31 * PINT  : INITIATION OF QI                                  **31**
!****** DIFFERENT FROM LIN ET AL.                                 ******
          PINT=0.0                                                   
          TAIR=(th0(i,j,k)+PT)*PPI                                     
           if (qi .le. cmin) qi=0.0                               
          IF(TAIR.LT.T0K)THEN                                        
            TAIRC=TAIR-T0K                                        
            RTAIR=1./(TAIR-C76)                                   
            Y2=EXP(C218-C580*RTAIR)                               
            QSI=C380*rp0*Y2                                   
            ESI=C610*Y2                                           
            SSI=QV/QSI-1.                                
            NCI=MIN(RN25*EXP(BETA*TAIRC),1.)                       
!     Do not initiate the maximum number of nuclei. Some ice may already
!     present, so only initiate that needed to get up to the maximum num
!     Use ami50 g as mass of 50 micron size particle (assumed to be the 
!     size of ice particles), and use 1.e-9 g as initial mass of ice    
!     particles                                                         
            dd=MAX(1.e-9*nci*rrho-qi*1.e-9/ami50 , 0.)        
            DM=MAX((QV-QSI),0.)                          
            RSUB1=C580*ASC*QSI*RTAIR*RTAIR                  
            PINT=MIN(DD,DM)                                  
            DEP=DM/(1.+RSUB1)                                  
            PINT=MIN(PINT,DEP)                               
            if (pint .le. cmin) pint=0.0                          
            PT=PT+(lhs*ene1-ene2)*PINT
            QV=QV-PINT                                         
            QI=QI+PINT                                         
          ENDIF                                                         
!--------------------------------------
!  cut saturation .... do later
!--------------------------------------
!* 10 * PSDEP : DEPOSITION OR SUBLIMATION OF QS                   **10**
!* 20 * PGSUB : SUBLIMATION OF QG                                 **20**
          PSDEP=0.0                                                  
          PSSUB=0.0                                                  
          PGSUB=0.0                                                  
          r3456=tem2
          TAIR=(th0(i,j,k)+PT)*PPI                                     
          IF((QS+QG).GT.CMIN)THEN              
            IF(QS.LT.cmin) QS=0.0                                 
            IF(QG.LT.cmin) QG=0.0                                 
            RTAIR=1./(TAIR-C76)                                   
            QSI=C380*rp0*EXP(C218-C580*RTAIR)                 
            SSI=QV/QSI-1.                                
            Y1=RN10A*RHO/(TCA*TAIR**2)+1./(DWV*QSI)   
            Y2=.78/ZS**2+RN101*tem4*SCV    &
                 *exp(alog(ZS)*(-BSH5))
            PSDEP=R10T*SSI*Y2/Y1                            
            PSSUB=PSDEP                                           
            PSDEP=MAX(PSDEP,0.)                                 
            PSSUB=MAX(-QS,MIN(PSSUB,0.))                   
            IF(IHAIL.EQ.1) THEN                                         
               Y2=.78/ZG**2+SCV*RN20B*tem1*exp(alog(ZG)*(-BGH5))
            ELSE                                                        
               Y2=.78/ZG**2+SCV*RN20B*tem4*exp(alog(ZG)*(-BGH5))
            ENDIF                                                       
            PGSUB=R20T*SSI*Y2/Y1                            
            DM=QV-QSI                                      
            RSUB1=C580*ASC*QSI*RTAIR*RTAIR                  
!     ********   DEPOSITION OR SUBLIMATION OF QS  **********************
            Y1=DM/(1.+RSUB1)                                   
            PSDEP=MIN(PSDEP,MAX(Y1,0.))                    
            Y2=MIN(Y1,0.)                                       
            PSSUB=MAX(PSSUB,Y2)                              
!     ********   SUBLIMATION OF QG   ***********************************
            DD=MAX((-Y2-QS),0.)                              
            PGSUB=MIN(DD,QG,MAX(PGSUB,0.))              
!      DLT1=CVMGP(1.,0.,QC+QI-1.E-5)                           
            IF((QC+QI-1.E-5).GE.0.)THEN                           
              DLT1=1.                                                
            ELSE                                                        
              DLT1=0.                                                
            ENDIF                                                       
            PSDEP=DLT1*PSDEP                                   
            PSSUB=(1.-DLT1)*PSSUB                              
            PGSUB=(1.-DLT1)*PGSUB                              
            PT=PT+(lhs*ene1-ene2)*(PSDEP+PSSUB-PGSUB)
            QV=QV+PGSUB-PSSUB-PSDEP                      
            QS=QS+PSDEP+PSSUB                               
            QG=QG-PGSUB                                        
          ENDIF                                                         
!* 23 * ERN : EVAPORATION OF QR (SUBSATURATION)                   **23**
          ERN=0.0                                                    
          IF(QR.GT.CMIN)THEN                                         
            TAIR=(th0(i,j,k)+PT)*PPI                                   
            RTAIR=1./(TAIR-C358)                                  
            QSW=C380*rp0*EXP(C172-C409*RTAIR)                 
            SSW=QV/QSW-1.0                               
            DM=QV-QSW                                      
            RSUB1=C409*AVC*QSW*RTAIR*RTAIR                  
            DD1=MAX(-DM/(1.+RSUB1),0.0)                      
            Y1=.78/ZR**2+RN23A*tem4*SCV    &
                 *exp(alog(ZR)*(-BWH5))
            Y2=RN23B*RHO/(TCA*TAIR**2)+1./(DWV*QSW)   
            ERN=R23T*SSW*Y1/Y2                              
            ERN=MIN(DD1,QR,MAX(ERN,0.))                 
            PT=PT-(lhv*ene1-ene2)*ERN
            QV=QV+ERN                                          
            QR=QR-ERN                                          
          ENDIF                                                         
          dum=ruh(i)*rvh(j)*rmh(i,j,k)
          bud3(k)=bud3(k)+rr(i,j,k)*ERN*dum
          IF(QC.LE.cmin)QC=0.                                     
          IF(QR.LE.cmin)QR=0.                                     
          IF(QI.LE.cmin)QI=0.                                     
          IF(QS.LE.cmin)QS=0.                                     
          IF(QG.LE.cmin)QG=0.                                     
        IF(eqtset.eq.2)THEN
          dum1=abs(qv-qv3d(i,j,k))+abs(qc-qc3d(i,j,k))+abs(qr-qr3d(i,j,k))   &
              +abs(qi-qi3d(i,j,k))+abs(qs-qs3d(i,j,k))+abs(qg-qg3d(i,j,k))
          if(dum1.gt.1.0e-7)then
            pp3d(i,j,k)=((rhod(i,j,k)*(rd+rv*qv)*(th0(i,j,k)+pt)*rp00)**rddcv)-pi0(i,j,k)
            prs(i,j,k)=p00*((pi0(i,j,k)+pp3d(i,j,k))**cpdrd)
          endif
        ELSE
          rhod(i,j,k)=prs(i,j,k)/(rd*(th0(i,j,k)+pt)*(pi0(i,j,k)+pp3d(i,j,k))*(1.0+qv*reps))
        ENDIF

          TH3D(I,J,K)=PT
          QV3D(I,J,K)=QV
          QC3D(I,J,K)=QC
          QR3D(I,J,K)=QR
          QI3D(I,J,K)=QI
          QS3D(I,J,K)=QS
          QG3D(I,J,K)=QG
          vtr(i,j,k)=vfr*0.01
          vts(i,j,k)=vfs*0.01
          vtg(i,j,k)=vfg*0.01
          vti(i,j,k)=0.200

      enddo
      enddo
      enddo

      tem6=dx*dy*dz

      do k=1,nk
        tauto=tauto+bud1(k)*tem6
      enddo

      do k=1,nk
        taccr=taccr+bud2(k)*tem6
      enddo

      do k=1,nk
        tevar=tevar+bud3(k)*tem6
      enddo

      if(timestats.ge.1) time_microphy=time_microphy+mytime()

!C**********************************************************************
!                                                                       
      END subroutine goddard                                                              


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


!***********************************************************************
      SUBROUTINE CONSAT
      use input
      use cm1libs , only : gamma
      implicit none
!***********************************************************************
!     (LIN) SPECIFY SOME CONSTANTS IN SATICE ROUTINE                   *
!     LIN ET.AL.  J. CLIM. APPL. METEOR.  22, 1065-1092                *
!     MODIFIED AND CODED BY TAO AND SIMPSON (JAS, 1989; TAO, 1993)     *
!     RECENT CHANGES (6.25.01) BY SCOTT BRAUN INCLUDE
!         * OPTION TO CHOOSE HAIL OR GRAUPEL AS THIRD ICE CATEGORY
!         * OPTION OF SATURATION ADJUSTMENT SCHEMES
!         * INCLUSION OF GAMMA FUNCTION FOR EASIER VARIATION OF FALL
!           SPEED COEFFICIENTS
!***********************************************************************

      real A1(31),A2(31)
      DATA A1/.7939E-7,.7841E-6,.3369E-5,.4336E-5,.5285E-5,.3728E-5,       &
         .1852E-5,.2991E-6,.4248E-6,.7434E-6,.1812E-5,.4394E-5,.9145E-5,   &
         .1725E-4,.3348E-4,.1725E-4,.9175E-5,.4412E-5,.2252E-5,.9115E-6,   &
         .4876E-6,.3473E-6,.4758E-6,.6306E-6,.8573E-6,.7868E-6,.7192E-6,   &
         .6513E-6,.5956E-6,.5333E-6,.4834E-6/
      DATA A2/.4006,.4831,.5320,.5307,.5319,.5249,.4888,.3894,.4047,    &
         .4318,.4771,.5183,.5463,.5651,.5813,.5655,.5478,.5203,.4906,   &
         .4447,.4126,.3960,.4149,.4320,.4506,.4483,.4460,.4433,.4413,   &
         .4382,.4361/

      real cp,cpi,cpi2,grvt,tca,dwv,dva,amw,ars,scv,rw,cw,ci,cd1,cd2,     &
           ga3b,ga4b,ga6b,ga5bh,ga3g,ga4g,ga5gh,ga3d,ga4d,ga5dh,esw,      &
           eri,ami,esr,eiw,ui50,ri50,cmn,y1,rn13,egw,egi,egi2,egr,apri,   &
           bpri,erw,cn0

      integer i,k

!
!
!     USE GRAUPEL OR HAIL (0=GRAUPEL, 1=HAIL)
!
!!!!!! 
!!!!!!      IHAIL=1       ! Now specified in namelist.input
!!!!!! 
!
!*****   IWATER=0 USES A SLIGHT VARIANT OF THE ORIGINAL TAO ET AL METHOD
!*****   THE ONLY DIFFERENCE IS THAT THE WEIGHTING BETWEEN THE LIQUID
!*****   AND ICE SATURATION VALUES IS DONE BY TEMPERATURE RATHER THAN MA
!*****   IWATER=1 USES A SEQUENTIAL METHOD IN WHICH THE ADJUSTMENT IS FI
!*****   DONE FOR LIQUID WATER FOR TEMPERATURES WARMER THAN 253K, THEN F
!*****   ICE ONLY WHERE THE TEMPERATURE IS COLDER THAN 258K. THE MAIN EF
!*****   THIS CHANGE IS TO REDUCE THE AMOUNT OF SUPERCOOLED WATER AT VER
!*****   TEMPERATURES
!!!!!! 
!!!!!!      IWATER=1
!!!!!! 
!*****************************************************************
 
!
      CP=1.0057E7
      CPI=4.*ATAN(1.)
      CPI2=CPI*CPI
      GRVT=981.
      TCA=2.43E3
      DWV=.226
      DVA=1.718E-4
      AMW=18.016
      ARS=8.314E7
      SCV=2.2904487
      T0K=273.15
      T00K=233.15
      ALV=2.501000E10
      ALS=2.834000E10
      ALF=ALS-ALV
      AVC=ALV/CP
      AFC=ALF/CP
      ASC=ALS/CP
      RW=4.615E6
      CW=4.190E7
      CI=2.106000E7
      C76=7.66
      C358=29.65
      C172=17.67
      C409=17.67*(273.15-29.65)
      C218=21.8745584
      C580=21.8745584*(273.15-7.66)
      C380=10.0*611.2*287.04/461.5
      C610=6.1078E3
      C149=1.496286E-5
      C879=8.794142
      C141=1.4144354E7
 
!***   DEFINE THE DENSITY AND SIZE DISTRIBUTION OF PRECIPITATION
!***   DEFINE THE COEFFICIENTS USED IN TERMINAL VELOCITY
!**********   HAIL OR GRAUPEL PARAMETERS   **********
      if (ihail .eq. 1) then
        ROQG=.9
        TNG=.0002
        CD1=6.E-1
        CD2=4.*GRVT/(3.*CD1)
        AGG=SQRT(CD2*ROQG)
        BGG=.5
      else
        ROQG=.4
        TNG=.04
        AGG=351.2
        BGG=.37
      endif
!**********         SNOW PARAMETERS        **********
! Note ... see Potter, 1991, JAM, p. 1040 for more info about these changes
      ROQS=.1
      ROQS_POTTER=1.0
      TNSS=1.
!!!      ASS=152.93
!!!      BSS=.25
      ASS=179.2
      BSS=.42
!**********         RAIN PARAMETERS        **********
      ROQR=1.
      TNW=.08
      AWW=2115.
      BWW=.8
!*****************************************************************
!
!
      BGH=.5*BGG
      BSH=.5*BSS
      BWH=.5*BWW
      BGQ=.25*BGG
      BSQ=.25*BSS
      BWQ=.25*BWW
      GA3B=gamma(3.+BWW)
      GA4B=gamma(4.+BWW)
      GA6B=gamma(6.+BWW)
      GA5BH=gamma((5.+BWW)/2.)
      GA3G=gamma(3.+BGG)
      GA4G=gamma(4.+BGG)
      GA5GH=gamma((5.+BGG)/2.)
      GA3D=gamma(3.+BSS)
      GA4D=gamma(4.+BSS)
      GA5DH=gamma((5.+BSS)/2.)
      ZRC=(CPI*ROQR*TNW)**0.25
      ZSC=(CPI*ROQS_POTTER*TNSS)**0.25
      ZGC=(CPI*ROQG*TNG)**0.25
      VRC=AWW*GA4B/(6.*ZRC**BWW)
      VSC=ASS*GA4D/(6.*ZSC**BSS)
      VGC=AGG*GA4G/(6.*ZGC**BGG)
!-------------------------------
!  fudge check
      if(ihail.eq.1 .and. bgg.ne.0.5)then
        print *,'  BGG must be 0.5 for hail (its fudged into code)!'
        print *,'        (sorry)'
        call stopcm1
      endif
!!!      if(bss.ne.0.25)then
!!!        print *,'  BSS must be 0.25 (its fudged into code)!'
!!!        print *,'        (sorry)'
!!!        call stopcm1
!!!      endif
      if(bww.ne.0.8)then
        print *,'  BWW must be 0.8 (its fudged into code)!'
        print *,'        (sorry)'
        call stopcm1
      endif
!-------------------------------
!     ****************************
      RN1=1.E-3
      RN2=1.E-3
      BND1=5.E-4
      BND2=1.25E-3
      RN3=.25*CPI*TNSS*ASS*GA3D
      ESW=1.
      RN4=.25*CPI*ESW*TNSS*ASS*GA3D
      ERI=1.
      RN5=.25*CPI*ERI*TNW*AWW*GA3B
      AMI=1./(24.*4.19E-10)
      RN6=CPI2*ERI*TNW*AWW*ROQR*GA6B*AMI
      ESR=1.
      RN7=CPI2*ESR*TNW*TNSS*ROQS
      RN8=CPI2*ESR*TNW*TNSS*ROQR
      RN9=CPI2*TNSS*TNG*ROQS
      RN10=2.*CPI*TNSS
      RN101=.31*GA5DH*SQRT(ASS)
      RN10A=ALS*ALS/RW
      RN11=2.*CPI*TNSS/ALF
      RN11A=CW/ALF
      AMI40=2.41e-8
      AMI50=3.76e-8
      AMI100=1.51e-7
      EIW=1.
      UI50=20.
      RI50=10.e-3
      CMN=1.05E-15
      RN12=CPI*EIW*UI50*RI50**2
      DO 10 K=1,31
        Y1=1.-A2(K)
        RN13=A1(K)*Y1/(AMI100**Y1-AMI40**Y1)
        RN12A(K)=RN13/AMI100
        RN12B(K)=A1(K)*AMI100**A2(K)
        RN25A(K)=A1(K)*CMN**A2(K)
   10 CONTINUE
      EGW=1.
      EGI=.1
      EGI2=1.
      RN14=.25*CPI*EGW*TNG*GA3G*agg
      RN15=.25*CPI*EGI*TNG*GA3G*agg
      RN15A=.25*CPI*EGI2*TNG*GA3G*agg
      EGR=1.
      RN16=CPI2*EGR*TNG*TNW*ROQR
      RN17=2.*CPI*TNG
      RN17A=.31*GA5GH*sqrt(agg)
      RN17B=CW-CI
      RN17C=CW
      APRI=.66
      BPRI=1.E-4
      RN18=20.*CPI2*BPRI*TNW*ROQR
      RN18A=APRI
      RN19=2.*CPI*TNG/ALF
      RN19A=.31*GA5GH*sqrt(agg)
      RN19B=CW/ALF
      RN20=2.*CPI*TNG
      RN20A=ALS*ALS/RW
      RN20B=.31*GA5GH*sqrt(agg)
      BND3=2.0E-3
      RN21=1.E3*1.569E-12/0.15
      ERW=1.
      RN22=.25*CPI*ERW*AWW*TNW*GA3B
      RN23=2.*CPI*TNW
      RN23A=.31*GA5BH*SQRT(AWW)
      RN23B=ALV*ALV/RW
      CN0=1.E-6
      RN25=CN0
      RN30A=ALV*ALS*AMW/(TCA*ARS)
      RN30B=ALV/TCA
      RN30C=ARS/(DWV*AMW)
      RN31=1.E-17
      BETA=-.46
      RN32=4.*51.545E-4
!-----------------------------------------------
      RT0=1./(T0K-T00K)
      BW3=BWW+3.
      BS3=BSS+3.
      BG3=BGG+3.
      BWH5=2.5+BWH
      BSH5=2.5+BSH
      BGH5=2.5+BGH
      BW6=BWW+6.
      BS6=BSS+6.
      BETAH=.5*BETA
!-----------------------------------------------
!  lookup tables
!
!  for pwr81, temperature range is from -100 to +50 Celsius in increments
!  of 1 Celsius
      do i=0,151
        pwr81(i)=(173.15+i)**0.81
      enddo
!  rho*q from 0 to 50e-6 in increments of 1e-9
      do i=0,50001
        pwr2(i)=(i*1.0e-9)**bwq
      enddo
!-----------------------------------------------
      END subroutine consat


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


!***********************************************************************
      SUBROUTINE CONSAT2(d2t)
      implicit none
      real d2t
      R10T=RN10*D2T
      R11AT=RN11A*D2T
      R19BT=RN19B*D2T
      R20T=-RN20*D2T
      R23T=-RN23*D2T
      END subroutine consat2

  END MODULE goddard_module
hifrq.F/        1744672191  3193  100   100644  53923     `
  MODULE hifrq_module

  implicit none

  private
  public :: writeout_hifrq

  integer, parameter :: fnum = 67
  integer, parameter :: varmax = 10000

  integer :: ncid,wloop

  CONTAINS

!-------------------------------------------------------------------------------
!
!  hifrq:  code to write some output at a relatively high frequency
!          (compared to standard 3d output)
!
!-------------------------------------------------------------------------------

    subroutine writeout_hifrq(                                                 &
                   nstep,mtime,nwriteh,qname,dt,dosfcflx,                      &
                   icrs,icenter,jcenter,xcenter,ycenter,                       &
                   xh,rxh,arh1,arh2,uh,ruh,xf,rxf,arf1,arf2,uf,ruf,            &
                   yh,vh,rvh,yf,vf,rvf,                                        &
                   xfref,xhref,yfref,yhref,rds,sigma,rdsf,sigmaf,              &
                   tauh,taus,zh,mh,rmh,c1,c2,tauf,zf,mf,rmf,                   &
                   rho0s,pi0s,prs0s,rth0s,                                     &
                   pi0,rho0,prs0,thv0,th0,rth0,qv0,qc0,u0,v0,                  &
                   qi0,rr0,rf0,rrf0,                                           &
                   zs,gz,rgz,gzu,rgzu,gzv,rgzv,dzdx,dzdy,gx,gxu,gy,gyv,        &
                   tsk,znt,ust,stau,thflux,qvflux,cd,ch,cq,u1,v1,s1,xland,psfc,tlh,psmth, &
                   dum1,dum2,dum3,dum4,dum5,dum6,dum7,dum8,                    &
                   divx,rho,rr,rf,prs,t11,t12,t13,t22,t23,t33,                 &
                   rru,u3d,ugr ,utmp ,                                         &
                   rrv,v3d,vgr ,vtmp ,                                         &
                   rrw,w3d,wten,wtmp ,                                         &
                   pp3d,ppten,sten,th3d,sadv,thten,thten1,                     &
                   q3d,qten,kmh,kmv,khh,khv,tkea,tke3d,tketen,                 &
                   nm,defv,defh,dissten,                                       &
                   thpten,qvpten,qcpten,qipten,upten,vpten,xkzh,xkzq,xkzm,     &
                   rain,raincv,u10,v10,s10,br,brcr,hpbl,t2,q2,hfx,qfx,prate,cm0, &
                   swten,lwten,cldfra,qke,                                     &
                   lwupt,lwuptc,lwdnt,lwdntc,lwupb,lwupbc,lwdnb,lwdnbc,        &
                   swupt,swuptc,swdnt,swdntc,swupb,swupbc,swdnb,swdnbc,        &
                   lwcf,swcf,wprof,dumk1,dumk2,                                &
                   tdiag,qdiag,udiag,vdiag,wdiag,pdiag,out2d,out3d,getdbz,getvt, &
                   cir,crr,cangle,                                             &
                   myi1p,myi2p,myj1p,myj2p,kbdy,bndy,                          &
                   sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,flag,               &
                   dat1,dat2,dat3,reqt,reqs_s)
        ! end hifrq
    use input
    use constants
    use cm1libs , only : rslf,rsif
!!!    use adv_module , only : advs
    use bc_module
    use ib_module
#ifdef NETCDF
    use writeout_nc_module , only : writehifrq_nc
#endif
#ifdef MPI
    use comm_module
    use mpi
#endif
    implicit none

    integer, intent(in) :: nstep
    double precision, intent(in) :: mtime
    integer, intent(inout) :: nwriteh
    character(len=3), intent(in), dimension(maxq) :: qname
    real, intent(inout) :: dt
    logical, intent(in) :: dosfcflx
    integer, intent(in) :: icrs
    integer, intent(inout) :: icenter,jcenter
    real,    intent(inout) :: xcenter,ycenter
    real, intent(in), dimension(ib:ie) :: xh,rxh,arh1,arh2,uh,ruh
    real, intent(in), dimension(ib:ie+1) :: xf,rxf,arf1,arf2,uf,ruf
    real, intent(in), dimension(jb:je) :: yh,vh,rvh
    real, intent(in), dimension(jb:je+1) :: yf,vf,rvf
    real, intent(in), dimension(1-ngxy:nx+ngxy+1) :: xfref,xhref
    real, intent(in), dimension(1-ngxy:ny+ngxy+1) :: yfref,yhref
    real, intent(in), dimension(kb:ke) :: rds,sigma
    real, intent(in), dimension(kb:ke+1) :: rdsf,sigmaf
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: tauh,taus,zh,mh,rmh,c1,c2
    real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: tauf,zf,mf,rmf
    real, intent(in), dimension(ib:ie,jb:je) :: rho0s,pi0s,prs0s,rth0s
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: pi0,rho0,prs0,thv0,th0,rth0,qv0,qc0
    real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: u0
    real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: v0
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: qi0,rr0,rf0,rrf0
    real, intent(in), dimension(ib:ie,jb:je) :: zs
    real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,rgzu,gzv,rgzv,dzdx,dzdy
    real, intent(in), dimension(itb:ite,jtb:jte,ktb:kte) :: gx,gxu,gy,gyv
    real, intent(in), dimension(ib:ie,jb:je) :: tsk,znt,ust,stau,thflux,qvflux,cd,ch,cq,  &
                                                u1,v1,s1,xland,psfc,tlh,psmth
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum1,dum2,dum3,dum4,dum5,dum6,dum7,dum8
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: divx,rho,rr,rf,prs
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: t11,t12,t13,t22,t23,t33
    real, intent(inout), dimension(ib:ie+1,jb:je,kb:ke) :: rru,u3d,ugr,utmp
    real, intent(inout), dimension(ib:ie,jb:je+1,kb:ke) :: rrv,v3d,vgr,vtmp
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: rrw,w3d,wten,wtmp
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: pp3d,ppten,sten
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: th3d,sadv,thten,thten1
    real, intent(inout), dimension(ibm:iem,jbm:jem,kbm:kem,numq) :: q3d,qten
    real, intent(inout), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmh,kmv,khh,khv
    real, intent(inout), dimension(ibt:iet,jbt:jet,kbt:ket) :: tkea,tke3d,tketen
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: nm,defv,defh,dissten
    real, intent(in), dimension(ibb:ieb,jbb:jeb,kbb:keb) :: thpten,qvpten,qcpten,qipten,upten,vpten
    real, intent(in), dimension(ibb:ieb,jbb:jeb,kbb:keb) :: xkzh,xkzq,xkzm
    real, intent(in), dimension(ib:ie,jb:je,nrain) :: rain,raincv
    real, intent(in), dimension(ibl:iel,jbl:jel) :: u10,v10,s10,br,brcr,hpbl,t2,q2,hfx,qfx
    real, intent(in), dimension(ib:ie,jb:je) :: prate,cm0
    real, intent(in), dimension(ibr:ier,jbr:jer,kbr:ker) :: swten,lwten,cldfra
    real, intent(in), dimension(ibmynn:iemynn,jbmynn:jemynn,kbmynn:kemynn) :: qke
    real, intent(in), dimension(ibr:ier,jbr:jer) :: lwupt,lwuptc,lwdnt,lwdntc,lwupb,lwupbc,lwdnb,lwdnbc
    real, intent(in), dimension(ibr:ier,jbr:jer) :: swupt,swuptc,swdnt,swdntc,swupb,swupbc,swdnb,swdnbc
    real, intent(inout), dimension(ibr:ier,jbr:jer) :: lwcf,swcf
    real, intent(in),    dimension(kb:ke) :: wprof
    double precision, intent(inout), dimension(kb:ke) :: dumk1,dumk2
    real, intent(inout) , dimension(ibdt:iedt,jbdt:jedt,kbdt:kedt,ntdiag) :: tdiag
    real, intent(in) , dimension(ibdq:iedq,jbdq:jedq,kbdq:kedq,nqdiag) :: qdiag
    real, intent(in) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nudiag) :: udiag
    real, intent(in) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nvdiag) :: vdiag
    real, intent(in) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nwdiag) :: wdiag
    real, intent(in) , dimension(ibdp:iedp,jbdp:jedp,kbdp:kedp,npdiag) :: pdiag
    real, intent(inout), dimension(ib2d:ie2d,jb2d:je2d,nout2d) :: out2d
    real, intent(inout) , dimension(ib3d:ie3d,jb3d:je3d,kb3d:ke3d,nout3d) :: out3d
    logical, intent(in) :: getdbz,getvt
    integer, intent(in), dimension(ib:ie,jb:je) :: cir
    real, intent(in), dimension(ib:ie,jb:je) :: crr,cangle
    integer, intent(in), dimension(numprocs) :: myi1p,myi2p,myj1p,myj2p
    integer, intent(in), dimension(ibib:ieib,jbib:jeib) :: kbdy
      logical, intent(in), dimension(ibib:ieib,jbib:jeib,kbib:keib) :: bndy
    real, intent(inout), dimension(cmp,jmp,kmp)   :: sw31,sw32,se31,se32
    real, intent(inout), dimension(imp,cmp,kmp)   :: ss31,ss32,sn31,sn32
    logical, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: flag
    real, intent(inout), dimension(d3is,d3js) :: dat1
    real, intent(inout), dimension(d2is,d2js) :: dat2
    real, intent(inout), dimension(d3is,d3js,0:d3n-1) :: dat3
    integer, intent(inout), dimension(d3t) :: reqt
    integer, dimension(rmp) :: reqs_s

    !---------------------------------------------------------------------------

    integer :: nvar,orec,i,j,k,n,nn,nlevels,diffit,wloopmax
    real :: delz,delzmin,pint,plast,qvs,tx,havg,ucrit
    logical :: doit,domse
    double precision :: sum,weps,bfoo

    integer, dimension(nk) :: klev
    real, dimension(nk) :: zlev

    character(len=80), dimension(varmax) :: varname,vardesc,varunit
    integer, dimension(varmax) :: varlvls
    character(len=80) :: a1,a2
    character(len=16) :: a16

    !---------------------------------------------------------------------------

      if( myid.eq.0 ) print *
      if( myid.eq.0 ) print *,'  Entering writeout_hifrq ... '
      if( myid.eq.0 ) print *

      nlevels = 5
      zlev(1) =     0.0
      zlev(2) =   500.0
      zlev(3) =  1000.0
      zlev(4) =  2500.0
      zlev(5) =  5000.0

      if(myid.eq.0) print *
      if(myid.eq.0) print *,'  levels for hifrq output: '

      if(myid.eq.0) print *
      if(myid.eq.0) print *,'    ... requested levels ...'
      do n=1,nlevels
        if(myid.eq.0) print *,'    n,z = ',n,zlev(n)
      enddo

      ! find level that is closest to the requested level:
      do n=1,nlevels
        if( zlev(n).le.maxz )then
          delzmin = 1.0e30
          ! search from top, so that "ties" go to higher level
          do k=nk,1,-1
            delz = abs(sigma(k)-zlev(n))
            if( delz.lt.delzmin )then
              delzmin = delz
              klev(n) = k
            endif
          enddo
        else
          klev(n) = nk+1
        endif
      enddo

      if(myid.eq.0) print *
      if(myid.eq.0) print *,'    ... first pass ...'
      do n=1,nlevels
        if(myid.eq.0) print *,'    k,z = ',klev(n),sigma(klev(n))
      enddo

      ! make sure the same level is not selected more than once:
      do n=2,nlevels
        klev(n) = max( klev(n) , klev(n-1)+1 )
      enddo

      ! check that levels do not exceed nk:
      n = 1
      do while( n .le. nlevels )
        if( sigma(n).ge.maxz .or. klev(n).gt.nk )then
          nlevels = n-1
        endif
        n = n+1
      enddo

      if(myid.eq.0) print *
      if(myid.eq.0) print *,'    ... after checks ...'

      do n=1,nlevels
        if(myid.eq.0) print *,'    k,z = ',klev(n),sigma(klev(n))
      enddo

      if( nlevels.le.0 )then
        if(myid.eq.0)then
        print *
        print *,'  nlevels = 0,  no levels found '
        print *
        print *,'   stopping model in hifrq.F .... '
        print *
        endif
#ifdef MPI
        call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif
        call stopcm1
      endif

    !---------------------------------------------------------------------------
    ! open file:

      if( myid.eq.0 ) print *,'  nwriteh = ',nwriteh

      IF( output_format.eq.1 )THEN

        ! grads-format

        string = 'cm1out_hf_XXXXXX.dat'

        write(string(11:16),201) nwriteh
201     format(i6.6)

        if( myid.eq.0 )then
          print *,string
          close(unit=fnum)
          open(unit=fnum,file=string,form='unformatted',access='direct',recl=4*nx*ny)
        endif

        orec = 1

        wloopmax = 1

      ELSEIF( output_format.eq.2 )THEN

        ! netcdf-format
#ifdef NETCDF

        do i=1,maxstring
          string(i:i) = ' '
        enddo

        string = 'cm1out_hf_XXXXXX.nc'
        write(string(11:16),201) nwriteh
        if( myid.eq.0 ) print *,string

        wloopmax = 2

#endif
      ELSE

        print *
        print *,'  output_format = ',output_format
        print *
        print *,'  Invalid value for output_format in domaindiag '
        print *
        call stopcm1

      ENDIF

    !---------------------------------------------------------------------------

  bigwloop:  &
  DO wloop = 1 , wloopmax

      if( myid.eq.0 ) print *,'  wloop = ',wloop

      nvar = 0

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'mtime'
      vardesc(nvar) = 'model time (seconds since beginning of simulation)'
      varunit(nvar) = 's'
      varlvls(nvar) = 0

      do j=1,nj
      do i=1,ni
        dum1(i,j,1) = mtime
      enddo
      enddo

      call writehf(1,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

    IF( imoist.eq.1 )THEN

      nvar = nvar+1
      varname(nvar) = 'rain'
      vardesc(nvar) = 'accumulated surface rainfall'
      varunit(nvar) = 'cm'
      varlvls(nvar) = 0

      call writehf(1,rain(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( imoist.eq.1 .and. nrain.ge.2 )THEN

      nvar = nvar+1
      varname(nvar) = 'rain2'
      vardesc(nvar) = 'accumulated surface rainfall (translated)'
      varunit(nvar) = 'cm'
      varlvls(nvar) = 0

      call writehf(1,rain(ib,jb,2),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( imoist.eq.1 .and. cuparam.ge.1 )THEN

      nvar = nvar+1
      varname(nvar) = 'raincv'
      vardesc(nvar) = 'accumulated surface rainfall (convective, param.)'
      varunit(nvar) = 'cm'
      varlvls(nvar) = 0

      call writehf(1,raincv(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( imoist.eq.1 .and. cuparam.ge.1 .and. nrain.ge.2 )THEN

      nvar = nvar+1
      varname(nvar) = 'raincv2'
      vardesc(nvar) = 'translated accumulated surface rainfall (convective, param.)'
      varunit(nvar) = 'cm'
      varlvls(nvar) = 0

      call writehf(1,raincv(ib,jb,2),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( imoist.eq.1 )THEN

      nvar = nvar+1
      varname(nvar) = 'prate'
      vardesc(nvar) = 'surface precipitation rate'
      varunit(nvar) = 'kg/m2/s'
      varlvls(nvar) = 0

      call writehf(1,prate,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'thflux'
      vardesc(nvar) = 'surface potential temperature flux'
      varunit(nvar) = 'K m/s'
      varlvls(nvar) = 0

      call writehf(1,thflux,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

    IF( imoist.eq.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'qvflux'
      vardesc(nvar) = 'surface water vapor mixing ratio flux'
      varunit(nvar) = 'g/g m/s'
      varlvls(nvar) = 0

      call writehf(1,qvflux,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'hfx'
      vardesc(nvar) = 'surface sensible heat flux'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,hfx,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'qfx'
      vardesc(nvar) = 'surface latent heat flux'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,qfx,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'u10'
    if( imove.eq.1 )then
      vardesc(nvar) = 'u comp. of 10m wind speed (ground-rel.)'
    else
      vardesc(nvar) = 'u comp. of 10m wind speed'
    endif
      varunit(nvar) = 'm/s'
      varlvls(nvar) = 0

      call writehf(1,u10,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'v10'
    if( imove.eq.1 )then
      vardesc(nvar) = 'v comp. of 10m wind speed (ground-rel.)'
    else
      vardesc(nvar) = 'v comp. of 10m wind speed'
    endif
      varunit(nvar) = 'm/s'
      varlvls(nvar) = 0

      call writehf(1,v10,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

  !---------------------------------------------------------------------

    IF( sfcmodel.ge.1 )THEN

    ! radial and tangential velocity:
    doit = .true.

    docylsfc:  &
    if( doit )then
    if( doazimavg .or. do_adapt_move )then

              ! dum1 = u at s pts
              ! dum2 = v at s pts
              ! dum3 = ur at s pts
              ! dum4 = vt at s pts

        k = 1
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = u10(i,j)
          dum2(i,j,k) = v10(i,j)
          if( abs(crr(i,j)).lt.1.0e-4 )then
            dum3(i,j,k)=0.0
            dum4(i,j,k)=0.0
          else
            dum3(i,j,k)=dum2(i,j,k)*sin(cangle(i,j))+dum1(i,j,k)*cos(cangle(i,j))
            dum4(i,j,k)=dum2(i,j,k)*cos(cangle(i,j))-dum1(i,j,k)*sin(cangle(i,j))
          endif
        enddo
        enddo

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'urad10'
      vardesc(nvar) = 'rad. comp. of 10m wind speed (ground-rel.)'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = 0

      call writehf(1,dum3(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'vtan10'
      vardesc(nvar) = 'tang. comp. of 10m wind speed (ground-rel.)'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = 0

      call writehf(1,dum4(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

    endif
    endif  docylsfc

    ENDIF

  !---------------------------------------------------------------------

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 't2'
      vardesc(nvar) = 'diagnostic 2m temperature'
      varunit(nvar) = 'K'
      varlvls(nvar) = 0

      call writehf(1,t2,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'q2'
      vardesc(nvar) = 'diagnostic 2m mixing ratio'
      varunit(nvar) = 'kg/kg'
      varlvls(nvar) = 0

      call writehf(1,q2,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'ust'
      vardesc(nvar) = 'friction velocity (u star)'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = 0

      call writehf(1,ust,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'stau'
      vardesc(nvar) = 'surface stress'
      varunit(nvar) = 'm2/s2'
      varlvls(nvar) = 0

      call writehf(1,stau,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'znt'
      vardesc(nvar) = 'surface roughness length'
      varunit(nvar) = 'm'
      varlvls(nvar) = 0

      call writehf(1,znt,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'psfc'
      vardesc(nvar) = 'surface pressure'
      varunit(nvar) = 'Pa'
      varlvls(nvar) = 0

      call writehf(1,psfc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    if( do_adapt_move )then
      nvar = nvar+1
      varname(nvar) = 'psmth'
      vardesc(nvar) = 'psmth'
      varunit(nvar) = 'Pa'
      varlvls(nvar) = 0

      call writehf(1,psmth,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    endif

      !c-c-c-c-c-c-c-c-c-c

    IF( output_dbz.eq.1 .and. qd_dbz.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'cref'
      vardesc(nvar) = 'composite reflectivity'
      varunit(nvar) = 'dbz'
      varlvls(nvar) = 0

      do j=1,nj
      do i=1,ni
        dum1(i,j,1) = -1000.0
      enddo
      enddo

      do k=1,nk
      do j=1,nj
      do i=1,ni
        dum1(i,j,1) = max( dum1(i,j,1) , qdiag(i,j,k,qd_dbz) )
      enddo
      enddo
      enddo

      call writehf(1,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( imoist.eq.1 )THEN
      ! water paths, precipitable water:

      do j=1,nj
      do i=1,ni
        dum1(i,j,1) = 0.0
        dum1(i,j,2) = 0.0
        dum1(i,j,3) = 0.0
        dum1(i,j,4) = 0.0
      enddo
      enddo

      do k=1,nk
        if( nqv.ge.1 )then
          do j=1,nj
          do i=1,ni
            dum1(i,j,1) = dum1(i,j,1) + rho(i,j,k)*q3d(i,j,k,nqv)*dz*rmh(i,j,k)
            qvs = rslf(prs(i,j,k),(th0(i,j,k)+th3d(i,j,k))*(pi0(i,j,k)+pp3d(i,j,k)))
            dum1(i,j,4) = dum1(i,j,4) + rho(i,j,k)*qvs*dz*rmh(i,j,k)
          enddo
          enddo
        endif
        if( nqc.ge.1 )then
          do j=1,nj
          do i=1,ni
            dum1(i,j,2) = dum1(i,j,2) + rho(i,j,k)*q3d(i,j,k,nqc)*dz*rmh(i,j,k)
          enddo
          enddo
        endif
        if( nqr.ge.1 )then
          do j=1,nj
          do i=1,ni
            dum1(i,j,2) = dum1(i,j,2) + rho(i,j,k)*q3d(i,j,k,nqr)*dz*rmh(i,j,k)
          enddo
          enddo
        endif
        if( nqs.ge.1 )then
          do j=1,nj
          do i=1,ni
            dum1(i,j,3) = dum1(i,j,3) + rho(i,j,k)*q3d(i,j,k,nqs)*dz*rmh(i,j,k)
          enddo
          enddo
        endif
        if( nqg.ge.1 )then
          do j=1,nj
          do i=1,ni
            dum1(i,j,3) = dum1(i,j,3) + rho(i,j,k)*q3d(i,j,k,nqg)*dz*rmh(i,j,k)
          enddo
          enddo
        endif
        if( nqi.ge.1 )then
          do j=1,nj
          do i=1,ni
            dum1(i,j,3) = dum1(i,j,3) + rho(i,j,k)*q3d(i,j,k,nqi)*dz*rmh(i,j,k)
          enddo
          enddo
        endif
      enddo

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'prw'
      vardesc(nvar) = 'water vapor path'
      varunit(nvar) = 'kg/m^2'
      varlvls(nvar) = 0

      call writehf(1,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'clwvi'
      vardesc(nvar) = 'condensed water path'
      varunit(nvar) = 'kg/m^2'
      varlvls(nvar) = 0

      call writehf(1,dum1(ib,jb,2),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'clivi'
      vardesc(nvar) = 'ice water path'
      varunit(nvar) = 'kg/m^2'
      varlvls(nvar) = 0

      call writehf(1,dum1(ib,jb,3),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'spwr'
      vardesc(nvar) = 'saturated water vapor path'
      varunit(nvar) = 'kg/m^2'
      varlvls(nvar) = 0

      call writehf(1,dum1(ib,jb,4),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

    if( idoles .and. cm1setup.eq.4 )then
      nvar = nvar+1
      varname(nvar) = 'cm0'
      vardesc(nvar) = 'cm0'
      varunit(nvar) = 'unitless'
      varlvls(nvar) = 0

      call writehf(1,cm0,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    endif

      !c-c-c-c-c-c-c-c-c-c

    IF( (cm1setup.eq.2.or.cm1setup.eq.4) .and. horizturb.eq.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'tlh'
      vardesc(nvar) = 'horiz lengthscale for turbulence scheme'
      varunit(nvar) = 'm'
      varlvls(nvar) = 0

      call writehf(1,tlh,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'lwupt'
      vardesc(nvar) = 'lw flux, upward, top of atmosphere (OLR)'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,lwupt,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'lwdnt'
      vardesc(nvar) = 'lw flux, downward, top of atmosphere'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,lwdnt,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'lwupb'
      vardesc(nvar) = 'lw flux, upward, bottom of atmosphere'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,lwupb,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'lwdnb'
      vardesc(nvar) = 'lw flux, downward, bottom of atmosphere'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,lwdnb,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'swupt'
      vardesc(nvar) = 'sw flux, upward, top of atmosphere'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,swupt,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'swdnt'
      vardesc(nvar) = 'sw flux, downward, top of atmosphere'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,swdnt,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'swupb'
      vardesc(nvar) = 'sw flux, upward, bottom of atmosphere'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,swupb,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'swdnb'
      vardesc(nvar) = 'sw flux, downward, bottom of atmosphere'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,swdnb,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'lwuptc'
      vardesc(nvar) = 'lw flux, upward, top of atmosphere - clear sky'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,lwuptc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'lwdntc'
      vardesc(nvar) = 'lw flux, downward, top of atmosphere - clear sky'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,lwdntc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'lwupbc'
      vardesc(nvar) = 'lw flux, upward, bottom of atmosphere - clear sky'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,lwupbc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'lwdnbc'
      vardesc(nvar) = 'lw flux, downward, bottom of atmosphere - clear sky'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,lwdnbc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'swuptc'
      vardesc(nvar) = 'sw flux, upward, top of atmosphere - clear sky'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,swuptc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'swdntc'
      vardesc(nvar) = 'sw flux, downward, top of atmosphere - clear sky'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,swdntc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'swupbc'
      vardesc(nvar) = 'sw flux, upward, bottom of atmosphere - clear sky'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,swupbc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( radopt.eq.2 )THEN
      nvar = nvar+1
      varname(nvar) = 'swdnbc'
      vardesc(nvar) = 'sw flux, downward, bottom of atmosphere - clear sky'
      varunit(nvar) = 'W/m^2'
      varlvls(nvar) = 0

      call writehf(1,swdnbc,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    doit = .false.
    IF( doit )THEN
      nvar = nvar+1
      varname(nvar) = 'wa500'
      vardesc(nvar) = 'vertical velocity at 500 mb'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = 0

          !$omp parallel do default(shared)  &
          !$omp private(i,j,k,pint,plast)
          do j=1,nj
          do i=1,ni
            pint = 1.0e30
            k = 1
            do while( pint.gt.50000.0 .and. k.lt.nk )
              plast = pint
              k = k + 1
              pint = 0.5*(prs(i,j,k-1)+prs(i,j,k))
            enddo
            dum1(i,j,1) = w3d(i,j,k-1)+(w3d(i,j,k)-w3d(i,j,k-1))  &
                                      *(50000.0-plast)  &
                                      /(pint-plast)
          enddo
          enddo

      call writehf(1,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    domse = .false.

    IF( domse .and. imoist.eq.1 )THEN

      !$omp parallel do default(shared)  &
      !$omp private(i,j)
      do j=1,nj
      do i=1,ni
        dum2(i,j,1) = 0.0
      enddo
      enddo

      ! dum8 stores qice:
      if( iice.eq.1 )then
        dum8 = 0.0
      else
        do k=1,nk
          do j=1,nj
          do i=1,ni
            dum8(i,j,k) = 0.0
          enddo
          enddo
          do n=nqs1,nqs2
          do j=1,nj
          do i=1,ni
            dum8(i,j,k) = dum8(i,j,k)+q3d(i,j,k,n)
          enddo
          enddo
          enddo
        enddo
      endif

      do k=1,nk
      do j=1,nj
      do i=1,ni
        tx = (th0(i,j,k)+th3d(i,j,k))*(pi0(i,j,k)+pp3d(i,j,k))
        sadv(i,j,k) = cp*tx + g*zh(i,j,k)            &
                    +(lv1-lv2*tx)*q3d(i,j,k,nqv)     &
                    -((ls1-ls2*tx)-(lv1-lv2*tx))*dum8(i,j,k)
        dum2(i,j,1) = dum2(i,j,1) + rho(i,j,k)*sadv(i,j,k)*dz*rmh(i,j,k)
      enddo
      enddo
      enddo

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'fmse'
      vardesc(nvar) = 'mass-wgted vert intgrl of frzn moist static energy'
      varunit(nvar) = 'J/m^2'
      varlvls(nvar) = 0

      call writehf(1,dum2(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      sum = 0.0

      do j=1,nj
      do i=1,ni
        sum = sum + dum2(i,j,1)
      enddo
      enddo

#ifdef MPI
      call MPI_ALLREDUCE(MPI_IN_PLACE,sum,1,MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,ierr)
#endif

      havg = ( sum/dble(nx*ny) )

      do j=1,nj
      do i=1,ni
        dum2(i,j,2) = dum2(i,j,1)-havg
      enddo
      enddo

      nvar = nvar+1
      varname(nvar) = 'fmsepert'
      vardesc(nvar) = 'perturbation fmse'
      varunit(nvar) = 'J/m^2'
      varlvls(nvar) = 0

      call writehf(1,dum2(ib,jb,2),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      call bcs(sadv)
#ifdef MPI
      call comm_3s_start(sadv,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,reqs_s)
      call comm_3s_end(  sadv,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,reqs_s)
#endif

    if( td_hadv.ge.1 .and. td_vadv.ge.1 .and. ptype.eq.91919 )then

      stop 111

        diffit = 0
        bfoo = 0.0
        weps = cp*10.0*epsilon

!        call advs( 3 ,1,0,bfoo,xh,rxh,arh1,arh2,uh,ruh,xf,vh,rvh,gz,rgz,mh,rmh,           &
!                   rho0,rr0,rf0,rrf0,dum1,dum2,dum3,dum4,dum5,dum6,dum7,dum8,divx,        &
!                   rru,rrv,rrw,th3d,sadv,thten,0,0,dt   ,weps,                             &
!                   flag,sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,rdsf,c1,c2,rho,rr,diffit, &
!                   .true.,ibdt,iedt,jbdt,jedt,kbdt,kedt,ntdiag,tdiag,td_hadv,td_vadv,td_lsw, &
!                   td_hidiff,td_vidiff,td_hediff,wprof,dumk1,dumk2,hadvordrs,vadvordrs,kbdy,bndy,out3d)

      !$omp parallel do default(shared)  &
      !$omp private(i,j)
      do j=1,nj
      do i=1,ni
        dum3(i,j,1) = 0.0
        dum4(i,j,1) = 0.0
      enddo
      enddo

      do k=1,nk
      do j=1,nj
      do i=1,ni
        dum3(i,j,1) = dum3(i,j,1) + tdiag(i,j,k,td_hadv)*rho(i,j,k)*dz*rmh(i,j,k)
        dum4(i,j,1) = dum4(i,j,1) + tdiag(i,j,k,td_vadv)*rho(i,j,k)*dz*rmh(i,j,k)
      enddo
      enddo
      enddo

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'hadvfmse'
      vardesc(nvar) = 'vert intgrl of horiz advection of fmse'
      varunit(nvar) = 'J/m^2/s'
      varlvls(nvar) = 0

      call writehf(1,dum3(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'vadvfmse'
      vardesc(nvar) = 'vert intgrl of vert advection of fmse'
      varunit(nvar) = 'J/m^2/s'
      varlvls(nvar) = 0

      call writehf(1,dum4(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

    endif

      !c-c-c-c-c-c-c-c-c-c

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'th'
      vardesc(nvar) = 'potential temperature (K)'
      varunit(nvar) = 'K'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = th0(i,j,k)+th3d(i,j,k)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'prs'
      vardesc(nvar) = 'pressure'
      varunit(nvar) = 'Pa'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = prs(i,j,k)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'uinterp '
      vardesc(nvar) = 'u interpolated to scalar points (grid-relative)'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = 0.5*(u3d(i,j,k)+u3d(i+1,j,k))
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'vinterp '
      vardesc(nvar) = 'v interpolated to scalar points (grid-relative)'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = 0.5*(v3d(i,j,k)+v3d(i,j+1,k))
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    ! radial and tangential velocity:
    doit = .true.

    docyl:  &
    if( doit )then

      if(myid.eq.0) print *,'  doazimavg,do_adapt_move = ',doazimavg,do_adapt_move

    if( doazimavg .or. do_adapt_move )then

              ! dum1 = u at s pts
              ! dum2 = v at s pts
              ! dum3 = ur at s pts
              ! dum4 = vt at s pts

        do k=1,klev(nlevels)
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = 0.5*(u3d(i,j,k)+u3d(i+1,j,k)) + umove
          dum2(i,j,k) = 0.5*(v3d(i,j,k)+v3d(i,j+1,k)) + vmove
          if( abs(crr(i,j)).lt.1.0e-4 )then
            dum3(i,j,k)=0.0
            dum4(i,j,k)=0.0
          else
            dum3(i,j,k)=dum2(i,j,k)*sin(cangle(i,j))+dum1(i,j,k)*cos(cangle(i,j))
            dum4(i,j,k)=dum2(i,j,k)*cos(cangle(i,j))-dum1(i,j,k)*sin(cangle(i,j))
          endif
        enddo
        enddo
        enddo

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'urad'
      vardesc(nvar) = 'radial velocity (grnd-rel)'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = dum3(i,j,k)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'vtan'
      vardesc(nvar) = 'tangential velocity (grnd-rel)'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = dum4(i,j,k)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

      ucrit = -2.0

      ! inflow layer depth:
      do j=1,nj
      do i=1,ni
        if( dum3(i,j,1).lt.ucrit )then
          k = 1
          do while( dum3(i,j,k).lt.ucrit .and. k.le.nk )
            k = k+1
          enddo
          dum1(i,j,1) = zh(1,1,k-1)+(zh(1,1,k)-zh(1,1,k-1))  &
                                  *(    ucrit-dum3(i,j,k-1))  &
                                  /(dum3(i,j,k)-dum3(i,j,k-1))
        else
          dum1(i,j,1) = 0.0
        endif
      enddo
      enddo

      nvar = nvar+1
      varname(nvar) = 'zinfl'
      vardesc(nvar) = 'depth of inflow layer (u < -2 m/s)'
      varunit(nvar) = 'm'
      varlvls(nvar) = 0

      call writehf(1,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

    endif

    ENDIF  docyl

  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      !c-c-c-c-c-c-c-c-c-c

      nvar = nvar+1
      varname(nvar) = 'winterp '
      vardesc(nvar) = 'w interpolated to scalar points'
      varunit(nvar) = 'm/s'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = 0.5*(w3d(i,j,k)+w3d(i,j,k+1))
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)

      !c-c-c-c-c-c-c-c-c-c

    IF( imoist.eq.1 .and. nqv.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'qv'
      vardesc(nvar) = 'water vapor mixing ratio'
      varunit(nvar) = 'kg/kg'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = q3d(i,j,k,nqv)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( output_dbz.eq.1 .and. qd_dbz.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'dbz'
      vardesc(nvar) = 'reflectivity'
      varunit(nvar) = 'dbz'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = klev(n)
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = qdiag(i,j,k,qd_dbz)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sgsmodel.eq.1 .or. sgsmodel.eq.4 )THEN
      nvar = nvar+1
      varname(nvar) = 'tke'
      vardesc(nvar) = 'tke'
      varunit(nvar) = 'm2/s2'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = max( 2 , klev(n) )
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = tke3d(i,j,k)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( sgsmodel.ge.1 .or. horizturb.ge.1 )THEN
      nvar = nvar+1
      varname(nvar) = 'kmh'
      vardesc(nvar) = 'kmh'
      varunit(nvar) = 'm2/s'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = max( 2 , klev(n) )
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = kmh(i,j,k)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c

    IF( ipbl.eq.4 .or. ipbl.eq.5 )THEN
      nvar = nvar+1
      varname(nvar) = 'qke'
      vardesc(nvar) = 'twice TKE from MYNN'
      varunit(nvar) = 'm^2/s^2'
      varlvls(nvar) = nlevels

      do n=1,nlevels
        k = max( 1 , klev(n) )
        do j=1,nj
        do i=1,ni
          dum1(i,j,n) = qke(i,j,k)
        enddo
        enddo
      enddo

      call writehf(nlevels,dum1(ib,jb,1),dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    ENDIF

      !c-c-c-c-c-c-c-c-c-c


    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    ! close output file:

    id0:  IF( myid.eq.0 )THEN

!-------------------------------------------------------------------
!  grads format

    of2:  &
    IF( output_format.eq.1 )THEN

        do i=1,maxstring
          string(i:i) = ' '
        enddo

        ! grads-format
        ! (by default, for now)

        ! close binary output file:
        close(unit=fnum)

        ! write descriptor file:
          string = 'cm1out_hf.ctl'
          open(unit=66,file=string)
          string = 'cm1out_hf_00%y4.dat'
          write(66,101) string
          write(66,102)
          if( outunits.eq.2 )then
            write(66,113) trim(cm1version)
          else
            write(66,103) trim(cm1version)
          endif
          write(66,104) grads_undef
            if(stretch_x.ge.1)then
              write(66,214) nx
              do i=1,nx
                write(66,217) outunitconv*( 0.5*(xfref(i)+xfref(i+1)) )
              enddo
            else
              write(66,204) nx,outunitconv*xh(1),outunitconv*dx
            endif
            if(stretch_y.ge.1)then
              write(66,215) ny
              do j=1,ny
                write(66,217) outunitconv*( 0.5*(yfref(j)+yfref(j+1)) )
              enddo
            else
              write(66,205) ny,outunitconv*yh(1),outunitconv*dy
            endif
            write(66,107) nlevels
            do k=1,nlevels
              write(66,217) outunitconv*sigma(klev(k))
            enddo
          write(66,108) nwriteh
          write(66,109) nvar
          do n=1,nvar
              a1 = varname(n)
              a2 = vardesc(n)
              !---
              a16 = '                '
              nn = len(trim(varunit(n)))
              write(a16(2:15),314) varunit(n)
              write(a16(1:1),301 )       '('
              write(a16(nn+2:nn+2),301 ) ')'
              !---
                write(66,110) a1(1:12),varlvls(n),a2(1:40),a16
          enddo
          write(66,111)
          close(unit=66)

 301    format(a1)
 314    format(a14)

 101    format('dset ^',a)
 102    format('options template')
 103    format('title CM1 high-frequency output, using version ',a,'; units of x,y,z are km; time is generic, see variable mtime for actual times')
 113    format('title CM1 high-frequency output, using version ',a,'; units of x,y,z are meters; time is generic, see variable mtime for actual times')
 104    format('undef ',f10.1)
! 105    format('xdef ',i6,' linear ',f13.6,1x,f13.6)
 105    format('xdef ',i6,' linear ',es14.6e2,1x,es14.6e2)
 106    format('ydef ',i6,' linear 0 1')
 107    format('zdef ',i6,' levels')
! 217    format(2x,f13.6)
 217    format(2x,es14.6e2)
 108    format('tdef ',i10,' linear 00:00Z01JAN0001 1YR')
 109    format('vars ',i6)
 110    format(a12,2x,i6,' 99 ',a40,1x,a16)
 111    format('endvars')

! 204    format('xdef ',i6,' linear ',f13.6,1x,f13.6)
! 205    format('ydef ',i6,' linear ',f13.6,1x,f13.6)
 204    format('xdef ',i6,' linear ',es14.6e2,1x,es14.6e2)
 205    format('ydef ',i6,' linear ',es14.6e2,1x,es14.6e2)

 214    format('xdef ',i6,' levels ')
 215    format('ydef ',i6,' levels ')

!-------------------------------------------------------------------
! netcdf format

#ifdef NETCDF
    ELSEIF( output_format.eq.2 )THEN  of2

      call       writehifrq_nc(wloop,nlevels,nvar,varmax,varname,vardesc,varunit,varlvls,ncid,xhref,yhref,sigma,klev,zlev,mtime,dat2(1,1),dat2(1,2),dum1(ib,jb,kb))

#endif
    ENDIF  of2

    ENDIF  id0

  ENDDO  bigwloop

      if( myid.eq.0 ) print *
      if( myid.eq.0 ) print *,'  ... Leaving writeout_hifrq '
      if( myid.eq.0 ) print *

    end subroutine writeout_hifrq


  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    subroutine writehf(nout,var,dat1,dat2,dat3,reqt,orec,nvar,varname,vardesc,varunit,myi1p,myi2p,myj1p,myj2p)
    use input
#ifdef NETCDF
    use writeout_nc_module, only : disp_err
    use netcdf
#endif
    implicit none

    integer, intent(in) :: nout
    real, intent(in), dimension(ib:ie,jb:je,nout) :: var
    real, intent(inout), dimension(d3is,d3js) :: dat1
    real, intent(inout), dimension(d2is,d2js) :: dat2
    real, intent(inout), dimension(d3is,d3js,0:d3n-1) :: dat3
    integer, intent(inout), dimension(d3t) :: reqt
    integer, intent(inout) :: orec
    integer, intent(in) :: nvar
    character(len=80), intent(in), dimension(varmax) :: varname,vardesc,varunit
    integer, intent(in), dimension(numprocs) :: myi1p,myi2p,myj1p,myj2p

    integer :: i,j,k,varid,status

  if( output_format.eq.1 .or. ( output_format.eq.2 .and. wloop.eq.2 ) )then

    if(myid.eq.0) print *,nvar,trim(varname(nvar))

    DO k = 1 , nout

      call gather(var(ib,jb,k),dat1(1,1),dat2(1,1),dat3(1,1,0),reqt,myi1p,myi2p,myj1p,myj2p)

      if( myid.eq.0 )then

        if( output_format.eq.1 )then
          ! grads-format file:
          write(fnum,rec=orec) ((dat2(i,j),i=1,nx),j=1,ny)
          orec=orec+1
#ifdef NETCDF
        elseif( output_format.eq.2 )then
          status = nf90_inq_varid(ncid,trim(varname(nvar)),varid)
          if(status.ne.nf90_noerr)then
            print *,'  Error in write3d, varname = ',varname(nvar)
            print *,nf90_strerror(status)
            call stopcm1
          endif
          call disp_err( nf90_put_var(ncid,varid,dat2,(/1,1,k,1/),(/nx,ny,1,1/)) , .true. )
#endif
        endif

      endif

    ENDDO

  endif

    end subroutine writehf


  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


    subroutine gather(var,dat1,dat2,dat3,reqt,myi1p,myi2p,myj1p,myj2p)
    use input
#ifdef MPI
    use mpi
#endif
    implicit none

    real, intent(in), dimension(ib:ie,jb:je) :: var
    real, intent(inout), dimension(d3is,d3js) :: dat1
    real, intent(inout), dimension(d2is,d2js) :: dat2
    real, intent(inout), dimension(d3is,d3js,0:d3n-1) :: dat3
    integer, intent(inout), dimension(d3t) :: reqt
    integer, intent(in), dimension(numprocs) :: myi1p,myi2p,myj1p,myj2p

    !----

    integer :: i,j
#ifdef MPI
    integer :: fooi,fooj,nn,nnn,n1,n2,ntot,index2,nitmp,njtmp
    integer :: index,tag,proc,reqs
    integer, dimension(mpi_status_size,ppnode-1) :: status1
#endif

    !-------------------------------------------------------------------
    ! This subroutine collects data (from other processors if this is a
    ! MPI run) 
    !-------------------------------------------------------------------

#ifdef MPI
    tag = 1111
#endif

#ifndef MPI
      !-------------------- non-MPI section --------------------!
!$omp parallel do default(shared)   &
!$omp private(i,j)
      do j=1,nj
      do i=1,ni
        dat2(i,j)=var(i,j)
      enddo
      enddo
#else
      !-------------------- MPI section --------------------!

      IF(myid.ne.nodeleader)THEN
        ! ordinary processor ... send data to nodeleader:
!$omp parallel do default(shared)   &
!$omp private(i,j)
        do j=1,nj
        do i=1,ni
          dat1(i,j)=var(i,j)
        enddo
        enddo
        call MPI_ISEND(dat1(1,1),d3is*d3js,MPI_REAL,nodeleader,tag,MPI_COMM_WORLD,reqs,ierr)
        call MPI_WAIT(reqs,MPI_STATUS_IGNORE,ierr)
        ! DONE, ordinary processors
      ELSE
        ! begin nodeleader section:
          ! start receives from all other processors on a node:
          do proc=myid+1,myid+(ppnode-1)
            call MPI_IRECV(dat3(1,1,proc),d3is*d3js,MPI_REAL,proc,tag,MPI_COMM_WORLD,reqt(proc-myid),ierr)
          enddo
        IF(myid.ne.0)THEN
          ! nodeleader, not proc 0:
!$omp parallel do default(shared)  &
!$omp private(i,j)
          do j=1,nj
          do i=1,ni
            dat3(i,j,myid)=var(i,j)
          enddo
          enddo
          ! wait for receives to finish:
          call mpi_waitall(ppnode-1,reqt(1:ppnode-1),status1,ierr)
          ! send data to processor 0:
          call MPI_ISEND(dat3(1,1,myid),d3is*d3js*ppnode,MPI_REAL,0,tag+1,MPI_COMM_WORLD,reqs,ierr)
          ! wait for send to finish:
          call MPI_WAIT(reqs,MPI_STATUS_IGNORE,ierr)
          ! DONE, nodeleader (not proc 0)
        ELSE
          ! proc 0:
            ! start receives from other nodeleaders:
            do nn = 1,(nodes-1)
              if( nn.le.mynode )then
                proc = (nn-1)*ppnode
              else
                proc = nn*ppnode
              endif
              call MPI_IRECV(dat3(1,1,proc),d3is*d3js*ppnode,MPI_REAL,proc,tag+1,MPI_COMM_WORLD,reqt(ppnode-1+nn),ierr)
            enddo
          ! my data:
!$omp parallel do default(shared)  &
!$omp private(i,j)
            do j=1,nj
            do i=1,ni
              dat2(i,j)=var(i,j)
            enddo
            enddo
          ! wait for data to arrive:
          ntot = ppnode-1 + nodes-1 
          do nn=1,ntot
            call mpi_waitany(ntot,reqt(1:ntot),index,MPI_STATUS_IGNORE,ierr)
            if( index.le.(ppnode-1) )then
              ! data from ordinary procs on node:
              proc = myid+index
              fooi = myi1p(proc+1)-1
              fooj = myj1p(proc+1)-1
              nitmp = myi2p(proc+1)-myi1p(proc+1)+1
              njtmp = myj2p(proc+1)-myj1p(proc+1)+1
!$omp parallel do default(shared)  &
!$omp private(i,j)
              do j=1,njtmp
              do i=1,nitmp
                dat2(fooi+i,fooj+j) = dat3(i,j,proc)
              enddo
              enddo
            else
              ! data from other nodeleaders:
              index2 = index-(ppnode-1)
              if( index2.le.mynode )then
                index2 = index2-1
              endif
              n1 = index2*ppnode
              n2 = (index2+1)*ppnode-1
              do nnn = n1,n2
                proc = nnn
                fooi = myi1p(proc+1)-1
                fooj = myj1p(proc+1)-1
                nitmp = myi2p(proc+1)-myi1p(proc+1)+1
                njtmp = myj2p(proc+1)-myj1p(proc+1)+1
!$omp parallel do default(shared)  &
!$omp private(i,j)
                do j=1,njtmp
                do i=1,nitmp
                  dat2(fooi+i,fooj+j) = dat3(i,j,proc)
                enddo
                enddo
              enddo
            endif
          enddo
          ! DONE, proc 0
        ENDIF
        !-------------------- end MPI section --------------------!
      ENDIF
      ! seems to help with memory:
      call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif


      end subroutine gather


  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
  !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


  END MODULE hifrq_module

ib_module.F/    1744672191  3193  100   100644  60025     `
  module ib_module
  implicit none

  public

    integer :: ibib,ieib,jbib,jeib,kbib,keib
    integer :: kmaxib


  CONTAINS

!-----------------------------------------------------------------------

    subroutine ib_setup

      !-----------------------------------------
      ! USE IMMERSED BOUNDARY TECHNIQUE?

!   since cm1r21.0 ... this is now set in the namelist (param20 section)
!!!        do_ib  =  .false.    

      !-----------------------------------------

    end subroutine ib_setup

!-----------------------------------------------------------------------

    subroutine init_immersed_boundaries(                                &
                       xh,yh,xf,yf,sigma,sigmaf,zs,zh,bndy,kbdy,out3d,  &
                       west,newwest,east,neweast,                       &
                       south,newsouth,north,newnorth,reqs_p)

    use input
    use constants
    use bc_module
    use comm_module
#ifdef MPI
    use mpi
#endif

      real, intent(in), dimension(ib:ie) :: xh
      real, intent(in), dimension(jb:je) :: yh
      real, intent(in), dimension(ib:ie+1) :: xf
      real, intent(in), dimension(jb:je+1) :: yf
      real, intent(in), dimension(kb:ke) :: sigma
      real, intent(in), dimension(kb:ke+1) :: sigmaf
      real, intent(in), dimension(ib:ie,jb:je) :: zs
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: zh
      logical, intent(inout), dimension(ibib:ieib,jbib:jeib,kbib:keib) :: bndy
      integer, intent(inout), dimension(ibib:ieib,jbib:jeib) :: kbdy
      integer, intent(inout), dimension(rmp) :: reqs_p
      real, intent(inout), dimension(cmp,jmp) :: west,newwest,east,neweast
      real, intent(inout), dimension(imp,cmp) :: south,newsouth,north,newnorth
      real, intent(inout), optional, dimension(ib3d:ie3d,jb3d:je3d,kb3d:ke3d,nout3d) :: out3d

      integer :: i,j,k,n
      real :: aa,hh,xc,xloc,yloc,foox,fooy,shift
      real, dimension(:,:), allocatable :: zsfoo


      ! Define immersed grid cells when do_ib = .true.


      ! Set case here:

      ib_init  =  4



      allocate( zsfoo(ib:ie,jb:je) )
      zsfoo = 0.0

    !c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c

      IF( ib_init.eq.1 )THEN

        !  standard nh mountain wave case:

        hh =      400.0              ! max. height (m)
        aa =     1000.0              ! half width (m)
        xc =        0.0 + 0.5*dx     ! x-location (m)

        do j=jb,je
        do i=ib,ie
          zsfoo(i,j) = hh/( 1.0+( (xh(i)-xc)/aa )**2 )
        enddo
        enddo

      ENDIF

    !c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c

      IF( ib_init.eq.2 )THEN

        !  2D block for tests of advection scheme:

        hh =      400.0              ! max. height (m)

        if( nx.eq.1 )then
          do j=jb,je
          do i=ib,ie
            if( abs(yh(j)-centery).le.400.0 ) zsfoo(i,j) = hh
          enddo
          enddo
        else
          do j=jb,je
          do i=ib,ie
            if( abs(xh(i)-centerx).le.400.0 ) zsfoo(i,j) = hh
          enddo
          enddo
        endif

      ENDIF

    !c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c

      IF( ib_init.eq.3 )THEN

        ! multiple cubes

      do n=1,1
        if( n.eq.1 ) yloc = 0.5*maxy
        if( n.eq.2 ) yloc = 0.5*maxy + 3.0*100.0
        if( n.eq.3 ) yloc = 0.5*maxy - 3.0*100.0
        print *,'  n,yloc = ',n,yloc
        do j=jb,je
        do i=ib,ie
          ! place obstacle roughly 1/3 across the domain:
          if( abs(xh(i)-(minx+(maxx-minx)/3.0+360.0)).le.60.0 .and. abs(yh(j)-centery).le.60.0 ) zsfoo(i,j) = 120.0
        enddo
        enddo
      enddo

      ENDIF

    !c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c

    IF( ib_init.eq.4 )THEN

      ! Martinuzzi and Tropea (1993, JFE) wind tunnel channel case:

    IF( ny.eq.1 )THEN
      do j=jb,je
      do i=ib,ie
        if( abs(xh(i)-(minx+0.50*(maxx-minx)) ).le.(0.25*maxz) )then
          zsfoo(i,j) = 0.5*maxz
        endif
      enddo
      enddo
    ELSEIF( nx.eq.1 )THEN
      stop 12321
    ELSE
      do j=jb,je
      do i=ib,ie
        if( abs(xh(i)-(minx+0.50*(maxx-minx)) ).le.(0.25*maxz) .and.  &
            abs(yh(j)-centery).le.(0.25*maxz) )then
          zsfoo(i,j) = 0.5*maxz
        endif
      enddo
      enddo
    ENDIF

    ENDIF

    !c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c

    IF( ib_init.eq.5 )THEN

      ! cube in center of domain:

      do j=jb,je
      do i=ib,ie
        if( abs(xh(i)-centerx).le.250.0 .and. abs(yh(j)-centery).le.250.0 ) zsfoo(i,j) = 500.0
      enddo
      enddo

    ENDIF

    !c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c-c

    !---  DO NOT CHANGE ANYTHING BELOW HERE  ---!

        call bc2d(zsfoo)
#ifdef MPI
      nf=0
      nu=0
      nv=0
      nw=0
      call comm_2d_start(zsfoo,west,newwest,east,neweast,   &
                               south,newsouth,north,newnorth,reqs_p)
      call comm_2dew_end(zsfoo,west,newwest,east,neweast,reqs_p)
      call comm_2dns_end(zsfoo,south,newsouth,north,newnorth,reqs_p)
      call bcs2_2d(zsfoo)
      call bc2d(zsfoo)
      call getcorner3_2d(zsfoo)
#endif

      do k=1,nk
      do j=jb,je
      do i=ib,ie
        if( sigma(k).le.zsfoo(i,j) ) bndy(i,j,k) = .true.
      enddo
      enddo
      enddo

      ! last step:  get kbdy

      kmaxib = 0

      do k=1,nk
      do j=jb,je
      do i=ib,ie
        if( bndy(i,j,k) )then
          kbdy(i,j) = k+1
        endif
      enddo
      enddo
      enddo

      do j=jb,je
      do i=ib,ie
        kmaxib = max( kmaxib , kbdy(i,j) )
      enddo
      enddo

#ifdef MPI
      call MPI_ALLREDUCE(mpi_in_place,kmaxib,1,MPI_INTEGER,MPI_MAX,MPI_COMM_WORLD,ierr)
#endif

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,*) '    kmaxib    = ',kmaxib
      if(dowr) write(outfile,*)

      IF( kmaxib .gt. (nk-3) )THEN
        if(myid.eq.0)then
        print *
        print *,'  nk     = ',nk
        print *,'  kmaxib = ',kmaxib
        print *
        print *,'  kmaxib must be < (nk-3) '
        print *
        endif
#ifdef MPI
        call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif
        call stopcm1
      ENDIF

      deallocate( zsfoo )

    end subroutine init_immersed_boundaries

!-----------------------------------------------------------------------

    subroutine zero_out_uv(bndy,kbdy,u3d,v3d)

    use input
    use constants

      logical, intent(in), dimension(ibib:ieib,jbib:jeib,kbib:keib) :: bndy
      integer, intent(in), dimension(ibib:ieib,jbib:jeib) :: kbdy
      real, intent(inout), dimension(ib:ie+1,jb:je,kb:ke) :: u3d
      real, intent(inout), dimension(ib:ie,jb:je+1,kb:ke) :: v3d

      integer :: i,j,k

          ! set u to zero on east/west faces of immersed gridpoints:
          do k=1,kmaxib
          do j=0,nj+1
          do i=0,ni+1
            if( bndy(i,j,k) )then
              if( .not. bndy(i-1,j,k) )  u3d(i  ,j,k) = 0.0
              if( .not. bndy(i+1,j,k) )  u3d(i+1,j,k) = 0.0
              if( .not. bndy(i,j-1,k) )  v3d(i,j  ,k) = 0.0
              if( .not. bndy(i,j+1,k) )  v3d(i,j+1,k) = 0.0
            endif
          enddo
          enddo
          enddo

          ! set u to zero on east/west faces of immersed gridpoints:
          do k=1,kmaxib
          do j=1,nj
          do i=1,ni+1
            if( bndy(i-1,j,k).and.bndy(i,j,k) ) u3d(i,j,k) = 0.0
          enddo
          enddo
          enddo

          ! set v to zero on south/north faces of immersed gridpoints:
          do k=1,kmaxib
          do j=1,nj+1
          do i=1,ni
            if( bndy(i,j-1,k).and.bndy(i,j,k) ) v3d(i,j,k) = 0.0
          enddo
          enddo
          enddo

    end subroutine zero_out_uv

!-----------------------------------------------------------------------

    subroutine zero_out_w(bndy,kbdy,w3d)

    use input
    use constants

      logical, intent(in), dimension(ibib:ieib,jbib:jeib,kbib:keib) :: bndy
      integer, intent(in), dimension(ibib:ieib,jbib:jeib) :: kbdy
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: w3d

      integer :: i,j,k

        ! set gridpoints in/on immersed gridpoints to zero:
        do j=1,nj
        do i=1,ni
          do k = 1,kbdy(i,j)
            w3d(i,j,k) = 0.0
          enddo
        enddo
        enddo

    end subroutine zero_out_w

!-----------------------------------------------------------------------

    subroutine drag_obstacles(xh,yh,zh,zf,rho,rf,dum1,dum2,dum3,dum4,dum5,dum6,t11,t12,t13,t22,t23,t33,ua,va,wa,kbdy)

    use input
    use constants

    real, intent(in), dimension(ib:ie) :: xh
    real, intent(in), dimension(jb:je) :: yh
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: zh
    real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: zf
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rf
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: t11,t12,t13,t22,t23,t33
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum1,dum2,dum3,dum4,dum5,dum6
    real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: ua
    real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: va
    real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: wa
    integer, intent(in), dimension(ibib:ieib,jbib:jeib) :: kbdy

    integer :: i,j,k,kk
    real :: tem,tem2,rhox
    logical :: doit

!-----------------------------

!  drag on top & sides of obstacles


!  NOTE: if you are looking to set top_cd or side_cd, they are now specified 
!        in namelist.input (param20 section)


  doit = .true.
!!!  IF( doit )THEN
!!!    stop 4444

    doib:  &
    IF( do_ib )THEN

!!!      if( myid.eq.0 ) print *,'  top_cd,side_cd = ',top_cd,side_cd

      do k=1,nk
      do j=0,nj+1
      do i=0,ni+1
        dum1(i,j,k) = 0.5*(ua(i,j,k)+ua(i+1,j,k))
        dum2(i,j,k) = 0.5*(va(i,j,k)+va(i,j+1,k))
        dum4(i,j,k) = 0.5*(wa(i,j,k)+wa(i,j,k+1))
        dum3(i,j,k) = sqrt( dum1(i,j,k)**2 + dum2(i,j,k)**2 )
        dum5(i,j,k) = sqrt( dum4(i,j,k)**2 + dum1(i,j,k)**2 )  ! for south/north bndys
        dum6(i,j,k) = sqrt( dum4(i,j,k)**2 + dum2(i,j,k)**2 )  ! for west/east bndys
      enddo
      enddo
      enddo

!-----------------------------
!  sides of obstacles:

      tem = 0.25*side_cd

      do j=0,nj+1
      do i=0,ni+1
        kbdy_gt_1:  &
        if( kbdy(i,j).gt.1 )then
          do k=1,(kbdy(i,j)-1)
            t11(i,j,k) = 0.0
            t22(i,j,k) = 0.0
            t33(i,j,k) = 0.0
          enddo
          !-----
          if( kbdy(i-1,j).le.1 )then
            ! west side of obstacle:
            do k=1,(kbdy(i,j)-1)
              t12(i,j  ,k) = -tem * va(i-1,j  ,k) * (dum6(i-1,j,k)+dum6(i-1,j-1,k)) * (rho(i-1,j,k)+rho(i-1,j-1,k))
              t12(i,j+1,k) = -tem * va(i-1,j+1,k) * (dum6(i-1,j,k)+dum6(i-1,j+1,k)) * (rho(i-1,j,k)+rho(i-1,j+1,k))
              t13(i,j,k+1) = -tem * wa(i-1,j,k+1) * (dum6(i-1,j,k)+dum6(i-1,j,k+1)) * (rho(i-1,j,k)+rho(i-1,j,k+1))
            enddo
          endif
          if( kbdy(i+1,j).le.1 )then
            ! east side of obstacle:
            do k=1,(kbdy(i,j)-1)
              t12(i+1,j  ,k) =  tem * va(i+1,j  ,k) * (dum6(i+1,j,k)+dum6(i+1,j-1,k)) * (rho(i+1,j,k)+rho(i+1,j-1,k))
              t12(i+1,j+1,k) =  tem * va(i+1,j+1,k) * (dum6(i+1,j,k)+dum6(i+1,j+1,k)) * (rho(i+1,j,k)+rho(i+1,j+1,k))
              t13(i+1,j,k+1) =  tem * wa(i+1,j,k+1) * (dum6(i+1,j,k)+dum6(i+1,j,k+1)) * (rho(i+1,j,k)+rho(i+1,j,k+1))
            enddo
          endif
          !-----
          if( kbdy(i,j-1).le.1 )then
            ! south side of obstacle:
            do k=1,(kbdy(i,j)-1)
              t12(i  ,j,k) = -tem * ua(i  ,j-1,k) * (dum5(i,j-1,k)+dum5(i-1,j-1,k)) * (rho(i,j-1,k)+rho(i-1,j-1,k))
              t12(i+1,j,k) = -tem * ua(i+1,j-1,k) * (dum5(i,j-1,k)+dum5(i+1,j-1,k)) * (rho(i,j-1,k)+rho(i+1,j-1,k))
              t23(i,j,k+1) = -tem * wa(i,j-1,k+1) * (dum5(i,j-1,k)+dum5(i,j-1,k+1)) * (rho(i,j-1,k)+rho(i,j-1,k+1))
            enddo
          endif
          if( kbdy(i,j+1).le.1 )then
            ! north side of obstacle:
            do k=1,(kbdy(i,j)-1)
              t12(i  ,j+1,k) =  tem * ua(i  ,j+1,k) * (dum5(i,j+1,k)+dum5(i-1,j+1,k)) * (rho(i,j+1,k)+rho(i-1,j+1,k))
              t12(i+1,j+1,k) =  tem * ua(i+1,j+1,k) * (dum5(i,j+1,k)+dum5(i+1,j+1,k)) * (rho(i,j+1,k)+rho(i+1,j+1,k))
              t23(i,j+1,k+1) =  tem * wa(i,j+1,k+1) * (dum5(i,j+1,k)+dum5(i,j+1,k+1)) * (rho(i,j+1,k)+rho(i,j+1,k+1))
            enddo
          endif
          !-----
          ! check for corners:
          ! i am not sure what to do, so just set t12 to zero (for now)
          if( kbdy(i-1,j).le.1 .and. kbdy(i,j+1).le.1 .and. kbdy(i-1,j+1).le.1 )then
            ! nw corner:
            do k=1,(kbdy(i,j)-1)
              t12(i,j+1,k) = 0.0
            enddo
          endif
          if( kbdy(i+1,j).le.1 .and. kbdy(i,j+1).le.1 .and. kbdy(i+1,j+1).le.1 )then
            ! ne corner:
            do k=1,(kbdy(i,j)-1)
              t12(i+1,j+1,k) = 0.0
            enddo
          endif
          if( kbdy(i-1,j).le.1 .and. kbdy(i,j-1).le.1 .and. kbdy(i-1,j-1).le.1 )then
            ! sw corner:
            do k=1,(kbdy(i,j)-1)
              t12(i,j,k) = 0.0
            enddo
          endif
          if( kbdy(i+1,j).le.1 .and. kbdy(i,j-1).le.1 .and. kbdy(i+1,j-1).le.1 )then
            ! se corner:
            do k=1,(kbdy(i,j)-1)
              t12(i+1,j,k) = 0.0
            enddo
          endif
          !-----
          if( kbdy(i-1,j).gt.1 .and. kbdy(i,j-1).gt.1 .and. kbdy(i-1,j-1).gt.1 )then
            ! embedded on all sides:
            do k=1,(kbdy(i,j)-1)
              t12(i,j,k) = 0.0
            enddo
          endif
          !-----
        endif  kbdy_gt_1
      enddo
      enddo

!-----------------------------
!  tops of obstacles:

      ! t13:
      do j=1,nj
      do i=1,ni+1
        if( kbdy(i-1,j).gt.1 .or. kbdy(i,j).gt.1 )then
          k = max( kbdy(i-1,j) , kbdy(i,j) )
          rhox = 0.5*(   &
      (rho(i-1,j,k)+(rho(i-1,j,k+1)-rho(i-1,j,k))*(zf(i-1,j,k)-zh(i-1,j,k))/(zh(i-1,j,k+1)-zh(i-1,j,k))) &
     +(rho(i  ,j,k)+(rho(i  ,j,k+1)-rho(i  ,j,k))*(zf(i  ,j,k)-zh(i  ,j,k))/(zh(i  ,j,k+1)-zh(i  ,j,k))) )
          t13(i,j,k) = top_cd * rhox * ua(i,j,k) * 0.5*(dum3(i-1,j,k)+dum3(i,j,k))
        endif
        if( kbdy(i-1,j).gt.1 .and. kbdy(i,j).gt.1 )then
          kk = max( kbdy(i-1,j) , kbdy(i,j) ) - 1
          do k=1,kk
            t13(i,j,k) = 0.0
          enddo
        endif
      enddo
      enddo

      ! t23:
      do j=1,nj+1
      do i=1,ni
        if( kbdy(i,j-1).gt.1 .or. kbdy(i,j).gt.1 )then
          k = max( kbdy(i,j-1),kbdy(i,j) )
          rhox = 0.5*(   &
      (rho(i,j-1,k)+(rho(i,j-1,k+1)-rho(i,j-1,k))*(zf(i,j-1,k)-zh(i,j-1,k))/(zh(i,j-1,k+1)-zh(i,j-1,k))) &
     +(rho(i,j  ,k)+(rho(i,j  ,k+1)-rho(i,j  ,k))*(zf(i,j  ,k)-zh(i,j  ,k))/(zh(i,j  ,k+1)-zh(i,j  ,k))) )
          t23(i,j,k) = top_cd * rhox * va(i,j,k) * 0.5*(dum3(i,j-1,k)+dum3(i,j,k))
        endif
        if( kbdy(i,j-1).gt.1 .and. kbdy(i,j).gt.1 )then
          kk = max( kbdy(i,j-1),kbdy(i,j) ) - 1
          do k=1,kk
            t23(i,j,k) = 0.0
          enddo
        endif
      enddo
      enddo

    ENDIF  doib

!!!  ENDIF

    end subroutine drag_obstacles

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      !dir$ attributes forceinline :: flx3
      real function flx3(s1,s2,s3)
      implicit none

      real, intent(in) :: s1,s2,s3

      ! 3rd-order flux (eg, Wicker and Skamarock, 2002, MWR)

      flx3 = (  (-1.0/6.0)*s1  &
               +( 5.0/6.0)*s2  &
               +( 2.0/6.0)*s3  )

      end function flx3

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      !dir$ attributes forceinline :: flx4
      real function flx4(s1,s2,s3,s4)
      implicit none

      real, intent(in) :: s1,s2,s3,s4

      ! 4th-order flux (eg, Wicker and Skamarock, 2002, MWR)

      flx4 = (  (7.0/12.0)*(s3+s2)  &
               -(1.0/12.0)*(s4+s1)  )

      end function flx4

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      !dir$ attributes forceinline :: flx5
      real function flx5(s1,s2,s3,s4,s5)
      implicit none

      real, intent(in) :: s1,s2,s3,s4,s5

      ! 5th-order flux (eg, Wicker and Skamarock, 2002, MWR)

      flx5 = (  (  2.0/60.0)*s1  &
               +(-13.0/60.0)*s2  &
               +( 47.0/60.0)*s3  &
               +( 27.0/60.0)*s4  &
               +( -3.0/60.0)*s5  )

      end function flx5

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      !dir$ attributes forceinline :: flx6
      real function flx6(s1,s2,s3,s4,s5,s6)
      implicit none

      real, intent(in) :: s1,s2,s3,s4,s5,s6

      ! 6th-order flux (eg, Wicker and Skamarock, 2002, MWR)

      flx6 = (  (37.0/60.0)*(s4+s3)  &
               +(-8.0/60.0)*(s5+s2)  &
               +( 1.0/60.0)*(s6+s1)  )

      end function flx6

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      !dir$ attributes forceinline :: weno3
      real function weno3(s1,s2,s3,weps)
      implicit none

      real, intent(in) :: s1,s2,s3
      double precision, intent(in) :: weps

      double precision :: b1,b2
      double precision :: w1,w2

      integer, parameter :: siform = 2

      ! 3rd-order weighted essentially non-oscillatory (weno)
      ! Jiang and Shu, 1996, JCP

      b1 = (s1-s2)**2
      b2 = (s2-s3)**2

      if( siform.eq.1 )then
        ! original WENO (eg, Jiang and Shu, 1996, JCP)
        w1 = (1.0/3.0)/(weps+b1)**2
        w2 = (2.0/3.0)/(weps+b2)**2
      elseif( siform.eq.2 )then
        ! improved smoothness indicators (Borges et al, 2008, JCP)
        w1 = (1.0/3.0)*(1.0+min(1.0d30,abs(b1-b2)/(b1+weps))**2)
        w2 = (2.0/3.0)*(1.0+min(1.0d30,abs(b1-b2)/(b2+weps))**2)
      endif

      weno3 = ( w1*( (-1.0/2.0)*s1 + ( 3.0/2.0)*s2 )  &
               +w2*( ( 1.0/2.0)*s2 + ( 1.0/2.0)*s3 )  &
              )/( w1+w2 )

      end function weno3

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      !dir$ attributes forceinline :: weno5
      real function weno5(s1,s2,s3,s4,s5,weps)
      implicit none

      real, intent(in) :: s1,s2,s3,s4,s5
      double precision, intent(in) :: weps

      double precision :: b1,b2,b3
      double precision :: w1,w2,w3

      integer, parameter :: siform = 2

      ! 5th-order weighted essentially non-oscillatory (weno)
      ! Jiang and Shu, 1996, JCP

      b1 = (13.0/12.0)*( s1 -2.0*s2 +s3 )**2 + 0.25*(     s1 -4.0*s2 +3.0*s3 )**2
      b2 = (13.0/12.0)*( s2 -2.0*s3 +s4 )**2 + 0.25*(     s2             -s4 )**2
      b3 = (13.0/12.0)*( s3 -2.0*s4 +s5 )**2 + 0.25*( 3.0*s3 -4.0*s4     +s5 )**2

      if( siform.eq.1 )then
        ! original WENO (eg, Jiang and Shu, 1996, JCP)
        w1 = 0.1/(weps+b1)**2
        w2 = 0.6/(weps+b2)**2
        w3 = 0.3/(weps+b3)**2
      elseif( siform.eq.2 )then
        ! improved smoothness indicators (Borges et al, 2008, JCP)
        w1 = 0.1*(1.0+min(1.0d30,abs(b1-b3)/(b1+weps))**2)
        w2 = 0.6*(1.0+min(1.0d30,abs(b1-b3)/(b2+weps))**2)
        w3 = 0.3*(1.0+min(1.0d30,abs(b1-b3)/(b3+weps))**2)
      endif

      weno5 = ( w1*( ( 2.0/6.0)*s1 + (-7.0/6.0)*s2 + (11.0/6.0)*s3 )  &
               +w2*( (-1.0/6.0)*s2 + ( 5.0/6.0)*s3 + ( 2.0/6.0)*s4 )  &
               +w3*( ( 2.0/6.0)*s3 + ( 5.0/6.0)*s4 + (-1.0/6.0)*s5 )  &
              )/( w1+w2+w3 )

      end function weno5

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      !dir$ attributes forceinline :: upstrpd
      real function upstrpd(s1,s2,s3,weps)
      implicit none

      real, intent(in) :: s1,s2,s3
      double precision, intent(in) :: weps

      real :: dd,rr,phi

      ! Positive-definite upstream scheme of Beets & Koren (1996, 
      ! Department of Numerical Mathematics Rep. NM-R9601, Utrecht 
      ! University, 24 pp).

      dd = s2-s1
      rr = (s3-s2)/(sign(sngl(weps),dd)+dd)
      phi = max(0.0,min(rr,min( (1.0/6.0)+(2.0/6.0)*rr , 1.0 ) ) )
      upstrpd = s2 + phi*(s2-s1)

      end function upstrpd

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    subroutine ib_flx_init(bndy,hflxw,hflxe,hflxs,hflxn,dum1,dum2,     &
                           uw31,uw32,ue31,ue32,us31,us32,un31,un32,    &
                           vw31,vw32,ve31,ve32,vs31,vs32,vn31,vn32,reqs_u,reqs_v)

    use input
    use constants
    use bc_module
    use comm_module
#ifdef MPI
    use mpi
#endif

    logical, intent(in), dimension(ibib:ieib,jbib:jeib,kbib:keib) :: bndy
    integer, intent(inout), dimension(ibib:ieib,jbib:jeib,kmaxib) :: hflxw,hflxe,hflxs,hflxn
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum1,dum2
    real, intent(inout), dimension(cmp,jmp,kmp)   :: uw31,uw32,ue31,ue32
    real, intent(inout), dimension(imp+1,cmp,kmp) :: us31,us32,un31,un32
    real, intent(inout), dimension(cmp,jmp+1,kmp) :: vw31,vw32,ve31,ve32
    real, intent(inout), dimension(imp,cmp,kmp)   :: vs31,vs32,vn31,vn32
    integer, intent(inout), dimension(rmp) :: reqs_u,reqs_v

    integer :: i,j,k
    logical :: doit

    DO k=1,kmaxib
      do j=jb,je
      do i=ib,ie-1
        if( bndy(i,j,k) .and. ( .not. bndy(i+1,j,k) ) )then
          !---  east face  ---!
          if( i+1 .le. ie                      ) hflxe(i+1,j,k) = 1
          if( i+2 .le. ie .and. hadvordrs.ge.3 ) hflxe(i+2,j,k) = 3
          if( i+3 .le. ie .and. hadvordrs.ge.5 ) hflxe(i+3,j,k) = 5
        endif
      enddo
      enddo
    ENDDO
    DO k=1,kmaxib
      do j=jb,je
      do i=ib+1,ie
        if( bndy(i,j,k) .and. ( .not. bndy(i-1,j,k) ) )then
          !---  west face  ---!
          if( i   .ge. ib                      ) hflxw(i  ,j,k) = 1
          if( i-1 .ge. ib .and. hadvordrs.ge.3 ) hflxw(i-1,j,k) = 3
          if( i-2 .ge. ib .and. hadvordrs.ge.5 ) hflxw(i-2,j,k) = 5
        endif
      enddo
      enddo
    ENDDO
    DO k=1,kmaxib
      do j=jb,je-1
      do i=ib,ie
        if( bndy(i,j,k) .and. ( .not. bndy(i,j+1,k) ) )then
          !---  north face  ---!
          if( j+1 .le. je                      ) hflxn(i,j+1,k) = 1
          if( j+2 .le. je .and. hadvordrs.ge.3 ) hflxn(i,j+2,k) = 3
          if( j+3 .le. je .and. hadvordrs.ge.5 ) hflxn(i,j+3,k) = 5
        endif
      enddo
      enddo
    ENDDO
    DO k=1,kmaxib
      do j=jb+1,je
      do i=ib,ie
        if( bndy(i,j,k) .and. ( .not. bndy(i,j-1,k) ) )then
          !---  south face  ---!
          if( j   .ge. jb                      ) hflxs(i,j  ,k) = 1
          if( j-1 .ge. jb .and. hadvordrs.ge.3 ) hflxs(i,j-1,k) = 3
          if( j-2 .ge. jb .and. hadvordrs.ge.5 ) hflxs(i,j-2,k) = 5
        endif
      enddo
      enddo
    ENDDO

      end subroutine ib_flx_init

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    subroutine ib_side_flx(stag,ix,jy,kz,c1,c2,rru,rrv,dumx,dumy,a,hadvorder,bndy,hflxw,hflxe,hflxs,hflxn,out3d)
    use input
    implicit none

    ! reduce order of horizontal advective fluxes near sides of obstacles:

    integer, intent(in) :: stag
    integer, intent(in) :: ix,jy,kz
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: c1,c2
    real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: rru
    real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: rrv
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dumx,dumy
    real, intent(in), dimension(1-ngxy:ix+ngxy,1-ngxy:jy+ngxy,1-ngz:kz+ngz)   :: a
    integer, intent(in) :: hadvorder
    logical, intent(in), dimension(ibib:ieib,jbib:jeib,kbib:keib) :: bndy
    integer, intent(in), dimension(ibib:ieib,jbib:jeib,kmaxib) :: hflxw,hflxe,hflxs,hflxn
    real, intent(inout), optional, dimension(ib3d:ie3d,jb3d:je3d,kb3d:ke3d,nout3d) :: out3d

    integer :: i,j,k,i1,i2,j1,j2
    real :: ubar,vbar,cc1,cc2
    logical :: doit

    doit = .true.
!!!    if( doit )then

  IF( stag.eq.1 )THEN

    DO k=1,(kmaxib-1)
      do j=1,nj+1
      !dir$ vector always
      do i=1,ni+1
        !---------------------------------------
          !---  east face  ---!
        if( hflxe(i,j,k).eq.1 )then
          dumx(i,j,k) = 0.0
        endif
        if( hflxe(i,j,k).eq.3 )then
          if(rru(i,j,k).ge.0.0)then
            dumx(i,j,k) = rru(i,j,k)*0.5*(a(i-1,j,k)+a(i,j,k))
          else
            dumx(i,j,k) = rru(i,j,k)*flx3(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k))
          endif
        endif
        if( hflxe(i,j,k).eq.5 )then
          if(rru(i,j,k).ge.0.0)then
            dumx(i,j,k) = rru(i,j,k)*flx3(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k))
          endif
        endif
        !---------------------------------------
          !---  west face  ---!
        if( hflxw(i,j,k).eq.1 )then
          dumx(i,j,k) = 0.0
        endif
        if( hflxw(i,j,k).eq.3 )then
          if(rru(i,j,k).ge.0.0)then
            dumx(i,j,k) = rru(i,j,k)*flx3(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k))
          else
            dumx(i,j,k) = rru(i,j,k)*0.5*(a(i-1,j,k)+a(i,j,k))
          endif
        endif
        if( hflxw(i,j,k).eq.5 )then
          if(rru(i,j,k).lt.0.0)then
            dumx(i,j,k) = rru(i,j,k)*flx3(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k))
          endif
        endif
        !---------------------------------------
          !---  north face  ---!
        if( hflxn(i,j,k).eq.1 )then
          dumy(i,j,k) = 0.0
        endif
        if( hflxn(i,j,k).eq.3 )then
          if(rrv(i,j,k).ge.0.0)then
            dumy(i,j,k) = rrv(i,j,k)*0.5*(a(i,j-1,k)+a(i,j,k))
          else
            dumy(i,j,k) = rrv(i,j,k)*flx3(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k))
          endif
        endif
        if( hflxn(i,j,k).eq.5 )then
          if(rrv(i,j,k).ge.0.0)then
            dumy(i,j,k) = rrv(i,j,k)*flx3(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k))
          endif
        endif
        !---------------------------------------
          !---  south face  ---!
        if( hflxs(i,j,k).eq.1 )then
          dumy(i,j,k) = 0.0
        endif
        if( hflxs(i,j,k).eq.3 )then
          if(rrv(i,j,k).ge.0.0)then
            dumy(i,j,k) = rrv(i,j,k)*flx3(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k))
          else
            dumy(i,j,k) = rrv(i,j,k)*0.5*(a(i,j-1,k)+a(i,j  ,k))
          endif
        endif
        if( hflxs(i,j,k).eq.5 )then
          if(rrv(i,j,k).lt.0.0)then
            dumy(i,j,k) = rrv(i,j,k)*flx3(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k))
          endif
        endif
        !---------------------------------------
      enddo
      enddo
    ENDDO

  ELSEIF( stag.eq.2 )THEN

    if( doit )then
    DO k=1,(kmaxib-1)
      do j=1,nj+1
      !dir$ vector always
      do i=0,ni+1
        !---------------------------------------
          !---  east face  ---!
        if( hflxe(i,j,k).eq.1 )then
          ubar = 0.5*(rru(i,j,k)+rru(i+1,j,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*0.5*(a(i  ,j,k)+a(i+1,j,k))
          else
            dumx(i,j,k) = ubar*flx3(a(i+2,j,k),a(i+1,j,k),a(i  ,j,k))
          endif
        endif
        if( hflxe(i,j,k).eq.3 )then
          ubar = 0.5*(rru(i,j,k)+rru(i+1,j,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*flx3(a(i-1,j,k),a(i  ,j,k),a(i+1,j,k))
          endif
        endif
        !---------------------------------------
          !---  west face  ---!
        if( hflxw(i,j,k).eq.3 )then
          ubar = 0.5*(rru(i,j,k)+rru(i+1,j,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*flx3(a(i-1,j,k),a(i  ,j,k),a(i+1,j,k))
          else
            dumx(i,j,k) = ubar*0.5*(a(i  ,j,k)+a(i+1,j,k))
          endif
        endif
        if( hflxw(i,j,k).eq.5 )then
          ubar = 0.5*(rru(i,j,k)+rru(i+1,j,k))
          if(ubar.lt.0.0)then
            dumx(i,j,k) = ubar*flx3(a(i+2,j,k),a(i+1,j,k),a(i  ,j,k))
          endif
        endif
        !---------------------------------------
          !---  north face  ---!
        if( hflxn(i,j,k).eq.3 .or. hflxn(i-1,j,k).eq.3 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i-1,j,k))
          if( vbar.ge.0.0 )then
            dumy(i,j,k) = vbar*0.5*(a(i,j-1,k)+a(i,j  ,k))
          else
            dumy(i,j,k) = vbar*flx3(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k))
          endif
        endif
        if( hflxn(i,j,k).eq.5 .or. hflxn(i-1,j,k).eq.5 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i-1,j,k))
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*flx3(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k))
          endif
        endif
        !---------------------------------------
          !---  south face  ---!
        if( hflxs(i,j,k).eq.3 .or. hflxs(i-1,j,k).eq.3 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i-1,j,k))
          if( vbar.ge.0.0 )then
            dumy(i,j,k) = vbar*flx3(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k))
          else
            dumy(i,j,k) = vbar*0.5*(a(i,j-1,k)+a(i,j  ,k))
          endif
        endif
        if( hflxs(i,j,k).eq.5 .or. hflxs(i-1,j,k).eq.5 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i-1,j,k))
          if( vbar.lt.0.0 )then
            dumy(i,j,k) = vbar*flx3(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k))
          endif
        endif
        !---------------------------------------
      enddo
      enddo
    ENDDO
    endif

  ELSEIF( stag.eq.3 )THEN

    if( doit )then
    DO k=1,(kmaxib-1)
      do j=0,nj+1
      !dir$ vector always
      do i=1,ni+1
        !---------------------------------------
          !---  east face  ---!
        if( hflxe(i,j,k).eq.3 .or. hflxe(i,j-1,k).eq.3 )then
          ubar = 0.5*(rru(i,j,k)+rru(i,j-1,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*0.5*(a(i-1,j,k)+a(i  ,j,k))
          else
            dumx(i,j,k) = ubar*flx3(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k))
          endif
        endif
        if( hflxe(i,j,k).eq.5 .or. hflxe(i,j-1,k).eq.5 )then
          ubar = 0.5*(rru(i,j,k)+rru(i,j-1,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*flx3(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k))
          endif
        endif
        !---------------------------------------
          !---  west face  ---!
        if( hflxw(i,j,k).eq.3 .or. hflxw(i,j-1,k).eq.3 )then
          ubar = 0.5*(rru(i,j,k)+rru(i,j-1,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*flx3(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k))
          else
            dumx(i,j,k) = ubar*0.5*(a(i-1,j,k)+a(i  ,j,k))
          endif
        endif
        if( hflxw(i,j,k).eq.5 .or. hflxw(i,j-1,k).eq.5 )then
          ubar = 0.5*(rru(i,j,k)+rru(i,j-1,k))
          if(ubar.lt.0.0)then
            dumx(i,j,k) = ubar*flx3(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k))
          endif
        endif
        !---------------------------------------
          !---  north face  ---!
        if( hflxn(i,j,k).eq.1 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i,j+1,k))
          if( vbar.ge.0.0 )then
            dumy(i,j,k) = vbar*0.5*(a(i,j  ,k)+a(i,j+1,k))
          else
            dumy(i,j,k) = vbar*flx3(a(i,j+2,k),a(i,j+1,k),a(i,j  ,k))
          endif
        endif
        if( hflxn(i,j,k).eq.3 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i,j+1,k))
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*flx3(a(i,j-1,k),a(i,j  ,k),a(i,j+1,k))
          endif
        endif
        !---------------------------------------
          !---  south face  ---!
        if( hflxs(i,j,k).eq.3 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i,j+1,k))
          if( vbar.ge.0.0 )then
            dumy(i,j,k) = vbar*flx3(a(i,j-1,k),a(i,j  ,k),a(i,j+1,k))
          else
            dumy(i,j,k) = vbar*0.5*(a(i,j  ,k)+a(i,j+1,k))
          endif
        endif
        if( hflxs(i,j,k).eq.5 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i,j+1,k))
          if( vbar.lt.0.0 )then
            dumy(i,j,k) = vbar*flx3(a(i,j+2,k),a(i,j+1,k),a(i,j  ,k))
          endif
        endif
        !---------------------------------------
      enddo
      enddo
    ENDDO
    endif

  ELSEIF( stag.eq.4 )THEN

  if( doit )then
    DO k=1,(kmaxib-1)
      do j=1,nj+1
      !dir$ vector always
      do i=1,ni+1
        !---------------------------------------
          !---  east face  ---!
        if( hflxe(i,j,k).eq.1 )then
          dumx(i,j,k) = 0.0
        endif
        if( hflxe(i,j,k).eq.3 )then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          ubar = cc2*rru(i,j,k)+cc1*rru(i,j,k-1)
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*0.5*(a(i-1,j,k)+a(i,j,k))
          else
            dumx(i,j,k) = ubar*flx3(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k))
          endif
        endif
        if( hflxe(i,j,k).eq.5 )then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          ubar = cc2*rru(i,j,k)+cc1*rru(i,j,k-1)
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*flx3(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k))
          else
            dumx(i,j,k) = ubar*flx5(a(i+2,j,k),a(i+1,j,k),a(i  ,j,k),a(i-1,j,k),a(i-2,j,k))
          endif
        endif
        !---------------------------------------
          !---  west face  ---!
        if( hflxw(i,j,k).eq.1 )then
          dumx(i,j,k) = 0.0
        endif
        if( hflxw(i,j,k).eq.3 )then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          ubar = cc2*rru(i,j,k)+cc1*rru(i,j,k-1)
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*flx3(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k))
          else
            dumx(i,j,k) = ubar*0.5*(a(i-1,j,k)+a(i,j,k))
          endif
        endif
        if( hflxw(i,j,k).eq.5 )then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          ubar = cc2*rru(i,j,k)+cc1*rru(i,j,k-1)
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*flx5(a(i-3,j,k),a(i-2,j,k),a(i-1,j,k),a(i  ,j,k),a(i+1,j,k))
          else
            dumx(i,j,k) = ubar*flx3(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k))
          endif
        endif
        !---------------------------------------
          !---  north face  ---!
        if( hflxn(i,j,k).eq.1 )then
          dumy(i,j,k) = 0.0
        endif
        if( hflxn(i,j,k).eq.3 )then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          vbar = cc2*rrv(i,j,k)+cc1*rrv(i,j,k-1)
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*0.5*(a(i,j-1,k)+a(i,j,k))
          else
            dumy(i,j,k) = vbar*flx3(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k))
          endif
        endif
        if( hflxn(i,j,k).eq.5 )then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          vbar = cc2*rrv(i,j,k)+cc1*rrv(i,j,k-1)
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*flx3(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k))
          else
            dumy(i,j,k) = vbar*flx5(a(i,j+2,k),a(i,j+1,k),a(i,j  ,k),a(i,j-1,k),a(i,j-2,k))
          endif
        endif
        !---------------------------------------
          !---  south face  ---!
        if( hflxs(i,j,k).eq.1 )then
          dumy(i,j,k) = 0.0
        endif
        if( hflxs(i,j,k).eq.3 )then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          vbar = cc2*rrv(i,j,k)+cc1*rrv(i,j,k-1)
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*flx3(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k))
          else
            dumy(i,j,k) = vbar*0.5*(a(i,j-1,k)+a(i,j  ,k))
          endif
        endif
        if( hflxs(i,j,k).eq.5 )then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          vbar = cc2*rrv(i,j,k)+cc1*rrv(i,j,k-1)
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*flx5(a(i,j-3,k),a(i,j-2,k),a(i,j-1,k),a(i,j  ,k),a(i,j+1,k))
          else
            dumy(i,j,k) = vbar*flx3(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k))
          endif
        endif
        !---------------------------------------
      enddo
      enddo
    ENDDO
  endif

  ENDIF

!!!    endif

    end subroutine ib_side_flx

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    subroutine ib_side_weno(stag,ix,jy,kz,c1,c2,rru,rrv,dumx,dumy,a,hadvorder,bndy,hflxw,hflxe,hflxs,hflxn,weps,out3d)
    use input
    implicit none

    ! reduce order of horizontal advective fluxes near sides of obstacles:

    integer, intent(in) :: stag
    integer, intent(in) :: ix,jy,kz
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: c1,c2
    real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: rru
    real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: rrv
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dumx,dumy
    real, intent(in), dimension(1-ngxy:ix+ngxy,1-ngxy:jy+ngxy,1-ngz:kz+ngz)   :: a
    integer, intent(in) :: hadvorder
    logical, intent(in), dimension(ibib:ieib,jbib:jeib,kbib:keib) :: bndy
    integer, intent(in), dimension(ibib:ieib,jbib:jeib,kmaxib) :: hflxw,hflxe,hflxs,hflxn
    double precision, intent(in) :: weps
    real, intent(inout), optional, dimension(ib3d:ie3d,jb3d:je3d,kb3d:ke3d,nout3d) :: out3d

    integer :: i,j,k,i1,i2,j1,j2
    real :: ubar,vbar,cc1,cc2
    logical :: doit

    doit = .true.
!!!    if( doit )then

  IF( stag.eq.1 )THEN

    DO k=1,(kmaxib-1)
      do j=1,nj+1
      !dir$ vector always
      do i=1,ni+1
        !---------------------------------------
          !---  east face  ---!
        if( hflxe(i,j,k).eq.1 )then
          dumx(i,j,k) = 0.0
        endif
        if( hflxe(i,j,k).eq.3 )then
          if(rru(i,j,k).ge.0.0)then
            dumx(i,j,k) = rru(i,j,k)*0.5*(a(i-1,j,k)+a(i,j,k))
          else
            dumx(i,j,k) = rru(i,j,k)*upstrpd(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k),weps)
          endif
        endif
        if( hflxe(i,j,k).eq.5 )then
          if(rru(i,j,k).ge.0.0)then
            dumx(i,j,k) = rru(i,j,k)*upstrpd(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k),weps)
          endif
        endif
        !---------------------------------------
          !---  west face  ---!
        if( hflxw(i,j,k).eq.1 )then
          dumx(i,j,k) = 0.0
        endif
        if( hflxw(i,j,k).eq.3 )then
          if(rru(i,j,k).ge.0.0)then
            dumx(i,j,k) = rru(i,j,k)*upstrpd(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k),weps)
          else
            dumx(i,j,k) = rru(i,j,k)*0.5*(a(i-1,j,k)+a(i,j,k))
          endif
        endif
        if( hflxw(i,j,k).eq.5 )then
          if(rru(i,j,k).lt.0.0)then
            dumx(i,j,k) = rru(i,j,k)*upstrpd(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k),weps)
          endif
        endif
        !---------------------------------------
          !---  north face  ---!
        if( hflxn(i,j,k).eq.1 )then
          dumy(i,j,k) = 0.0
        endif
        if( hflxn(i,j,k).eq.3 )then
          if(rrv(i,j,k).ge.0.0)then
            dumy(i,j,k) = rrv(i,j,k)*0.5*(a(i,j-1,k)+a(i,j,k))
          else
            dumy(i,j,k) = rrv(i,j,k)*upstrpd(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k),weps)
          endif
        endif
        if( hflxn(i,j,k).eq.5 )then
          if(rrv(i,j,k).ge.0.0)then
            dumy(i,j,k) = rrv(i,j,k)*upstrpd(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k),weps)
          endif
        endif
        !---------------------------------------
          !---  south face  ---!
        if( hflxs(i,j,k).eq.1 )then
          dumy(i,j,k) = 0.0
        endif
        if( hflxs(i,j,k).eq.3 )then
          if(rrv(i,j,k).ge.0.0)then
            dumy(i,j,k) = rrv(i,j,k)*upstrpd(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k),weps)
          else
            dumy(i,j,k) = rrv(i,j,k)*0.5*(a(i,j-1,k)+a(i,j  ,k))
          endif
        endif
        if( hflxs(i,j,k).eq.5 )then
          if(rrv(i,j,k).lt.0.0)then
            dumy(i,j,k) = rrv(i,j,k)*upstrpd(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k),weps)
          endif
        endif
        !---------------------------------------
      enddo
      enddo
    ENDDO

  ELSEIF( stag.eq.2 )THEN

    if( doit )then
    DO k=1,(kmaxib-1)
      do j=1,nj+1
      !dir$ vector always
      do i=0,ni+1
        !---------------------------------------
          !---  east face  ---!
        if( hflxe(i,j,k).eq.1 )then
          ubar = 0.5*(rru(i,j,k)+rru(i+1,j,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*0.5*(a(i  ,j,k)+a(i+1,j,k))
          else
            dumx(i,j,k) = ubar*upstrpd(a(i+2,j,k),a(i+1,j,k),a(i  ,j,k),weps)
          endif
        endif
        if( hflxe(i,j,k).eq.3 )then
          ubar = 0.5*(rru(i,j,k)+rru(i+1,j,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*upstrpd(a(i-1,j,k),a(i  ,j,k),a(i+1,j,k),weps)
          endif
        endif
        !---------------------------------------
          !---  west face  ---!
        if( hflxw(i,j,k).eq.3 )then
          ubar = 0.5*(rru(i,j,k)+rru(i+1,j,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*upstrpd(a(i-1,j,k),a(i  ,j,k),a(i+1,j,k),weps)
          else
            dumx(i,j,k) = ubar*0.5*(a(i  ,j,k)+a(i+1,j,k))
          endif
        endif
        if( hflxw(i,j,k).eq.5 )then
          ubar = 0.5*(rru(i,j,k)+rru(i+1,j,k))
          if(ubar.lt.0.0)then
            dumx(i,j,k) = ubar*upstrpd(a(i+2,j,k),a(i+1,j,k),a(i  ,j,k),weps)
          endif
        endif
        !---------------------------------------
          !---  north face  ---!
        if( hflxn(i,j,k).eq.3 .or. hflxn(i-1,j,k).eq.3 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i-1,j,k))
          if( vbar.ge.0.0 )then
            dumy(i,j,k) = vbar*0.5*(a(i,j-1,k)+a(i,j  ,k))
          else
            dumy(i,j,k) = vbar*upstrpd(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k),weps)
          endif
        endif
        if( hflxn(i,j,k).eq.5 .or. hflxn(i-1,j,k).eq.5 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i-1,j,k))
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*upstrpd(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k),weps)
          endif
        endif
        !---------------------------------------
          !---  south face  ---!
        if( hflxs(i,j,k).eq.3 .or. hflxs(i-1,j,k).eq.3 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i-1,j,k))
          if( vbar.ge.0.0 )then
            dumy(i,j,k) = vbar*upstrpd(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k),weps)
          else
            dumy(i,j,k) = vbar*0.5*(a(i,j-1,k)+a(i,j  ,k))
          endif
        endif
        if( hflxs(i,j,k).eq.5 .or. hflxs(i-1,j,k).eq.5 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i-1,j,k))
          if( vbar.lt.0.0 )then
            dumy(i,j,k) = vbar*upstrpd(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k),weps)
          endif
        endif
        !---------------------------------------
      enddo
      enddo
    ENDDO
    endif

  ELSEIF( stag.eq.3 )THEN

    if( doit )then
    DO k=1,(kmaxib-1)
      do j=0,nj+1
      !dir$ vector always
      do i=1,ni+1
        !---------------------------------------
          !---  east face  ---!
        if( hflxe(i,j,k).eq.3 .or. hflxe(i,j-1,k).eq.3 )then
          ubar = 0.5*(rru(i,j,k)+rru(i,j-1,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*0.5*(a(i-1,j,k)+a(i  ,j,k))
          else
            dumx(i,j,k) = ubar*upstrpd(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k),weps)
          endif
        endif
        if( hflxe(i,j,k).eq.5 .or. hflxe(i,j-1,k).eq.5 )then
          ubar = 0.5*(rru(i,j,k)+rru(i,j-1,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*upstrpd(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k),weps)
          endif
        endif
        !---------------------------------------
          !---  west face  ---!
        if( hflxw(i,j,k).eq.3 .or. hflxw(i,j-1,k).eq.3 )then
          ubar = 0.5*(rru(i,j,k)+rru(i,j-1,k))
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*upstrpd(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k),weps)
          else
            dumx(i,j,k) = ubar*0.5*(a(i-1,j,k)+a(i  ,j,k))
          endif
        endif
        if( hflxw(i,j,k).eq.5 .or. hflxw(i,j-1,k).eq.5 )then
          ubar = 0.5*(rru(i,j,k)+rru(i,j-1,k))
          if(ubar.lt.0.0)then
            dumx(i,j,k) = ubar*upstrpd(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k),weps)
          endif
        endif
        !---------------------------------------
          !---  north face  ---!
        if( hflxn(i,j,k).eq.1 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i,j+1,k))
          if( vbar.ge.0.0 )then
            dumy(i,j,k) = vbar*0.5*(a(i,j  ,k)+a(i,j+1,k))
          else
            dumy(i,j,k) = vbar*upstrpd(a(i,j+2,k),a(i,j+1,k),a(i,j  ,k),weps)
          endif
        endif
        if( hflxn(i,j,k).eq.3 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i,j+1,k))
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*upstrpd(a(i,j-1,k),a(i,j  ,k),a(i,j+1,k),weps)
          endif
        endif
        !---------------------------------------
          !---  south face  ---!
        if( hflxs(i,j,k).eq.3 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i,j+1,k))
          if( vbar.ge.0.0 )then
            dumy(i,j,k) = vbar*upstrpd(a(i,j-1,k),a(i,j  ,k),a(i,j+1,k),weps)
          else
            dumy(i,j,k) = vbar*0.5*(a(i,j  ,k)+a(i,j+1,k))
          endif
        endif
        if( hflxs(i,j,k).eq.5 )then
          vbar = 0.5*(rrv(i,j,k)+rrv(i,j+1,k))
          if( vbar.lt.0.0 )then
            dumy(i,j,k) = vbar*upstrpd(a(i,j+2,k),a(i,j+1,k),a(i,j  ,k),weps)
          endif
        endif
        !---------------------------------------
      enddo
      enddo
    ENDDO
    endif

  ELSEIF( stag.eq.4 )THEN

  if( doit )then
    DO k=1,(kmaxib-1)
      do j=1,nj+1
      !dir$ vector always
      do i=1,ni+1
        !---------------------------------------
          !---  east face  ---!
        if( hflxe(i,j,k).eq.1 )then
          dumx(i,j,k) = 0.0
        endif
        if( hflxe(i,j,k).eq.3 )then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          ubar = cc2*rru(i,j,k)+cc1*rru(i,j,k-1)
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*0.5*(a(i-1,j,k)+a(i,j,k))
          else
            dumx(i,j,k) = ubar*upstrpd(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k),weps)
          endif
        endif
        if( hflxe(i,j,k).eq.5 )then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          ubar = cc2*rru(i,j,k)+cc1*rru(i,j,k-1)
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*upstrpd(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k),weps)
          else
            dumx(i,j,k) = ubar*flx5(a(i+2,j,k),a(i+1,j,k),a(i  ,j,k),a(i-1,j,k),a(i-2,j,k))
          endif
        endif
        !---------------------------------------
          !---  west face  ---!
        if( hflxw(i,j,k).eq.1 )then
          dumx(i,j,k) = 0.0
        endif
        if( hflxw(i,j,k).eq.3 )then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          ubar = cc2*rru(i,j,k)+cc1*rru(i,j,k-1)
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*upstrpd(a(i-2,j,k),a(i-1,j,k),a(i  ,j,k),weps)
          else
            dumx(i,j,k) = ubar*0.5*(a(i-1,j,k)+a(i,j,k))
          endif
        endif
        if( hflxw(i,j,k).eq.5 )then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          ubar = cc2*rru(i,j,k)+cc1*rru(i,j,k-1)
          if(ubar.ge.0.0)then
            dumx(i,j,k) = ubar*flx5(a(i-3,j,k),a(i-2,j,k),a(i-1,j,k),a(i  ,j,k),a(i+1,j,k))
          else
            dumx(i,j,k) = ubar*upstrpd(a(i+1,j,k),a(i  ,j,k),a(i-1,j,k),weps)
          endif
        endif
        !---------------------------------------
          !---  north face  ---!
        if( hflxn(i,j,k).eq.1 )then
          dumy(i,j,k) = 0.0
        endif
        if( hflxn(i,j,k).eq.3 )then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          vbar = cc2*rrv(i,j,k)+cc1*rrv(i,j,k-1)
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*0.5*(a(i,j-1,k)+a(i,j,k))
          else
            dumy(i,j,k) = vbar*upstrpd(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k),weps)
          endif
        endif
        if( hflxn(i,j,k).eq.5 )then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          vbar = cc2*rrv(i,j,k)+cc1*rrv(i,j,k-1)
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*upstrpd(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k),weps)
          else
            dumy(i,j,k) = vbar*flx5(a(i,j+2,k),a(i,j+1,k),a(i,j  ,k),a(i,j-1,k),a(i,j-2,k))
          endif
        endif
        !---------------------------------------
          !---  south face  ---!
        if( hflxs(i,j,k).eq.1 )then
          dumy(i,j,k) = 0.0
        endif
        if( hflxs(i,j,k).eq.3 )then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          vbar = cc2*rrv(i,j,k)+cc1*rrv(i,j,k-1)
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*upstrpd(a(i,j-2,k),a(i,j-1,k),a(i,j  ,k),weps)
          else
            dumy(i,j,k) = vbar*0.5*(a(i,j-1,k)+a(i,j  ,k))
          endif
        endif
        if( hflxs(i,j,k).eq.5 )then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          vbar = cc2*rrv(i,j,k)+cc1*rrv(i,j,k-1)
          if(vbar.ge.0.0)then
            dumy(i,j,k) = vbar*flx5(a(i,j-3,k),a(i,j-2,k),a(i,j-1,k),a(i,j  ,k),a(i,j+1,k))
          else
            dumy(i,j,k) = vbar*upstrpd(a(i,j+1,k),a(i,j  ,k),a(i,j-1,k),weps)
          endif
        endif
        !---------------------------------------
      enddo
      enddo
    ENDDO
  endif

  ENDIF

!!!    endif

    end subroutine ib_side_weno

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    subroutine ib_lwr_flx(stag,ix,jy,kz,c1,c2,rrw,dumz,a,kbdy,vadvorder)
    use input
    implicit none

    ! reduce order of vertical advective fluxes near top of obstacles:

    integer, intent(in) :: stag
    integer, intent(in) :: ix,jy,kz
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: c1,c2
    real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: rrw
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dumz
    real, intent(in), dimension(1-ngxy:ix+ngxy,1-ngxy:jy+ngxy,1-ngz:kz+ngz)   :: a
    integer, intent(in), dimension(ibib:ieib,jbib:jeib) :: kbdy
    integer, intent(in) :: vadvorder

    integer :: i,j,k,i1,i2,j1,j2,kval
    real :: wbar,cc1,cc2

  IF( stag.eq.1 )THEN

    do j=1,nj
    !dir$ vector always
    do i=1,ni
      if( kbdy(i,j).gt.1 )then
        do k=1,kbdy(i,j)
          dumz(i,j,k) = 0.0
        enddo
        k = kbdy(i,j)+1
        if(rrw(i,j,k).ge.0.0)then
          dumz(i,j,k) = rrw(i,j,k)*(c1(i,j,k)*a(i,j,k-1)+c2(i,j,k)*a(i,j,k))
        else
          dumz(i,j,k) = rrw(i,j,k)*flx3(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1))
        endif
        if( vadvorder.ge.5 )then
          k = kbdy(i,j)+2
          if(rrw(i,j,k).ge.0.0)then
            dumz(i,j,k) = rrw(i,j,k)*flx3(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ))
          else
            dumz(i,j,k) = rrw(i,j,k)*flx5(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),a(i,j,k-2))
          endif
        endif
      endif
    enddo
    enddo

  ELSEIF( stag.eq.2 )THEN
    ! u-staggered:

      if(ibw.eq.1)then
        i1=2
      else
        i1=1
      endif
 
      if(ibe.eq.1)then
        i2=ni+1-1
      else
        i2=ni+1
      endif

    do j=1,nj
    !dir$ vector always
    do i=i1,i2
      kval = max(kbdy(i-1,j),kbdy(i,j))
      if( kval.gt.1 )then
        do k=1,kval
          dumz(i,j,k) = 0.0
        enddo
        k = kval+1
        wbar = 0.5*(rrw(i,j,k)+rrw(i-1,j,k))
        if(wbar.ge.0.0)then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          dumz(i,j,k) = wbar*(cc1*a(i,j,k-1)+cc2*a(i,j,k))
        else
          dumz(i,j,k) = wbar*flx3(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1))
        endif
        if( vadvorder.ge.5 )then
          k = kval+2
          wbar = 0.5*(rrw(i,j,k)+rrw(i-1,j,k))
          if(wbar.ge.0.0)then
            dumz(i,j,k) = wbar*flx3(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ))
          else
            dumz(i,j,k) = wbar*flx5(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),a(i,j,k-2))
          endif
        endif
      endif
    enddo
    enddo

  ELSEIF( stag.eq.3 )THEN
    ! v-staggered:

      if(ibs.eq.1)then
        j1=2
      else
        j1=1
      endif
 
      if(ibn.eq.1)then
        j2=nj+1-1
      else
        j2=nj+1
      endif

    do j=j1,j2
    !dir$ vector always
    do i=1,ni
      kval = max(kbdy(i,j-1),kbdy(i,j))
      if( kval.gt.1 )then
        do k=1,kval
          dumz(i,j,k) = 0.0
        enddo
        k = kval+1
        wbar = 0.5*(rrw(i,j,k)+rrw(i,j-1,k))
        if(wbar.ge.0.0)then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          dumz(i,j,k) = wbar*(cc1*a(i,j,k-1)+cc2*a(i,j,k))
        else
          dumz(i,j,k) = wbar*flx3(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1))
        endif
        if( vadvorder.ge.5 )then
          k = kval+2
          wbar = 0.5*(rrw(i,j,k)+rrw(i,j-1,k))
          if(wbar.ge.0.0)then
            dumz(i,j,k) = wbar*flx3(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ))
          else
            dumz(i,j,k) = wbar*flx5(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),a(i,j,k-2))
          endif
        endif
      endif
    enddo
    enddo

  ELSEIF( stag.eq.4 )THEN

    do j=1,nj
    !dir$ vector always
    do i=1,ni
      if( kbdy(i,j).gt.1 )then
        do k=1,(kbdy(i,j)-1)
          dumz(i,j,k) = 0.0
        enddo
        k = kbdy(i,j)
        wbar = 0.5*(rrw(i,j,k)+rrw(i,j,k+1))
        if(wbar.ge.0.0)then
          dumz(i,j,k) = wbar*0.5*(a(i,j,k)+a(i,j,k+1))
        else
          dumz(i,j,k) = wbar*flx3(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ))
        endif
        if( vadvorder.ge.5 )then
          k = kbdy(i,j)+1
          wbar = 0.5*(rrw(i,j,k)+rrw(i,j,k+1))
          if(wbar.ge.0.0)then
            dumz(i,j,k) = wbar*flx3(a(i,j,k-1),a(i,j,k  ),a(i,j,k+1))
          else
            dumz(i,j,k) = wbar*flx5(a(i,j,k+3),a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1))
          endif
        endif
      endif
    enddo
    enddo

  ENDIF

    end subroutine ib_lwr_flx

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    subroutine ib_lwr_weno(stag,ix,jy,kz,c1,c2,rrw,dumz,a,kbdy,vadvorder,weps)
    use input
    implicit none

    ! reduce order of vertical advective fluxes near top of obstacles (for weno):

    integer, intent(in) :: stag
    integer, intent(in) :: ix,jy,kz
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: c1,c2
    real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: rrw
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dumz
    real, intent(in), dimension(1-ngxy:ix+ngxy,1-ngxy:jy+ngxy,1-ngz:kz+ngz)   :: a
    integer, intent(in), dimension(ibib:ieib,jbib:jeib) :: kbdy
    integer, intent(in) :: vadvorder
    double precision, intent(in) :: weps

    integer :: i,j,k,i1,i2,j1,j2,kval
    real :: wbar,cc1,cc2

  IF( stag.eq.1 )THEN

    do j=1,nj
    !dir$ vector always
    do i=1,ni
      if( kbdy(i,j).gt.1 )then
        do k=1,kbdy(i,j)
          dumz(i,j,k) = 0.0
        enddo
        k = kbdy(i,j)+1
        if(rrw(i,j,k).ge.0.0)then
          dumz(i,j,k) = rrw(i,j,k)*(c1(i,j,k)*a(i,j,k-1)+c2(i,j,k)*a(i,j,k))
        else
          dumz(i,j,k) = rrw(i,j,k)*upstrpd(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),weps)
        endif
        if( vadvorder.ge.5 )then
          k = kbdy(i,j)+2
          if(rrw(i,j,k).ge.0.0)then
            dumz(i,j,k) = rrw(i,j,k)*upstrpd(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),weps)
          else
            dumz(i,j,k) = rrw(i,j,k)*weno5(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),a(i,j,k-2),weps)
          endif
        endif
      endif
    enddo
    enddo

  ELSEIF( stag.eq.2 )THEN
    ! u-staggered:

      if(ibw.eq.1)then
        i1=2
      else
        i1=1
      endif
 
      if(ibe.eq.1)then
        i2=ni+1-1
      else
        i2=ni+1
      endif

    do j=1,nj
    !dir$ vector always
    do i=i1,i2
      kval = max(kbdy(i-1,j),kbdy(i,j))
      if( kval.gt.1 )then
        do k=1,kval
          dumz(i,j,k) = 0.0
        enddo
        k = kval+1
        wbar = 0.5*(rrw(i,j,k)+rrw(i-1,j,k))
        if(wbar.ge.0.0)then
          cc2 = 0.5*(c2(i-1,j,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          dumz(i,j,k) = wbar*(cc1*a(i,j,k-1)+cc2*a(i,j,k))
        else
          dumz(i,j,k) = wbar*upstrpd(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),weps)
        endif
        if( vadvorder.ge.5 )then
          k = kval+2
          wbar = 0.5*(rrw(i,j,k)+rrw(i-1,j,k))
          if( wbar.ge.0.0 )then
            dumz(i,j,k) = wbar*upstrpd(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),weps)
          else
            dumz(i,j,k) = wbar*weno5(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),a(i,j,k-2),weps)
          endif
        endif
      endif
    enddo
    enddo

  ELSEIF( stag.eq.3 )THEN
    ! v-staggered:

      if(ibs.eq.1)then
        j1=2
      else
        j1=1
      endif
 
      if(ibn.eq.1)then
        j2=nj+1-1
      else
        j2=nj+1
      endif

    do j=j1,j2
    !dir$ vector always
    do i=1,ni
      kval = max(kbdy(i,j-1),kbdy(i,j))
      if( kval.gt.1 )then
        do k=1,kval
          dumz(i,j,k) = 0.0
        enddo
        k = kval+1
        wbar = 0.5*(rrw(i,j,k)+rrw(i,j-1,k))
        if(wbar.ge.0.0)then
          cc2 = 0.5*(c2(i,j-1,k)+c2(i,j,k))
          cc1 = 1.0-cc2
          dumz(i,j,k) = wbar*(cc1*a(i,j,k-1)+cc2*a(i,j,k))
        else
          dumz(i,j,k) = wbar*upstrpd(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),weps)
        endif
        if( vadvorder.ge.5 )then
          k = kval+2
          wbar = 0.5*(rrw(i,j,k)+rrw(i,j-1,k))
          if( wbar.ge.0.0 )then
            dumz(i,j,k) = wbar*upstrpd(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),weps)
          else
            dumz(i,j,k) = wbar*weno5(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),a(i,j,k-2),weps)
          endif
        endif
      endif
    enddo
    enddo

  ELSEIF( stag.eq.4 )THEN

    do j=1,nj
    !dir$ vector always
    do i=1,ni
      if( kbdy(i,j).gt.1 )then
        do k=1,(kbdy(i,j)-1)
          dumz(i,j,k) = 0.0
        enddo
        k = kbdy(i,j)
        wbar = 0.5*(rrw(i,j,k)+rrw(i,j,k+1))
        if(wbar.ge.0.0)then
          dumz(i,j,k) = wbar*0.5*(a(i,j,k)+a(i,j,k+1))
        else
          dumz(i,j,k) = wbar*upstrpd(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),weps)
        endif
        if( vadvorder.ge.5 )then
          k = kbdy(i,j)+1
          wbar = 0.5*(rrw(i,j,k)+rrw(i,j,k+1))
          if( wbar.ge.0.0 )then
            dumz(i,j,k) = wbar*upstrpd(a(i,j,k-1),a(i,j,k  ),a(i,j,k+1),weps)
          else
            dumz(i,j,k) = wbar*weno5(a(i,j,k+3),a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),weps)
          endif
        endif
      endif
    enddo
    enddo

  ENDIF

    end subroutine ib_lwr_weno

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

  end module ib_module

init3d.F/       1744672191  3193  100   100644  90547     `
  MODULE init3d_module

  implicit none

  private
  public :: init3d,getset

  CONTAINS

!-----------------------------------------------------------------------------
!
!  subroutine INIT3D:  Specify initial conditions for CM1. 
!
!    Note:  init3d assumes that the base state arrays (th0,pi0,rho0,etc)
!           have already been specified.
!
!    Note:  In general, the code below assumes that the 3d initial state
!           for CM1 is simply the base-state conditions (from BASE) plus
!           specified perturbations (defined in INIT3D).  Hence, most 
!           code below calculates perturbation potential temp., pressure,
!           etc  (tha,ppi arrays).
!
!           See the documentation near the top of solve.F and/or Table 1
!           in the document "The governing equations for CM1"
!           (http://www2.mmm.ucar.edu/people/bryan/cm1/cm1_equations.pdf)
!           for more details about variables and arrays in CM1
!
!-----------------------------------------------------------------------------
!  Quick Index:
!    ua/u3d     = velocity in x-direction (m/s)  (grid-relative)
!    va/v3d     = velocity in y-direction (m/s)  (grid-relative)
!       Note: when imove=1, ground-relative winds are umove+ua, umove+u3d,
!                                                     vmove+va, vmove+v3d.
!    wa/w3d     = velocity in z-direction (m/s)
!    tha/th3d   = perturbation potential temperature (K)
!    ppi/pp3d   = perturbation nondimensional pressure ("Exner function")
!    qa/q3d     = mixing ratios of moisture (kg/kg)
!    tkea/tke3d = SUBGRID turbulence kinetic energy (m^2/s^2)
!    kmh/kmv    = turbulent diffusion coefficients for momentum (m^2/s)
!    khh/khv    = turbulent diffusion coefficients for scalars (m^2/s)
!                 (h = horizontal, v = vertical)
!    prs        = pressure (Pa)
!    rho        = density (kg/m^3)
!
!    th0,pi0,prs0,etc = base-state arrays
!
!    xh         = x (m) at scalar points
!    xf         = x (m) at u points
!    yh         = y (m) at scalar points
!    yf         = y (m) at v points
!    zh         = z (m above sea level) of scalar points (aka, "half levels")
!    zf         = z (m above sea level) of w points (aka, "full levels")
!
!    For the axisymmetric model (axisymm=1), xh and xf are radius (m).
!
!  See "The governing equations for CM1" for more details:
!        http://www2.mmm.ucar.edu/people/bryan/cm1/cm1_equations.pdf
!-----------------------------------------------------------------------------

      subroutine init3d(xh,rxh,uh,ruh,xf,rxf,uf,ruf,yh,vh,rvh,yf,vf,rvf,  &
                        xfref,xhref,yfref,yhref,sigma,c1,c2,gz,zs,        &
                        zh,mh,rmh,zf,mf,rmf,rho0s,pi0s,prs0s,             &
                        pi0,prs0,rho0,thv0,th0,rth0,qv0,                  &
                        u0,v0,qc0,qi0,rr0,rf0,rrf0,                       &
                        rain,sws,svs,sps,srs,sgs,sus,shs,                 &
                        thflux,qvflux,cd,ch,cq,f2d,                       &
                        dum1,dum2,dum3,dum4,divx,rho,prs,                 &
                        rru,ua,u3d,uten,uten1,rrv,va,v3d,vten,vten1,      &
                        rrw,wa,w3d,wten,wten1,ppi,pp3d,ppten,sten,        &
                        tha,th3d,thten,thten1,qa,q3d,qten,                &
                        kmh,kmv,khh,khv,tkea,tke3d,tketen,                &
                        pta,pt3d,ptten,                                   &
                        pdata,cfb,cfa,cfc,ad1,ad2,pdt,lgbth,lgbph,rhs,trans)

      use input
      use constants
      use misclibs
      use cm1libs , only : rslf,rsif
      use bc_module
      use module_mp_nssl_2mom, only: ccn, lccn, irenuc
      use poiss_module
      use parcel_module , only : getparcelzs
#ifdef MPI
      use mpi
#endif

      implicit none
 
      real, dimension(ib:ie) :: xh,rxh,uh,ruh
      real, dimension(ib:ie+1) :: xf,rxf,uf,ruf
      real, dimension(jb:je) :: yh,vh,rvh
      real, dimension(jb:je+1) :: yf,vf,rvf
      real, intent(in), dimension(1-ngxy:nx+ngxy+1) :: xfref,xhref
      real, intent(in), dimension(1-ngxy:ny+ngxy+1) :: yfref,yhref
      real, intent(in), dimension(kb:ke) :: sigma
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: c1,c2
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz
      real, intent(in), dimension(ib:ie,jb:je) :: zs
      real, dimension(ib:ie,jb:je,kb:ke) :: zh,mh,rmh
      real, dimension(ib:ie,jb:je,kb:ke+1) :: zf,mf,rmf
      real, dimension(ib:ie,jb:je) :: rho0s,pi0s,prs0s
      real, dimension(ib:ie,jb:je,kb:ke) :: pi0,prs0,rho0,thv0,th0,rth0,qv0
      real, dimension(ib:ie,jb:je,kb:ke) :: qc0,qi0,rr0,rf0,rrf0
      real, dimension(ib:ie,jb:je,nrain) :: rain,sws,svs,sps,srs,sgs,sus,shs
      real, dimension(ib:ie,jb:je) :: thflux,qvflux,cd,ch,cq,f2d
      real, dimension(ib:ie,jb:je,kb:ke) :: dum1,dum2,dum3,dum4
      real, dimension(ib:ie,jb:je,kb:ke) :: divx,rho,prs
      real, dimension(ib:ie+1,jb:je,kb:ke) :: u0,rru,ua,u3d,uten,uten1
      real, dimension(ib:ie,jb:je+1,kb:ke) :: v0,rrv,va,v3d,vten,vten1
      real, dimension(ib:ie,jb:je,kb:ke+1) :: rrw,wa,w3d,wten,wten1
      real, dimension(ib:ie,jb:je,kb:ke) :: ppi,pp3d,ppten,sten
      real, dimension(ib:ie,jb:je,kb:ke) :: tha,th3d,thten,thten1
      real, dimension(ibm:iem,jbm:jem,kbm:kem,numq) :: qa,q3d,qten
      real, dimension(ibc:iec,jbc:jec,kbc:kec) :: kmh,kmv,khh,khv
      real, dimension(ibt:iet,jbt:jet,kbt:ket) :: tkea,tke3d,tketen
      real, dimension(ibp:iep,jbp:jep,kbp:kep,npt) :: pta,pt3d,ptten
      real, dimension(nparcels,npvals) :: pdata
      real, dimension(ipb:ipe,jpb:jpe,kpb:kpe) :: cfb
      real, dimension(kpb:kpe) :: cfa,cfc,ad1,ad2
      complex, dimension(ipb:ipe,jpb:jpe,kpb:kpe) :: pdt,lgbth,lgbph
      complex, dimension(ipb:ipe,jpb:jpe) :: rhs,trans
 
!-----------------------------------------------------------------------

      integer i,j,k,kk,l,n,nn,nbub,nloop
      integer ic,jc,ifoo,jfoo
      real ric,rjc
      real xc,yc,zc,bhrad,bvrad,bptpert,beta,tmp,zdep
      real thvnew(nk),pinew(nk)
      real thl,ql,qt,th1,t1,ql2,rm,cpm,v1,v2,th2

      real, dimension(:), allocatable :: rref,vt
      real, dimension(:,:), allocatable :: vref,piref,pref,thref,thvref,qvref,rhref
      real :: rmax,vmax
      double precision :: frac,angle
      real :: r0,zdd,dd2,dd1,rr,diff,xref,yref,xsave,ysave,rrmax
      real :: mult,nominal_dx
      integer :: ival,ni1,ni2,ni3
      integer :: i1,i2,ii,jj,nref
      real :: r0_re87,rmax_re87,vmax_re87

      real rmin,foo1,foo2,umax,umin,vmin
      real :: rand,rand2,amplitude
      integer, dimension(:), allocatable :: sand
      double precision :: dpi

      logical :: setppi,maintain_rh

      real :: rm1,rm2,rm3,rdc,w2,w3,v3

      logical :: rhmods
      real :: rhmax,rmid,rscale,zmid,zscale,rh0,rh1
      real :: tnew,fliq,fice,qsi,qsw,qvs

      logical :: dobsmod
      real :: th_sfc,pi_sfc,pifoo,prsfoo,thfoo,t0
      real :: prs_sfc,t_sfc,hs
      integer :: tctype
      real :: tem
      double precision :: tem1,tem2,temd
      logical :: doit


      ! Note:  By default, CM1 uses the same set of psuedorandom numbers 
      !        every time it is called.  To use truly random perturbations 
      !        (ie, different sets of random perturbations every time CM1 
      !        is used), then change this varliable to .true.
      logical, parameter :: use_truly_random_pert  =  .false.

!--------------------------

      if(dowr) write(outfile,*) 'Inside INIT3D'
      if(dowr) write(outfile,*)

      convinit = 0
      wnudge = 0
      setppi = .true.
      maintain_rh = .false.

!------------------------------------------------------------------
!  Initialize surface swath arrays:

      do n=1,nrain
      do j=jb,je
      do i=ib,ie
        ! these are all positive-definite, so set initial value to zero:
        rain(i,j,n)=0.0
        sws(i,j,n)=0.0
        srs(i,j,n)=0.0
        sgs(i,j,n)=0.0
        shs(i,j,n)=0.0
        ! for sps, we want to get a MINIMUM value at the surface, so...
        ! set sps to an absurdly large number:
        sps(i,j,n)=200000.0
        ! svs and sus can be negative or positive, 
        ! but we want to get a MAXIMUM value, so...
        ! set svs and sus to an absurdly low (negative) number:
        svs(i,j,n)=-1000.0
        sus(i,j,n)=-1000.0
      enddo
      enddo
      enddo

!-----------------------------------------------------------------------
!  Set winds to base-state values:

      do k=kb,ke
      do j=jb,je
      do i=ib,ie+1
        ua(i,j,k)=u0(i,j,k)
        u3d(i,j,k)=u0(i,j,k)
      enddo
      enddo
      enddo

      do k=kb,ke
      do j=jb,je+1
      do i=ib,ie
        va(i,j,k)=v0(i,j,k)
        v3d(i,j,k)=v0(i,j,k)
      enddo
      enddo
      enddo


      IF( idoles .and. iusetke .and. ( testcase.eq.3 .or. testcase.eq.4 .or.  testcase.eq.5 .or. testcase.eq.9 .or. testcase.eq.11 ) )THEN
          IF( testcase.eq.3 )THEN
            ! shallow Cu case (Siebesma at al, 2003, JAS)
            do k=1,nk+1
            do j=jbt,jet
            do i=ibt,iet
              tkea(i,j,k)=max(0.0,1.0-zf(i,j,k)/3000.0)
              tke3d(i,j,k)=tkea(i,j,k)
            enddo
            enddo
            enddo
          ELSEIF( testcase.eq.9 .or. testcase.eq.11 )THEN
            ! stable boundary layer (Beare et al. 2006, BLM)
            do k=1,nk+1
            do j=jbt,jet
            do i=ibt,iet
              if( zh(i,j,k).lt.255.0 )then
                tkea(i,j,k)=0.4*((1.0-zf(i,j,k)/255.0)**3)
              else
                tkea(i,j,k)=0.0
              endif
              tke3d(i,j,k)=tkea(i,j,k)
            enddo
            enddo
            enddo
          ELSE
            tkea = 1.0
            tke3d = 1.0
          ENDIF
          call bcw(tkea,1)
          call bcw(tke3d,1)
      ENDIF


!-----------------------------------------------------------------------

    IF ( ( ptype .ge. 26 .and. ptype.le.29 ) .and. lccn .gt. 0 ) THEN
! initialize CCN concentrations as constant mixing ratios througout the domain
      do k=kbm,kem
      do j=jbm,jem
      do i=ibm,iem
       IF ( irenuc < 5 ) THEN ! number of unactivated ccn
       qa (i,j,k,lccn-1) = ccn/1.225
       q3d(i,j,k,lccn-1) = ccn/1.225
       ELSE ! treat as number of activated ccn
       qa (i,j,k,lccn-1) = 0.0
       q3d(i,j,k,lccn-1) = 0.0
       ENDIF
      enddo
      enddo
      enddo
    ENDIF

!-----------------------------------------------------------------------
!  Set qv to base state value:

    im1:  &
    IF(imoist.eq.1)THEN

      do k=kbm,kem
      do j=jbm,jem
      do i=ibm,iem
        qa(i,j,k,nqv)=qv0(i,j,k)
      enddo
      enddo
      enddo

!---- This is here to ensure that certain idealized cases work ----

    pt1:  &
    IF( ptype.ge.1 )THEN

      IF( (isnd.eq.4 .or. isnd.eq.9 .or. isnd.eq.10 .or. isnd.eq.11 .or. isnd.eq.15) )THEN

        do k=kbm,kem
        do j=jbm,jem
        do i=ibm,iem
          qa(i,j,k,nqc)=qc0(i,j,k)
        enddo
        enddo
        enddo

      ENDIF

      IF( (isnd.eq.4 .or. isnd.eq.9 .or. isnd.eq.10) .and. iice.eq.1 )THEN

        do k=kbm,kem
        do j=jbm,jem
        do i=ibm,iem
          qa(i,j,k,nqi)=qi0(i,j,k)
        enddo
        enddo
        enddo

      ENDIF

    ENDIF  pt1

    ENDIF  im1

!-----

    IF(iptra.eq.1)THEN
      ! define concentrations for passive fluid tracers here:
      do n=1,npt
      do k=kbp,kep
      do j=jbp,jep
      do i=ibp,iep
        if(n.eq.1)then
          pta(i,j,k,n)=0.0
          if(zh(i,j,k).lt.3000.0) pta(i,j,k,n)=0.001
        endif
        if(n.eq.2)then
          pta(i,j,k,n)=0.0
          if(zh(i,j,k).gt.3000.0.and.zh(i,j,k).lt.6000.0) pta(i,j,k,n)=0.001
        endif
        if(n.eq.3)then
          pta(i,j,k,n)=0.0
          if(zh(i,j,k).gt.6000.0.and.zh(i,j,k).lt.9000.0) pta(i,j,k,n)=0.001
        endif
      enddo
      enddo
      enddo
      enddo
    ENDIF

!-----
!  parcel info:

      IF(iprcl.eq.1)THEN
        ! define initial locations of parcels here:
        !   pdata(*,prx) = x location (m)
        !   pdata(*,pry) = y location (m)
        !   pdata(*,prz) = z location (m ASL)

        ! initialize to really small number (so we can use the allreduce command below)
        do n=1,nparcels
          pdata(n,prx) = -1.0e30
          pdata(n,pry) = -1.0e30
          pdata(n,prz) = -1.0e30
        enddo

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  Parcels ! '
        if(dowr) write(outfile,*) '  npvals,nparcels = ',npvals,nparcels
        if(dowr) write(outfile,*) '  Initial parcel locations (x,y,z):'
        n = 0
        do k=1,10
        do j=1,60
        do i=1,60
          n = n + 1
          if(n.gt.nparcels)then
            if(dowr) write(outfile,*)
            if(dowr) write(outfile,*) ' You are trying to define too many parcels'
            if(dowr) write(outfile,*)
            if(dowr) write(outfile,*) ' Increase the value of nparcels in namelist.input'
            if(dowr) write(outfile,*)
            call stopcm1
          endif
          pdata(n,prx) = minx + 2000.0*(i-1)
          pdata(n,pry) = miny + 2000.0*(j-1)
          pdata(n,prz) = zh(1,1,1) + 1000.0*(k-1)
!!!          if(dowr) write(outfile,*) n,pdata(n,prx),pdata(n,pry),pdata(n,prz)
        enddo
        enddo
        enddo
        if(dowr) write(outfile,*)

#ifdef MPI
        ! this ensures that every processor has all parcel locations:
        call MPI_ALLREDUCE(MPI_IN_PLACE,pdata(1,1),3*nparcels,MPI_REAL,MPI_MAX,MPI_COMM_WORLD,ierr)
#endif

        IF(axisymm.eq.1.or.ny.eq.1)THEN
          ! 170719,  for 2d setup (x,z), fix all y values:
          DO n=1,nparcels
            pdata(n,pry) = 0.0
          ENDDO
        ENDIF
        IF(nx.eq.1)THEN
          ! 170719,  for 2d setup (y,z), fix all x values:
          DO n=1,nparcels
            pdata(n,prx) = 0.0
          ENDDO
        ENDIF

      ENDIF

!-----------------------------------------------------------------------
!  initialize random number generator:

      IF( use_truly_random_pert )THEN

        ! randomly reinitializes the pseudorandom number generator:
        call reinit_random_seed

      ELSE

        ! generate same set of pseudorandom numbers every time:
        ! (default for cm1)
        !-----------------------------------!
        !----- don't change this code) -----!
        ! initialize the random number generator
        call random_seed(size=k)
        k = max(2,k)
        if(dowr) write(outfile,*) '  seed_size = ',k
        allocate( sand(k) )
        do n=1,k
          sand(n) = nint( 2.0e9*(2.0*float(n-1)/float(k-1)-1.0) )
        enddo
        call random_seed(put=sand(1:k))
        call random_number(rand)
        if(dowr) write(outfile,*) '  rand-1 = ',rand
        deallocate( sand )
        !----- don't change this code) -----!
        !-----------------------------------!

      ENDIF

!-----------------------------------------------------------------------
!  iinit = 1
!  Warm bubble
!  reference:

      IF(iinit.eq.1)THEN

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  Warm bubble'
        if(dowr) write(outfile,*)

        ric     =  centerx  ! center of bubble in x-direction (m)
        rjc     =  centery  ! center of bubble in y-direction (m)
        zc      =   1400.0  ! height of center of bubble above ground (m)
        bhrad   =  10000.0  ! horizontal radius of bubble (m)
        bvrad   =   1400.0  ! vertical radius of bubble (m)
        bptpert =      1.0  ! max potential temp perturbation (K)

        ! By default, CM1 sets qv=constant at a constant height level for 
        ! this value of iinit.  If you would rather have rh=constant at 
        ! a constant height level, then set this to .true.
        maintain_rh = .false.

        do k=1,nk
        do j=1,nj
        do i=1,ni
          beta=sqrt(                             &
                    ((xh(i)-ric)/bhrad)**2       &
                   +((yh(j)-rjc)/bhrad)**2       &
                   +((zh(i,j,k)-zc)/bvrad)**2)
          if(beta.lt.1.0)then
            tha(i,j,k)=bptpert*(cos(0.5*pi*beta)**2)
          else
            tha(i,j,k)=0.0
          endif
        enddo
        enddo
        enddo

!-----------------------------------------------------------------------
!  iinit = 2
!  Cold pool (dam break style)
!  reference:  

      ELSEIF(iinit.eq.2)THEN

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  Cold pool .... periodic in N-S'
        if(dowr) write(outfile,*)

        ric      =   centerx   ! eastern edge of cold pool
        zdep     =    2500.0   ! depth of cold pool (m)
        bptpert  =      -6.0   ! max temp perturbation at sfc (K)

        ! By default, CM1 sets qv=constant at a constant height level for 
        ! this value of iinit.  If you would rather have rh=constant at 
        ! a constant height level, then set this to .true.
        maintain_rh = .true.

        do k=1,nk
        do j=1,nj
        do i=1,ni
          if( (xh(i).le.ric).and.(zh(i,j,k).lt.zdep) )then
            tha(i,j,k)=bptpert*(zdep-zh(i,j,k))/zdep
          else
            tha(i,j,k)=0.0
          endif
        enddo
        enddo
        enddo

!-----------------------------------------------------------------------
!  iinit = 3
!  Line of warm bubbles
!  reference:  

      ELSEIF(iinit.eq.3)THEN

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  Line of warm bubbles'
        if(dowr) write(outfile,*)
 
        nbub    =      3     ! number of warm bubbles
        ric     =  30000.0   ! center of bubble in x-direction (m)
        zc      =   1400.0   ! height of center of bubble above ground (m)
        bhrad   =  10000.0   ! horizontal radius of bubble (m)
        bvrad   =   1400.0   ! vertical radius of bubble (m)
        bptpert =      2.0   ! max potential temp perturbation (K)

        ! By default, CM1 sets qv=constant at a constant height level for 
        ! this value of iinit.  If you would rather have rh=constant at 
        ! a constant height level, then set this to .true.
        maintain_rh = .false.

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          tha(i,j,k)=0.0
        enddo
        enddo
        enddo

        do n=1,nbub

          if(n.eq.1) rjc=  3000.0
          if(n.eq.2) rjc= 33000.0
          if(n.eq.3) rjc= 63000.0

          if(dowr) write(outfile,*) '  ric,rjc=',n,ric,rjc
 
          do k=kb,ke
          do j=jb,je
          do i=ib,ie
            beta=sqrt(                        &
                    ((xh(i)-ric)/bhrad)**2    &
                   +((yh(j)-rjc)/bhrad)**2    &
                   +((zh(i,j,k)-zc)/bvrad)**2)
            if(beta.lt.1.0)then
              tha(i,j,k)=bptpert*(cos(0.5*pi*beta)**2)
            else
              tha(i,j,k)=max(0.0,tha(i,j,k))
            endif
          enddo
          enddo
          enddo

        enddo


!-----------------------------------------------------------------------
!  iinit = 4
!  moist bubble for moist benchmark
!  reference:  Bryan and Fritsch, 2002, MWR, 130, 2917-2928.

      ELSEIF(iinit.eq.4)THEN

        ! parameters for dry counterpart bubble

        ric      =      0.0       ! x-location of bubble center (m)
        zc       =   2000.0       ! z-location of bubble center (m)
        bhrad    =   2000.0       ! horizontal radius of bubble (m)
        bvrad    =   2000.0       ! vertical radius of bubble (m)
        bptpert  =      2.0       ! maximum potential temp. pert. (K)

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          beta=sqrt( ((xh(i)-ric)/bhrad)**2    &
                    +((zh(i,j,k)-zc)/bvrad)**2)
          if(beta.lt.1.0)then
            dum1(i,j,k)=bptpert*(cos(0.5*pi*beta)**2)
          else
            dum1(i,j,k)=0.
          endif
        enddo
        enddo
        enddo

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          tha(i,j,k)=0.
          ppi(i,j,k)=0.
          dum2(i,j,k)=qv0(i,j,k)/(rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k)))
        enddo
        enddo
        enddo

        do nn=1,30
          do k=kb,ke
          do j=jb,je
          do i=ib,ie
            qa(i,j,k,nqv)=dum2(i,j,k)*rslf(prs0(i,j,k),(th0(i,j,k)+tha(i,j,k))*pi0(i,j,k))
          enddo
          enddo
          enddo

          do k=kb,ke
          do j=jb,je
          do i=ib,ie
            qa(i,j,k,nqc)=max(qt_mb-qa(i,j,k,nqv),0.0)
          enddo
          enddo
          enddo

          do k=kb,ke
          do j=jb,je
          do i=ib,ie
            tha(i,j,k)=( (dum1(i,j,k)/300.)+(1.0+qt_mb)/(1.0+qa(i,j,k,nqv)) )  &
               *thv0(i,j,k)*(1.0+qa(i,j,k,nqv))/(1.0+reps*qa(i,j,k,nqv)) - th0(i,j,k)
            if(abs(tha(i,j,k)).lt.1.e-4) tha(i,j,k)=0.
          enddo
          enddo
          enddo
        enddo

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          qa(i,j,k,nqv)=rslf(prs0(i,j,k),(th0(i,j,k)+tha(i,j,k))*pi0(i,j,k))
          qa(i,j,k,nqc)=max(qt_mb-qa(i,j,k,nqv),0.0)
        enddo
        enddo
        enddo

!-----------------------------------------------------------------
!  iinit = 5
!  density current sim

      ELSEIF(iinit.eq.5)THEN

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  Cold pool (elipse, following Straka)'
        if(dowr) write(outfile,*)

        ric     =     0.0
        rjc     =     0.0
        zc      =  3000.0
        bhrad   =  4000.0
        bvrad   =  2000.0
        bptpert =   -15.0

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          beta=sqrt(                           &
                     ((xh(i)-ric)/bhrad)**2    &
!!!                    +((yh(j)-rjc)/bhrad)**2    &
                    +((zh(i,j,k)-zc)/bvrad)**2)
          if(beta.lt.1.0)then
            dum1(i,j,k)=bptpert*(cos(pi*beta)+1.0)*0.5
          else
            dum1(i,j,k)=0.0
          endif
        enddo
        enddo
        enddo

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          tmp=(th0(i,j,k)*pi0(i,j,k))+dum1(i,j,k)
          tha(i,j,k)=tmp/pi0(i,j,k)-th0(i,j,k)
          if(abs(tha(i,j,k)).lt.1.e-4) tha(i,j,k)=0.0
          ppi(i,j,k)=0.0
        enddo
        enddo
        enddo

!------------------------------------------------------------------
!  Analytic tropical cyclone-like vortex

      ELSEIF(iinit.eq.7)THEN

        ! for 3d runs, place TC in center of domain, by default:
        xref  =  centerx
        yref  =  centery

        ! TC center could be placed elsewhere.  Use this code:
!!!        xref  =   200000.0    ! x location of TC center (m)
!!!        yref  =  -100000.0    ! y location of TC center (m)


        ! type of analytic vortex:
        !    1 = Rotunno and Emanuel (1987)
        !    2 = modified Rankine vortex  ( this is now default, starting in cm1r20.1 )
        tctype  =  2



        !      Default analytic vortex since cm1r20.1:
        ! for tctype=2, parameters for modified Rankine vortex:
        vmax =   15.0         ! V max (m/s)
        rm1  =  75000.0       ! 1st radius (m): location of Vmax
        rm2  = 200000.0       ! 2nd radius (m): max radius for specified radial decay rate
        rm3  = 500000.0       ! 3rd radius (m): location where V=0
        rdc  =  -0.35         ! radial decay rate (nondimensional) between rm1 and rm2
                              !   ( where v = Vmax (r/rm1)^rdc )


        ! for tctype=1, parameters for Rotunno-Emanuel (1987) analytic vortex:
        r0_re87     =   412500.0
        rmax_re87   =    82500.0
        vmax_re87   =       15.0


        ! for all tctypes:
        zdd         =    15000.0     ! height (ASL) where V=0


        !  170502, experimental code for moist initial vortex:
        rhmods  =   .false.    !  use this code?
        rhmax   =    0.98      !  max value of relative humidity in core
        rmid    =  300000.0    !  radius (m) for middle of tanh function in r
        rscale  =  100000.0    !  radial scale (m) for tanh function in r
        zmid    =   18000.0    !  height (m) for middle of tanh function in z
        zscale  =    2000.0    !  vertical scale (m) for tanh function in z


      !----------------------------------------------------------------!
      ! do not change anything below here !

        IF(axisymm.eq.1)THEN
          ! axisymmetric grid ... use actual grid:

          nref = nx
          xref = 0.0
          yref = 0.0

          allocate( rref(nref) )
          rref=0.0

          do i=1,nref
            rref(i) = 0.5*(xfref(i)+xfref(i+1))
          enddo
          rrmax = rref(nref)

        ELSE
          ! 3d Cartesian grid:

          nref = nx/2 + 3

          allocate( rref(nref) )
          rref=0.0

          do i=1,nref
            rref(i) = xhref( nx/2 + i )
          enddo

          rrmax = rref(nref)

          if( myid.eq.0 ) print *,'  xref,yref     = ',xref,yref
          if( myid.eq.0 ) print *,'  rrmax,nref = ',rrmax,nref

        ENDIF


        allocate(    vt(nref) )
        allocate(  vref(nref,0:nk+1))
        allocate( piref(nref,0:nk+1))
        allocate(  pref(nref,0:nk+1))
        allocate( thref(nref,0:nk+1))
        allocate(thvref(nref,0:nk+1))
        allocate( qvref(nref,0:nk+1))
        allocate( rhref(nref,0:nk+1))

            vt=0.0
          vref=0.0
         piref=0.0
          pref=0.0
         thref=0.0
        thvref=0.0
         qvref=0.0
         rhref=0.0

        IF(ibalance.ne.0)THEN
          if(dowr) write(outfile,*)
          if(dowr) write(outfile,*) ' Please use ibalance = 0 with iinit=7'
          if(dowr) write(outfile,*)
          if(dowr) write(outfile,*) ' ... stopping inside init3d ... '
          if(dowr) write(outfile,*)
          call stopcm1
        ENDIF
        IF(terrain_flag)THEN
          if(dowr) write(outfile,*)
          if(dowr) write(outfile,*) ' iinit=7 is not setup for use with terrain'
          if(dowr) write(outfile,*)
          if(dowr) write(outfile,*) ' ... stopping inside init3d ... '
          if(dowr) write(outfile,*)
          call stopcm1
        ENDIF


      IF( tctype.eq.1 )THEN
        ! Rotunno-Emanuel (1987) vortex:
        dd2 = 2.0 * rmax_re87 / ( r0_re87 + rmax_re87 )
        do i=1,nref
          if(rref(i).lt.r0_re87)then
            dd1 = 2.0 * rmax_re87 / ( rref(i) + rmax_re87 )
            vt(i) = sqrt( vmax_re87**2 * (rref(i)/rmax_re87)**2     &
            * ( dd1 ** 3 - dd2 ** 3 ) + 0.25*fcor*fcor*rref(i)*rref(i) )   &
                    - 0.5 * fcor * rref(i)
          else
            vt(i) = 0.0
          endif
        enddo
      ELSEIF( tctype.eq.2 )THEN
        ! modified Rankine vortex:
        do i=1,nref
          if( rref(i).lt.rm1 )then
            vt(i) = vmax*rref(i)/rm1
          elseif( rref(i).lt.rm2 )then
            vt(i) = vmax*( (rref(i)/rm1)**rdc )
          elseif( rref(i).lt.rm3 )then
            v2 = vmax*( (rref(i)/rm1)**rdc )
            v3 = vmax*0.5*(1.0-(rref(i)-rm2)/(rm3-rm2))
            w3 = (rref(i)-rm2)/(rm3-rm2)
            w2 = 1.0-w3
            vt(i) = w2*v2+w3*v3
          else
            vt(i) = 0.0
          endif
        enddo
      ENDIF


        if( myid.eq.0 )then
          print *
          print *,'  tangential velocity profile:  r (km), v (m/s):'
          do i=1,nref
            print *,i,rref(i),vt(i)
          enddo
          print *
        endif


        ! just distribute linearly from surface to zdd
        ! (as in Rotunno-Emanuel 1987)
        do k=1,nk
        do i=1,nref
          if(zh(1,1,k).lt.zdd)then
            vref(i,k) = vt(i) * (zdd-zh(1,1,k))/(zdd-0.0)
          else
            vref(i,k) = 0.0
          endif
        enddo
        enddo

        do k=1,nk
          ! store environmental relative humidity (RH) in dum2 array:
          dum2(1,1,k) = qv0(1,1,k)/(rslf(prs0(1,1,k),th0(1,1,k)*pi0(1,1,k)))
          do i=1,nref
            rhref(i,k) = dum2(1,1,k)
            thref(i,k) = 0.0
            piref(i,k) = 0.0
            pref(i,k) = prs0(1,1,k)
          enddo
        enddo

        IF( rhmods )THEN
          ! increase RH in the inner core region (see parameters above)
          do k=1,nk
          do i=1,nref
            rhref(i,k) = max( dum2(1,1,k) , dum2(1,1,k) + (rhmax-dum2(1,1,k))*0.5*( 1.0+tanh( -(rref(i)-rmid)/rscale ) )  &
                                                                             *0.5*( 1.0+tanh( -(zh(1,1,k)-zmid)/zscale ) )  )
          enddo
          enddo
        ENDIF

      ! need to iterate for qv to converge:
      DO nloop=1,20

        ! get pressure (pref) and theta-v (thvref) from pi-pert (piref) and theta-pert (thref):
        do k=1,nk
        do i=1,nref
          pref(i,k) = p00*((pi0(1,1,k)+piref(i,k))**cpdrd)
          if(imoist.eq.1)then
            tnew=(th0(1,1,k)+thref(i,k))*(pi0(1,1,k)+piref(i,k))
            if( iice.eq.1 )then
              fliq=max(min((tnew-233.15)/(273.15-233.15),1.0),0.0)
              fice=1.0-fliq
              qsw=0.0
              if(tnew.gt.233.15)then
                qsw=fliq*rslf(pref(i,k),tnew)
              endif
              qsi=0.0
              if(tnew.lt.273.15)then
                qsi=fice*rsif(pref(i,k),tnew)
              endif
              qvs=qsw+qsi
            else
              qvs=rslf(pref(i,k),tnew)
            endif
            qvref(i,k) = rhref(i,k)*qvs
          endif
          thvref(i,k)=(th0(1,1,k)+thref(i,k))*(1.0+reps*qvref(i,k))   &
                                             /(1.0+qvref(i,k))
        enddo
        enddo

        ! get pi-pert from gradient-wind equation:
        do k=1,nk
          piref(nref,k)=0.0
          do i=nref,2,-1
            piref(i-1,k) = piref(i,k)                                       &
         + (rref(i-1)-rref(i))/(cp*0.5*(thvref(i-1,k)+thvref(i,k))) * 0.5 * &
             ( vref(i  ,k)*vref(i  ,k)/rref(i)                              &
              +vref(i-1,k)*vref(i-1,k)/rref(i-1)                            &
               + fcor * ( vref(i,k) + vref(i-1,k) ) )
          enddo
        enddo

        do i=1,nref
          piref(i,   0) = piref(i, 1)
          piref(i,nk+1) = piref(i,nk)
        enddo

        ! get theta-pert from hydrostatic equation:
        do k=2,nk
        do i=1,nref
          thref(i,k) = 0.5*( cp*0.5*(thvref(i,k)+thvref(i,k+1))*(piref(i,k+1)-piref(i,k))*rdz*mf(1,1,k+1)     &
                            +cp*0.5*(thvref(i,k)+thvref(i,k-1))*(piref(i,k)-piref(i,k-1))*rdz*mf(1,1,k) )   &
                          *thv0(1,1,k)/g
          thref(i,k)=(thv0(1,1,k)+thref(i,k))*(1.0+qvref(i,k))/(1.0+reps*qvref(i,k))-th0(1,1,k)
        enddo
        enddo

        k=1
        do i=1,nref
          thref(i,k) = ( cp*0.5*(thvref(i,k)+thvref(i,k+1))*(piref(i,k+1)-piref(i,k))*rdz*mf(1,1,k+1) )   &
                          *thv0(1,1,k)/g
          thref(i,k)=(thv0(1,1,k)+thref(i,k))*(1.0+qvref(i,k))/(1.0+reps*qvref(i,k))-th0(1,1,k)
        enddo

        if(dowr) write(outfile,*) nloop,thref(1,1),qvref(1,1),piref(1,1)

      ENDDO   ! enddo for iteration


        tha = 0.0
        ppi = 0.0
        ua = 0.0
        va = 0.0

        xsave = xref
        ysave = yref

        grid:  &
        IF(axisymm.eq.1)THEN
          ! for axisymmetric model, we are done:

          do k=1,nk
          do j=0,nj+2
          do i=1,ni
             va(i,j,k) =  vref(i,k)
            ppi(i,j,k) = piref(i,k)
            tha(i,j,k) = thref(i,k)
            if(imoist.eq.1) qa(i,j,k,nqv) = qvref(i,k)
          enddo
          enddo
          enddo

        ELSE  grid
          ! for 3d model, we need to interpolate:

          if( myid.eq.0 ) print *
          if( myid.eq.0 ) print *,'  Interpolate to Cartesian grid: '

      ! loop through all possible neighbor domains:
      nnloop:  &
      do nn = 1 , 9

        doit = .false.

        if(     nn.eq.1 )then
          doit = .true.
          xref = xsave
          yref = ysave
        elseif( nn.eq.2 )then
          if( ebc.eq.1 .and. wbc.eq.1 .and. sbc.eq.1 .and. nbc.eq.1 )then
          doit = .true.
          xref = xsave + (maxx-minx)
          yref = ysave + (maxy-miny)
          endif
        elseif( nn.eq.3 )then
          if( ebc.eq.1 .and. wbc.eq.1 .and. sbc.eq.1 .and. nbc.eq.1 )then
          doit = .true.
          xref = xsave - (maxx-minx)
          yref = ysave - (maxy-miny)
          endif
        elseif( nn.eq.4 )then
          if( ebc.eq.1 .and. wbc.eq.1 .and. sbc.eq.1 .and. nbc.eq.1 )then
          doit = .true.
          xref = xsave + (maxx-minx)
          yref = ysave - (maxy-miny)
          endif
        elseif( nn.eq.5 )then
          if( ebc.eq.1 .and. wbc.eq.1 .and. sbc.eq.1 .and. nbc.eq.1 )then
          doit = .true.
          xref = xsave - (maxx-minx)
          yref = ysave + (maxy-miny)
          endif
        elseif( nn.eq.6 )then
          if( ebc.eq.1 .and. wbc.eq.1 )then
          doit = .true.
          xref = xsave + (maxx-minx)
          yref = ysave
          endif
        elseif( nn.eq.7 )then
          if( ebc.eq.1 .and. wbc.eq.1 )then
          doit = .true.
          xref = xsave - (maxx-minx)
          yref = ysave
          endif
        elseif( nn.eq.8 )then
          if( sbc.eq.1 .and. nbc.eq.1 )then
          doit = .true.
          xref = xsave
          yref = ysave + (maxy-miny)
          endif
        elseif( nn.eq.9 )then
          if( sbc.eq.1 .and. nbc.eq.1 )then
          doit = .true.
          xref = xsave
          yref = ysave - (maxy-miny)
          endif
        endif

        IF( doit )THEN

          ! interpolate to Cartesian grid:
          if( myid.eq.0 ) print *,'  nn,xref,yref = ',nn,xref,yref

          do k=1,nk
          do j=0,nj+1
          do i=0,ni+1
            ! scalar points:
            tem1 = xh(i)-xref
            tem2 = yh(j)-yref
            rr = dsqrt( tem1**2 + tem2**2 )
          if( rr.lt.rrmax )then
            ! need to account for grid stretching.  Do simple search:
            diff = -1.0e20
            ii = 0
            do while( diff.lt.0.0 )
              ii = ii + 1
              if( ii.gt.nref )then
                write(6,*)
                write(6,*) ' ii,nref = ',ii,nref
                write(6,*) ' rr      = ',rr,xref
                write(6,*) ' rref    = ',rref(ii-1),rref(ii-1)-rr
                write(6,*)
                call stopcm1
              endif
              diff = rref(ii)-rr
            enddo
            if( abs(rr-rref(ii)).lt.tsmall .and. ii.eq.1 ) ii = 2
            i2 = ii
            i1 = i2-1
            frac = (      rr-rref(i1))   &
                  /(rref(i2)-rref(i1))
            ppi(i,j,k) = piref(i1,k)+(piref(i2,k)-piref(i1,k))*frac
            tha(i,j,k) = thref(i1,k)+(thref(i2,k)-thref(i1,k))*frac
            if(imoist.eq.1) qa(i,j,k,nqv) = qvref(i1,k)+(qvref(i2,k)-qvref(i1,k))*frac
          else
            if(nn.eq.1)then
              tha(i,j,k) = thref(nref,k)
              ppi(i,j,k) = piref(nref,k)
              qa(i,j,k,nqv) = qvref(nref,k)
            endif
          endif
          enddo
          enddo
          enddo

          do k=1,nk
          do j=0,nj+1
          do i=0,ni+2
            ! u points:
            tem1 = xf(i)-xref
            tem2 = yh(j)-yref
            rr = dsqrt( tem1**2 + tem2**2 )
          if( rr.lt.tsmall )then
            ua(i,j,k) = 0.0
          elseif( rr.lt.rrmax )then
            ! need to account for grid stretching.  Do simple search:
            diff = -1.0e20
            ii = 0
            do while( diff.lt.0.0 )
              ii = ii + 1
              if( ii.gt.nref )then
                write(6,*)
                write(6,*) ' ii,nref = ',ii,nref
                write(6,*) ' rr      = ',rr,xref
                write(6,*)
                call stopcm1
              endif
              diff = rref(ii)-rr
            enddo
            if( abs(rr-rref(ii)).lt.tsmall .and. ii.eq.1 ) ii = 2
            i2 = ii
            i1 = i2-1
            frac = (      rr-rref(i1))   &
                  /(rref(i2)-rref(i1))
            temd = -( dsin(datan2(tem2,tem1)) )
            ua(i,j,k) = ua(i,j,k) + ( vref(i1,k)+( vref(i2,k)- vref(i1,k))*frac )*temd
          endif
          enddo
          enddo
          enddo

          do k=1,nk
          do j=0,nj+2
          do i=0,ni+1
            ! v points:
            tem1 = xh(i)-xref
            tem2 = yf(j)-yref
            rr = dsqrt( tem1**2 + tem2**2 )
          if( rr.lt.tsmall )then
            va(i,j,k) = 0.0
          elseif( rr.lt.rrmax )then
            ! need to account for grid stretching.  Do simple search:
            diff = -1.0e20
            ii = 0
            do while( diff.lt.0.0 )
              ii = ii + 1
              if( ii.gt.nref )then
                write(6,*)
                write(6,*) ' ii,nref = ',ii,nref
                write(6,*) ' rr      = ',rr,xref
                write(6,*)
                call stopcm1
              endif
              diff = rref(ii)-rr
            enddo
            if( abs(rr-rref(ii)).lt.tsmall .and. ii.eq.1 ) ii = 2
            i2 = ii
            i1 = i2-1
            frac = (      rr-rref(i1))   &
                  /(rref(i2)-rref(i1))
            temd =  ( dcos(datan2(tem2,tem1)) )
            va(i,j,k) = va(i,j,k) + ( vref(i1,k)+( vref(i2,k)- vref(i1,k))*frac )*temd
          endif
          enddo
          enddo
          enddo


!!!          print *
!!!          print *,'  symmtest:'
!!!          j = nj/2 + 5
!!!          k = 1
!!!          do i=1,nref
!!!            print *,i,j,ua(i,j,k),va(j,i,k),ua(i,j,k)+va(j,i,k)
!!!          enddo
!!!          print *

        ENDIF

      enddo  nnloop

          if( myid.eq.0 ) print *

          xref = xsave
          yref = ysave

          ! 180607
          ! final step: add base-state wind profile
          do k=kb,ke
          do j=jb,je
          do i=ib,ie
            ua(i,j,k) = ua(i,j,k)+u0(i,j,k)
            va(i,j,k) = va(i,j,k)+v0(i,j,k)
          enddo
          enddo
          enddo

        ENDIF  grid


        ! all done, set some boundary conditions, calculate final pressure, etc:

        call bcu(ua)
        call bcv(va)
        call bcs(ppi)
        call bcs(tha)

        call calcprs(pi0,prs,ppi)

        deallocate(  rref)
        deallocate(    vt)
        deallocate(  vref)
        deallocate( piref)
        deallocate(  pref)
        deallocate( thref)
        deallocate(thvref)
        deallocate( qvref)
        deallocate( rhref)

        setppi = .false.

      !-----------------------------------
      ! add random theta perts for 3d runs:
      ! (plus or minus this value in K)

      IF( nx.gt.3 .and. ny.gt.3 )THEN

        amplitude = 0.1

        do k=1,nk
          ! cm1r17: loop over entire domain
          do jj=1,ny
          do ii=1,nx
            call random_number(rand)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              ! only add perts in the warm core:
              if( tha(i,j,k).ge.0.1 )  &
              tha(i,j,k)=tha(i,j,k)+amplitude*(2.0*rand-1.0)
            ENDIF
          enddo
          enddo
        enddo

      ENDIF

!-----------------------------------------------------------------------
!  iinit = 8
!  Line thermal with random small-amplitude perturbations

      ELSEIF(iinit.eq.8)THEN

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  Warm bubble'
        if(dowr) write(outfile,*)

        ric     =  centerx  ! center of bubble in x-direction (m)
        zc      =   1500.0  ! height of center of bubble above ground (m)
        bhrad   =  10000.0  ! horizontal radius of bubble (m)
        bvrad   =   1500.0  ! vertical radius of bubble (m)
        bptpert =      2.0  ! max potential temp perturbation (K)

        ! By default, CM1 sets qv=constant at a constant height level for 
        ! this value of iinit.  If you would rather have rh=constant at 
        ! a constant height level, then set this to .true.
        maintain_rh = .false.

        ! amplitude of random perturbations:
        amplitude = 0.20

        do k=1,nk
        do jj=1,ny
        do ii=1,nx
          call random_number(rand)
          i = ii - myi1 + 1
          j = jj - myj1 + 1
        IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
          beta=sqrt(                             &
                    ((xh(i)-ric)/bhrad)**2       &
                   +((zh(i,j,k)-zc)/bvrad)**2)
          if(beta.lt.1.0)then
            tha(i,j,k)=bptpert*(cos(0.5*pi*beta)**2)   &
                      +amplitude*(2.0*rand-1.0)
          else
            tha(i,j,k)=0.0
          endif
        ENDIF
        enddo
        enddo
        enddo

!------------------------------------------------------------------
!  iinit = 9
!  Forced convergence
!  Reference:  Loftus et al, 2008: MWR, v. 136, pp. 2408--2421.

      ELSEIF(iinit.eq.9)THEN

        ! User-defined settings:
        Dmax     =  -1.0e-3     ! maximum divergence (s^{-1})
        zdeep    =  2000.0      ! depth (m) of forced convergence
        lamx     = 10000.0      ! Loftus et al lambda_x parameter
        lamy     = 10000.0      ! Loftus at al lambda_y parameter
        xcent    =     0.0      ! x-location (m)
        ycent    =     0.0      ! y-location (m)
        convtime =   900.0      ! time (s) at beginning of simulation over
                                ! which convergence is applied

        ! Don't change anything below here:
        convinit = 1
        IF( ny.eq.1 )THEN
          ! 2D (x-z):
          Aconv = (-0.5*Dmax)/( (1.0/(lamx**2)) )
          lamy = 1.0e20
        ELSEIF( nx.eq.1 )THEN
          ! 2D (y-z):
          Aconv = (-0.5*Dmax)/( (1.0/(lamy**2)) )
          lamx = 1.0e20
        ELSE
          ! 3D:
          Aconv = (-0.5*Dmax)/( (1.0/(lamx**2))+(1.0/(lamy**2)) )
        ENDIF

!------------------------------------------------------------------
!  iinit = 10
!  momentum (u) forcing scheme (Morrison et al, 2015, JAS, pg 315)

      ELSEIF(iinit.eq.10)THEN

        xc_uforce     =  minx + 0.5*(maxx-minx)    ! x_c (m), center point of forcing in x
        xr_uforce     =  10000.0                   ! x_r (m), radius of forcing in x
        zr_uforce     =  10000.0                   ! z_r (m), radius of forcing in z
        alpha_uforce  =    0.1                     ! alpha (m/s/s), max intensity of forcing
        t1_uforce     =  3300.0                    ! time (s) to start ramping down u-forcing
        t2_uforce     =  3600.0                    ! time (s) to turn off u-forcing

!------------------------------------------------------------------
!  iinit = 11
!  Potential-temperature perturbation for inertia-gravity wave test case.
!  Reference:  Skamarock and Klemp, 1994, MWR, 122, 2623-2630.

      ELSEIF(iinit.eq.11)THEN

        do k=1,nk
        do j=1,nj
        do i=1,ni
          !----------
          ! Skamarock-Klemp-94 nonhydrostatic-scale inertia-gravity wave test:
          tha(i,j,k)=0.01*(sin(pi*zh(i,j,k)/10000.0))   &
                         /(1.0+((xh(i)-100000.0)/5000.0)**2)
          !----------
          ! Skamarock-Klemp-94 hydrostatic-scale inertia-gravity wave test:
!!!          tha(i,j,k)=0.01*(sin(pi*zh(i,j,k)/10000.0))   &
!!!                         /(1.0+((xh(i)-0.0)/100000.0)**2)
          !----------
        enddo
        enddo
        enddo

!------------------------------------------------------------------
!  iinit = 12
!  updraft nudging scheme (Naylor and Gilmore, 2012, MWR, pgs 3699-3705)

      ELSEIF(iinit.eq.12)THEN

        xc_wnudge     =  centerx                   ! x_c (m), center point of nudging in x
        xr_wnudge     =  10000.0                   ! x_r (m), radius of nudging in x

        yc_wnudge     =  centery                   ! y_c (m), center point of nudging in y
        yr_wnudge     =  10000.0                   ! y_r (m), radius of nudging in y

        zc_wnudge     =   1500.0                   ! z_c (m), center point of nudging in z
        zr_wnudge     =   1500.0                   ! z_r (m), radius of nudging in z

        alpha_wnudge  =      0.5                   ! alpha (1/s), inverse e-folding time for nudging
        wmax_wnudge   =     10.0                   ! w_max (m/s), max value of w to nudge towards

        t1_wnudge     =    900.0                   ! time (s) to start ramping down nudging
        t2_wnudge     =   1200.0                   ! time (s) to turn off nudging


        ! Don't change anything below here:
        wnudge = 1
        rxrwnudge = 1.0/max( xr_wnudge , 1.0e-12 )
        ryrwnudge = 1.0/max( yr_wnudge , 1.0e-12 )
        rzrwnudge = 1.0/max( zr_wnudge , 1.0e-12 )

!------------------------------------------------------------------
!  iinit = 13
!

      ELSEIF(iinit.eq.13)THEN

        bvrad = 1000.0

        do k=1,nk
        do j=1,nj
        do i=1,ni
          if( zh(i,j,k).lt.bvrad )then
            tha(i,j,k)=1.0*sin(2.0*pi*xh(i)/(0.25*(maxx-minx)))  &
                          *sin(2.0*pi*yh(j)/(0.25*(maxy-miny)))  &
                          *sin(2.0*pi*zh(i,j,k)/(2.0*bvrad))
          endif
        enddo
        enddo
        enddo

!------------------------------------------------------------------

      ENDIF    ! end of iinit options

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
        
      if(imoist.eq.1 .and. maintain_rh)then

        !! maintain rh
        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  Constant rh across domain:'
        if(dowr) write(outfile,*)

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          dum2(i,j,k)=qv0(i,j,k)/(rslf(prs0(i,j,k),th0(i,j,k)*pi0(i,j,k)))
          qa(i,j,k,nqv)=dum2(i,j,k)*rslf(prs0(i,j,k),(th0(i,j,k)+tha(i,j,k))*pi0(i,j,k))
        enddo
        enddo
        enddo

      endif

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

! Random perturbations:

      IF( irandp.eq.1 )THEN

!        do n=1,nint(var7)
!          if(myid.eq.0) print *,'  pert loop = ',n
!        do k=1,nk
!          do jj = 0,ny+1
!          do ii = 0,nx+1
!            call random_number(rand)
!          enddo
!          enddo
!        enddo
!        enddo

      IF( testcase.eq.0 )THEN
        ! not a pre-configured test case: 

        ! this is the amplitude of the theta perturbations
        ! (plus or minus this value in K)
        amplitude = 0.25

        ! random numbers added here
        ! (can be modified to only place perturbations in certain
        !  locations, but this default code simply puts them
        !  everywhere)
        do k=1,nk
          ! cm1r17: loop over entire domain
          do jj = 0,ny+2
          do ii = 0,nx+2
            call random_number(rand)
            call random_number(rand2)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              tha(i,j,k)=tha(i,j,k)+amplitude*(2.0*rand-1.0)
            ENDIF
          enddo
          enddo
        enddo

      ELSEIF( testcase.eq.1 .or. testcase.eq.2 .or. testcase.eq.6 .or. testcase.eq.10 .or. testcase.eq.11 .or. testcase.eq.15 )THEN

        ! 1: convective boundary layer (Sullivan and Patton, 2011, JAS)
        ! 2: shear-driven boundary layer (Moeng and Sullivan, 1994, JAS)
        ! 6: hurricane boundary layer (Bryan et al, 2017, BLM)

        amplitude = 0.10
        dpi = 4.0d0*datan(1.0d0)

        do k=1,nk
        if( zh(1,1,k).le.100.0 )then
          ! cm1r17: loop over entire domain
          do jj = 0,ny+1
          do ii = 0,nx+1
            call random_number(rand)
            call random_number(rand2)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              tha(i,j,k)=tha(i,j,k)+amplitude*(2.0*rand-1.0)
            ENDIF
          enddo
          enddo
        endif
        enddo

      ELSEIF( testcase.eq.3 )THEN

        ! shallow Cu (Siebesma et al, 2003, JAS)

        do k=1,nk
        if( zh(1,1,k).le.1600.0 )then
          ! cm1r17: loop over entire domain
          do jj = 0,ny+1
          do ii = 0,nx+1
            call random_number(rand)
            call random_number(rand2)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              tha(i,j,k)=tha(i,j,k)+0.1*(2.0*rand-1.0)
              qa(i,j,k,nqv)=qa(i,j,k,nqv)+0.001*0.025*(2.0*rand2-1.0)
            ENDIF
          enddo
          enddo
        endif
        enddo

      ELSEIF( testcase.eq.4 .or. testcase.eq.5 .or. testcase.eq.7 )THEN

        amplitude = 0.10

        do k=1,nk
        if( zh(1,1,k).le.1000.0 )then
          ! cm1r17: loop over entire domain
          do jj = 0,ny+1
          do ii = 0,nx+1
            call random_number(rand)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              tha(i,j,k)=tha(i,j,k)+amplitude*(2.0*rand-1.0)
            ENDIF
          enddo
          enddo
        endif
        enddo


      ELSEIF( testcase.eq.8 )THEN

        ! RCEMIP:
        do k=1,5
          amplitude = 0.10 - (k-1)*0.02
          if( myid.eq.0 ) print *,'  amplitude = ',k,amplitude
          ! cm1r17: loop over entire domain
          do jj = 0,ny+1
          do ii = 0,nx+1
            call random_number(rand)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              tha(i,j,k)=tha(i,j,k)+amplitude*(2.0*rand-1.0)
            ENDIF
          enddo
          enddo
        enddo

      ELSEIF( testcase.eq.9 )THEN

        ! stable boundary layer (Beare et al. 2006)
        amplitude = 0.10
        do k=1,nk
          if( zh(1,1,k).lt.50.0 )then
          do jj = 0,ny+1
          do ii = 0,nx+1
            call random_number(rand)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              tha(i,j,k)=tha(i,j,k)+amplitude*(2.0*rand-1.0)
            ENDIF
          enddo
          enddo
          endif
        enddo

      ELSEIF( testcase.eq.12 .or. testcase.eq.13 )THEN
        ! velocity perturbations:

        ! this is the amplitude of the theta perturbations
        ! (plus or minus this value in K)
        amplitude = 0.5

        ! random numbers added here
        ! (can be modified to only place perturbations in certain
        !  locations, but this default code simply puts them
        !  everywhere)
        do k=1,nk
          ! dum1,dum2 are define at scalar pts:
          do j=0,nj+1
          do i=0,ni+1
            dum1(i,j,k) = u0(1,1,k)
            dum2(i,j,k) = v0(1,1,k)
          enddo
          enddo
          ! cm1r17: loop over entire domain
          do jj = 0,ny+2
          do ii = 0+5,nx+1-5
            call random_number(rand)
            call random_number(rand2)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              dum1(i,j,k)=dum1(i,j,k)+amplitude*(2.0*rand-1.0)
              dum2(i,j,k)=dum2(i,j,k)+amplitude*(2.0*rand2-1.0)
!!!              tha(i,j,k)=tha(i,j,k)+0.5*(2.0*rand2-1.0)
            ENDIF
          enddo
          enddo
          ! interpolate to u,v pts:
          do j=1,nj+1
          do i=1,ni+1
            ua(i,j,k) = 0.5*(dum1(i-1,j,k)+dum1(i,j,k))
            va(i,j,k) = 0.5*(dum2(i,j-1,k)+dum2(i,j,k))
          enddo
          enddo
        enddo

      ELSE

        amplitude = 0.10

        do k=1,nk
          do jj = 0,ny+1
          do ii = 0,nx+1
            call random_number(rand)
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              tha(i,j,k)=tha(i,j,k)+amplitude*(2.0*rand-1.0)
            ENDIF
          enddo
          enddo
        enddo

      ENDIF

      ENDIF

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

!----------------------------------------------
!  arrays for elliptic solver

      IF( (ibalance.eq.2).or.(psolver.eq.4).or.(psolver.eq.5).or.(pdcomp) )THEN

        dpi = 4.0d0*datan(1.0d0)
        if(dowr) write(outfile,*) '  dpi = ',dpi

        IF(psolver.le.3)THEN
          do k=1,nk
            cfa(k)=mh(1,1,k)*mf(1,1,k  )*rf0(1,1,k  )*0.5*(thv0(1,1,k-1)+thv0(1,1,k))/(dz*dz*rho0(1,1,k)*thv0(1,1,k))
            cfc(k)=mh(1,1,k)*mf(1,1,k+1)*rf0(1,1,k+1)*0.5*(thv0(1,1,k)+thv0(1,1,k+1))/(dz*dz*rho0(1,1,k)*thv0(1,1,k))
            ad1(k) = 1.0/(cp*rho0(1,1,k)*thv0(1,1,k))
            ad2(k) = 1.0
          enddo
          cfa( 1) = 0.0
          cfc(nk) = 0.0
          do j=jpb,jpe
          do i=ipb,ipe
            do k=1,nk
              cfb(i,j,k)=2.0d0*( dcos(2.0d0*dpi*dble(i-1)/dble(ipe))          &
                                +dcos(2.0d0*dpi*dble(j-1)/dble(jpe))          &
                                -2.0d0)/(dx*dx) - cfa(k) - cfc(k)
            enddo
          enddo
          enddo
        ELSE
          do k=1,nk
            cfa(k)=mh(1,1,k)*mf(1,1,k  )*rf0(1,1,k  )/(dz*dz*rho0(1,1,k-1))
            cfc(k)=mh(1,1,k)*mf(1,1,k+1)*rf0(1,1,k+1)/(dz*dz*rho0(1,1,k+1))
            ad1(k) = 1.0
            ad2(k) = 1.0/rho0(1,1,k)
          enddo
          cfa( 1) = 0.0
          cfc(nk) = 0.0
          do j=jpb,jpe
          do i=ipb,ipe
            do k=2,nk-1
              cfb(i,j,k)=2.0d0*( dcos(2.0d0*dpi*dble(i-1)/dble(ipe))          &
                                +dcos(2.0d0*dpi*dble(j-1)/dble(jpe))          &
                                -2.0d0)/(dx*dx)                               &
                    -mh(1,1,k)*mf(1,1,k+1)*rf0(1,1,k+1)/(dz*dz*rho0(1,1,k))   &
                    -mh(1,1,k)*mf(1,1,k  )*rf0(1,1,k  )/(dz*dz*rho0(1,1,k))
            enddo
            cfb(i,j,1)=2.0d0*( dcos(2.0d0*dpi*dble(i-1)/dble(ipe))          &
                              +dcos(2.0d0*dpi*dble(j-1)/dble(jpe))          &
                              -2.0d0)/(dx*dx)                               &
                  -mh(1,1,1)*mf(1,1,2  )*rf0(1,1,2  )/(dz*dz*rho0(1,1,1))
            cfb(i,j,nk)=2.0d0*( dcos(2.0d0*dpi*dble(i-1)/dble(ipe))          &
                              +dcos(2.0d0*dpi*dble(j-1)/dble(jpe))          &
                              -2.0d0)/(dx*dx)                               &
                  -mh(1,1,nk)*mf(1,1,nk  )*rf0(1,1,nk  )/(dz*dz*rho0(1,1,nk))
          enddo
          enddo
        ENDIF

      ENDIF

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

!-----------------------------------------------------------------
!  Get 3d pressure


    IF(setppi)THEN

      do k=kb,ke
      do j=jb,je
      do i=ib,ie
        ppi(i,j,k)=0.0
      enddo
      enddo
      enddo

      IF(ibalance.eq.1)THEN

        ! hydrostatic balance ... integrate top-down

        do j=1,nj
        do i=1,ni
          ! virtual potential temperature

          if(imoist.eq.1)then
            do k=1,nk
              qt=0.0
              do n=nql1,nql2
                qt=qt+qa(i,j,k,n)
              enddo
              if(iice.eq.1)then
                do n=nqs1,nqs2
                  qt=qt+qa(i,j,k,n)
                enddo
              endif
              thvnew(k)=(th0(i,j,k)+tha(i,j,k))*(1.0+reps*qa(i,j,k,nqv))   &
                                               /(1.0+qa(i,j,k,nqv)+qt)
            enddo
          else
            do k=1,nk
              thvnew(k)=th0(i,j,k)+tha(i,j,k)
            enddo
          endif

          ! non-dimensional pressure
          pinew(nk)=pi0(i,j,nk)
          do k=nk-1,1,-1
            pinew(k)=pinew(k+1)+g*(zh(i,j,k+1)-zh(i,j,k))   &
                    /(cp*0.5*(thvnew(k+1)+thvnew(k)))
          enddo

          ! new pressure
          do k=1,nk
            ppi(i,j,k)=pinew(k)-pi0(i,j,k)
            if(abs(ppi(i,j,k)).lt.1.0e-6) ppi(i,j,k)=0.0
          enddo

        enddo
        enddo

      ELSEIF(ibalance.eq.2)THEN

        if(dowr) write(outfile,*)
        if(dowr) write(outfile,*) '  ibalance = 2'
        if(dowr) write(outfile,*)

        if(stretch_x.ge.1.or.stretch_y.ge.1)then
          print *,'  this option not supported with horizontal grid stretching'
          print *,'  (yet)'
          call stopcm1
        endif

#ifdef MPI
        print *,'  This option is not (yet) supported in MPI mode'
        print *,'  (sorry)'
        print *
        call stopcm1
#endif

        ! buoyancy pressure

        ! th3d stores theta-v

        if(imoist.eq.1)then
!$omp parallel do default(shared)  &
!$omp private(i,j,k)
          do k=1,nk
          do j=1,nj
          do i=1,ni
            qt=0.0
            do n=nql1,nql2
              qt=qt+qa(i,j,k,n)
            enddo
            if(iice.eq.1)then
              do n=nqs1,nqs2
                qt=qt+qa(i,j,k,n)
              enddo
            endif
            th3d(i,j,k)=(th0(i,j,k)+tha(i,j,k))*(1.0+reps*qa(i,j,k,nqv))   &
                       /(1.0+qa(i,j,k,nqv)+qt)
          enddo
          enddo
          enddo
        else
!$omp parallel do default(shared)  &
!$omp private(i,j,k)
          do k=1,nk
          do j=1,nj
          do i=1,ni
            th3d(i,j,k)=th0(i,j,k)+tha(i,j,k)
          enddo
          enddo
          enddo
        endif

!$omp parallel do default(shared)  &
!$omp private(i,j,k)
        do j=1,nj
        do i=1,ni
          th3d(i,j,0   ) = th3d(i,j,1)
          th3d(i,j,nk+1) = th3d(i,j,nk)
        enddo
        enddo

!$omp parallel do default(shared)  &
!$omp private(i,j,k)
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum4(i,j,k)=g*( th3d(i,j,k)/thv0(i,j,k)-1.0 )
        enddo
        enddo
        enddo

!$omp parallel do default(shared)  &
!$omp private(i,j,k)
        do j=1,nj
        do i=1,ni
          dum4(i,j,0   ) = -dum4(i,j,1)
          dum4(i,j,nk+1) = -dum4(i,j,nk)
        enddo
        enddo

!$omp parallel do default(shared)  &
!$omp private(i,j,k)
        do k=1,nk+1
        do j=1,nj
        do i=1,ni
          wten(i,j,k)=0.5*( dum4(i,j,k-1)+dum4(i,j,k) )
        enddo
        enddo
        enddo

!$omp parallel do default(shared)  &
!$omp private(i,j,k)
        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          ppi(i,j,k)=0.0
          dum3(i,j,k)=0.0
          divx(i,j,k)=0.0
          uten(i,j,k)=0.0
          vten(i,j,k)=0.0
        enddo
        enddo
        enddo

        call     poiss(uh,vh,mh,rmh,mf,rmf,pi0,thv0,rho0,rf0,    &
                       dum1,dum2,dum3,dum4,divx,ppi,uten,vten,wten, &
                       cfb,cfa,cfc,ad1,ad2,pdt,lgbth,lgbph,rhs,trans,dtl)

        IF(psolver.eq.4.or.psolver.eq.5.or.psolver.eq.6)THEN

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
          do k=kb,ke
          do j=jb,je
          do i=ib,ie
            ppi(i,j,k)=((prs0(1,1,k)+ppi(i,j,k)*rho0(1,1,k))*rp00)**rovcp   &
                      -pi0(1,1,k)
            pp3d(i,j,k)=ppi(i,j,k)
          enddo
          enddo
          enddo

        ENDIF

        call bcs(ppi)

      ENDIF

    ENDIF

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!  change base state:
!  WARNING:  for dycore testing only 
!    (do not modify)

  dobsmod = .false.
  bsmod:  IF( dobsmod )THEN
    print *,'  33333 '
    call stopcm1

        if(imoist.eq.1)then
          print *,' 77665 '
          call stopcm1
        endif

        print *
        do k=kb,ke
        do j=jb,je
        do i=ib,ie
!-----------------------------------------------
! isentropic:
          th_sfc   =   288.0   ! Potential temperature of atmosphere (K)
          pi_sfc   =   1.0     ! Exner function at surface
          thfoo=th_sfc
          pifoo=pi_sfc-g*zh(i,j,k)/(cp*th_sfc)
          prsfoo=p00*(pifoo**cpdrd)
!-----------------------------------------------
! isothermal:
!          prs_sfc  = p00
!          t_sfc    = 333.15
!          hs       = rd*t_sfc/g        ! scale height of atmosphere
!          prsfoo=prs_sfc*EXP(-zh(i,j,k)/hs)
!          pifoo=(prsfoo/p00)**(rd/cp)
!          thfoo=t_sfc/pifoo
!-----------------------------------------------

          tha(i,j,k) = th0(i,j,k)+tha(i,j,k) - thfoo
          ppi(i,j,k) = pi0(i,j,k)+ppi(i,j,k) - pifoo

          th0(i,j,k) = thfoo
          pi0(i,j,k) = pifoo
          prs0(i,j,k) = prsfoo

          thv0(i,j,k) = th0(i,j,k)
          t0 = th0(i,j,k)*pi0(i,j,k)
          rho0(i,j,k) = prs0(i,j,k)/(rd*t0)

        enddo
        enddo
        enddo

      do k=kb,ke
      do j=jb,je
      do i=ib,ie
        rr0(i,j,k)=1.0/rho0(i,j,k)
      enddo
      enddo
      enddo

      do k=2,nk
      do j=jb,je
      do i=ib,ie
!!!        rf0(i,j,k)=0.5*(rho0(i,j,k-1)+rho0(i,j,k))
        rf0(i,j,k)=c1(i,j,k)*rho0(i,j,k-1)+c2(i,j,k)*rho0(i,j,k)
      enddo
      enddo
      enddo

      do j=jb,je
      do i=ib,ie
        ! cm1r17, 2nd-order extrapolation:
        rf0(i,j,1) = cgs1*rho0(i,j,1)+cgs2*rho0(i,j,2)+cgs3*rho0(i,j,3)
        rf0(i,j,0)=rf0(i,j,1)
        rho0s(i,j) = rf0(i,j,1)
        ! cm1r17, 2nd-order extrapolation:
        rf0(i,j,nk+1) = cgt1*rho0(i,j,nk)+cgt2*rho0(i,j,nk-1)+cgt3*rho0(i,j,nk-2)
      enddo
      enddo

      do k=kb,ke
      do j=jb,je
      do i=ib,ie
        rrf0(i,j,k)=1.0/rf0(i,j,k)
      enddo
      enddo
      enddo

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          rth0(i,j,k)=1.0/th0(i,j,k)
        enddo
        enddo
        enddo

      call bcs(ppi)

  ENDIF  bsmod

!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,*) 'Leaving INIT3D'

      end subroutine init3d


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine getset(restarted,mass1,cloudvar,dt,   &
                        xh,rxh,arh1,arh2,uh,ruh,xf,rxf,arf1,arf2,uf,ruf,yh,vh,rvh,yf,vf,rvf, &
                        zs,gz,rgz,gzu,rgzu,gzv,rgzv,dzdx,dzdy,gx,gxu,gy,gyv,    &
                        rds,sigma,rdsf,sigmaf,zh,mh,rmh,c1,c2,zf,mf,rmf,dumk1,dumk2, &
                        pi0,th0,rho0,rf0,prs0,thv0,ust,znt,u1,v1,s1,cm0,u0,v0,rth0,rr,rf,rho,prs, &
                        dum1,dum2,dum3,dum4,dum5,dum6,dum7,dum8,                &
                        ua,u3d,va,v3d,wa,w3d,ppi,pp3d,ppx,phi1,phi2,            &
                        tha,th3d,qa,q3d,cme,csm,ce1,ce2,                        &
                        tkea,tke3d,kmh,kmv,khh,khv,nm,defv,defh,lenscl,dissten, &
                        t11,t12,t13,t22,t23,t33,iamsat,                         &
                        pta,pt3d,pdata,bndy,kbdy,timavg,                        &
                        upten,vpten,ucuten,vcuten,                              &
                        reqs_u,reqs_v,reqs_w,reqs_s,reqs_p,reqs_tk,             &
                        nw1,nw2,ne1,ne2,sw1,sw2,se1,se2,                        &
                        pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,                        &
                        uw31,uw32,ue31,ue32,us31,us32,un31,un32,                &
                        vw31,vw32,ve31,ve32,vs31,vs32,vn31,vn32,                &
                        ww31,ww32,we31,we32,ws31,ws32,wn31,wn32,                &
                        sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,                &
                        tkw1,tkw2,tke1,tke2,tks1,tks2,tkn1,tkn2,                &
                        kw1,kw2,ke1,ke2,ks1,ks2,kn1,kn2)

      use input
      use constants
      use misclibs
      use bc_module
      use comm_module
      use parcel_module , only : getparcelzs
      use ib_module
      use turb_module , only : tkebc,calcnm,calcdef,turbsmag
#ifdef MPI
      use mpi
#endif
      implicit none
 
      logical, intent(in) :: restarted
      double precision, intent(inout) :: mass1
      logical, intent(in), dimension(maxq) :: cloudvar
      real, intent(inout) :: dt
      real, intent(in), dimension(ib:ie) :: xh,rxh,arh1,arh2,uh,ruh
      real, intent(in), dimension(ib:ie+1) :: xf,rxf,arf1,arf2,uf,ruf
      real, intent(in), dimension(jb:je) :: yh,vh,rvh
      real, intent(in), dimension(jb:je+1) :: yf,vf,rvf
      real, intent(in), dimension(ib:ie,jb:je) :: zs
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,rgzu,gzv,rgzv,dzdx,dzdy
      real, intent(in), dimension(itb:ite,jtb:jte,ktb:kte) :: gx,gxu,gy,gyv
      real, intent(in), dimension(kb:ke) :: rds,sigma
      real, intent(in), dimension(kb:ke+1) :: rdsf,sigmaf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: zh,mh,rmh,c1,c2
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: zf,mf,rmf
      double precision, intent(inout), dimension(kb:ke) :: dumk1,dumk2
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: pi0,rho0,rf0,prs0,thv0
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: th0
      real, intent(inout), dimension(ib:ie,jb:je) :: ust,znt,u1,v1,s1,cm0
      real, intent(inout), dimension(ib:ie+1,jb:je,kb:ke) :: u0
      real, intent(inout), dimension(ib:ie,jb:je+1,kb:ke) :: v0
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: rth0
      real, dimension(ib:ie,jb:je,kb:ke) :: rr,rf,rho,prs
      real, dimension(ib:ie,jb:je,kb:ke) :: dum1,dum2,dum3,dum4,dum5,dum6,dum7,dum8
      real, dimension(ib:ie+1,jb:je,kb:ke) :: ua,u3d
      real, dimension(ib:ie,jb:je+1,kb:ke) :: va,v3d
      real, dimension(ib:ie,jb:je,kb:ke+1) :: wa,w3d
      real, dimension(ib:ie,jb:je,kb:ke) :: ppi,pp3d,ppx
      real, intent(inout), dimension(ibph:ieph,jbph:jeph,kbph:keph) :: phi1,phi2
      real, dimension(ib:ie,jb:je,kb:ke) :: tha,th3d
      real, dimension(ibm:iem,jbm:jem,kbm:kem,numq) :: qa,q3d
      real, dimension(ibc:iec,jbc:jec,kbc:kec) :: cme,csm,ce1,ce2
      real, dimension(ibt:iet,jbt:jet,kbt:ket) :: tkea,tke3d
      real, intent(inout), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmh,kmv,khh,khv
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: nm,defv,defh,lenscl,dissten
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: t11,t12,t13,t22,t23,t33
      logical, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: iamsat
      real, dimension(ibp:iep,jbp:jep,kbp:kep,npt) :: pta,pt3d
      real, intent(inout), dimension(nparcels,npvals) :: pdata
      logical, intent(in), dimension(ibib:ieib,jbib:jeib,kbib:keib) :: bndy
      integer, intent(in), dimension(ibib:ieib,jbib:jeib) :: kbdy
      real, intent(inout), dimension(ibb:ieb,jbb:jeb,kbb:keb) :: upten,vpten
      real, intent(inout), dimension(ibcu:iecu,jbcu:jecu,kbcu:kecu) :: ucuten,vcuten
      real, intent(inout), dimension(ibta:ieta,jbta:jeta,kbta:keta,ntavr) :: timavg
      integer, dimension(rmp) :: reqs_u,reqs_v,reqs_w,reqs_s,reqs_p,reqs_tk
      real, intent(inout), dimension(kmt) :: nw1,nw2,ne1,ne2,sw1,sw2,se1,se2
      real, intent(inout), dimension(jmp,kmp) :: pw1,pw2,pe1,pe2
      real, intent(inout), dimension(imp,kmp) :: ps1,ps2,pn1,pn2
      real, dimension(cmp,jmp,kmp)   :: uw31,uw32,ue31,ue32
      real, dimension(imp+1,cmp,kmp) :: us31,us32,un31,un32
      real, dimension(cmp,jmp+1,kmp) :: vw31,vw32,ve31,ve32
      real, dimension(imp,cmp,kmp)   :: vs31,vs32,vn31,vn32
      real, dimension(cmp,jmp,kmp-1) :: ww31,ww32,we31,we32
      real, dimension(imp,cmp,kmp-1) :: ws31,ws32,wn31,wn32
      real, dimension(cmp,jmp,kmp)   :: sw31,sw32,se31,se32
      real, dimension(imp,cmp,kmp)   :: ss31,ss32,sn31,sn32
      real, dimension(cmp,jmp,kmt)   :: tkw1,tkw2,tke1,tke2
      real, dimension(imp,cmp,kmt)   :: tks1,tks2,tkn1,tkn2
      real, intent(inout), dimension(jmp,kmt,4)     :: kw1,kw2,ke1,ke2
      real, intent(inout), dimension(imp,kmt,4)     :: ks1,ks2,kn1,kn2

!----------
 
      integer :: i,j,k,n
      real(kind=qp) :: temq
      real :: xw,xe,ys,yn,rtmp,rmin
      logical :: doit

      if(dowr) write(outfile,*) 'Inside GETSET'
      if(dowr) write(outfile,*)

!------------------------------------------------------------------

        IF( do_ib )THEN
          call zero_out_uv(bndy,kbdy,ua ,va )
          call zero_out_w(bndy,kbdy,wa )
          if( idoles .and. iusetke ) call zero_out_w(bndy,kbdy,tkea )
        ENDIF

!------------------------------------------------------------------
!  Make sure boundary values are set properly

      call bcu(ua)
      call bcv(va)
      call bcw(wa,1)
      call bcs(ppi)
      call bcs(tha)
      if(imoist.eq.1)then
        do n=1,numq
          call bcs(qa(ibm,jbm,kbm,n))
        enddo
      endif
      if( idoles .and. iusetke )then
        call bcw(tkea,1)
      endif
      if(iptra.eq.1)then
        do n=1,npt
          call bcs(pta(ib,jb,kb,n))
        enddo
      endif

      call bcu(u0)
      call bcv(v0)
      call bcs(th0)

#ifdef MPI
!------------------------------------------------------------------

      nf=0
      nu=0
      nv=0
      nw=0

      call comm_3u_start(ua,uw31,uw32,ue31,ue32,   &
                            us31,us32,un31,un32,reqs_u)
      call comm_3u_end(ua,uw31,uw32,ue31,ue32,   &
                          us31,us32,un31,un32,reqs_u)

      call comm_3v_start(va,vw31,vw32,ve31,ve32,   &
                            vs31,vs32,vn31,vn32,reqs_v)
      call comm_3v_end(va,vw31,vw32,ve31,ve32,   &
                          vs31,vs32,vn31,vn32,reqs_v)

      call comm_3w_start(wa,ww31,ww32,we31,we32,   &
                            ws31,ws32,wn31,wn32,reqs_w)
      call comm_3w_end(wa,ww31,ww32,we31,we32,   &
                          ws31,ws32,wn31,wn32,reqs_w)

      call comm_3s_start(ppi,sw31,sw32,se31,se32,   &
                             ss31,ss32,sn31,sn32,reqs_s)
      call comm_3s_end(ppi,sw31,sw32,se31,se32,   &
                           ss31,ss32,sn31,sn32,reqs_s)

      call comm_3s_start(tha,sw31,sw32,se31,se32,   &
                             ss31,ss32,sn31,sn32,reqs_s)
      call comm_3s_end(tha,sw31,sw32,se31,se32,   &
                           ss31,ss32,sn31,sn32,reqs_s)

      IF(imoist.eq.1)THEN
        do n=1,numq
          call comm_3s_start(qa(ibm,jbm,kbm,n),sw31,sw32,se31,se32,   &
                                               ss31,ss32,sn31,sn32,reqs_s)
          call comm_3s_end(qa(ibm,jbm,kbm,n),sw31,sw32,se31,se32,   &
                                             ss31,ss32,sn31,sn32,reqs_s)
        enddo
      ENDIF

      IF( idoles .and. iusetke )THEN
        call comm_3t_start(tkea,tkw1,tkw2,tke1,tke2,   &
                                tks1,tks2,tkn1,tkn2,reqs_tk)
        call comm_3t_end(tkea,tkw1,tkw2,tke1,tke2,   &
                              tks1,tks2,tkn1,tkn2,reqs_tk)
      ENDIF

      IF(iptra.eq.1)THEN
        do n=1,npt
          call comm_3s_start(pta(ib,jb,kb,n),sw31,sw32,se31,se32,   &
                                             ss31,ss32,sn31,sn32,reqs_s)
          call comm_3s_end(pta(ib,jb,kb,n),sw31,sw32,se31,se32,   &
                                           ss31,ss32,sn31,sn32,reqs_s)
        enddo
      ENDIF

      call comm_3u_start(u0,uw31,uw32,ue31,ue32,   &
                            us31,us32,un31,un32,reqs_u)
      call comm_3u_end(u0,uw31,uw32,ue31,ue32,   &
                          us31,us32,un31,un32,reqs_u)

      call comm_3v_start(v0,vw31,vw32,ve31,ve32,   &
                            vs31,vs32,vn31,vn32,reqs_v)
      call comm_3v_end(v0,vw31,vw32,ve31,ve32,   &
                          vs31,vs32,vn31,vn32,reqs_v)

      call comm_3s_start(th0,sw31,sw32,se31,se32,   &
                             ss31,ss32,sn31,sn32,reqs_s)
      call comm_3s_end(th0,sw31,sw32,se31,se32,   &
                           ss31,ss32,sn31,sn32,reqs_s)

      call MPI_BARRIER (MPI_COMM_WORLD,ierr)

#endif
      if(terrain_flag)then
        call bcwsfc(gz,dzdx,dzdy,ua,va,wa)
        call bc2d(wa(ib,jb,1))
      endif

      if( idoles .and. iusetke )then
        do j=1,nj
        do i=1,ni
          tkea(i,j,1) = tkea(i,j,2)
        enddo
        enddo
        call bc2d(tkea(ibt,jbt,1))
#ifdef MPI
        call comm_1s2d_start(tkea(ibt,jbt,1),sw31(1,1,1),sw32(1,1,1),se31(1,1,1),se32(1,1,1),   &
                                             ss31(1,1,1),ss32(1,1,1),sn31(1,1,1),sn32(1,1,1),reqs_s)
        call comm_1s2d_end(tkea(ibt,jbt,1),sw31(1,1,1),sw32(1,1,1),se31(1,1,1),se32(1,1,1),   &
                                           ss31(1,1,1),ss32(1,1,1),sn31(1,1,1),sn32(1,1,1),reqs_s)
        call bcs2_2d(tkea(ibt,jbt,1))
        call comm_2d_corner(tkea(ibt,jbt,1))
#endif
      endif

        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          rth0(i,j,k)=1.0/th0(i,j,k)
        enddo
        enddo
        enddo

!------------------------------------------------------------------

      do k=kb,ke
      do j=jb,je
      do i=ib,ie+1
        u3d(i,j,k)=ua(i,j,k)
      enddo
      enddo
      enddo
 
      do k=kb,ke
      do j=jb,je+1
      do i=ib,ie
        v3d(i,j,k)=va(i,j,k)
      enddo
      enddo
      enddo
 
      do k=kb,ke+1
      do j=jb,je
      do i=ib,ie
        w3d(i,j,k)=wa(i,j,k)
      enddo
      enddo
      enddo

      do k=kb,ke
      do j=jb,je
      do i=ib,ie
        pp3d(i,j,k)=ppi(i,j,k)
        th3d(i,j,k)=tha(i,j,k)
      enddo
      enddo
      enddo

      if(imoist.eq.1)then
        do n=1,numq
        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          q3d(i,j,k,n)=qa(i,j,k,n)
        enddo
        enddo
        enddo
        enddo
      endif

      if( idoles .and. iusetke )then
        do k=kbt,ket
        do j=jbt,jet
        do i=ibt,iet
          tke3d(i,j,k)=tkea(i,j,k)
        enddo
        enddo
        enddo
      endif

      if(iptra.eq.1)then
        do n=1,npt
        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          pt3d(i,j,k,n)=pta(i,j,k,n)
        enddo
        enddo
        enddo
        enddo
      endif

      if( psolver.eq.6 )then
        call bcs(phi1)
#ifdef MPI
        call comm_1s_start(phi1,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call comm_1s_end(phi1,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
#endif
        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          phi2(i,j,k)=phi1(i,j,k)
        enddo
        enddo
        enddo
      endif

!------------------------------------------------------------------
!  Get stuff

  IF( ( .not. restarted ) .or.( interp_on_restart ) )THEN

    IF(psolver.eq.4.or.psolver.eq.5.or.psolver.eq.6.or.psolver.eq.7)THEN

!$omp parallel do default(shared)  &
!$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni
        rho(i,j,k)=rho0(i,j,k)
        prs(i,j,k)=prs0(i,j,k)
      enddo
      enddo
      enddo

    ELSE

      if(myid.eq.0) print *
      if(myid.eq.0) print *,'  getting prs,rho '
      if(myid.eq.0) print *

      IF( imoist.eq.1 )THEN

        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,nj
        do i=1,ni
          prs(i,j,k)=p00*((pi0(i,j,k)+pp3d(i,j,k))**cpdrd)
          rho(i,j,k)=prs(i,j,k)                         &
             /( (th0(i,j,k)+th3d(i,j,k))*(pi0(i,j,k)+pp3d(i,j,k))     &
               *(rd+max(0.0,q3d(i,j,k,nqv))*rv) )
        enddo
        enddo
        enddo

      ELSE

        !$omp parallel do default(shared)  &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,nj
        do i=1,ni
          prs(i,j,k)=p00*((pi0(i,j,k)+pp3d(i,j,k))**cpdrd)
          rho(i,j,k)=prs(i,j,k)   &
             /(rd*(th0(i,j,k)+th3d(i,j,k))*(pi0(i,j,k)+pp3d(i,j,k)))
        enddo
        enddo
        enddo

      ENDIF

    ENDIF

  ENDIF


    IF( psolver.le.3 )THEN

        call bcs(rho)
#ifdef MPI
        call comm_1s_start(rho,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call comm_1s_end(rho,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call bcs2(rho)
        call getcorner(rho,nw1(1),nw2(1),ne1(1),ne2(1),sw1(1),sw2(1),se1(1),se2(1))
#endif

      !$omp parallel do default(shared)  &
      !$omp private(i,j,k)
        do k=1,nk
        do j=1,nj
        do i=1,ni
          rr(i,j,k) = 1.0/rho(i,j,k)
          rf(i,j,k) = (c1(i,j,k)*rho(i,j,k-1)+c2(i,j,k)*rho(i,j,k))
        enddo
        enddo
        enddo

        call bcs(rr)
#ifdef MPI
        call comm_1s_start(rr,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call comm_1s_end(rr,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call bcs2(rr)
        call getcorner(rr,nw1(1),nw2(1),ne1(1),ne2(1),sw1(1),sw2(1),se1(1),se2(1))
#endif
        call bcs(rf)
#ifdef MPI
        call comm_1s_start(rf,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call comm_1s_end(rf,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call bcs2(rf)
        call getcorner(rf,nw1(1),nw2(1),ne1(1),ne2(1),sw1(1),sw2(1),se1(1),se2(1))
#endif

        ! meh 1 !
      !$omp parallel do default(shared)  &
      !$omp private(i,j,k)
        do j=0,nj+1
        do i=0,ni+1
          ! cm1r17, 2nd-order extrapolation:
          rf(i,j,1) = cgs1*rho(i,j,1)+cgs2*rho(i,j,2)+cgs3*rho(i,j,3)
          rf(i,j,nk+1) = cgt1*rho(i,j,nk)+cgt2*rho(i,j,nk-1)+cgt3*rho(i,j,nk-2)
        enddo
        enddo

    ELSE

      do k=kb,ke
      do j=jb,je
      do i=ib,ie
        rho(i,j,k) = rho0(i,j,k)
        rr(i,j,k) = 1.0/rho0(i,j,k)
        rf(i,j,k) = rf0(i,j,k)
      enddo
      enddo
      enddo

    ENDIF

!------------------------------------------------------------------
!  cm1r18:  get total mass of dry air at t=0

      IF( ( .not. restarted ) .or. ( interp_on_restart ) )THEN

        if(myid.eq.0) print *
        if(myid.eq.0) print *,'  Getting mass1 '
        if(myid.eq.0) print *

        dumk1 = 0.0

        IF( axisymm.eq.0 )THEN
          do k=1,nk
          do j=1,nj
          do i=1,ni
            dumk1(k) = dumk1(k) + rho(i,j,k)*ruh(i)*rvh(j)*rmh(i,j,k)
          enddo
          enddo
          enddo
        ELSEIF( axisymm.eq.1 )THEN
          do k=1,nk
          do j=1,nj
          do i=1,ni
            dumk1(k) = dumk1(k) + rho(i,j,k)*ruh(i)*rvh(j)*rmh(i,j,k)*pi*(xf(i+1)**2-xf(i)**2)
          enddo
          enddo
          enddo
        ELSE
          stop 2223
        ENDIF

#ifdef MPI
        call MPI_ALLREDUCE(mpi_in_place,dumk1(1),nk,MPI_DOUBLE_PRECISION,MPI_SUM,MPI_COMM_WORLD,ierr)
#endif

        temq = 0.0

        do k=1,nk
          temq = temq + dumk1(k)
        enddo

        mass1 = temq

        if( myid.eq.0 ) print *
        if( myid.eq.0 ) print *,'  mass1 = ',mass1
        if( myid.eq.0 ) print *

      ENDIF

!------------------------------------------------------------------
!  cm1r19.5:

    IF( psolver.eq.2 .or. psolver.eq.3 .or. psolver.eq.6 .or. psolver.eq.7 )THEN

      IF( ( .not. restarted ) .or. ( interp_on_restart ) )THEN

        if( myid.eq.0 ) print *
        if( myid.eq.0 ) print *,'  setting initial ppx '
        if( myid.eq.0 ) print *

        IF( psolver.eq.2 .or. psolver.eq.3 .or. psolver.eq.7 )THEN

          !$omp parallel do default(shared)   &
          !$omp private(i,j,k)
          do k=1,nk
          do j=1,nj
          do i=1,ni
            ppx(i,j,k)=ppi(i,j,k)
          enddo
          enddo
          enddo

        ELSEIF( psolver.eq.6 )THEN

          !$omp parallel do default(shared)   &
          !$omp private(i,j,k)
          do k=1,nk
          do j=1,nj
          do i=1,ni
            ppx(i,j,k)=phi1(i,j,k)
          enddo
          enddo
          enddo

        ENDIF

      ENDIF

      call bcs(ppx)
#ifdef MPI
      call comm_1s_start(ppx,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
      call comm_1s_end(ppx,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
#endif

    ENDIF

!------------------------------------------------------------------

      if( iprcl.eq.1 .and. terrain_flag )THEN
        ! get terrain at parcel locations:
        if( prsig.ge.1 )then
          call getparcelzs(xh,uh,ruh,xf,yh,vh,rvh,yf,zs,pdata)
        else
          print *,'  invalid value for prsig: ',prsig
          call stopcm1
        endif
        if( .not. restarted )then
          ! 181022:  not a restart ... initialize sigma
          do n=1,nparcels
            ! get sigma from z:
            ! (see Section 3 of "The governing equations for CM1", 
            !  http://www2.mmm.ucar.edu/people/bryan/cm1/cm1_equations.pdf)
            pdata(n,prsig) = zt*(pdata(n,prz)-pdata(n,przs))/(zt-pdata(n,przs))
          enddo
        else
          ! 181022:  this is a restart ... get z
          do n=1,nparcels
            ! get z from sigma:
            ! (see Section 3 of "The governing equations for CM1", 
            !  http://www2.mmm.ucar.edu/people/bryan/cm1/cm1_equations.pdf)
            pdata(n,prz) = pdata(n,przs) + pdata(n,prsig)*((zt-pdata(n,przs))*rzt)
          enddo
        endif
      endif

!------------------------------------------------------------------

      ifidoles:  &
      IF( idoles )THEN

        cm1setupval:  &
        if( cm1setup.eq.1 )then

          ! LES:
          ! cm0 is the same everywhere

          cm0 = c_m

        elseif( cm1setup.eq.4 )then  cm1setupval

          ! LES embedded within mesoscale model:
          ! cm0 is non-zero in the inner part of the domain only

          cm0 = 0.0

          IF( les_subdomain_shape.eq.1 )THEN
            ! square/rectangle:

            xw = centerx - 0.5*les_subdomain_xlen
            xe = centerx + 0.5*les_subdomain_xlen
            ys = centery - 0.5*les_subdomain_ylen
            yn = centery + 0.5*les_subdomain_ylen

            if( myid.eq.0 ) print *
            if( myid.eq.0 ) print *,'  centerx,centery = ',centerx,centery
            if( myid.eq.0 ) print *,'  xw,xe           = ',xw,xe
            if( myid.eq.0 ) print *,'  ys,yn           = ',ys,yn
            if( myid.eq.0 ) print *

            do j=jb,je
            do i=ib,ie
              if( xh(i).gt.xw .and. xh(i).lt.xe .and. yh(j).gt.ys .and. yh(j).lt.yn )then
                cm0(i,j) = c_m
                ! 220301:
                if( xh(i).lt. xw+les_subdomain_trnslen ) cm0(i,j) = min( cm0(i,j) ,  c_m*(xh(i)-xw)/les_subdomain_trnslen )
                if( xh(i).gt. xe-les_subdomain_trnslen ) cm0(i,j) = min( cm0(i,j) , -c_m*(xh(i)-xe)/les_subdomain_trnslen )
                if( yh(j).lt. ys+les_subdomain_trnslen ) cm0(i,j) = min( cm0(i,j) ,  c_m*(yh(j)-ys)/les_subdomain_trnslen )
                if( yh(j).gt. yn-les_subdomain_trnslen ) cm0(i,j) = min( cm0(i,j) , -c_m*(yh(j)-yn)/les_subdomain_trnslen )
              endif
            enddo
            enddo

          ELSE

            if( myid.eq.0 )then
              print *
              print *,'  undefined value for les_subdomain_shape '
              print *
              print *,'    24987 '
              print *
            endif

            call stopcm1

          ENDIF

        endif  cm1setupval

        ! cm0 should now be set ... get other variables:
        do k=kb,ke
        do j=jb,je
        do i=ib,ie
          if( cm0(i,j).gt.cmemin )then
            cme(i,j,k) = cm0(i,j)
            ce1(i,j,k) = cme(i,j,k) * c_l * c_l * ( 1.0 / ri_c - 1.0 )
            ce2(i,j,k) = max( 0.0 , cme(i,j,k) * pi * pi - ce1(i,j,k) )
            csm(i,j,k) = ( cme(i,j,k) * cme(i,j,k) * cme(i,j,k) / ( ce1(i,j,k) + ce2(i,j,k) ) )**0.25   ! Smagorinsky constant
          endif
        enddo
        enddo
        enddo

      ENDIF  ifidoles

!------------------------------------------------------------------
!  Get eddy diffusivities if interpolating on restart:

    doit = .true.
    IF( doit )THEN

    iorst:  &
    IF( interp_on_restart .and. ( cm1setup.eq.1 .or. cm1setup.eq.4 ) )THEN
    if( idoles .and. iusetke )then

      if(myid.eq.0) print *
      if(myid.eq.0) print *,'  Getting initial subgrid tke ... '
      if(myid.eq.0) print *

        iamsat = .false.
        call calcnm(c1,c2,mf,pi0,thv0,th0,cloudvar,nm,dum1,dum2,dum3,dum4,dum5,dum6,   &
                    prs,ppi,tha,qa,iamsat)

        call calcdef(    rds,sigma,rdsf,sigmaf,zs,gz,rgz,gzu,rgzu,gzv,rgzv,                &
                     xh,rxh,arh1,arh2,uh,xf,rxf,arf1,arf2,uf,vh,vf,mh,c1,c2,mf,defv,defh,  &
                     dum1,dum2,ua,va,wa,t11,t12,t13,t22,t23,t33,gx,gy,rho,rr,rf)


        call     turbsmag(  0  ,dt,ruh,rvh,rmh,mf,rmf,th0,rf,              &
                          nm,defv,defh,dum4,dum5  ,dum6  ,zf,znt  ,ust,csm, &
                          kmh,kmv,khh,khv,lenscl,dissten,                  &
                          nw1,nw2,ne1,ne2,sw1,sw2,se1,se2,                 &
                          kw1(1,1,1),kw2(1,1,1),ke1(1,1,1),ke2(1,1,1),     &
                          ks1(1,1,1),ks2(1,1,1),kn1(1,1,1),kn2(1,1,1),     &
                          kw1(1,1,2),kw2(1,1,2),ke1(1,1,2),ke2(1,1,2),     &
                          ks1(1,1,2),ks2(1,1,2),kn1(1,1,2),kn2(1,1,2))

      do k=2,nk
      do j=1,nj
      do i=1,ni
        if( cm0(i,j).gt.cmemin )  &
        tkea(i,j,k) = (kmv(i,j,k)/(cme(i,j,k)*lenscl(i,j,k)))**2
      enddo
      enddo
      enddo

        IF( do_ib ) call zero_out_w(bndy,kbdy,tkea )
        call bcw(tkea,1)
#ifdef MPI
        call comm_3t_start(tkea,tkw1,tkw2,tke1,tke2,   &
                                tks1,tks2,tkn1,tkn2,reqs_tk)
        call comm_3t_end(tkea,tkw1,tkw2,tke1,tke2,   &
                              tks1,tks2,tkn1,tkn2,reqs_tk)
#endif
        do j=1,nj
        do i=1,ni
          tkea(i,j,1) = tkea(i,j,2)
        enddo
        enddo
        call bc2d(tkea(ibt,jbt,1))
#ifdef MPI
        call comm_1s2d_start(tkea(ibt,jbt,1),sw31(1,1,1),sw32(1,1,1),se31(1,1,1),se32(1,1,1),   &
                                             ss31(1,1,1),ss32(1,1,1),sn31(1,1,1),sn32(1,1,1),reqs_s)
        call comm_1s2d_end(tkea(ibt,jbt,1),sw31(1,1,1),sw32(1,1,1),se31(1,1,1),se32(1,1,1),   &
                                           ss31(1,1,1),ss32(1,1,1),sn31(1,1,1),sn32(1,1,1),reqs_s)
        call bcs2_2d(tkea(ibt,jbt,1))
        call comm_2d_corner(tkea(ibt,jbt,1))
#endif
        do k=kbt,ket
        do j=jbt,jet
        do i=ibt,iet
          tke3d(i,j,k)=tkea(i,j,k)
        enddo
        enddo
        enddo

    endif
    ENDIF  iorst
    ENDIF

!------------------------------------------------------------------

      if( use_pbl )then

        call bcs(upten)
        call bcs(vpten)
#ifdef MPI
        call comm_1s_start(upten,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call comm_1s_end(upten,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call comm_1s_start(vpten,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
        call comm_1s_end(vpten,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
#endif
        IF( axisymm.eq.1 )THEN
          ! cm1r19 bug fix:
          !$omp parallel do default(shared)   &
          !$omp private(i,k)
          do k=1,nk
            upten(0,1,k) = -upten(1,1,k)
            upten(ni+1,1,k) = upten(ni,1,k)
            do i=0,ni+1
              vpten(i,0,k) = vpten(i,1,k)
              vpten(i,2,k) = vpten(i,1,k)
              vpten(i,3,k) = vpten(i,1,k)
            enddo
          enddo
        ENDIF

      endif

!------------------------------------------------------------------

    IF( cuparam.eq.1 )THEN
      call bcs(ucuten)
      call bcs(vcuten)
#ifdef MPI
      call comm_1s_start(ucuten,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
      call comm_1s_end(ucuten,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
      call comm_1s_start(vcuten,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
      call comm_1s_end(vcuten,pw1,pw2,pe1,pe2,ps1,ps2,pn1,pn2,reqs_p)
#endif
      ENDIF

!------------------------------------------------------------------

        tavgcode:  &
        IF( dotimeavg .and. ( (.not. restarted) .or. interp_on_restart ) )THEN
          if(myid.eq.0) print *
          if(myid.eq.0) print *,'  initializing timeavg fields '
          if(myid.eq.0) print *
          if(utav.ge.1)then
            do k=1,keta
            do j=0,nj+1
            do i=0,ni+2
              timavg(i,j,k,utav) = u3d(i,j,k)
            enddo
            enddo
            enddo
          endif
          if(vtav.ge.1)then
            do k=1,keta
            do j=0,nj+2
            do i=0,ni+1
              timavg(i,j,k,vtav) = v3d(i,j,k)
            enddo
            enddo
            enddo
          endif
          if(wtav.ge.1)then
            do k=1,keta
            do j=0,nj+1
            do i=0,ni+1
              timavg(i,j,k,wtav) = w3d(i,j,k)
            enddo
            enddo
            enddo
          endif
          if(ttav.ge.1)then
            do k=1,keta
            do j=0,nj+1
            do i=0,ni+1
              timavg(i,j,k,ttav) = th3d(i,j,k)
            enddo
            enddo
            enddo
          endif
          if(etav.ge.1)then
            do k=1,keta
            do j=0,nj+1
            do i=0,ni+1
              timavg(i,j,k,etav) = tke3d(i,j,k)
            enddo
            enddo
            enddo
          endif
          if(qtav.ge.1)then
            do k=1,keta
            do j=0,nj+1
            do i=0,ni+1
              timavg(i,j,k,qtav) = q3d(i,j,k,nqv)
            enddo
            enddo
            enddo
          endif
        ENDIF  tavgcode

!------------------------------------------------------------------

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,*) 'Leaving GETSET'
 
      end subroutine getset


  END MODULE init3d_module

init_physics.F/ 1744672191  3193  100   100644  10116     `
  MODULE init_physics_module

  implicit none

  CONTAINS

      subroutine init_physics(prs0,rf0,dum1,dum2,dum3,u0,ua,v0,va,o30,   &
                             lu_index,xland,emiss,thc,albd,znt,mavail,tsk,u1,v1,s1, &
                             zh,u10,v10,wspd,lowlyr,ivgtyp,ust,sice)
      use input
      use constants
      use module_sf_slab
      use module_sf_sfclay
      use radtrns3d_module
      use module_ra_rrtmg_lw , only : rrtmg_lwinit
      use module_ra_rrtmg_sw , only : rrtmg_swinit
      use module_sf_mynn , only : mynn_sf_init_driver
      use module_sf_myjsfc , only : myjsfcinit
      use sf_sfclayrev , only : sf_sfclayrev_init
      use cu_ntiedtke, only : cu_ntiedtke_init
#ifdef MPI
      use mpi
#endif
      implicit none

      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: prs0,rf0
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum1,dum2,dum3
      real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: u0,ua
      real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: v0,va
      real, intent(inout), dimension(ibr:ier,jbr:jer,kbr:ker) :: o30
      integer, intent(in), dimension(ibl:iel,jbl:jel) :: lu_index
      real, intent(inout), dimension(ibl:iel,jbl:jel) :: emiss,thc,albd,mavail
      real, intent(inout), dimension(ib:ie,jb:je) :: tsk,znt,u1,v1,s1,xland
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: zh
      real, intent(inout), dimension(ibl:iel,jbl:jel) :: u10,v10,wspd
      integer, intent(inout), dimension(ibmyj:iemyj,jbmyj:jemyj) :: lowlyr,ivgtyp
      real, intent(inout), dimension(ib:ie,jb:je) :: ust
      real, intent(inout), dimension(ibmyj:iemyj,jbmyj:jemyj) :: sice

      real :: foo1,foo2,foo3,foo4,foo5,foo6
      real :: p_top

      character(len=80) :: errmsg
      integer :: errflg

!-----------------------------------------------------------------------
!-----  USERS SHOULD NOT NEED TO CHANGE ANYTHING IN THIS FILE ----------
!-----  (unless you really, really know what you are doing -------------
!-----------------------------------------------------------------------

      if(radopt.ge.1)then
        ! initialize radiation code:
        p_top = cgt1*prs0(1,1,nk)+cgt2*prs0(1,1,nk-1)+cgt3*prs0(1,1,nk-2)
        if(myid.eq.0) print *,'  p_top = ',p_top
        call setradwrk(nir,njr,nkr)
        call julday( year, month, day, jday )
        if(dowr) write(outfile,*) '  jday = ',jday
        if( radopt.eq.1 )  &
        call initrad(myid,year,month,day,hour,minute,second,jday,nir,njr,nkr)
        o30 = 1.0e-12
        if( radopt.eq.1 )  &
        call fito3(nir,njr,1,1,nkr,dum1(1,1,1),dum2(1,1,1),prs0,o30,ib,ie,jb,je,kb,ke,nk)
        ! Settings from Goddard scheme:
        call getgoddardvars(foo1,foo2,foo3,foo4,foo5,foo6,ptype)
        roqr = foo1
        tnw  = foo2
        roqs = foo3
        tns  = foo4
        roqg = foo5
        tng  = foo6
      endif

      IF( radopt.eq.2 )then

!!!             aclwalloc = .false.
!!!             acswalloc = .false.

#ifdef MPI
             call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif
             if(myid.eq.0) print *,'  rrtmg_lwinit '
#ifdef MPI
             call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif
             CALL rrtmg_lwinit(                                             &
                  p_top=p_top,                                              &
                  allowed_to_read = .true.         ,                        &
                   myid = myid ,                                            &
                  ids=1  ,ide=ni+1 , jds= 1 ,jde=nj+1 , kds=1  ,kde=nk+1 ,  &
                  ims=ib ,ime=ie   , jms=jb ,jme=je   , kms=kb ,kme=ke ,    &
                  its=1  ,ite=ni   , jts=1  ,jte=nj   , kts=1  ,kte=nk )

!!!             aclwalloc = .true.

#ifdef MPI
             call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif
             if(myid.eq.0) print *,'  rrtmg_swinit '
#ifdef MPI
             call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif
             CALL rrtmg_swinit(                                              &
                   allowed_to_read = .true.         ,                        &
                   myid = myid ,                                             &
                  ids=1  ,ide=ni+1 , jds= 1 ,jde=nj+1 , kds=1  ,kde=nk+1 ,   &
                  ims=ib ,ime=ie   , jms=jb ,jme=je   , kms=kb ,kme=ke ,     &
                  its=1  ,ite=ni   , jts=1  ,jte=nj   , kts=1  ,kte=nk )
#ifdef MPI
             call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif
             if(myid.eq.0) print *,'  done rrtmg init '
#ifdef MPI
             call MPI_BARRIER (MPI_COMM_WORLD,ierr)
#endif

!!!             acswalloc = .true.

      ENDIF

      IF( isfcflx.eq.1 )THEN
        if( sfcmodel.eq.2 )then
          call sfclayinit
        endif
        if( sfcmodel.eq.3 )then
          if(myid.eq.0) print *,'  sf_sfclayrev_init '
          call sf_sfclayrev_init(errmsg=errmsg,errflg=errflg)
        endif
        if( sfcmodel.eq.6 )then
          call mynn_sf_init_driver( .true. )
        endif
        if( sfcmodel.eq.7 )then
          call   MYJSFCINIT(LOWLYR=lowlyr,USTAR=ust,Z0=znt                            &
                           ,SEAMASK=xland,XICE=sice,IVGTYP=ivgtyp,RESTART=.false.                &
                           ,ALLOWED_TO_READ=.false.                    &
                 ,ids=1  ,ide=ni+1 , jds= 1 ,jde=nj+1 , kds=1  ,kde=nk+1 ,                     &
                  ims=ib ,ime=ie   , jms=jb ,jme=je   , kms=kb ,kme=ke ,                       &
                  its=1  ,ite=ni   , jts=1  ,jte=nj   , kts=1  ,kte=nk  )
        endif
      ENDIF

      if( cuparam.eq.1 )then
      if(myid.eq.0) print *
      if(myid.eq.0) print *,'  cu_ntiedtke_init '
      if(myid.eq.0) print *
      call  cu_ntiedtke_init(con_cp=cp,      &
                             con_rd=rd,      &
                             con_rv=rv,      &
                             con_xlv=xlv,    &
                             con_xls=xls,    &
                             con_xlf=xlf,    &
                             con_grav=g,     &
                             errmsg=errmsg,  &
                             errflg=errflg)
      endif

!-----------------------------------------------------------------------

      end subroutine init_physics


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine getgoddardvars(foo1,foo2,foo3,foo4,foo5,foo6,ptype)
      use goddard_module, only : ROQR,ROQG,ROQS,TNW,TNG,TNSS
      implicit none

      real, intent(inout) :: foo1,foo2,foo3,foo4,foo5,foo6
      integer, intent(in) :: ptype

    IF(ptype.eq.2)THEN
      foo1 = roqr
      foo2 = tnw
      foo3 = roqs
      foo4 = tnss
      foo5 = roqg
      foo6 = tng
    ELSE
      ! 130903: set to reasonable values to prevent divide-by-zeros
      ! if goodard microphysics scheme is not being used
      foo1 = 1.
      foo2 = .08
      foo3 = .1
      foo4 = 1.
      foo5 = .4
      foo6 = .04
    ENDIF

      end subroutine getgoddardvars


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine initrad(myid,year,month,day,hour,minute,second,jday,   &
                         nir,njr,nkr)
      use radtrns3d_module
      use irrad3d_module
      implicit none

      integer, intent(in) :: myid,year,month,day,hour,minute,second,jday,   &
                             nir,njr,nkr

      integer :: ip,iw,it
      logical :: high

      real, parameter :: pi  = 3.14159265358979323

!----------------------------------------------------------------------

  IF ( rlwopt == 0 ) THEN
    high = .false.
  ELSE
    high = .true.
  END IF

  if(myid.eq.0) print *,'  high = ',high

!----------------------------------------------------------------------
!  from zenangl:

    pi2 = 2.0 * pi
    deg2rad = pi/180.0
    rad2deg = 1./deg2rad

    hour0 = FLOAT(hour)                                                 &
          + FLOAT(minute)/60.0                                          &
          + FLOAT(second)/3600.0

    IF ( MOD(year, 4) == 0 ) THEN
      yrday = 366.
    ELSE
      yrday = 365.
    END IF

!!! not using arps MPI code:  GHB, 100720
!!! hard-wire these in, just in case:
    nxmid = 1
    nymid = 1
    source = 0

!----------------------------------------------------------------------
!  from irrad:

!-----tables co2 and h2o are only used with 'high' option

    IF (high) THEN

      DO iw=1,nh
        DO ip=1,nx
          h11(ip,iw,1)=1.0-h11(ip,iw,1)
          h21(ip,iw,1)=1.0-h21(ip,iw,1)
          h71(ip,iw,1)=1.0-h71(ip,iw,1)
        END DO
      END DO

      DO iw=1,nc
        DO ip=1,nx
          c1(ip,iw,1)=1.0-c1(ip,iw,1)
        END DO
      END DO

!-----tables are replicated to avoid memory bank conflicts

      DO it=2,nt
        DO iw=1,nc
          DO ip=1,nx
            c1 (ip,iw,it)= c1(ip,iw,1)
            c2 (ip,iw,it)= c2(ip,iw,1)
            c3 (ip,iw,it)= c3(ip,iw,1)
          END DO
        END DO
        DO iw=1,nh
          DO ip=1,nx
            h11(ip,iw,it)=h11(ip,iw,1)
            h12(ip,iw,it)=h12(ip,iw,1)
            h13(ip,iw,it)=h13(ip,iw,1)
            h21(ip,iw,it)=h21(ip,iw,1)
            h22(ip,iw,it)=h22(ip,iw,1)
            h23(ip,iw,it)=h23(ip,iw,1)
            h71(ip,iw,it)=h71(ip,iw,1)
            h72(ip,iw,it)=h72(ip,iw,1)
            h73(ip,iw,it)=h73(ip,iw,1)
          END DO
        END DO
      END DO

    END IF

!-----always use table look-up for ozone transmittance

    DO iw=1,no
      DO ip=1,nx
        o1(ip,iw,1)=1.0-o1(ip,iw,1)
      END DO
    END DO

    DO it=2,nt
      DO iw=1,no
        DO ip=1,nx
          o1 (ip,iw,it)= o1(ip,iw,1)
          o2 (ip,iw,it)= o2(ip,iw,1)
          o3 (ip,iw,it)= o3(ip,iw,1)
        END DO
      END DO
    END DO

      return
      end subroutine initrad

  END MODULE init_physics_module
init_surface.F/ 1744672191  3193  100   100644  14725     `
  MODULE init_surface_module

  implicit none

  CONTAINS

      subroutine init_surface(num_soil_layers,dosfcflx,xh,ruh,xf,yh,rvh,yf,   &
           lu_index,xland,tsk,slab_zs,slab_dzs,tslb, &
           emiss,thc,albd,znt,rznt,mavail,dsxy,prs0s,prs0,   &
           tmn,tml,t0ml,hml,h0ml,huml,hvml,tmoml,z0base)

      use input
      use constants
      use module_sf_oml

      implicit none

      integer, intent(in) :: num_soil_layers
      logical, intent(inout) :: dosfcflx
      real, intent(in), dimension(ib:ie) :: xh,ruh
      real, intent(in), dimension(ib:ie+1) :: xf
      real, intent(in), dimension(jb:je) :: yh,rvh
      real, intent(in), dimension(jb:je+1) :: yf
      integer, intent(inout), dimension(ibl:iel,jbl:jel) :: lu_index
      real, intent(inout), dimension(ib:ie,jb:je) :: tsk,znt,rznt,xland
      real, intent(inout), dimension(num_soil_layers) :: slab_zs,slab_dzs
      real, intent(inout), dimension(ibl:iel,jbl:jel,num_soil_layers) :: tslb
      real, intent(inout), dimension(ibl:iel,jbl:jel) :: emiss,thc,albd,mavail,dsxy
      real, intent(in), dimension(ib:ie,jb:je) :: prs0s
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: prs0
      real, intent(inout), dimension(ibl:iel,jbl:jel) :: tmn,tml,t0ml,hml,h0ml,huml,hvml,tmoml
      real, intent(inout), dimension(ibmyj:iemyj,jbmyj:jemyj) :: z0base

      integer :: i,j,k,l
      real :: x1,x2,xcoast

!-----------------------------------------------------------------------
!  BEGIN user settings

    IF( (sfcmodel.ge.1) .or. (bbc.eq.3) )THEN

      ! Initialize the surface:

      ! Key:
      ! tsk      = "skin temperature" (K) of soil/water  (~1 cm deep)
      ! tmn      = deep-layer temperature (K) of soil  (sfcmodel=2,3,4,6,7 only)
      ! xland    = land/water flag:   1 for land,   2 for water
      ! lu_index = land use index   (1-33) (see LANDUSE.TBL file)

!----------
!  Deafult ... fill in arrays with values from Namelist:

      do j=jb,je
      do i=ib,ie
        tsk(i,j)      = tsk0
      enddo
      enddo

      do j=jbl,jel
      do i=ibl,iel
        tmn(i,j)      = tmn0
        xland(i,j)    = xland0
        lu_index(i,j) = lu0
      enddo
      enddo

!----------
!  Initialize the sea breeze test case from WRF:

      IF( initsfc.eq.2 )THEN 

        ! sea breeze test case from WRF:
        ! (modified on 150830 to match WRF3.7 setup)

        x1 = minx + (3.0/8.0)*(maxx-minx)
        x2 = minx + (5.0/8.0)*(maxx-minx)

        do j=jb,je
        do i=ib,ie
          if( xh(i).ge.x1 .and. xh(i).le.x2 )then
            ! land:
            xland(i,j) = 1.0
            lu_index(i,j) = 18
            tsk(i,j) = 280.0
          else
            ! water:
            xland(i,j) = 2.0
            lu_index(i,j) = 16
            tsk(i,j) = 287.0
          endif
          tmn(i,j) = tsk(i,j)-0.5
        enddo
        enddo

!----------

      ELSEIF( initsfc.eq.3 ) THEN

        do j=jb,je
        do i=ib,ie
          if( xh(i).le.centerx )then
            znt(i,j) = 0.010
          else
            znt(i,j) = 0.001
          endif
        enddo
        enddo

!----------

      ELSEIF( initsfc.eq.4 ) THEN

        xcoast = minx + 0.5*(maxx-minx)

        do j=jb,je
        do i=ib,ie
          if( xh(i) .lt. xcoast )then
            xland(i,j) = 1.0
            lu_index(i,j) = 18
          else
            xland(i,j) = 2.0
            lu_index(i,j) = 16
          endif
        enddo
        enddo

!----------
!  if initsfc is not 1,2:

      ELSEIF( initsfc.ne.1 .and. initsfc.ne.2 )THEN

        ! build your own initial conditions here:

!!!        do j=jb,je
!!!        do i=ib,ie
!!!          tsk(i,j)      = ?
!!!          tmn(i,j)      = ?
!!!          xland(i,j)    = ?
!!!          lu_index(i,j) = ?
!!!        enddo
!!!        enddo

!----------

      ENDIF     ! endif for initsfc options


!     END of user settings
!-----------------------------------------------------------------------
!     NO NOT CHANGE ANYTHING BELOW HERE

    IF( sfcmodel.eq.2 .or. sfcmodel.eq.3 .or. sfcmodel.eq.4 .or. sfcmodel.eq.6 .or. sfcmodel.eq.7 )THEN

      IF (num_soil_layers.NE.1)THEN
      slab_dzs(1)=.01
      slab_zs(1)=.5*slab_dzs(1)
      DO l=2,num_soil_layers
         slab_dzs(l)=2*slab_dzs(l-1)
         slab_zs(l)=slab_zs(l-1)+.5*slab_dzs(l-1)+.5*slab_dzs(l)
      ENDDO
      DO l=1,num_soil_layers
         DO j=jb,je
            DO i=ib,ie
              tslb(i,j,l)=( tsk(i,j)*(slab_zs(num_soil_layers)-slab_zs(l))   &
                          + tmn(i,j)*(slab_zs(l)-slab_zs(1)) ) / &
                          ( slab_zs(num_soil_layers)-slab_zs(1) )
            ENDDO
         ENDDO
      ENDDO
      ENDIF

    ENDIF

    IF( sfcmodel.ge.1 )THEN

      IF( axisymm.eq.1 .or. ny.eq.1 )THEN

        do j=jb,je
        do i=ib,ie
          dsxy(i,j) = dx*ruh(i)
        enddo
        enddo

      ELSEIF( nx.eq.1 )THEN

        do j=jb,je
        do i=ib,ie
          dsxy(i,j) = dy*rvh(j)
        enddo
        enddo

      ELSE

        do j=jb,je
        do i=ib,ie
!!!          dsxy(i,j) = sqrt( (dx*ruh(i))**2 + (dy*rvh(j))**2 )
          dsxy(i,j) = max( dx*ruh(i) , dy*rvh(j) )
        enddo
        enddo

      ENDIF

    ENDIF

  ENDIF    ! endif for sfcmodel >= 1

!-----------------------------------------------------------------------
! ensure interoperability of surface schemes and turbulence schemes:
!   NOTE:  DO NOT modify anything here unless you really, really
!          know what you are doing

      ! parameters needed in turb subroutines:
      dosfcflx = .false.

      IF( cm1setup.ge.1 .or. ipbl.eq.2 )THEN
        if( isfcflx.eq.1 ) dosfcflx = .true.
        if( sfcmodel.eq.2 .or. sfcmodel.eq.3 .or. sfcmodel.eq.4 .or. sfcmodel.eq.6 .or. sfcmodel.eq.7 )then
          dosfcflx = .true.
        endif
      ENDIF
      IF( ipbl.eq.1 .or. ipbl.eq.3 .or. ipbl.eq.4 .or. ipbl.eq.5 )THEN
        ! sfc flux/drag is handled by ysu/gfsedmf/mynn pbl subroutines:
        dosfcflx = .false.
      ENDIF

      ! 230424: bug fix
      IF( cm1setup.eq.4 .and. isfcflx.eq.1 ) dosfcflx = .true.

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,*) '  Settings used in this simulation:'
      if(dowr) write(outfile,*) '  isfcflx  = ',isfcflx
      if(dowr) write(outfile,*) '  bbc      = ',bbc
      if(dowr) write(outfile,*) '  dosfcflx = ',dosfcflx
      if(dowr) write(outfile,*)

!-----------------------------------------------------------------------
!  Initialize land-surface parameters:

      if( sfcmodel.ge.1 .or. bbc.eq.3 )then
        ! initialize MM5/WRF landuse categories:
        call getlanduse(season,myid,ib,ie,jb,je,ibl,iel,jbl,jel,   &
                        lu_index,xland,emiss,thc,albd,znt,mavail)
      endif

!-----------------------------------------------------------------------
!  special cases:

      if( set_znt.eq.1 )then
        do j=jb,je
        do i=ib,ie
          znt(i,j) = max(1.0e-12,cnst_znt)
        enddo
        enddo
      endif

      if( testcase.eq.13 .and. (nx.gt.ny) )then
        ! UF Boundary Layer Wind Tunnel case:
        do j=jb,je
        do i=ib,ie
          if( xh(i).le.minx+(maxx-minx)/3.0 )then
            znt(i,j) = 0.011
          else
            znt(i,j) = 0.001
          endif
        enddo
        enddo
      endif

!-----------------------------------------------------------------------
!  reality checks:

      IF( sfcmodel.ge.1 .or. bbc.eq.3 )THEN

        do j=jb,je
        do i=ib,ie

          ! 171020:
          if( xland(i,j).gt.1.5 ) mavail(i,j) = 1.0

          IF( nint(xland(i,j)).le.0 .or. nint(xland(i,j)).ge.3 )THEN
            print *
            print *,'  Invalid value for xland '
            print *
            print *,'    xland must be 1 (for land) or 2 (for water) '
            print *
            print *,'  Stopping CM1 .... '
            print *
            call stopcm1
          ENDIF
          if( sfcmodel.eq.2 .or. sfcmodel.eq.3 .or. sfcmodel.eq.4 .or. sfcmodel.eq.6 .or. sfcmodel.eq.7 )then
          IF( lu_index(i,j).le.0 .or. lu_index(i,j).ge.34 )THEN
            print *
            print *,'  Invalid value for lu_index '
            print *
            print *,'    lu_index must be between 1 and 33 '
            print *,'    (see LANDUSE.TBL for more info) '
            print *
            print *,'  Stopping CM1 .... '
            print *
            call stopcm1
          ENDIF
          endif
          IF( tsk(i,j).lt.100.0 )THEN
            print *
            print *,'  WARNING:  tsk is less than 100 K '
            print *
            print *,'  Stopping CM1 .... '
            print *
            call stopcm1
          ENDIF
          if( sfcmodel.eq.2 .or. sfcmodel.eq.3 .or. sfcmodel.eq.4 .or. sfcmodel.eq.6 .or. sfcmodel.eq.7 )then
          IF( tmn(i,j).lt.100.0 )THEN
            print *
            print *,'  WARNING:  tmn is less than 100 K '
            print *
            print *,'  Stopping CM1 .... '
            print *
            call stopcm1
          ENDIF
          endif
        enddo
        enddo

      ENDIF

!-----------------------------------------------------------------------
!  Initialize the ocean mixed layer model:

      if(oceanmodel.eq.2)then
        call omlinit(outfile,oml_hml0, tsk,                     &
                       tml,t0ml,hml,h0ml,huml,hvml,tmoml,       &
                       .false.,         .true. ,                &
                         1, ni+1,   1, nj+1,   1, nk+1,         &
                        ib, ie,  jb, je,  kb, ke,               &
                         1, ni,   1, nj,   1, nk                )
      endif

!-----------------------------------------------------------------------

      do j=jb,je
      do i=ib,ie
        rznt(i,j) = 1.0/max(1.0e-20,znt(i,j))
      enddo
      enddo

      if( sfcmodel.eq.7 )then
        do j=jb,je
        do i=ib,ie
          z0base(i,j) = znt(i,j)
        enddo
        enddo
        print *,'  znt,z0base = ',znt(1,1),z0base(1,1)
      endif

!-----------------------------------------------------------------------

      end subroutine init_surface


!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine getlanduse(season,myid,ib,ie,jb,je,ibl,iel,jbl,jel,   &
                            lu_index,xland,emiss,thc,albedo,znt,mavail)
#ifdef MPI
      use mpi
#endif
      implicit none

      integer, intent(in) :: season,myid,ib,ie,jb,je,ibl,iel,jbl,jel
      integer, intent(in), dimension(ibl:iel,jbl:jel) :: lu_index
      real, intent(inout), dimension(ibl:iel,jbl:jel) :: emiss,thc,albedo,mavail
      real, intent(inout), dimension(ib:ie,jb:je) :: znt,xland

      integer, parameter :: max_cats = 33    ! max categories
      integer, parameter :: max_seas =  2    ! max seasons

      integer, parameter :: iswater = 16  ! water must be category 16

      real, dimension(:,:), allocatable :: albd,slmo,sfem,sfz0,therin,scfx,sfhc
      integer :: cat,sea

      integer :: i,j,is,isn,ierr

      allocate(   albd(max_cats,max_seas) )
      allocate(   slmo(max_cats,max_seas) )
      allocate(   sfem(max_cats,max_seas) )
      allocate(   sfz0(max_cats,max_seas) )
      allocate( therin(max_cats,max_seas) )
      allocate(   scfx(max_cats,max_seas) )
      allocate(   sfhc(max_cats,max_seas) )

!-----------------------------------------------------------------------

      IF( myid.eq.0 )THEN
        open(unit=11,file='LANDUSE.TBL',status='old',err=888)
        read(11,*,err=808)
        read(11,*,err=808)
        do isn=1,max_seas
          read(11,*,err=808)
          do is=1,max_cats
            read(11,*,err=808) i,albd(is,isn),slmo(is,isn),sfem(is,isn),sfz0(is,isn), &
                       therin(is,isn),scfx(is,isn),sfhc(is,isn)
          enddo
        enddo
        close(unit=11)
!        print *
!        print *,'  summer:'
!        print *,'  albd = ',albd(:,1)
!        print *,'  slmo = ',slmo(:,1)
!        print *,'  sfem = ',sfem(:,1)
!        print *,'  sfz0 = ',sfz0(:,1)
!        print *,'  ther = ',therin(:,1)
!        print *,'  scfx = ',scfx(:,1)
!        print *,'  sfhc = ',sfhc(:,1)
!        print *
!        print *,'  winter:'
!        print *,'  albd = ',albd(:,2)
!        print *,'  slmo = ',slmo(:,2)
!        print *,'  sfem = ',sfem(:,2)
!        print *,'  sfz0 = ',sfz0(:,2)
!        print *,'  ther = ',therin(:,2)
!        print *,'  scfx = ',scfx(:,2)
!        print *,'  sfhc = ',sfhc(:,2)
      ENDIF

#ifdef MPI
      call MPI_BCAST(albd  ,max_cats*max_seas,MPI_REAL,0,MPI_COMM_WORLD,ierr)
      call MPI_BCAST(slmo  ,max_cats*max_seas,MPI_REAL,0,MPI_COMM_WORLD,ierr)
      call MPI_BCAST(sfem  ,max_cats*max_seas,MPI_REAL,0,MPI_COMM_WORLD,ierr)
      call MPI_BCAST(sfz0  ,max_cats*max_seas,MPI_REAL,0,MPI_COMM_WORLD,ierr)
      call MPI_BCAST(therin,max_cats*max_seas,MPI_REAL,0,MPI_COMM_WORLD,ierr)
      call MPI_BCAST(scfx  ,max_cats*max_seas,MPI_REAL,0,MPI_COMM_WORLD,ierr)
      call MPI_BCAST(sfhc  ,max_cats*max_seas,MPI_REAL,0,MPI_COMM_WORLD,ierr)
#endif

!-----------------------------------------------------------------------

      ! ISN = season:    summer = 1    winter = 2
      ISN = season

      do j=jb,je
      do i=ib,ie
        IS = lu_index(i,j)
        ! SET NO-DATA POINTS (IS=0) TO WATER
        IF(IS.EQ.0)THEN
          IS=ISWATER
        ENDIF
        if( albd(is,isn).le.0.0 )then
          print *,'  category not found '
          call stopcm1
        endif
        ALBEDO(I,J) = ALBD(IS,ISN)/100.
        THC(i,j) = THERIN(IS,ISN)/100.
        EMISS(I,J) = SFEM(IS,ISN)
        ZNT(I,J) = SFZ0(IS,ISN)/100.
        MAVAIL(I,J) = SLMO(IS,ISN)
        IF(IS.NE.ISWATER)THEN
          XLAND(I,J)=1.0
        ELSE
          XLAND(I,J)=2.0
        ENDIF
      enddo
      enddo

!-----------------------------------------------------------------------

      deallocate(   albd )
      deallocate(   slmo )
      deallocate(   sfem )
      deallocate(   sfz0 )
      deallocate( therin )
      deallocate(   scfx )
      deallocate(   sfhc )


      return

!-----------------------------------------------------------------------

808   print *
      print *,'  There was an error reading the LANDUSE.TBL file '
      print *
      call stopcm1

888   print *
      print *,'  There was an error opening the LANDUSE.TBL file '
      print *
      print *,'  Please make sure that LANDUSE.TBL is in the same directory '
      print *,'  as cm1.exe ... it is distributed with CM1 in the "run" directory '
      print *
      call stopcm1

      end subroutine getlanduse

  END MODULE init_surface_module

init_terrain.F/ 1744672191  3193  100   100644  9455      `
  MODULE init_terrain_module

  implicit none

  CONTAINS

      subroutine init_terrain(xh,uh,xf,uf,yh,vh,yf,vf,rds,sigma,rdsf,sigmaf,  &
                              zh,zf,zs,gz,rgz,gzu,rgzu,gzv,rgzv,         &
                              dzdx,dzdy,gx,gxu,gy,gyv,                   &
                              reqs_u,reqs_v,reqs_s,reqs_p,               &
                              nw1,nw2,ne1,ne2,sw1,sw2,se1,se2,           &
                              sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,   &
                              uw31,uw32,ue31,ue32,us31,us32,un31,un32,   &
                              vw31,vw32,ve31,ve32,vs31,vs32,vn31,vn32,   &
                              west,newwest,east,neweast,                 &
                              south,newsouth,north,newnorth)

      use input
      use constants
      use bc_module
      use adv_routines , only : zsgrad
      use comm_module
#ifdef MPI
      use mpi
#endif
      implicit none

      real, intent(in), dimension(ib:ie) :: xh,uh
      real, intent(in), dimension(ib:ie+1) :: xf,uf
      real, intent(in), dimension(jb:je) :: yh,vh
      real, intent(in), dimension(jb:je+1) :: yf,vf
      real, intent(inout), dimension(kb:ke) :: rds,sigma
      real, intent(inout), dimension(kb:ke+1) :: rdsf,sigmaf
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: zh
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: zf
      real, intent(inout), dimension(ib:ie,jb:je) :: zs
      real, intent(inout), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,rgzu,gzv,rgzv,dzdx,dzdy
      real, intent(inout), dimension(itb:ite,jtb:jte,ktb:kte) :: gx,gxu,gy,gyv
      integer, intent(inout), dimension(rmp) :: reqs_u,reqs_v,reqs_s,reqs_p
      real, intent(inout), dimension(kmt) :: nw1,nw2,ne1,ne2,sw1,sw2,se1,se2
      real, intent(inout), dimension(cmp,jmp,kmp)   :: sw31,sw32,se31,se32
      real, intent(inout), dimension(imp,cmp,kmp)   :: ss31,ss32,sn31,sn32
      real, intent(inout), dimension(cmp,jmp,kmp)   :: uw31,uw32,ue31,ue32
      real, intent(inout), dimension(imp+1,cmp,kmp) :: us31,us32,un31,un32
      real, intent(inout), dimension(cmp,jmp+1,kmp) :: vw31,vw32,ve31,ve32
      real, intent(inout), dimension(imp,cmp,kmp)   :: vs31,vs32,vn31,vn32
      real, intent(inout), dimension(cmp,jmp) :: west,newwest,east,neweast
      real, intent(inout), dimension(imp,cmp) :: south,newsouth,north,newnorth

      integer :: i,j,k,irec,ii,jj
      real :: hh,aa,xval,xc,yc
      real :: tem1,tem2,rr,angle
      real, dimension(:,:), allocatable :: zs_all

#ifdef MPI
      character(len=50) :: fname
#endif

!-----------------------------------------------------------------------
!     SPECIFY TERRAIN HERE
!-----------------------------------------------------------------------

!----------------------------------------------------------
!  itern = 1
!  bell-shaped  (eg, Durran and Klemp, 1983, MWR, pg 2341)

        IF(itern.eq.1)THEN

          hh =      400.0              ! max. height (m)
          aa =     1000.0              ! half width (m)
          xc =        0.0 + 0.5*dx     ! x-location (m)

          do j=jb,je
          do i=ib,ie
            zs(i,j)=hh/( 1.0+( (xh(i)-xc)/aa )**2 )
          enddo
          enddo

!---------------
!  itern = 2
!  Schaer case  (eg, Klemp et al, 2003, MWR, pg 1229)

        ELSEIF(itern.eq.2)THEN

          do j=jb,je
          do i=ib,ie
            xval=dx*(i-ni/2)
            zs(i,j)=250.0*exp(-(xval/5000.0)**2)*(cos(pi*xval/4000.0)**2)
          enddo
          enddo

!---------------
!  itern = 3
!  Doernbrack et al, 2005, ASL, pg 118

        ELSEIF(itern.eq.3)THEN

          hh =      500.0     ! max. height (m)
          aa =    20000.0     ! half width (m)

          do j=jb,je
          do i=ib,ie
            xval = sqrt( (xh(i)-0.25*maxx)**2   &
                        +(yh(j)-0.25*maxy)**2   &
                                             )
            zs(i,j)=hh*( (1.0+(xval/aa)**2 )**(-1.5) )
          enddo
          enddo

!----------------------------------------------------------
!  itern = 4
!  read from GrADS file "perts.dat"

        ELSEIF(itern.eq.4)THEN

          ! 170313:  zs_all array stores terrain for the entire domain
          allocate( zs_all(nx,ny) )

          ! only processor 0 reads file:

          IF( myid.eq.0 )THEN

            open(unit=73,file='perts.dat',status='old',   &
                 form='unformatted',access='direct',recl=4*nx*ny)

            read(73,rec=1) ((zs_all(i,j),i=1,nx),j=1,ny)

            close(unit=73)

          ENDIF

#ifdef MPI
          ! communicate data to all processors:
          call MPI_BCAST(zs_all,nx*ny,MPI_REAL,0,MPI_COMM_WORLD,ierr)
#endif

          ! 170313:
          do jj=1,ny
          do ii=1,nx
            i = ii - myi1 + 1
            j = jj - myj1 + 1
            ! check to see if this processor has this gridpoint:
            IF( i.ge.ib .and. i.le.ie .and. j.ge.jb .and. j.le.je )THEN
              zs(i,j) = zs_all(ii,jj)
            ENDIF
          enddo
          enddo

          ! zs_all no longer needed ... deallocate:
          deallocate( zs_all )

!----------------------------------------------------------

        ENDIF

!--------------------------------------------------------------
!  DO NOT CHANGE ANYTHING BELOW HERE !
!--------------------------------------------------------------

        call bc2d(zs)
#ifdef MPI
        nf=0
        nu=0
        nv=0
        nw=0
        call comm_2d_start(zs,west,newwest,east,neweast,   &
                              south,newsouth,north,newnorth,reqs_p)
        call comm_2dew_end(zs,west,newwest,east,neweast,reqs_p)
        call comm_2dns_end(zs,south,newsouth,north,newnorth,reqs_p)
        call bcs2_2d(zs)
        call bc2d(zs)
        call getcorner3_2d(zs)
#endif

        zt = maxz
        rzt = 1.0/maxz

        if(dowr) write(outfile,*)
        do k=1,nk+1
          if(dowr) write(outfile,*) '  sigmaf:',k,sigmaf(k)
        enddo
        if(dowr) write(outfile,*)

        do k=1,nk
        do j=jb,je
        do i=ib,ie
          zh(i,j,k)=zs(i,j)+sigma(k)*(zt-zs(i,j))/zt
        enddo
        enddo
        enddo

        do k=kb,ke+1
        do j=jb,je
        do i=ib,ie
          zf(i,j,k)=zs(i,j)+sigmaf(k)*(zt-zs(i,j))/zt
        enddo
        enddo
        enddo

        call zsgrad(zs,gz,dzdx,dzdy,uh,vh)

!--------------------------------
!  set boundary points

        call bc2d(dzdx)
        call bc2d(dzdy)

#ifdef MPI
        call comm_2d_start(dzdx,west,newwest,east,neweast,   &
                                south,newsouth,north,newnorth,reqs_p)
        call comm_2dew_end(dzdx,west,newwest,east,neweast,reqs_p)
        call comm_2dns_end(dzdx,south,newsouth,north,newnorth,reqs_p)
        call bcs2_2d(dzdx)
        call bc2d(dzdx)
        call getcorner3_2d(dzdx)

        call comm_2d_start(dzdy,west,newwest,east,neweast,   &
                                south,newsouth,north,newnorth,reqs_p)
        call comm_2dew_end(dzdy,west,newwest,east,neweast,reqs_p)
        call comm_2dns_end(dzdy,south,newsouth,north,newnorth,reqs_p)
        call bcs2_2d(dzdy)
        call bc2d(dzdy)
        call getcorner3_2d(dzdy)
#endif

!--------------------------------
!  the metric terms:

        do j=jb,je
        do i=ib,ie
           gz(i,j)=zt/(zt-zs(i,j))
          rgz(i,j)=(zt-zs(i,j))/zt
        enddo
        enddo

        call bc2d(rgz)
#ifdef MPI
        call comm_2d_start(rgz,west,newwest,east,neweast,   &
                               south,newsouth,north,newnorth,reqs_p)
        call comm_2dew_end(rgz,west,newwest,east,neweast,reqs_p)
        call comm_2dns_end(rgz,south,newsouth,north,newnorth,reqs_p)
        call bcs2_2d(rgz)
        call bc2d(rgz)
        call getcorner3_2d(rgz)
#endif

        do j=jb+1,je
        do i=ib+1,ie
           gzu(i,j)=zt/(zt-0.5*(zs(i-1,j)+zs(i,j)))
          rgzu(i,j)=(zt-0.5*(zs(i-1,j)+zs(i,j)))/zt
           gzv(i,j)=zt/(zt-0.5*(zs(i,j-1)+zs(i,j)))
          rgzv(i,j)=(zt-0.5*(zs(i,j-1)+zs(i,j)))/zt
        enddo
        enddo

        do k=1,nk+1
        do j=jb+1,je-1
        do i=ib+1,ie-1
          gx(i,j,k)=(zt-sigmaf(k))*gz(i,j)*(rgzu(i+1,j)-rgzu(i,j))*rdx*uh(i)
          gxu(i,j,k)=(zt-sigmaf(k))*gzu(i,j)*(rgz(i,j)-rgz(i-1,j))*rdx*uf(i)
          gy(i,j,k)=(zt-sigmaf(k))*gz(i,j)*(rgzv(i,j+1)-rgzv(i,j))*rdy*vh(j)
          gyv(i,j,k)=(zt-sigmaf(k))*gzv(i,j)*(rgz(i,j)-rgz(i,j-1))*rdy*vf(j)
        enddo
        enddo
        enddo

!--------------------------------

        do j=jb,je
        do i=ib,ie
          zf(i,j,0)=zf(i,j,1)-(zf(i,j,2)-zf(i,j,1))
          zf(i,j,nk+2)=zf(i,j,nk+1)+(zf(i,j,nk+1)-zf(i,j,nk))
          zh(i,j,0)=0.5*(zf(i,j,0)+zf(i,j,1))
          zh(i,j,nk+1)=0.5*(zf(i,j,nk+1)+zf(i,j,nk+2))
        enddo
        enddo

        if(dowr) write(outfile,*)
        do i=ib,ie
          if(dowr) write(outfile,*) '  zs at nj/2:',i,zs(i,nj/2)
        enddo
        if(dowr) write(outfile,*)

        if(dowr) write(outfile,*)
        do j=jb,je
          if(dowr) write(outfile,*) '  zs at ni/2:',j,zs(ni/2,j)
        enddo
        if(dowr) write(outfile,*)

!---------------------------------------

      do k=2,nk
        rds(k) = 1.0/(sigma(k)-sigma(k-1))
      enddo

      do k=1,nk
        rdsf(k) = 1.0/(sigmaf(k+1)-sigmaf(k))
      enddo

!-----------------------------------------------------------------------

      end subroutine init_terrain


  END MODULE init_terrain_module

/24             1744672191  3193  100   100644  27918     `
  MODULE interp_routines

  implicit none

  private

  public :: vinterp_weno5
  public :: vinterp_flx5,vinterp_flx6


    !-----------------------------------------------------!
    !       WENO only:                                    !
    ! formulation for weno "smoothness indicators"        !
          !  1 = original (eg, Jiang and Shu, 1996, JCP)
          !  2 = Borges et al. (2008, JCP)
    integer, parameter :: siform = 2
    !-----------------------------------------------------!


  CONTAINS

!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    subroutine vinterp_weno5(stag,ix,jy,kz,c1,c2,rrw,dumz,a,pdef,pdefweno,weps)
    use input
    implicit none

    integer, intent(in) :: stag
    integer, intent(in) :: ix,jy,kz
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: c1,c2
    real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: rrw
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dumz
    real, intent(in), dimension(1-ngxy:ix+ngxy,1-ngxy:jy+ngxy,1-ngz:kz+ngz)   :: a
    integer, intent(in) :: pdef,pdefweno
    double precision, intent(in) :: weps

    integer :: i,j,k,i1,i2,j1,j2
    real :: wbar,cc1,cc2
    real :: s1,s2,s3,s4,s5
    real :: bmin,bmax
    logical :: doit

    bmin = weps

!ccccccccccccccccccccccccccccccccccc
!  s-staggered variable:

  IF( stag.eq.1 )THEN

  pdefs:  &
  if( pdefweno.eq.1 )then

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,s1,s2,s3,s4,s5,bmax,doit)
    DO j=1,nj
      do k=3,nk-1
      !dir$ vector always
      do i=1,ni
        if(rrw(i,j,k).ge.0.0)then
          s1=a(i,j,k-3)
          s2=a(i,j,k-2)
          s3=a(i,j,k-1)
          s4=a(i,j,k  )
          s5=a(i,j,k+1)
        else
          s1=a(i,j,k+2)
          s2=a(i,j,k+1)
          s3=a(i,j,k  )
          s4=a(i,j,k-1)
          s5=a(i,j,k-2)
        endif
        doit = .false.
        bmax = max(abs(s1),abs(s2),abs(s3),abs(s4),abs(s5))
        if( bmax.gt.bmin ) doit = .true.
        IF( k.eq.3 .and. rrw(i,j,k).gt.0.0 ) doit = .false.
        IF( k.eq.(nk-1) .and. rrw(i,j,k).lt.0.0 ) doit = .false.
        IF(doit)THEN
          dumz(i,j,k) = weno5(s1,s2,s3,s4,s5,weps)
        ELSE
          dumz(i,j,k) = 0.0
        ENDIF
      enddo
      enddo

      !----

      ! flux at k=3 if w > 0
      k = 3
      !dir$ vector always
      do i=1,ni
        if( rrw(i,j,k).gt.0.0 )then
          dumz(i,j,k) = upstrpd(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),weps)
        endif
      enddo

      ! flux at k=(nk-1) if w < 0
      k = nk-1
      !dir$ vector always
      do i=1,ni
        if( rrw(i,j,k).lt.0.0 )then
          dumz(i,j,k) = upstrpd(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),weps)
        endif
      enddo

      !----

      k = 2
      !dir$ vector always
      do i=1,ni
        if( rrw(i,j,k).ge.0.0 )then
          dumz(i,j,k) = (c1(i,j,k)*a(i,j,k-1)+c2(i,j,k)*a(i,j,k))
        else
          dumz(i,j,k) = upstrpd(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),weps)
        endif
      enddo

      k = nk
      !dir$ vector always
      do i=1,ni
        if( rrw(i,j,k).gt.0.0 )then
          dumz(i,j,k) = upstrpd(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),weps)
        else
          dumz(i,j,k) = (c1(i,j,k)*a(i,j,k-1)+c2(i,j,k)*a(i,j,k))
        endif
      enddo

    ENDDO

  !--------------------------------------!
  else  pdefs

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k)
    DO j=1,nj
      do k=4,nk-2
      !dir$ vector always
      do i=1,ni
        if(rrw(i,j,k).ge.0.0)then
          dumz(i,j,k) = weno5(a(i,j,k-3),a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),a(i,j,k+1),weps)
        else
          dumz(i,j,k) = weno5(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),a(i,j,k-2),weps)
        endif
      enddo
      enddo

      !----

      ! flux at k=3 if w > 0
      k = 3
      !dir$ vector always
      do i=1,ni
        if( rrw(i,j,k).ge.0.0 )then
          dumz(i,j,k) = upstrpd(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),weps)
        else
          dumz(i,j,k) = weno5(a(i,j,k+2),a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),a(i,j,k-2),weps)
        endif
      enddo

      ! flux at k=(nk-1) if w < 0
      k = nk-1
      !dir$ vector always
      do i=1,ni
        if( rrw(i,j,k).gt.0.0 )then
          dumz(i,j,k) = weno5(a(i,j,k-3),a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),a(i,j,k+1),weps)
        else
          dumz(i,j,k) = upstrpd(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),weps)
        endif
      enddo

      !----

      k = 2
      !dir$ vector always
      do i=1,ni
        if( rrw(i,j,k).ge.0.0 )then
          dumz(i,j,k) = (c1(i,j,k)*a(i,j,k-1)+c2(i,j,k)*a(i,j,k))
        else
          dumz(i,j,k) = upstrpd(a(i,j,k+1),a(i,j,k  ),a(i,j,k-1),weps)
        endif
      enddo

      k = nk
      !dir$ vector always
      do i=1,ni
        if( rrw(i,j,k).gt.0.0 )then
          dumz(i,j,k) = upstrpd(a(i,j,k-2),a(i,j,k-1),a(i,j,k  ),weps)
        else
          dumz(i,j,k) = (c1(i,j,k)*a(i,j,k-1)+c2(i,j,k)*a(i,j,k))
        endif
      enddo

    ENDDO

  endif  pdefs

!ccccccccccccccccccccccccccccccccccc
!  u-staggered variable:

  ELSEIF( stag.eq.2 )THEN
    ! u-staggered:

