      pi_sp = 4.0_sp*atan(1.0_sp)
      pi_dp = 4.0_dp*atan(1.0_dp)
      pi_qp = 4.0_qp*atan(1.0_qp)

      if(dowr) write(outfile,*)
      if(dowr) write(outfile,*) '  pi_sp = ',pi_sp
      if(dowr) write(outfile,*) '  pi_dp = ',pi_dp
