      wbar = 0.5*(rrw(i,j,k)+rrw(i,j,k+1))
      if( wbar.ge.0.0 )then
        dum1(i,j,k) = (wa(i,j,k+1)-wa(i,j,k))*rdz*mh(1,1,k)*wbar*(  &
            flx3(wa(i,j,k-1),wa(i,j,k  ),wa(i,j,k+1))  &
           -flx4(wa(i,j,k-1),wa(i,j,k  ),wa(i,j,k+1),wa(i,j,k+2)) )
      else
        dum1(i,j,k) = (wa(i,j,k+1)-wa(i,j,k))*rdz*mh(1,1,k)*wbar*(  &
            flx5(wa(i,j,k+3),wa(i,j,k+2),wa(i,j,k+1),wa(i,j,k  ),wa(i,j,k-1))  &
           -flx4(wa(i,j,k-1),wa(i,j,k  ),wa(i,j,k+1),wa(i,j,k+2)) )
      endif
    enddo
    enddo

    k = nk-1
    !$omp parallel do default(shared)   &
    !$omp private(i,j,wbar)
    do j=1,nj
    do i=1,ni
      wbar = 0.5*(rrw(i,j,k)+rrw(i,j,k+1))
      if( wbar.ge.0.0 )then
        dum1(i,j,k) = (wa(i,j,k+1)-wa(i,j,k))*rdz*mh(1,1,k)*wbar*(  &
            flx5(wa(i,j,k-2),wa(i,j,k-1),wa(i,j,k  ),wa(i,j,k+1),wa(i,j,k+2))  &
           -flx4(wa(i,j,k-1),wa(i,j,k  ),wa(i,j,k+1),wa(i,j,k+2)) )
      else
        dum1(i,j,k) = (wa(i,j,k+1)-wa(i,j,k))*rdz*mh(1,1,k)*wbar*(  &
            flx3(wa(i,j,k+2),wa(i,j,k+1),wa(i,j,k  ))  &
           -flx4(wa(i,j,k-1),wa(i,j,k  ),wa(i,j,k+1),wa(i,j,k+2)) )
      endif
    enddo
    enddo

    k = 1
    !$omp parallel do default(shared)   &
    !$omp private(i,j,wbar)
    do j=1,nj
    do i=1,ni
      wbar = 0.5*(rrw(i,j,k)+rrw(i,j,k+1))
      if( wbar.lt.0.0 )then
        dum1(i,j,k) = (wa(i,j,k+1)-wa(i,j,k))*rdz*mh(1,1,k)*wbar*(  &
                         flx3(wa(i,j,k+2),wa(i,j,k+1),wa(i,j,k  )) &
                        -0.5*(wa(i,j,k)+wa(i,j,k+1)) )
      else
        dum1(i,j,k) = 0.0
      endif
    enddo
    enddo

    k = nk
    !$omp parallel do default(shared)   &
    !$omp private(i,j,wbar)
    do j=1,nj
    do i=1,ni
      wbar = 0.5*(rrw(i,j,k)+rrw(i,j,k+1))
      if( wbar.gt.0.0 )then
        dum1(i,j,k) = (wa(i,j,k+1)-wa(i,j,k))*rdz*mh(1,1,k)*wbar*(  &
                         flx3(wa(i,j,k-1),wa(i,j,k  ),wa(i,j,k+1)) &
                        -0.5*(wa(i,j,k)+wa(i,j,k+1)) )
      else
        dum1(i,j,k) = 0.0
      endif
    enddo
    enddo

  ELSE

    dum1 = 0.0

  ENDIF

  ELSE

    dum1 = 0.0

  ENDIF   acheck2

!----------

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          =               -(c1(1,1,k)*dum1(i,j,k-1)+c2(1,1,k)*dum1(i,j,k))
      epsd1(i,j,k) = epsd1(i,j,k) + max( 0.0 , tem )
      epsd2(i,j,k) = epsd2(i,j,k) + min( 0.0 , tem )
      !-----
      epsd1(i,j,k) = epsd1(i,j,k)*rrf0(1,1,k)
      epsd2(i,j,k) = epsd2(i,j,k)*rrf0(1,1,k)
    enddo
    enddo
    enddo

!--------------------------------------------------------------
!  finished

  ENDIF  docalc

      if(timestats.ge.1) time_diag=time_diag+mytime()

      end subroutine getepsd


!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc


      subroutine getepst(xh,rxh,uh,xf,rxf,uf,vh,vf,mh,c1,c2,mf,ua ,va ,wa ,  &
                         t11,t12,t13,t22,t23,t33,rf,                         &
                         dum1,dum2,epst,epstp,epstn)
      use input
      use constants
      implicit none

      real, intent(in), dimension(ib:ie) :: xh,rxh,uh
      real, intent(in), dimension(ib:ie+1) :: xf,rxf,uf
      real, intent(in), dimension(jb:je) :: vh
      real, intent(in), dimension(jb:je+1) :: vf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh,c1,c2
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf
      real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: ua
      real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: va
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: wa
      real, intent(in),    dimension(ib:ie,jb:je,kb:ke) :: t11,t12,t13,t22,t23,t33,rf
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum1,dum2
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: epst
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke), optional :: epstp,epstn

      integer :: i,j,k
      real :: rrf,tem

!--------------------------------------------------------------
!  horizontal terms, Cartesian grid:

!----------
!  u-x:
!  v-y:

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=1,nk
    do j=1,nj
    do i=1,ni
      dum1(i,j,k) = (ua(i+1,j,k)-ua(i,j,k))*rdx*uh(i)*t11(i,j,k)
      dum2(i,j,k) = (va(i,j+1,k)-va(i,j,k))*rdy*vh(j)*t22(i,j,k)
    enddo
    enddo
    enddo

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          = ( c1(1,1,k)*(dum1(i,j,k-1)+dum2(i,j,k-1)) &
                      +c2(1,1,k)*(dum1(i,j,k  )+dum2(i,j,k  )) )
      epst(i,j,k) = tem
    enddo
    enddo
    enddo

    if( present(epstp) .and. present(epstn) )then
    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          = ( c1(1,1,k)*(dum1(i,j,k-1)+dum2(i,j,k-1)) &
                      +c2(1,1,k)*(dum1(i,j,k  )+dum2(i,j,k  )) )
      epstp(i,j,k) = max( 0.0 , tem )
      epstn(i,j,k) = min( 0.0 , tem )
    enddo
    enddo
    enddo
    endif

!----------
!  u-y:
!  v-x:

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=1,nk
    do j=1,nj+1
    do i=1,ni+1
      dum1(i,j,k) = t12(i,j,k)*( (ua(i,j,k)-ua(i,j-1,k))*rdy*vf(j) &
                                +(va(i,j,k)-va(i-1,j,k))*rdx*uf(i) )
    enddo
    enddo
    enddo

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          =                0.25*(                                                   &
         ( c2(1,1,k)*((dum1(i,j,k  )+dum1(i+1,j+1,k  ))+(dum1(i,j+1,k  )+dum1(i+1,j,k  )))   &
          +c1(1,1,k)*((dum1(i,j,k-1)+dum1(i+1,j+1,k-1))+(dum1(i,j+1,k-1)+dum1(i+1,j,k-1))) ) )
      epst(i,j,k) = epst(i,j,k) + tem
    enddo
    enddo
    enddo

    if( present(epstp) .and. present(epstn) )then
    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          =                0.25*(                                                   &
         ( c2(1,1,k)*((dum1(i,j,k  )+dum1(i+1,j+1,k  ))+(dum1(i,j+1,k  )+dum1(i+1,j,k  )))   &
          +c1(1,1,k)*((dum1(i,j,k-1)+dum1(i+1,j+1,k-1))+(dum1(i,j+1,k-1)+dum1(i+1,j,k-1))) ) )
      epstp(i,j,k) = epstp(i,j,k) + max( 0.0 , tem )
      epstn(i,j,k) = epstn(i,j,k) + min( 0.0 , tem )
    enddo
    enddo
    enddo
    endif

!----------
!  w-x:
!  w-y:
!  u-z:
!  v-z:

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=2,nk
    do j=1,nj+1
    do i=1,ni+1
      dum1(i,j,k) = ( (wa(i,j,k)-wa(i-1,j,k))*rdx*uf(i)     &
                     +(ua(i,j,k)-ua(i,j,k-1))*rdz*mf(1,1,k) )*t13(i,j,k)
      dum2(i,j,k) = ( (wa(i,j,k)-wa(i,j-1,k))*rdy*vf(j)     &
                     +(va(i,j,k)-va(i,j,k-1))*rdz*mf(1,1,k) )*t23(i,j,k)
    enddo
    enddo
    enddo

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          = 0.5*( (dum1(i,j,k)+dum1(i+1,j,k)) &
                          +(dum2(i,j,k)+dum2(i,j+1,k)) )
      epst(i,j,k) = epst(i,j,k) + tem
    enddo
    enddo
    enddo

    if( present(epstp) .and. present(epstn) )then
    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          = 0.5*( (dum1(i,j,k)+dum1(i+1,j,k)) &
                          +(dum2(i,j,k)+dum2(i,j+1,k)) )
      epstp(i,j,k) = epstp(i,j,k) + max( 0.0 , tem )
      epstn(i,j,k) = epstn(i,j,k) + min( 0.0 , tem )
    enddo
    enddo
    enddo
    endif

!----------
! w-z:

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem)
    do k=1,nk
    do j=1,nj
    do i=1,ni
      dum1(i,j,k) = (wa(i,j,k+1)-wa(i,j,k))*rdz*mh(1,1,k)*t33(i,j,k)
    enddo
    enddo
    enddo

    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem,rrf)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          =                (c1(1,1,k)*dum1(i,j,k-1)+c2(1,1,k)*dum1(i,j,k))
      epst(i,j,k) = epst(i,j,k) + tem
      !-------------------------
      rrf = 1.0/rf(i,j,k)
      epst(i,j,k) = epst(i,j,k)*rrf
    enddo
    enddo
    enddo

    if( present(epstp) .and. present(epstn) )then
    !$omp parallel do default(shared)   &
    !$omp private(i,j,k,tem,rrf)
    do k=2,nk
    do j=1,nj
    do i=1,ni
      tem          =                (c1(1,1,k)*dum1(i,j,k-1)+c2(1,1,k)*dum1(i,j,k))
      epstp(i,j,k) = epstp(i,j,k) + max( 0.0 , tem )
      epstn(i,j,k) = epstn(i,j,k) + min( 0.0 , tem )
      !-------------------------
      rrf = 1.0/rf(i,j,k)
      epstp(i,j,k) = epstp(i,j,k)*rrf
      epstn(i,j,k) = epstn(i,j,k)*rrf
    enddo
    enddo
    enddo
    endif

!--------------------------------------------------------------
!  finished

      if(timestats.ge.1) time_turb=time_turb+mytime()

      end subroutine getepst


!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

  END MODULE turb_module

turbtend.F/     1744672191  3193  100   100644  88004     `
  MODULE turbtend_module

  implicit none

  private
  public :: turbs,turbt,turbu,turbv,turbw,turbsz,turbuz,turbvz

  real :: fac,fac2

  CONTAINS


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbs(iflux,dt,dosfcflx,xh,rxh,arh1,arh2,uh,xf,arf1,arf2,uf,vh,vf,sflux,  &
                       rds,sigma,rdsf,sigmaf,mh,mf,gz,rgz,gzu,rgzu,gzv,rgzv,gx,gxu,gy,gyv, &
                       turbx,turby,turbz,dumx,dumy,dumz,rho,rr,rf,s,sten,khh,khv,cm0,dum7,dum8, &
                       dobud,ibd,ied,jbd,jed,kbd,ked,ndiag,diag,sd_hturb,sd_vturb,ivar)
      use input
      use constants
      use cm1libs , only : rslf,rsif
      implicit none

      integer, intent(in) :: iflux
      real, intent(in) :: dt
      logical, intent(in) :: dosfcflx
      real, intent(in), dimension(ib:ie) :: xh,rxh,arh1,arh2,uh
      real, intent(in), dimension(ib:ie+1) :: xf,arf1,arf2,uf
      real, intent(in), dimension(jb:je) :: vh
      real, intent(in), dimension(jb:je+1) :: vf
      real, intent(in), dimension(ib:ie,jb:je) :: sflux
      real, intent(in), dimension(kb:ke) :: rds,sigma
      real, intent(in), dimension(kb:ke+1) :: rdsf,sigmaf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,rgzu,gzv,rgzv
      real, intent(in), dimension(itb:ite,jtb:jte,ktb:kte) :: gx,gxu,gy,gyv
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: turbx,turby,turbz,dumx,dumy,dumz,sten
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rr,rf,s
      real, intent(in), dimension(ibc:iec,jbc:jec,kbc:kec) :: khh,khv
      real, intent(in), dimension(ib:ie,jb:je) :: cm0
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: dum7,dum8
      logical, intent(in) :: dobud
      integer, intent(in) :: ibd,ied,jbd,jed,kbd,ked,ndiag,sd_hturb,sd_vturb
      real, intent(inout) , dimension(ibd:ied,jbd:jed,kbd:ked,ndiag) :: diag
      integer, intent(in) :: ivar    ! 1 = potential temperature
                                     ! 2 = water vapor mixing ratio

      integer :: i,j,k
      real :: r1,r2

!---------------------------------------------------------------

  dohoriz:  &
  IF( dohturb )THEN

  IF(.not.terrain_flag)THEN

    IF(axisymm.eq.0)THEN
      ! Cartesian without terrain:

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk

        do j=1,nj+1
        do i=1,ni+1
          !  x-direction
          dumx(i,j,k)= -0.125*( rho(i,j,k)+rho(i-1,j,k) )           &
                             *(  (khh(i,j,k  )+ khh(i-1,j,k  ))     &
                                +(khh(i,j,k+1)+ khh(i-1,j,k+1)) )   &
                             *(    s(i,j,k)-   s(i-1,j,k) )*rdx*uf(i)
          !  y-direction
          dumy(i,j,k)= -0.125*( rho(i,j,k)+rho(i,j-1,k) )           &
                             *(  (khh(i,j,k  )+ khh(i,j-1,k  ))     &
                                +(khh(i,j,k+1)+ khh(i,j-1,k+1)) )   &
                            *(    s(i,j,k)-   s(i,j-1,k) )*rdy*vf(j)
        enddo
        enddo

        IF( wbc.eq.2 .and. ibw.eq.1 )THEN
          do j=1,nj
            dumx(1,j,k) = dumx(2,j,k)
          enddo
        ENDIF
        IF( ebc.eq.2 .and. ibe.eq.1 )THEN
          do j=1,nj
            dumx(ni+1,j,k) = dumx(ni,j,k)
          enddo
        ENDIF

        IF( sbc.eq.2 .and. ibs.eq.1 )THEN
          do i=1,ni
            dumy(i,1,k) = dumy(i,2,k)
          enddo
        ENDIF
        IF( nbc.eq.2 .and. ibn.eq.1 )THEN
          do i=1,ni
            dumy(i,nj+1,k) = dumy(i,nj,k)
          enddo
        ENDIF

        do j=1,nj
        do i=1,ni
          turbx(i,j,k) = -(dumx(i+1,j,k)-dumx(i,j,k))*rdx*uh(i)
          turby(i,j,k) = -(dumy(i,j+1,k)-dumy(i,j,k))*rdy*vh(j)
        enddo
        enddo

      enddo

    ELSE
      ! axisymmetric:

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk
      do j=1,nj

        do i=1,ni+1
          dumx(i,j,k)= -0.125*( rho(i,j,k)+rho(i-1,j,k) )           &
                             *(  (khh(i,j,k  )+ khh(i-1,j,k  ))     &
                                +(khh(i,j,k+1)+ khh(i-1,j,k+1)) )   &
                             *(    s(i,j,k)-   s(i-1,j,k) )*rdx*uf(i)
        enddo

        IF( ebc.eq.2 .and. ibe.eq.1 )THEN
          dumx(ni+1,j,k) = arh1(ni)*dumx(ni,j,k)/arh2(ni)
        ENDIF

        !-----
        if(wbc.eq.3.or.wbc.eq.4)then
          ! assume zero flux:
          dumx(1,j,k) = 0.0
        endif
        if(ebc.eq.3.or.ebc.eq.4)then
          ! assume zero flux:
          dumx(ni+1,j,k) = 0.0
        endif
        !-----

        do i=1,ni
          turbx(i,j,k)=-(arh2(i)*dumx(i+1,j,k)-arh1(i)*dumx(i,j,k))*rdx*uh(i)
          turby(i,j,k)=0.0
        enddo

      enddo
      enddo

    ENDIF   ! endif for axisymm check

!---------------------------------------------------------------

  ELSE
      ! Cartesian with terrain:

      ! use turbz as a temporary array for s at w-pts:
!$omp parallel do default(shared)   &
!$omp private(i,j,k,r1,r2)
      do j=0,nj+1

        ! lowest model level:
        do i=0,ni+1
          turbz(i,j,1) = cgs1*s(i,j,1)+cgs2*s(i,j,2)+cgs3*s(i,j,3)
        enddo

        ! upper-most model level:
        do i=0,ni+1
          turbz(i,j,nk+1) = cgt1*s(i,j,nk)+cgt2*s(i,j,nk-1)+cgt3*s(i,j,nk-2)
        enddo

        ! interior:
        do k=2,nk
        r2 = (sigmaf(k)-sigma(k-1))*rds(k)
        r1 = 1.0-r2
        do i=0,ni+1
          turbz(i,j,k) = r1*s(i,j,k-1)+r2*s(i,j,k)
        enddo
        enddo

      enddo

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk

        ! x-flux
        do j=1,nj
        do i=1,ni+1
          dumx(i,j,k)= -0.125*( gz(i,j)*rho(i,j,k)+gz(i-1,j)*rho(i-1,j,k) )  &
                             *(  (khh(i,j,k  )+ khh(i-1,j,k  ))     &
                                +(khh(i,j,k+1)+ khh(i-1,j,k+1)) )*( &
                  (s(i,j,k)*rgz(i,j)-s(i-1,j,k)*rgz(i-1,j))         &
                   *rdx*uf(i)                                       &
              +0.5*( gxu(i,j,k+1)*(turbz(i,j,k+1)+turbz(i-1,j,k+1)) &
                    -gxu(i,j,k  )*(turbz(i,j,k  )+turbz(i-1,j,k  )) &
                   )*rdsf(k)*rgzu(i,j) )
        enddo
        enddo

        ! y-flux
        do j=1,nj+1
        do i=1,ni
          dumy(i,j,k)= -0.125*( gz(i,j)*rho(i,j,k)+gz(i,j-1)*rho(i,j-1,k) )  &
                             *(  (khh(i,j,k  )+ khh(i,j-1,k  ))     &
                                +(khh(i,j,k+1)+ khh(i,j-1,k+1)) )*( &
                  (s(i,j,k)*rgz(i,j)-s(i,j-1,k)*rgz(i,j-1))         &
                   *rdy*vf(j)                                       &
              +0.5*( gyv(i,j,k+1)*(turbz(i,j,k+1)+turbz(i,j-1,k+1)) &
                    -gyv(i,j,k  )*(turbz(i,j,k  )+turbz(i,j-1,k  )) &
                   )*rdsf(k)*rgzv(i,j) )
        enddo
        enddo

      enddo

      ! use turbz,dumz as temporary arrays for fluxes at w-pts:
!$omp parallel do default(shared)   &
!$omp private(i,j,k,r1,r2)
      do j=1,nj+1
        ! lowest model level:
        do i=1,ni+1
          turbz(i,j,1) = cgs1*dumx(i,j,1)+cgs2*dumx(i,j,2)+cgs3*dumx(i,j,3)
           dumz(i,j,1) = cgs1*dumy(i,j,1)+cgs2*dumy(i,j,2)+cgs3*dumy(i,j,3)
        enddo

        ! upper-most model level:
        do i=1,ni+1
          turbz(i,j,nk+1) = cgt1*dumx(i,j,nk)+cgt2*dumx(i,j,nk-1)+cgt3*dumx(i,j,nk-2)
           dumz(i,j,nk+1) = cgt1*dumy(i,j,nk)+cgt2*dumy(i,j,nk-1)+cgt3*dumy(i,j,nk-2)
        enddo

        ! interior:
        do k=2,nk
        r2 = (sigmaf(k)-sigma(k-1))*rds(k)
        r1 = 1.0-r2
        do i=1,ni+1
          turbz(i,j,k) = r1*dumx(i,j,k-1)+r2*dumx(i,j,k)
           dumz(i,j,k) = r1*dumy(i,j,k-1)+r2*dumy(i,j,k)
        enddo
        enddo
      enddo

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk

        ! x-tendency
        do j=1,nj
        do i=1,ni
          turbx(i,j,k) = -gz(i,j)*( dumx(i+1,j,k)*rgzu(i+1,j)             &
                                   -dumx(i  ,j,k)*rgzu(i  ,j) )*rdx*uh(i) &
                -( ( gx(i,j,k+1)*(turbz(i,j,k+1)+turbz(i+1,j,k+1))        &
                    -gx(i,j,k  )*(turbz(i,j,k  )+turbz(i+1,j,k  )) )      &
                 )*0.5*rdsf(k)
        enddo
        enddo

        ! y-tendency
        do j=1,nj
        do i=1,ni
          turby(i,j,k) = -gz(i,j)*( dumy(i,j+1,k)*rgzv(i,j+1)             &
                                   -dumy(i,j  ,k)*rgzv(i,j  ) )*rdy*vh(j) &
                -( ( gy(i,j,k+1)*( dumz(i,j,k+1)+ dumz(i,j+1,k+1))        &
                    -gy(i,j,k  )*( dumz(i,j,k  )+ dumz(i,j+1,k  )) )      &
                 )*0.5*rdsf(k)
        enddo
        enddo

      enddo

  ENDIF  ! endif for terrain check

!-----------------------------------------------------------------
!  open boundary conditions:

    IF( wbc.eq.2 .or. ebc.eq.2 .or. sbc.eq.2 .or. nbc.eq.2 )THEN
!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      DO k=1,nk

        IF( wbc.eq.2 .and. ibw.eq.1 )THEN
          do j=1,nj
            turbx(1,j,k) = 0.0
          enddo
        ENDIF
        IF( ebc.eq.2 .and. ibe.eq.1 )THEN
          do j=1,nj
            turbx(ni,j,k) = 0.0
          enddo
        ENDIF

        IF( sbc.eq.2 .and. ibs.eq.1 )THEN
          do i=1,ni
            turby(i,1,k) = 0.0
          enddo
        ENDIF
        IF( nbc.eq.2 .and. ibn.eq.1 )THEN
          do i=1,ni
            turby(i,nj,k) = 0.0
          enddo
        ENDIF

      ENDDO
    ENDIF

  ELSE  dohoriz

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni
        turbx(i,j,k)=0.0
        turby(i,j,k)=0.0
      enddo
      enddo
      enddo

  ENDIF  dohoriz

!---------------------------------------------------------------------
!  z-direction

  dovert:  &
  IF( dovturb )THEN

      call       turbsz(iflux,dt,dosfcflx,sflux,mh,mf,  &
                       turbz,dumx,dumy,dumz,rho,rr,rf,s,khv,dum7,dum8,ivar)

  ELSE  dovert

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni
        turbz(i,j,k)=0.0
      enddo
      enddo
      enddo

  ENDIF  dovert


!---------------------------------------------------------------------
!  Tendencies:

    IF(axisymm.eq.0)THEN

      IF( cm1setup.eq.4 )THEN
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,nj
        do i=1,ni
          if( cm0(i,j) .le. cmemin )then
            ! zero-out turb tendencies outside of LES domain:
            turbx(i,j,k) = 0.0
            turby(i,j,k) = 0.0
            turbz(i,j,k) = 0.0
          endif

          sten(i,j,k)=sten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))*rr(i,j,k)
        enddo
        enddo
        enddo
      ELSE
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k)
        do k=1,nk
        do j=1,nj
        do i=1,ni

          sten(i,j,k)=sten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))*rr(i,j,k)
        enddo
        enddo
        enddo
      ENDIF

    ELSE

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni
        sten(i,j,k)=sten(i,j,k)+(turbx(i,j,k)+turbz(i,j,k))*rr(i,j,k)
      enddo
      enddo
      enddo

    ENDIF

!---------------------------------------------------------------------
!  Diagnostics:

      IF( dobud )THEN
      if( sd_hturb.ge.1 .and. sd_vturb.ge.1 )then
        if( axisymm.eq.0 )then
          !$omp parallel do default(shared)   &
          !$omp private(i,j,k)
          do k=1,nk
          do j=1,nj
          do i=1,ni
            diag(i,j,k,sd_hturb) = (turbx(i,j,k)+turby(i,j,k))*rr(i,j,k)
            diag(i,j,k,sd_vturb) = turbz(i,j,k)*rr(i,j,k)
          enddo
          enddo
          enddo
        else
          !$omp parallel do default(shared)   &
          !$omp private(i,j,k)
          do k=1,nk
          do j=1,nj
          do i=1,ni
            diag(i,j,k,sd_hturb) = turbx(i,j,k)*rr(i,j,k)
            diag(i,j,k,sd_vturb) = turbz(i,j,k)*rr(i,j,k)
          enddo
          enddo
          enddo
        endif
      endif
      ENDIF

!---------------------------------------------------------------------

      if(timestats.ge.1) time_ttend=time_ttend+mytime()

      return
      end subroutine turbs


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbsz(iflux,dt,dosfcflx,sflux,mh,mf,  &
                       turbz,dum1,dum2,dumz,rho,rr,rf,s,khv,dum7,dum8,ivar)
      use input
      use constants
      use cm1libs , only : rslf,rsif
      implicit none

      integer, intent(in) :: iflux
      real, intent(in) :: dt
      logical, intent(in) :: dosfcflx
      real, intent(in), dimension(ib:ie,jb:je) :: sflux
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: turbz,dum1,dum2,dumz
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rr,rf,s
      real, intent(in), dimension(ibc:iec,jbc:jec,kbc:kec) :: khv
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: dum7,dum8
      integer, intent(in) :: ivar

      integer :: i,j,k
      real :: rdt,tema,temb,temc
      real :: tem,r1,r2,cfa,cfb,cfc,cfd,kappa,ptcb,ptct


    if( cm1setup.eq.3 )then
      kappa = viscosity/pr_num
      ! bottom/top boundary conditions:
      if( ivar.eq.1 )then
        ! potential temperature:
        ptcb = ptc_bot - th0r
        ptct = ptc_top - th0r
      elseif( ivar.eq.2 )then
        ! water vapor mixing ratio:
        ! (assume saturation)
        ptcb = rslf( base_pbot , ptc_bot*base_pibot )
        ptct = rslf( base_ptop , ptc_top*base_pitop )
      else
        ptcb = 0.0
        ptct = 0.0
      endif
    endif

  ifimpls:  &
  IF( doimpl.eq.0 )THEN
      ! explicit vertical turbulence:

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      DO j=1,nj

        do k=2,nk
        do i=1,ni
          dumz(i,j,k)= -khv(i,j,k)*(s(i,j,k)-s(i,j,k-1))*rdz*mf(i,j,k)*rf(i,j,k)
        enddo
        enddo

        IF( cm1setup.eq.1 .or. cm1setup.eq.2 .or. cm1setup.eq.4 )THEN
          ! LES or mesoscale modeling:

          IF(bcturbs.eq.1)THEN
 
            do i=1,ni
              dumz(i,j,1)=0.0
              dumz(i,j,nk+1)=0.0
            enddo

          ELSEIF(bcturbs.eq.2)THEN
 
            do i=1,ni
              dumz(i,j,1)=dumz(i,j,2)
              dumz(i,j,nk+1)=dumz(i,j,nk)
            enddo

          ENDIF

          if(iflux.eq.1 .and. dosfcflx)then
            do i=1,ni
              dumz(i,j,1) = sflux(i,j)*rf(i,j,1)
            enddo
          endif

        ELSEIF( cm1setup.eq.3 )THEN

          if(bc_temp.eq.1)then
            ! specified theta at boundary

            do i=1,ni
              dumz(i,j,1) = -kappa*2.0*(s(i,j,1)-ptcb)*rdz*mf(i,j,1)*rf(i,j,1)
              dumz(i,j,nk+1) = -kappa*2.0*(ptct-s(i,j,nk))*rdz*mf(i,j,nk+1)*rf(i,j,nk+1)
            enddo

          elseif(bc_temp.eq.2)then
            ! specified flux at boundary

            do i=1,ni
              dumz(i,j,1) = kappa*ptc_bot*rf(i,j,1)
              dumz(i,j,nk+1) = kappa*ptc_top*rf(i,j,nk+1)
            enddo

          endif

        ELSE

          print *,'  21086 '
          call stopcm1

        ENDIF

        do k=1,nk
        do i=1,ni
          turbz(i,j,k) = -(dumz(i,j,k+1)-dumz(i,j,k))*rdz*mh(i,j,k)
        enddo
        enddo

      ENDDO

  ELSE  ifimpls

      ! implicit vertical turbulence:

      rdt = 1.0/dt
      tema = -1.0*dt*vialpha*rdz*rdz
      temb = dt*vibeta*rdz*rdz
      temc = dt*rdz

      ! boundary conditions:
      IF( cm1setup.eq.1 .or. cm1setup.eq.2 .or. cm1setup.eq.4 )THEN
        ! LES or mesoscale modeling:
        IF(bcturbs.eq.1)THEN
          !$omp parallel do default(shared)   &
          !$omp private(i,j)
          do j=1,nj
          do i=1,ni
            dumz(i,j,1)=0.0
            dumz(i,j,nk+1)=0.0
          enddo
          enddo
        ELSEIF(bcturbs.eq.2)THEN
          !$omp parallel do default(shared)   &
          !$omp private(i,j)
          do j=1,nj
          do i=1,ni
            dumz(i,j,1) = -khv(i,j,2)*(s(i,j,2)-s(i,j,1))*rdz*mf(i,j,2)*rf(i,j,2)
            dumz(i,j,nk+1) = -khv(i,j,nk)*(s(i,j,nk)-s(i,j,nk-1))*rdz*mf(i,j,nk)*rf(i,j,nk)
          enddo
          enddo
        ENDIF
        if(iflux.eq.1 .and. dosfcflx)then
          ! surface heat/moisture flux:
          !$omp parallel do default(shared)   &
          !$omp private(i,j)
          do j=1,nj
          do i=1,ni
            dumz(i,j,1)=sflux(i,j)*rf(i,j,1)
          enddo
          enddo
        endif
      ELSEIF( cm1setup.eq.3 )THEN
        ! DNS bc:
        if(bc_temp.eq.1)then
          ! specified theta at boundary
          !$omp parallel do default(shared)   &
          !$omp private(i,j)
          do j=1,nj
          do i=1,ni
            dumz(i,j,1) = -kappa*2.0*(s(i,j,1)-ptcb)*rdz*mf(i,j,1)*rf(i,j,1)
            dumz(i,j,nk+1) = -kappa*2.0*(ptct-s(i,j,nk))*rdz*mf(i,j,nk+1)*rf(i,j,nk+1)
          enddo
          enddo
        elseif(bc_temp.eq.2)then
          ! specified flux at boundary
          !$omp parallel do default(shared)   &
          !$omp private(i,j)
          do j=1,nj
          do i=1,ni
            dumz(i,j,1) = kappa*ptc_bot*rf(i,j,1)
            dumz(i,j,nk+1) = kappa*ptc_top*rf(i,j,nk+1)
          enddo
          enddo
        endif
      ENDIF

      k = 1

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem)
      do j=1,nj
      DO i=1,ni
          r2 = dum8(i,j,k)
          cfc = tema*r2
          cfb = 1.0 - cfc
          cfd = s(i,j,k) + temb*( -r2*s(i,j,k)+r2*s(i,j,k+1) )  &
                         + temc*dumz(i,j,1)*mh(i,j,1)*rr(i,j,1)
        tem = 1.0/cfb
        dum1(i,j,1)=-cfc*tem
        dum2(i,j,1)= cfd*tem
      ENDDO
      enddo

        do k=2,nk-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem)
        do j=1,nj
        do i=1,ni
          r1 = dum7(i,j,k)
          r2 = dum8(i,j,k)
          cfa = tema*r1
          cfc = tema*r2
          cfb = 1.0 - cfa - cfc
          cfd = s(i,j,k) + temb*(r1*s(i,j,k-1)-(r1+r2)*s(i,j,k)+r2*s(i,j,k+1) )
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum1(i,j,k)=-cfc*tem
          dum2(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
        enddo
        enddo

        enddo

        k = nk
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem)
        do j=1,nj
        do i=1,ni
          r1 = dum7(i,j,k)
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = s(i,j,k) + temb*( r1*s(i,j,k-1)-r1*s(i,j,k) )  &
                         - temc*dumz(i,j,nk+1)*mh(i,j,nk)*rr(i,j,nk)
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dumz(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          turbz(i,j,k) = rho(i,j,k)*(dumz(i,j,k)-s(i,j,k))*rdt
        enddo
        enddo

        do k=nk-1,1,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=1,nj
        DO i=1,ni
          dumz(i,j,k)=dum1(i,j,k)*dumz(i,j,k+1)+dum2(i,j,k)
          turbz(i,j,k) = rho(i,j,k)*(dumz(i,j,k)-s(i,j,k))*rdt
        ENDDO
        enddo

        enddo

  ENDIF  ifimpls

      end subroutine turbsz


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbt(dt,xh,rxh,uh,xf,uf,vh,vf,mh,mf,rho,rr,rf,          &
                       rds,sigma,gz,rgz,gzu,rgzu,gzv,rgzv,                &
                       turbx,turby,turbz,dumx,dumy,dumz,t,tten,kmh,kmv)
      use input
      use constants
      implicit none

      real, intent(in) :: dt
      real, intent(in), dimension(ib:ie) :: xh,rxh,uh
      real, intent(in), dimension(ib:ie+1) :: xf,uf
      real, intent(in), dimension(jb:je) :: vh
      real, intent(in), dimension(jb:je+1) :: vf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rr,rf
      real, intent(in), dimension(kb:ke) :: rds,sigma
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,rgzu,gzv,rgzv
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: turbx,turby,turbz,dumx,dumy,dumz
      real, intent(in), dimension(ibt:iet,jbt:jet,kbt:ket) :: t
      real, intent(inout), dimension(ibt:iet,jbt:jet,kbt:ket) :: tten
      real, intent(in), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmh,kmv

      integer :: i,j,k
      real :: rdt,tema,temb,temc
      real :: tem,r1,r2,rrf
      real :: cfa,cfb,cfc,cfd

!---------------------------------------------------------------

    IF(.not.terrain_flag)THEN
      ! Cartesian without terrain:

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=2,nk

        do j=1,nj+1
        do i=1,ni+1
          !  x-direction
          ! note:  K is multiplied by 2:
          dumx(i,j,k)= -0.25*( rf(i,j,k)+rf(i-1,j,k) )   &
                       *2.0*( kmh(i,j,k)+kmh(i-1,j,k) )   &
                           *(   t(i,j,k)-  t(i-1,j,k) )*rdx*uf(i)
          !  y-direction
          ! note:  K is multiplied by 2:
          dumy(i,j,k)= -0.25*( rf(i,j,k)+rf(i,j-1,k) )   &
                       *2.0*( kmh(i,j,k)+kmh(i,j-1,k) )   &
                           *(   t(i,j,k)-  t(i,j-1,k) )*rdy*vf(j)
        enddo
        enddo

        IF( wbc.eq.2 .and. ibw.eq.1 )THEN
          do j=1,nj
            dumx(1,j,k) = dumx(2,j,k)
          enddo
        ENDIF
        IF( ebc.eq.2 .and. ibe.eq.1 )THEN
          do j=1,nj
            dumx(ni+1,j,k) = dumx(ni,j,k)
          enddo
        ENDIF

        IF( sbc.eq.2 .and. ibs.eq.1 )THEN
          do i=1,ni
            dumy(i,1,k) = dumy(i,2,k)
          enddo
        ENDIF
        IF( nbc.eq.2 .and. ibn.eq.1 )THEN
          do i=1,ni
            dumy(i,nj+1,k) = dumy(i,nj,k)
          enddo
        ENDIF

        do j=1,nj
        do i=1,ni
          turbx(i,j,k) = -(dumx(i+1,j,k)-dumx(i,j,k))*rdx*uh(i)
          turby(i,j,k) = -(dumy(i,j+1,k)-dumy(i,j,k))*rdy*vh(j)
        enddo
        enddo

      enddo

!---------------------------------------------------------------
!  Cartesian with terrain:

    ELSE

      ! turbz stores t at s-pts:
!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk
        do j=0,nj+1
        do i=0,ni+1
          turbz(i,j,k) = 0.5*(t(i,j,k)+t(i,j,k+1))
        enddo
        enddo
      enddo

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=2,nk

        ! x-flux:
        do j=1,nj
        do i=1,ni+1
          ! note:  K is multiplied by 2:
          dumx(i,j,k)= -0.25*( gz(i,j)*rf(i,j,k)+gz(i-1,j)*rf(i-1,j,k) )                 &
                       *2.0*( kmh(i,j,k)+kmh(i-1,j,k) )*(                                &
                            (t(i,j,k)*rgz(i,j)-t(i-1,j,k)*rgz(i-1,j))*rdx*uf(i)          &
                     +0.5*( (zt-sigma(k  ))*(turbz(i-1,j,k  )+turbz(i,j,k  ))            &
                           -(zt-sigma(k-1))*(turbz(i-1,j,k-1)+turbz(i,j,k-1))            &
                          )*rds(k)*(rgz(i,j)-rgz(i-1,j))*rdx*uf(i)                       &
                                                        )
        enddo
        enddo

        ! y-flux:
        do j=1,nj+1
        do i=1,ni
          ! note:  K is multiplied by 2:
          dumy(i,j,k)= -0.25*( gz(i,j)*rf(i,j,k)+gz(i,j-1)*rf(i,j-1,k) )                 &
                       *2.0*( kmh(i,j,k)+kmh(i,j-1,k) )*(                                &
                            (t(i,j,k)*rgz(i,j)-t(i,j-1,k)*rgz(i,j-1))*rdy*vf(j)          &
                     +0.5*( (zt-sigma(k  ))*(turbz(i,j-1,k  )+turbz(i,j,k  ))            &
                           -(zt-sigma(k-1))*(turbz(i,j-1,k-1)+turbz(i,j,k-1))            &
                          )*rds(k)*(rgz(i,j)-rgz(i,j-1))*rdy*vf(j)                       &
                                                        )
        enddo
        enddo

      enddo

!$omp parallel do default(shared)   &
!$omp private(i,j)
        do j=1,nj+1
        do i=1,ni+1
          dumx(i,j,   1)=0.0
          dumx(i,j,nk+1)=0.0
          dumy(i,j,   1)=0.0
          dumy(i,j,nk+1)=0.0
        enddo
        enddo

      ! turbz stores dumx at s-pts:
      !  dumz stores dumy at s-pts:
!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk
        do j=1,nj+1
        do i=1,ni+1
          turbz(i,j,k)=0.5*(dumx(i,j,k)+dumx(i,j,k+1))
           dumz(i,j,k)=0.5*(dumy(i,j,k)+dumy(i,j,k+1))
        enddo
        enddo
      enddo

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=2,nk

        ! x-tendency:
        do j=1,nj
        do i=1,ni
          turbx(i,j,k) = -(dumx(i+1,j,k)*rgzu(i+1,j)-dumx(i,j,k)*rgzu(i,j))*gz(i,j)*rdx*uh(i) &
                         -0.5*( (zt-sigma(k  ))*(turbz(i,j,k  )+turbz(i+1,j,k  ))             &
                               -(zt-sigma(k-1))*(turbz(i,j,k-1)+turbz(i+1,j,k-1))             &
                              )*rds(k)*(rgzu(i+1,j)-rgzu(i,j))*gz(i,j)*rdx*uh(i)
        enddo
        enddo

        ! y-tendency:
        do j=1,nj
        do i=1,ni
          turby(i,j,k) = -(dumy(i,j+1,k)*rgzv(i,j+1)-dumy(i,j,k)*rgzv(i,j))*gz(i,j)*rdy*vh(j) &
                         -0.5*( (zt-sigma(k  ))*( dumz(i,j,k  )+ dumz(i,j+1,k  ))             &
                               -(zt-sigma(k-1))*( dumz(i,j,k-1)+ dumz(i,j+1,k-1))             &
                              )*rds(k)*(rgzv(i,j+1)-rgzv(i,j))*gz(i,j)*rdy*vh(j)
        enddo
        enddo

      enddo

    ENDIF  ! endif for terrain check

!-----------------------------------------------------------------
!  open boundary conditions:

    IF( wbc.eq.2 .or. ebc.eq.2 .or. sbc.eq.2 .or. nbc.eq.2 )THEN
!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      DO k=2,nk

        IF( wbc.eq.2 .and. ibw.eq.1 )THEN
          do j=1,nj
            turbx(1,j,k) = 0.0
          enddo
        ENDIF
        IF( ebc.eq.2 .and. ibe.eq.1 )THEN
          do j=1,nj
            turbx(ni,j,k) = 0.0
          enddo
        ENDIF

        IF( sbc.eq.2 .and. ibs.eq.1 )THEN
          do i=1,ni
            turby(i,1,k) = 0.0
          enddo
        ENDIF
        IF( nbc.eq.2 .and. ibn.eq.1 )THEN
          do i=1,ni
            turby(i,nj,k) = 0.0
          enddo
        ENDIF

      ENDDO
    ENDIF

!---------------------------------------------------------------------
!  z-direction

  ifimplt:  &
  IF( doimpl.eq.0 )THEN
      ! explicit vertical turbulence:

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni
        ! note:  K is multiplied by 2:
        dumz(i,j,k) = -(kmv(i,j,k)+kmv(i,j,k+1))*(t(i,j,k+1)-t(i,j,k))*rdz*mh(i,j,k)*rho(i,j,k)
      enddo
      enddo
      enddo

      if( bbc.eq.3 )then
      ! 210504: tke is approximately constant in the surface layer (thus dt/dz=0)
      do j=1,nj
      do i=1,ni
        dumz(i,j,1) = 0.0
      enddo
      enddo
      endif

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=2,nk
      do j=1,nj
      do i=1,ni
        turbz(i,j,k) = -(dumz(i,j,k)-dumz(i,j,k-1))*rdz*mf(i,j,k)
        tten(i,j,k)=tten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))/rf(i,j,k)
      enddo
      enddo
      enddo

  ELSE

      ! implicit vertical turbulence:

      rdt = 1.0/dt
      tema = -1.0*dt*vialpha*rdz*rdz
      temb =      dt*vibeta*rdz*rdz
      temc = dt*rdz

        k=2
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrf)
        do j=1,nj
        do i=1,ni
          rrf = mf(i,j,k)/rf(i,j,k)
          r2 = (kmv(i,j,k  )+kmv(i,j,k+1))*mh(i,j,k  )*rho(i,j,k  )*rrf
          cfc = tema*r2
          cfb = 1.0 - cfc
          cfd = t(i,j,k) + temb*( r2*t(i,j,k+1)-r2*t(i,j,k) )
!!!          tem = -(kmv(i,j,k-1)+kmv(i,j,k))*(t(i,j,k)-t(i,j,k-1))*rdz*mh(i,j,k-1)*rho(i,j,k-1)
!!!          cfd = cfd + temc*tem*rrf
          tem = 1.0/cfb
          dumx(i,j,k) = -cfc*tem
          dumy(i,j,k) =  cfd*tem
        enddo
        enddo

        do k=3,(nk-1)

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrf)
        do j=1,nj
        do i=1,ni
          rrf = mf(i,j,k)/rf(i,j,k)
          r1 = (kmv(i,j,k-1)+kmv(i,j,k  ))*mh(i,j,k-1)*rho(i,j,k-1)*rrf
          r2 = (kmv(i,j,k  )+kmv(i,j,k+1))*mh(i,j,k  )*rho(i,j,k  )*rrf
          cfa = tema*r1
          cfc = tema*r2
          cfb = 1.0 - cfa - cfc
          cfd = t(i,j,k) + temb*(r2*t(i,j,k+1)-(r1+r2)*t(i,j,k)+r1*t(i,j,k-1))
          tem = 1.0/(cfa*dumx(i,j,k-1)+cfb)
          dumx(i,j,k) = -cfc*tem
          dumy(i,j,k) = (cfd-cfa*dumy(i,j,k-1))*tem
        enddo
        enddo

        enddo

        k = nk

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrf)
        do j=1,nj
        do i=1,ni
          rrf = mf(i,j,k)/rf(i,j,k)
          r1 = (kmv(i,j,k-1)+kmv(i,j,k  ))*mh(i,j,k-1)*rho(i,j,k-1)*rrf
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = t(i,j,k) + temb*( -r1*t(i,j,k)+r1*t(i,j,k-1) )
!!!          tem = -(kmv(i,j,k)+kmv(i,j,k+1))*(t(i,j,k+1)-t(i,j,k))*rdz*mh(i,j,k)*rho(i,j,k)
!!!          cfd = cfd - temc*tem*rrf
          tem = 1.0/(cfa*dumx(i,j,k-1)+cfb)
          dumz(i,j,k) = (cfd-cfa*dumy(i,j,k-1))*tem
          turbz(i,j,k) = rf(i,j,k)*(dumz(i,j,k)-t(i,j,k))*rdt
          tten(i,j,k)=tten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))/rf(i,j,k)
        enddo
        enddo

        do k=(nk-1),2,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=1,nj
        do i=1,ni
          dumz(i,j,k) = dumx(i,j,k)*dumz(i,j,k+1)+dumy(i,j,k)
          turbz(i,j,k) = rf(i,j,k)*(dumz(i,j,k)-t(i,j,k))*rdt
          tten(i,j,k)=tten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))/rf(i,j,k)
        enddo
        enddo

        enddo

  ENDIF  ifimplt

!---------------------------------------------------------------------

      if(timestats.ge.1) time_ttend=time_ttend+mytime()

      return
      end subroutine turbt


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbu(dt,xh,ruh,xf,rxf,arf1,arf2,uf,vh,mh,mf,rmf,rho,rf,  &
                       zs,gz,rgz,gzu,gzv,rds,sigma,rdsf,sigmaf,gxu,     &
                       turbx,turby,turbz,dum1,dum2,dum3,dum7,dum8,dum9,u,uten,w,t11,t12,t13,t22,kmv,cm0, &
                       kmw,ufw,u1b,u2pt,ufwk,doubud,udiag)
      use input
      use constants
      implicit none

      real, intent(in) :: dt
      real, intent(in), dimension(ib:ie) :: xh,ruh
      real, intent(in), dimension(ib:ie+1) :: xf,rxf,arf1,arf2,uf
      real, intent(in), dimension(jb:je) :: vh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf,rmf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rf
      real, intent(in), dimension(ib:ie,jb:je) :: zs
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,gzv
      real, intent(in), dimension(kb:ke) :: rds,sigma
      real, intent(in), dimension(kb:ke+1) :: rdsf,sigmaf
      real, intent(in), dimension(itb:ite,jtb:jte,ktb:kte) :: gxu
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: turbx,turby,turbz,dum1,dum2,dum3,dum7,dum8,dum9
      real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: u
      real, intent(inout), dimension(ib:ie+1,jb:je,kb:ke) :: uten
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: w
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: t11,t12,t13,t22
      real, intent(in), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmv
      real, intent(in), dimension(ib:ie,jb:je) :: cm0
      real, intent(in), dimension(kb:ke) :: kmw,ufw,u1b
      real, intent(inout), dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: u2pt
      real, intent(in),    dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: ufwk
      logical, intent(in) :: doubud
      real, intent(inout) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nudiag) :: udiag

      integer :: i,j,k,i1,i2
      real :: rdt,tema,temb,temc
      real :: tem,r1,r2,rru0
      real :: cfa,cfb,cfc,cfd

!---------------------------------------------------------------

  dohoriz:  &
  IF( dohturb )THEN

  IF(.not.terrain_flag)THEN

    IF(axisymm.eq.0)THEN

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk

        !  x-direction
        !  y-direction
        do j=1,nj
        do i=1,ni+1
          turbx(i,j,k)=(t11(i,j,k)-t11(i-1,j,k))*rdx*uf(i)
          turby(i,j,k)=(t12(i,j+1,k)-t12(i,j,k))*rdy*vh(j)
        enddo
        enddo

      enddo

    ELSE

!$omp parallel do default(shared)   &
!$omp private(j,k)
      do k=1,nk

        do j=1,nj
        turbx(1,j,k)=0.0
        do i=2,ni+1
          turbx(i,j,k) = ( arf2(i)*arf2(i)*t11(i,j,k) - arf1(i)*arf1(i)*t11(i-1,j,k) )*rdx*uf(i)
        enddo
        IF(ebc.eq.3.or.ebc.eq.4)THEN
          turbx(ni+1,j,k)=0.0
        ENDIF
        enddo

      enddo

    ENDIF

!---------------------------------------------------------------
!  Terrain:

  ELSE

      ! dum1 stores t11 at w-pts:
      ! dum2 stores t12 at w-pts:
!$omp parallel do default(shared)   &
!$omp private(i,j,k,r1,r2)
      do j=1,nj+1

          ! lowest model level:
          do i=0,ni+1
            dum1(i,j,1) = cgs1*t11(i,j,1)+cgs2*t11(i,j,2)+cgs3*t11(i,j,3)
            dum2(i,j,1) = cgs1*t12(i,j,1)+cgs2*t12(i,j,2)+cgs3*t12(i,j,3)
          enddo

          ! upper-most model level:
          do i=0,ni+1
            dum1(i,j,nk+1) = cgt1*t11(i,j,nk)+cgt2*t11(i,j,nk-1)+cgt3*t11(i,j,nk-2)
            dum2(i,j,nk+1) = cgt1*t12(i,j,nk)+cgt2*t12(i,j,nk-1)+cgt3*t12(i,j,nk-2)
          enddo

          ! interior:
          do k=2,nk
          r2 = (sigmaf(k)-sigma(k-1))*rds(k)
          r1 = 1.0-r2
          do i=0,ni+1
            dum1(i,j,k) = r1*t11(i,j,k-1)+r2*t11(i,j,k)
            dum2(i,j,k) = r1*t12(i,j,k-1)+r2*t12(i,j,k)
          enddo
          enddo

      enddo

!$omp parallel do default(shared)   &
!$omp private(i,j,k,r1,r2)
      do k=1,nk

        !  x-direction
        do j=1,nj
        do i=1,ni+1
          turbx(i,j,k)=gzu(i,j)*(t11(i,j,k)*rgz(i,j)-t11(i-1,j,k)*rgz(i-1,j))*rdx*uf(i)  &
                      +0.5*( gxu(i,j,k+1)*(dum1(i-1,j,k+1)+dum1(i,j,k+1))                &
                            -gxu(i,j,k  )*(dum1(i-1,j,k  )+dum1(i,j,k  )) )*rdsf(k)
        enddo
        enddo

        !  y-direction
        do j=1,nj
        do i=1,ni+1
          r1 = 0.25*((rgz(i-1,j-1)+rgz(i,j))+(rgz(i-1,j)+rgz(i,j-1)))
          r2 = 0.25*((rgz(i-1,j+1)+rgz(i,j))+(rgz(i-1,j)+rgz(i,j+1)))
          turby(i,j,k)=gzu(i,j)*(t12(i,j+1,k)*r2-t12(i,j,k)*r1)*rdy*vh(j)      &
                      +0.5*( (zt-sigmaf(k+1))*(dum2(i,j,k+1)+dum2(i,j+1,k+1))  &
                            -(zt-sigmaf(k  ))*(dum2(i,j,k  )+dum2(i,j+1,k  ))  &
                           )*gzu(i,j)*(r2-r1)*rdy*vh(j)*rdsf(k)
        enddo
        enddo

      enddo

  ENDIF  ! endif for terrain check

!-----------------------------------------------------------------
!  open boundary conditions:

    IF( wbc.eq.2 .or. ebc.eq.2 .or. sbc.eq.2 .or. nbc.eq.2 )THEN
!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      DO k=1,nk

        IF( wbc.eq.2 .and. ibw.eq.1 )THEN
          do j=1,nj
            turbx(1,j,k) = 0.0
          enddo
        ENDIF
        IF( ebc.eq.2 .and. ibe.eq.1 )THEN
          do j=1,nj
            turbx(ni+1,j,k) = 0.0
          enddo
        ENDIF

        IF( sbc.eq.2 .and. ibs.eq.1 )THEN
          do i=1,ni+1
            turby(i,1,k) = 0.0
          enddo
        ENDIF
        IF( nbc.eq.2 .and. ibn.eq.1 )THEN
          do i=1,ni+1
            turby(i,nj,k) = 0.0
          enddo
        ENDIF

      ENDDO
    ENDIF

  ELSE  dohoriz

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni+1
        turbx(i,j,k)=0.0
        turby(i,j,k)=0.0
      enddo
      enddo
      enddo

  ENDIF  dohoriz

!-----------------------------------------------------------------
!  z-direction

  dovert:  &
  IF( dovturb )THEN

      call       turbuz(dt,xh,ruh,xf,rxf,arf1,arf2,uf,vh,mh,mf,rmf,rho,rf,  &
                       zs,gz,rgz,gzu,gzv,rds,sigma,rdsf,sigmaf,gxu,     &
                       turbz,dum1,dum2,dum3,dum7,dum9,u ,w ,t11,t12,t13,t22,kmv, &
                       kmw,ufw,u1b,u2pt,ufwk)

  ELSE  dovert

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni+1
        turbz(i,j,k)=0.0
      enddo
      enddo
      enddo

  ENDIF  dovert


!-----------------------------------------------------------------
!  Tendencies:

    IF(axisymm.eq.0)THEN

      IF( cm1setup.eq.4 )THEN
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k,rru0)
        do k=1,nk
        do j=1,nj
        do i=1,ni+1
          if( 0.5*(cm0(i-1,j)+cm0(i,j)) .le. cmemin )then
            ! zero-out turb tendencies outside of LES domain:
            turbx(i,j,k) = 0.0
            turby(i,j,k) = 0.0
            turbz(i,j,k) = 0.0
          endif
          rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
          uten(i,j,k)=uten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))*rru0
        enddo
        enddo
        enddo
      ELSE
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k,rru0)
        do k=1,nk
        do j=1,nj
        do i=1,ni+1
          rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
          uten(i,j,k)=uten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))*rru0
        enddo
        enddo
        enddo
      ENDIF

    ELSE

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k,rru0)
      do k=1,nk
      do j=1,nj
      do i=2,ni+1
        rru0 = 1.0/(0.5*(arf1(i)*rho(i-1,j,k)+arf2(i)*rho(i,j,k)))
        uten(i,j,k)=uten(i,j,k)+(turbx(i,j,k)+turbz(i,j,k))*rru0
      enddo
      enddo
      enddo

    ENDIF

!---------------------------------------------------------------------
!  Diagnostics:

      IF( doubud )THEN
      if( ud_hturb.ge.1 .and. ud_vturb.ge.1 )then
        if( axisymm.eq.0 )then
          !$omp parallel do default(shared)   &
          !$omp private(i,j,k,rru0)
          do k=1,nk
          do j=1,nj
          do i=1,ni+1
            rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
            udiag(i,j,k,ud_hturb) = (turbx(i,j,k)+turby(i,j,k))*rru0
            udiag(i,j,k,ud_vturb) = turbz(i,j,k)*rru0
          enddo
          enddo
          enddo
        else
          !$omp parallel do default(shared)   &
          !$omp private(i,j,k,rru0)
          do k=1,nk
          do j=1,nj
          do i=2,ni+1
            rru0 = 1.0/(0.5*(arf1(i)*rho(i-1,j,k)+arf2(i)*rho(i,j,k)))
            udiag(i,j,k,ud_hturb) = turbx(i,j,k)*rru0
            udiag(i,j,k,ud_vturb) = turbz(i,j,k)*rru0
          enddo
          enddo
          enddo
        endif
      endif
      ENDIF

!-------------------------------------------------------------------
!  All done

      if(timestats.ge.1) time_ttend=time_ttend+mytime()

      return
      end subroutine turbu


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbuz(dt,xh,ruh,xf,rxf,arf1,arf2,uf,vh,mh,mf,rmf,rho,rf,  &
                       zs,gz,rgz,gzu,gzv,rds,sigma,rdsf,sigmaf,gxu,     &
                       turbz,dum1,dum2,dum3,dum7,dum9,u ,w ,t11,t12,t13,t22,kmv, &
                       kmw,ufw,u1b,u2pt,ufwk)
      use input
      use constants
      implicit none

      real, intent(in) :: dt
      real, intent(in), dimension(ib:ie) :: xh,ruh
      real, intent(in), dimension(ib:ie+1) :: xf,rxf,arf1,arf2,uf
      real, intent(in), dimension(jb:je) :: vh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf,rmf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rf
      real, intent(in), dimension(ib:ie,jb:je) :: zs
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,gzv
      real, intent(in), dimension(kb:ke) :: rds,sigma
      real, intent(in), dimension(kb:ke+1) :: rdsf,sigmaf
      real, intent(in), dimension(itb:ite,jtb:jte,ktb:kte) :: gxu
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: turbz,dum1,dum2,dum3,dum7,dum9
      real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: u
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: w
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: t11,t12,t13,t22
      real, intent(in), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmv
      real, intent(in), dimension(kb:ke) :: kmw,ufw,u1b
      real, intent(inout), dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: u2pt
      real, intent(in),    dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: ufwk

      integer :: i,j,k,i1,i2
      real :: rdt,tema,temb,temc
      real :: tem,r1,r2,rru0
      real :: cfa,cfb,cfc,cfd

  ifimplu:  &
  IF( doimpl.eq.0 )THEN
      ! explicit vertical turbulence:

      tem = rdz*0.5

      i1 = 1
      i2 = ni+1

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni+1
        turbz(i,j,k)=(t13(i,j,k+1)-t13(i,j,k))*tem*(mh(i-1,j,k)+mh(i,j,k))
      enddo
      enddo
      enddo

  ELSE

      ! implicit vertical turbulence:

    check_grid:  &
    IF(axisymm.eq.0)THEN
      ! Cartesian grid:

      rdt = 0.5/dt
      tema = -0.0625*dt*vialpha*rdz*rdz
      temb =  0.0625*dt*vibeta*rdz*rdz
      temc =  0.5*dt*rdz

      i1 = 1
      i2 = ni+1

      IF( .not. terrain_flag )THEN
        ! without terrain:

        !--------
        k = 1
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
          tem = (mh(i-1,j,k)+mh(i,j,k))*rru0
          r2 = (kmv(i-1,j,k+1)+kmv(i,j,k+1))*(mf(i-1,j,k+1)+mf(i,j,k+1))   &
              *(rf(i-1,j,k+1)+rf(i,j,k+1))*tem
          cfc = tema*r2
          cfb = 1.0 - cfc
          cfd = u(i,j,k) + temb*( r2*u(i,j,k+1)-r2*u(i,j,k) )  &
                         - temc*t13(i,j,1)*(mh(i-1,j,1)+mh(i,j,1))*rru0
          tem = 1.0/cfb
          dum1(i,j,1)=-cfc*tem
          dum2(i,j,1)= cfd*tem
          dum7(i,j,1) = 0.0
        enddo
        enddo
        !--------
        do k=2,nk-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
          tem = (mh(i-1,j,k)+mh(i,j,k))*rru0
          r1 = (kmv(i-1,j,k  )+kmv(i,j,k  ))*(mf(i-1,j,k  )+mf(i,j,k  ))   &
              *(rf(i-1,j,k  )+rf(i,j,k  ))*tem
          r2 = (kmv(i-1,j,k+1)+kmv(i,j,k+1))*(mf(i-1,j,k+1)+mf(i,j,k+1))   &
              *(rf(i-1,j,k+1)+rf(i,j,k+1))*tem
          cfa = tema*r1
          cfc = tema*r2
          cfb = 1.0 - cfa - cfc
          cfd = u(i,j,k) + temb*( r2*u(i,j,k+1)-(r1+r2)*u(i,j,k)+r1*u(i,j,k-1) )
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum1(i,j,k)=-cfc*tem
          dum2(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          ! explicit piece ... dwdx term
          dum7(i,j,k)=(w(i,j,k)-w(i-1,j,k))*rdx*uf(i)   &
                     *0.25*( kmv(i-1,j,k)+kmv(i,j,k) )  &
                          *( rf(i-1,j,k)+rf(i,j,k) )
        enddo
        enddo

        enddo
        !--------
        k = nk
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
          tem = (mh(i-1,j,k)+mh(i,j,k))*rru0
          r1 = (kmv(i-1,j,k  )+kmv(i,j,k  ))*(mf(i-1,j,k  )+mf(i,j,k  ))   &
              *(rf(i-1,j,k  )+rf(i,j,k  ))*tem
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = u(i,j,k) + temb*( -r1*u(i,j,k)+r1*u(i,j,k-1) )  &
                         + temc*t13(i,j,nk+1)*(mh(i-1,j,nk)+mh(i,j,nk))*rru0
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum3(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          turbz(i,j,k) = (rho(i-1,j,k)+rho(i,j,k))*(dum3(i,j,k)-u(i,j,k))*rdt
          ! explicit piece ... dwdx term
          dum7(i,j,k)=(w(i,j,k)-w(i-1,j,k))*rdx*uf(i)   &
                     *0.25*( kmv(i-1,j,k)+kmv(i,j,k) )  &
                          *( rf(i-1,j,k)+rf(i,j,k) )
          turbz(i,j,k)=turbz(i,j,k)+(0.0-dum7(i,j,k))*rdz*0.5*(mh(i-1,j,k)+mh(i,j,k))
        enddo
        enddo
        !--------

        do k=nk-1,1,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=1,nj
        do i=i1,i2
          dum3(i,j,k)=dum1(i,j,k)*dum3(i,j,k+1)+dum2(i,j,k)
          turbz(i,j,k) = (rho(i-1,j,k)+rho(i,j,k))*(dum3(i,j,k)-u(i,j,k))*rdt
          ! explicit piece ... dwdx term
          turbz(i,j,k)=turbz(i,j,k)+(dum7(i,j,k+1)-dum7(i,j,k))*rdz*0.5*(mh(i-1,j,k)+mh(i,j,k))
        enddo
        enddo

        enddo

      ELSE
        ! with terrain:

        ! dum9 stores w at scalar-pts:

        !$omp parallel do default(shared)   &
        !$omp private(i,j,k)
        DO k=1,nk
        do j=0,nj+1
        do i=0,ni+1
          dum9(i,j,k)=0.5*(w(i,j,k)+w(i,j,k+1))
        enddo
        enddo
        ENDDO

        !--------
        k = 1
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
          tem = (mh(i-1,j,k)+mh(i,j,k))*rru0
          r2 = (kmv(i-1,j,k+1)+kmv(i,j,k+1))*(mf(i-1,j,k+1)+mf(i,j,k+1))   &
              *(rf(i-1,j,k+1)+rf(i,j,k+1))*tem
          cfc = tema*r2
          cfb = 1.0 - cfc
          cfd = u(i,j,k) + temb*( r2*u(i,j,k+1)-r2*u(i,j,k) )  &
                         - temc*t13(i,j,1)*(mh(i-1,j,1)+mh(i,j,1))*rru0
          tem = 1.0/cfb
          dum1(i,j,1)=-cfc*tem
          dum2(i,j,1)= cfd*tem
          dum7(i,j,1) = 0.0
        enddo
        enddo
        !--------
        do k=2,nk-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
          tem = (mh(i-1,j,k)+mh(i,j,k))*rru0
          r1 = (kmv(i-1,j,k  )+kmv(i,j,k  ))*(mf(i-1,j,k  )+mf(i,j,k  ))   &
              *(rf(i-1,j,k  )+rf(i,j,k  ))*tem
          r2 = (kmv(i-1,j,k+1)+kmv(i,j,k+1))*(mf(i-1,j,k+1)+mf(i,j,k+1))   &
              *(rf(i-1,j,k+1)+rf(i,j,k+1))*tem
          cfa = tema*r1
          cfc = tema*r2
          cfb = 1.0 - cfa - cfc
          cfd = u(i,j,k) + temb*( r2*u(i,j,k+1)-(r1+r2)*u(i,j,k)+r1*u(i,j,k-1) )
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum1(i,j,k)=-cfc*tem
          dum2(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          ! explicit piece ... dwdx term
          dum7(i,j,k)=(w(i,j,k)*rgz(i,j)-w(i-1,j,k)*rgz(i-1,j))*rdx*uf(i)          &
                  +0.5*rds(k)*( (zt-sigma(k  ))*(dum9(i,j,k  )+dum9(i-1,j,k  ))    &
                               -(zt-sigma(k-1))*(dum9(i,j,k-1)+dum9(i-1,j,k-1)) )  &
                             *(rgz(i,j)-rgz(i-1,j))*rdx*uf(i)
          dum7(i,j,k)=dum7(i,j,k)*0.25*( kmv(i-1,j,k)+kmv(i,j,k) )                 &
                                      *( gz(i-1,j)*rf(i-1,j,k)+gz(i,j)*rf(i,j,k) )
        enddo
        enddo

        enddo
        !--------
        k = nk
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
          tem = (mh(i-1,j,k)+mh(i,j,k))*rru0
          r1 = (kmv(i-1,j,k  )+kmv(i,j,k  ))*(mf(i-1,j,k  )+mf(i,j,k  ))   &
              *(rf(i-1,j,k  )+rf(i,j,k  ))*tem
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = u(i,j,k) + temb*( -r1*u(i,j,k)+r1*u(i,j,k-1) )  &
                         + temc*t13(i,j,nk+1)*(mh(i-1,j,nk)+mh(i,j,nk))*rru0
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum3(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          turbz(i,j,k) = (rho(i-1,j,k)+rho(i,j,k))*(dum3(i,j,k)-u(i,j,k))*rdt
          ! explicit piece ... dwdx term
          dum7(i,j,k)=(w(i,j,k)*rgz(i,j)-w(i-1,j,k)*rgz(i-1,j))*rdx*uf(i)          &
                  +0.5*rds(k)*( (zt-sigma(k  ))*(dum9(i,j,k  )+dum9(i-1,j,k  ))    &
                               -(zt-sigma(k-1))*(dum9(i,j,k-1)+dum9(i-1,j,k-1)) )  &
                             *(rgz(i,j)-rgz(i-1,j))*rdx*uf(i)
          dum7(i,j,k)=dum7(i,j,k)*0.25*( kmv(i-1,j,k)+kmv(i,j,k) )                 &
                                      *( gz(i-1,j)*rf(i-1,j,k)+gz(i,j)*rf(i,j,k) )
          turbz(i,j,k)=turbz(i,j,k)+(0.0-dum7(i,j,k))*rdz*0.5*(mh(i-1,j,k)+mh(i,j,k))
        enddo
        enddo
        !--------

        do k=nk-1,1,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=1,nj
        do i=i1,i2
          dum3(i,j,k)=dum1(i,j,k)*dum3(i,j,k+1)+dum2(i,j,k)
          turbz(i,j,k) = (rho(i-1,j,k)+rho(i,j,k))*(dum3(i,j,k)-u(i,j,k))*rdt
          ! explicit piece ... dwdx term
          turbz(i,j,k)=turbz(i,j,k)+(dum7(i,j,k+1)-dum7(i,j,k))*rdz*0.5*(mh(i-1,j,k)+mh(i,j,k))
        enddo
        enddo

        enddo

      ENDIF

      !------------------------------------------------------------
      !------------------------------------------------------------
      !------------------------------------------------------------

    ELSEIF(axisymm.eq.1)THEN
      ! axisymmetric grid:

      rdt = 0.5/dt
      tema = -0.25*dt*vialpha*rdz*rdz
      temb =  0.25*dt*vibeta*rdz*rdz
      temc =  dt*rdz

      i1 = 2
      i2 = ni+1

        !--------
        k = 1
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(arf1(i)*rho(i-1,j,k)+arf2(i)*rho(i,j,k)))
          tem = mh(1,1,k)*rru0
          r2 = (kmv(i-1,j,k+1)+kmv(i,j,k+1))*mf(1,1,k+1)   &
              *(arf1(i)*rf(i-1,j,k+1)+arf2(i)*rf(i,j,k+1))*tem
          cfc = tema*r2
          cfb = 1.0 - cfc
          cfd = u(i,j,k) + temb*( r2*u(i,j,k+1)-r2*u(i,j,k) )  &
                         - temc*t13(i,j,1)*mh(1,1,1)*rru0
          tem = 1.0/cfb
          dum1(i,j,1)=-cfc*tem
          dum2(i,j,1)= cfd*tem
          dum7(i,j,1) = 0.0
        enddo
        enddo
        !--------
        do k=2,nk-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(arf1(i)*rho(i-1,j,k)+arf2(i)*rho(i,j,k)))
          tem = mh(1,1,k)*rru0
          r1 = (kmv(i-1,j,k  )+kmv(i,j,k  ))*mf(1,1,k  )   &
              *(arf1(i)*rf(i-1,j,k  )+arf2(i)*rf(i,j,k  ))*tem
          r2 = (kmv(i-1,j,k+1)+kmv(i,j,k+1))*mf(1,1,k+1)   &
              *(arf1(i)*rf(i-1,j,k+1)+arf2(i)*rf(i,j,k+1))*tem
          cfa = tema*r1
          cfc = tema*r2
          cfb = 1.0 - cfa - cfc
          cfd = u(i,j,k) + temb*( r2*u(i,j,k+1)-(r1+r2)*u(i,j,k)+r1*u(i,j,k-1) )
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum1(i,j,k)=-cfc*tem
          dum2(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          ! explicit piece ... dwdx term
          dum7(i,j,k)=(w(i,j,k)-w(i-1,j,k))*rdx*uf(i)
          dum7(i,j,k)=dum7(i,j,k)*0.25*( arf1(i)*kmv(i-1,j,k)+arf2(i)*kmv(i,j,k) )  &
                                      *(arf1(i)*rf(i-1,j,k)+arf2(i)*rf(i,j,k))
        enddo
        enddo

        enddo
        !--------
        k = nk
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rru0)
        do j=1,nj
        do i=i1,i2
          rru0 = 1.0/(0.5*(arf1(i)*rho(i-1,j,k)+arf2(i)*rho(i,j,k)))
          tem = mh(1,1,k)*rru0
          r1 = (kmv(i-1,j,k  )+kmv(i,j,k  ))*mf(1,1,k  )   &
              *(arf1(i)*rf(i-1,j,k  )+arf2(i)*rf(i,j,k  ))*tem
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = u(i,j,k) + temb*( -r1*u(i,j,k)+r1*u(i,j,k-1) )  &
                         + temc*t13(i,j,nk+1)*mh(1,1,nk)*rru0
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum3(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          turbz(i,j,k) = (arf1(i)*rho(i-1,j,k)+arf2(i)*rho(i,j,k))*(dum3(i,j,k)-u(i,j,k))*rdt
          ! explicit piece ... dwdx term
          dum7(i,j,k)=(w(i,j,k)-w(i-1,j,k))*rdx*uf(i)
          dum7(i,j,k)=dum7(i,j,k)*0.25*( arf1(i)*kmv(i-1,j,k)+arf2(i)*kmv(i,j,k) )  &
                                      *(arf1(i)*rf(i-1,j,k)+arf2(i)*rf(i,j,k))
          turbz(i,j,k)=turbz(i,j,k)+(0.0-dum7(i,j,k))*rdz*0.5*(mh(i-1,j,k)+mh(i,j,k))
        enddo
        enddo
        !--------

        do k=nk-1,1,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=1,nj
        do i=i1,i2
          dum3(i,j,k)=dum1(i,j,k)*dum3(i,j,k+1)+dum2(i,j,k)
          turbz(i,j,k) = (arf1(i)*rho(i-1,j,k)+arf2(i)*rho(i,j,k))*(dum3(i,j,k)-u(i,j,k))*rdt
          ! explicit piece ... dwdx term
          turbz(i,j,k)=turbz(i,j,k)+(dum7(i,j,k+1)-dum7(i,j,k))*rdz*0.5*(mh(i-1,j,k)+mh(i,j,k))
        enddo
        enddo

        enddo

    ENDIF  check_grid

    !------------------------------------------------------------


  ENDIF  ifimplu

      IF(axisymm.eq.1)THEN
        !$omp parallel do default(shared)   &
        !$omp private(k)
        DO k=1,nk
          turbz(1,1,k) = 0.0
        ENDDO
        IF( ebc.eq.3 .or. ebc.eq.4 )THEN
          !$omp parallel do default(shared)   &
          !$omp private(k)
          do k=1,nk
            turbz(ni+1,1,k)=0.0
          enddo
        ENDIF
      ENDIF

!-----------------------------------------------------------------
!  2nd part of 2-part model:

      IF( dot2p )THEN

        do k=2,ntwk
!!!          tem = 0.5*rdz*mf(1,1,k)
          do j=1,nj
          do i=i1,i2
!!!            dum2(i,j,k) = tem*kmw(k)*(u1b(k)-u1b(k-1))*(rf(i-1,j,k)+rf(i,j,k))
!!!            dum2(i,j,k) = ufw(k)*0.5*(rf(i-1,j,k)+rf(i,j,k))
            dum2(i,j,k) = 0.5*(rf(i-1,j,k)*ufwk(i-1,j,k)+rf(i,j,k)*ufwk(i,j,k))
          enddo
          enddo
        enddo

        do j=1,nj
        do i=i1,i2
          dum2(i,j,1) = 0.0
          dum2(i,j,ntwk+1) = 0.0
        enddo
        enddo

        do k=1,ntwk
          tem = rdz*mh(1,1,k)
          do j=1,nj
          do i=i1,i2
            turbz(i,j,k) = turbz(i,j,k)+tem*(dum2(i,j,k+1)-dum2(i,j,k))
            ! 211207: save 2-pt tendency
            rru0 = 1.0/(0.5*(rho(i-1,j,k)+rho(i,j,k)))
            u2pt(i,j,k)=tem*(dum2(i,j,k+1)-dum2(i,j,k))*rru0
          enddo
          enddo
        enddo

      ENDIF

!-----------------------------------------------------------------

      return
      end subroutine turbuz


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbv(dt,xh,rxh,arh1,arh2,uh,xf,rvh,vf,mh,mf,rho,rr,rf,   &
                       zs,gz,rgz,gzu,gzv,rds,sigma,rdsf,sigmaf,gyv,  &
                       turbx,turby,turbz,dum1,dum2,dum3,dum7,dum8,dum9,v,vten,w,t12,t22,t23,kmv,cm0, &
                       kmw,vfw,v1b,v2pt,vfwk,dovbud,vdiag)
      use input
      use constants
      implicit none

      real, intent(in) :: dt
      real, intent(in), dimension(ib:ie) :: xh,rxh,arh1,arh2,uh
      real, intent(in), dimension(ib:ie+1) :: xf
      real, intent(in), dimension(jb:je) :: rvh
      real, intent(in), dimension(jb:je+1) :: vf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rr,rf
      real, intent(in), dimension(ib:ie,jb:je) :: zs
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,gzv
      real, intent(in), dimension(kb:ke) :: rds,sigma
      real, intent(in), dimension(kb:ke+1) :: rdsf,sigmaf
      real, intent(in), dimension(itb:ite,jtb:jte,ktb:kte) :: gyv
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: turbx,turby,turbz,dum1,dum2,dum3,dum7,dum8,dum9
      real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: v
      real, intent(inout), dimension(ib:ie,jb:je+1,kb:ke) :: vten
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: w
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: t12,t22,t23
      real, intent(in), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmv
      real, intent(in), dimension(ib:ie,jb:je) :: cm0
      real, intent(in), dimension(kb:ke) :: kmw,vfw,v1b
      real, intent(inout), dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: v2pt
      real, intent(in),    dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: vfwk
      logical, intent(in) :: dovbud
      real, intent(inout) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nvdiag) :: vdiag
 
      integer :: i,j,k,j1,j2
      real :: rdt,tema,temb,temc
      real :: tem,r1,r2,rrv0
      real :: cfa,cfb,cfc,cfd

!---------------------------------------------------------------

  dohoriz:  &
  IF( dohturb )THEN

  IF(.not.terrain_flag)THEN

    IF(axisymm.eq.0)THEN

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk

        !  x-direction
        !  y-direction
        do j=1,nj+1
        do i=1,ni
          turbx(i,j,k)=(t12(i+1,j,k)-t12(i,j,k))*rdx*uh(i)
          turby(i,j,k)=(t22(i,j,k)-t22(i,j-1,k))*rdy*vf(j)
        enddo
        enddo

      enddo

    ELSE

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk

        do j=1,nj
        do i=1,ni
          turbx(i,j,k)=(arh2(i)*arh2(i)*t12(i+1,j,k)-arh1(i)*arh1(i)*t12(i,j,k))*rdx*uh(i)
        enddo
        enddo

        do j=1,nj
        do i=1,ni
          turby(i,j,k)=0.0
        enddo
        enddo

      enddo

    ENDIF

!---------------------------------------------------------------
!  Terrain:

  ELSE

      ! dum1 stores t12 at w-pts:
      ! dum2 stores t22 at w-pts:
!$omp parallel do default(shared)   &
!$omp private(i,j,k,r1,r2)
      do j=0,nj+1

          ! lowest model level:
          do i=1,ni+1
            dum1(i,j,1) = cgs1*t12(i,j,1)+cgs2*t12(i,j,2)+cgs3*t12(i,j,3)
            dum2(i,j,1) = cgs1*t22(i,j,1)+cgs2*t22(i,j,2)+cgs3*t22(i,j,3)
          enddo

          ! upper-most model level:
          do i=1,ni+1
            dum1(i,j,nk+1) = cgt1*t12(i,j,nk)+cgt2*t12(i,j,nk-1)+cgt3*t12(i,j,nk-2)
            dum2(i,j,nk+1) = cgt1*t22(i,j,nk)+cgt2*t22(i,j,nk-1)+cgt3*t22(i,j,nk-2)
          enddo

          ! interior:
          do k=2,nk
          r2 = (sigmaf(k)-sigma(k-1))*rds(k)
          r1 = 1.0-r2
          do i=1,ni+1
            dum1(i,j,k) = r1*t12(i,j,k-1)+r2*t12(i,j,k)
            dum2(i,j,k) = r1*t22(i,j,k-1)+r2*t22(i,j,k)
          enddo
          enddo

      enddo

!$omp parallel do default(shared)   &
!$omp private(i,j,k,r1,r2)
      do k=1,nk

        !  x-direction
        do j=1,nj+1
        do i=1,ni
          r1 = 0.25*((rgz(i-1,j-1)+rgz(i,j))+(rgz(i-1,j)+rgz(i,j-1)))
          r2 = 0.25*((rgz(i+1,j-1)+rgz(i,j))+(rgz(i+1,j)+rgz(i,j-1)))
          turbx(i,j,k)=gzv(i,j)*(t12(i+1,j,k)*r2-t12(i,j,k)*r1)*rdx*uh(i)      &
                      +0.5*( (zt-sigmaf(k+1))*(dum1(i,j,k+1)+dum1(i+1,j,k+1))  &
                            -(zt-sigmaf(k  ))*(dum1(i,j,k  )+dum1(i+1,j,k  ))  &
                           )*gzv(i,j)*(r2-r1)*rdx*uh(i)*rdsf(k)
        enddo
        enddo

        !  y-direction
        do j=1,nj+1
        do i=1,ni
          turby(i,j,k)=gzv(i,j)*(t22(i,j,k)*rgz(i,j)-t22(i,j-1,k)*rgz(i,j-1))*rdy*vf(j)  &
                      +0.5*( gyv(i,j,k+1)*(dum2(i,j-1,k+1)+dum2(i,j,k+1))                &
                            -gyv(i,j,k  )*(dum2(i,j-1,k  )+dum2(i,j,k  )) )*rdsf(k)
        enddo
        enddo

      enddo

  ENDIF  ! endif for terrain check

!-----------------------------------------------------------------
!  open boundary conditions:

    IF( wbc.eq.2 .or. ebc.eq.2 .or. sbc.eq.2 .or. nbc.eq.2 )THEN
!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      DO k=1,nk

        IF( wbc.eq.2 .and. ibw.eq.1 )THEN
          do j=1,nj+1
            turbx(1,j,k) = 0.0
          enddo
        ENDIF
        IF( ebc.eq.2 .and. ibe.eq.1 )THEN
          do j=1,nj+1
            turbx(ni,j,k) = 0.0
          enddo
        ENDIF

        IF( sbc.eq.2 .and. ibs.eq.1 )THEN
          do i=1,ni
            turby(i,1,k) = 0.0
          enddo
        ENDIF
        IF( nbc.eq.2 .and. ibn.eq.1 )THEN
          do i=1,ni
            turby(i,nj+1,k) = 0.0
          enddo
        ENDIF

      ENDDO
    ENDIF

  ELSE  dohoriz

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj+1
      do i=1,ni
        turbx(i,j,k)=0.0
        turby(i,j,k)=0.0
      enddo
      enddo
      enddo

  ENDIF  dohoriz

!-----------------------------------------------------------------
!  z-direction

  dovert:  &
  IF( dovturb )THEN

      call       turbvz(dt,xh,rxh,arh1,arh2,uh,xf,rvh,vf,mh,mf,rho,rr,rf,   &
                       zs,gz,rgz,gzu,gzv,rds,sigma,rdsf,sigmaf,gyv,  &
                       turbz,dum1,dum2,dum3,dum7,dum9,v ,w ,t12,t22,t23,kmv, &
                       kmw,vfw,v1b,v2pt,vfwk)

  ELSE  dovert

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj+1
      do i=1,ni
        turbz(i,j,k)=0.0
      enddo
      enddo
      enddo

  ENDIF  dovert


!-----------------------------------------------------------------
!  Tendencies:

    IF(axisymm.eq.0)THEN

      IF( cm1setup.eq.4 )THEN
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k,rrv0)
        do k=1,nk
        do j=1,nj+1
        do i=1,ni
          if( 0.5*(cm0(i,j-1)+cm0(i,j)) .le. cmemin )then
            ! zero-out turb tendencies outside of LES domain:
            turbx(i,j,k) = 0.0
            turby(i,j,k) = 0.0
            turbz(i,j,k) = 0.0
          endif
          rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
          vten(i,j,k)=vten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))*rrv0
        enddo
        enddo
        enddo
      ELSE
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k,rrv0)
        do k=1,nk
        do j=1,nj+1
        do i=1,ni
          rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
          vten(i,j,k)=vten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))*rrv0
        enddo
        enddo
        enddo
      ENDIF

    ELSE

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=1,nk
      do j=1,nj
      do i=1,ni
        vten(i,j,k)=vten(i,j,k)+(turbx(i,j,k)+turbz(i,j,k))*rr(i,j,k)
      enddo
      enddo
      enddo

    ENDIF

!---------------------------------------------------------------------
!  Diagnostics:

      IF( dovbud )THEN
      if( vd_hturb.ge.1 .and. vd_vturb.ge.1 )then
        if( axisymm.eq.0 )then
          !$omp parallel do default(shared)   &
          !$omp private(i,j,k,rrv0)
          do k=1,nk
          do j=1,nj+1
          do i=1,ni
            rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
            vdiag(i,j,k,vd_hturb) = (turbx(i,j,k)+turby(i,j,k))*rrv0
            vdiag(i,j,k,vd_vturb) = turbz(i,j,k)*rrv0
          enddo
          enddo
          enddo
        else
          !$omp parallel do default(shared)   &
          !$omp private(i,j,k)
          do k=1,nk
          do j=1,nj
          do i=1,ni
            vdiag(i,j,k,vd_hturb) = turbx(i,j,k)*rr(i,j,k)
            vdiag(i,j,k,vd_vturb) = turbz(i,j,k)*rr(i,j,k)
            vdiag(i,2,k,vd_hturb) = vdiag(i,1,k,vd_hturb)
            vdiag(i,2,k,vd_vturb) = vdiag(i,1,k,vd_vturb)
          enddo
          enddo
          enddo
        endif
      endif
      ENDIF

!-------------------------------------------------------------------
!  All done
 
      if(timestats.ge.1) time_ttend=time_ttend+mytime()
 
      return
      end subroutine turbv


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbvz(dt,xh,rxh,arh1,arh2,uh,xf,rvh,vf,mh,mf,rho,rr,rf,   &
                       zs,gz,rgz,gzu,gzv,rds,sigma,rdsf,sigmaf,gyv,  &
                       turbz,dum1,dum2,dum3,dum7,dum9,v ,w ,t12,t22,t23,kmv, &
                       kmw,vfw,v1b,v2pt,vfwk)
      use input
      use constants
      implicit none

      real, intent(in) :: dt
      real, intent(in), dimension(ib:ie) :: xh,rxh,arh1,arh2,uh
      real, intent(in), dimension(ib:ie+1) :: xf
      real, intent(in), dimension(jb:je) :: rvh
      real, intent(in), dimension(jb:je+1) :: vf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rr,rf
      real, intent(in), dimension(ib:ie,jb:je) :: zs
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,gzv
      real, intent(in), dimension(kb:ke) :: rds,sigma
      real, intent(in), dimension(kb:ke+1) :: rdsf,sigmaf
      real, intent(in), dimension(itb:ite,jtb:jte,ktb:kte) :: gyv
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: turbz,dum1,dum2,dum3,dum7,dum9
      real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: v
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: w
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: t12,t22,t23
      real, intent(in), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmv
      real, intent(in), dimension(kb:ke) :: kmw,vfw,v1b
      real, intent(inout), dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: v2pt
      real, intent(in),    dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: vfwk
 
      integer :: i,j,k,j1,j2
      real :: rdt,tema,temb,temc
      real :: tem,r1,r2,rrv0
      real :: cfa,cfb,cfc,cfd

  ifimplv:  &
  IF( doimpl.eq.0 )THEN
      ! explicit vertical turbulence:

      tem = rdz*0.5

      j1 = 1
      j2 = nj+1

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk
      do j=1,nj+1
      do i=1,ni
        turbz(i,j,k)=(t23(i,j,k+1)-t23(i,j,k))*tem*(mh(i,j-1,k)+mh(i,j,k))
      enddo
      enddo
      enddo

  ELSE

      ! implicit vertical turbulence:

      IF( .not. terrain_flag )THEN

        ! without terrain:

        rdt = 0.5/dt
        tema = -0.0625*dt*vialpha*rdz*rdz
        temb =  0.0625*dt*vibeta*rdz*rdz
        temc =  0.5*dt*rdz

        if( axisymm.eq.1 )then
          j1 = 1
          j2 = 1
        else
          j1 = 1
          j2 = nj+1
        endif

        !--------
        k = 1
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrv0)
        do j=j1,j2
        do i=1,ni
          rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
          tem = (mh(i,j-1,k)+mh(i,j,k))*rrv0
          r2 = (kmv(i,j-1,k+1)+kmv(i,j,k+1))*(mf(i,j-1,k+1)+mf(i,j,k+1))   &
              *(rf(i,j-1,k+1)+rf(i,j,k+1))*tem
          cfc = tema*r2
          cfb = 1.0 - cfc
          cfd = v(i,j,k) + temb*( r2*v(i,j,k+1)-r2*v(i,j,k) )  &
                         - temc*t23(i,j,1)*(mh(i,j-1,1)+mh(i,j,1))*rrv0
          tem = 1.0/cfb
          dum1(i,j,1)=-cfc*tem
          dum2(i,j,1)= cfd*tem
          dum7(i,j,1) = 0.0
        enddo
        enddo
        !--------
        do k=2,nk-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrv0)
        do j=j1,j2
        do i=1,ni
          rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
          tem = (mh(i,j-1,k)+mh(i,j,k))*rrv0
          r1 = (kmv(i,j-1,k  )+kmv(i,j,k  ))*(mf(i,j-1,k  )+mf(i,j,k  ))   &
              *(rf(i,j-1,k  )+rf(i,j,k  ))*tem
          r2 = (kmv(i,j-1,k+1)+kmv(i,j,k+1))*(mf(i,j-1,k+1)+mf(i,j,k+1))   &
              *(rf(i,j-1,k+1)+rf(i,j,k+1))*tem
          cfa = tema*r1
          cfc = tema*r2
          cfb = 1.0 - cfa - cfc
          cfd = v(i,j,k) + temb*( r2*v(i,j,k+1)-(r1+r2)*v(i,j,k)+r1*v(i,j,k-1) )
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum1(i,j,k)=-cfc*tem
          dum2(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          ! explicit piece ... dwdy term
          dum7(i,j,k)=(w(i,j,k)-w(i,j-1,k))*rdy*vf(j)   &
                     *0.25*( kmv(i,j-1,k)+kmv(i,j,k) )  &
                          *( rf(i,j-1,k)+rf(i,j,k) )
        enddo
        enddo

        enddo
        !--------
        k = nk
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrv0)
        do j=j1,j2
        do i=1,ni
          rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
          tem = (mh(i,j-1,k)+mh(i,j,k))*rrv0
          r1 = (kmv(i,j-1,k  )+kmv(i,j,k  ))*(mf(i,j-1,k  )+mf(i,j,k  ))   &
              *(rf(i,j-1,k  )+rf(i,j,k  ))*tem
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = v(i,j,k) + temb*( -r1*v(i,j,k)+r1*v(i,j,k-1) )  &
                         + temc*t23(i,j,nk+1)*(mh(i,j-1,nk)+mh(i,j,nk))*rrv0
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum3(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          turbz(i,j,k) = (rho(i,j-1,k)+rho(i,j,k))*(dum3(i,j,k)-v(i,j,k))*rdt
          ! explicit piece ... dwdy term
          dum7(i,j,k)=(w(i,j,k)-w(i,j-1,k))*rdy*vf(j)   &
                     *0.25*( kmv(i,j-1,k)+kmv(i,j,k) )  &
                          *( rf(i,j-1,k)+rf(i,j,k) )
          turbz(i,j,k)=turbz(i,j,k)+(0.0-dum7(i,j,k))*rdz*0.5*(mh(i,j-1,k)+mh(i,j,k))
        enddo
        enddo
        !--------

        do k=nk-1,1,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=j1,j2
        do i=1,ni
          dum3(i,j,k)=dum1(i,j,k)*dum3(i,j,k+1)+dum2(i,j,k)
          turbz(i,j,k) = (rho(i,j-1,k)+rho(i,j,k))*(dum3(i,j,k)-v(i,j,k))*rdt
          ! explicit piece ... dwdy term
          turbz(i,j,k)=turbz(i,j,k)+(dum7(i,j,k+1)-dum7(i,j,k))*rdz*0.5*(mh(i,j-1,k)+mh(i,j,k))
        enddo
        enddo

        enddo

    !------------------------------------------------------------

      ELSE

        ! with terrain:

        ! dum9 stores w at scalar-pts:

        !$omp parallel do default(shared)   &
        !$omp private(i,j,k)
        DO k=1,nk
        do j=0,nj+1
        do i=0,ni+1
          dum9(i,j,k)=0.5*(w(i,j,k)+w(i,j,k+1))
        enddo
        enddo
        ENDDO

        rdt = 0.5/dt
        tema = -0.0625*dt*vialpha*rdz*rdz
        temb =  0.0625*dt*vibeta*rdz*rdz
        temc =  0.5*dt*rdz

        j1 = 1
        j2 = nj+1

        !--------
        k = 1
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrv0)
        do j=j1,j2
        do i=1,ni
          rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
          tem = (mh(i,j-1,k)+mh(i,j,k))*rrv0
          r2 = (kmv(i,j-1,k+1)+kmv(i,j,k+1))*(mf(i,j-1,k+1)+mf(i,j,k+1))   &
              *(rf(i,j-1,k+1)+rf(i,j,k+1))*tem
          cfc = tema*r2
          cfb = 1.0 - cfc
          cfd = v(i,j,k) + temb*( r2*v(i,j,k+1)-r2*v(i,j,k) )  &
                         - temc*t23(i,j,1)*(mh(i,j-1,1)+mh(i,j,1))*rrv0
          tem = 1.0/cfb
          dum1(i,j,1)=-cfc*tem
          dum2(i,j,1)= cfd*tem
          dum7(i,j,1) = 0.0
        enddo
        enddo
        !--------
        do k=2,nk-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrv0)
        do j=j1,j2
        do i=1,ni
          rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
          tem = (mh(i,j-1,k)+mh(i,j,k))*rrv0
          r1 = (kmv(i,j-1,k  )+kmv(i,j,k  ))*(mf(i,j-1,k  )+mf(i,j,k  ))   &
              *(rf(i,j-1,k  )+rf(i,j,k  ))*tem
          r2 = (kmv(i,j-1,k+1)+kmv(i,j,k+1))*(mf(i,j-1,k+1)+mf(i,j,k+1))   &
              *(rf(i,j-1,k+1)+rf(i,j,k+1))*tem
          cfa = tema*r1
          cfc = tema*r2
          cfb = 1.0 - cfa - cfc
          cfd = v(i,j,k) + temb*( r2*v(i,j,k+1)-(r1+r2)*v(i,j,k)+r1*v(i,j,k-1) )
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum1(i,j,k)=-cfc*tem
          dum2(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          dum7(i,j,k)=(w(i,j,k)*rgz(i,j)-w(i,j-1,k)*rgz(i,j-1))*rdy*vf(j)          &
                  +0.5*rds(k)*( (zt-sigma(k  ))*(dum9(i,j,k  )+dum9(i,j-1,k  ))    &
                               -(zt-sigma(k-1))*(dum9(i,j,k-1)+dum9(i,j-1,k-1)) )  &
                             *(rgz(i,j)-rgz(i,j-1))*rdy*vf(j)
          ! explicit piece ... dwdy term
          dum7(i,j,k)=dum7(i,j,k)*0.25*( kmv(i,j-1,k)+kmv(i,j,k) )                 &
                                      *( gz(i,j-1)*rf(i,j-1,k)+gz(i,j)*rf(i,j,k) )
        enddo
        enddo

        enddo
        !--------
        k = nk
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrv0)
        do j=j1,j2
        do i=1,ni
          rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
          tem = (mh(i,j-1,k)+mh(i,j,k))*rrv0
          r1 = (kmv(i,j-1,k  )+kmv(i,j,k  ))*(mf(i,j-1,k  )+mf(i,j,k  ))   &
              *(rf(i,j-1,k  )+rf(i,j,k  ))*tem
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = v(i,j,k) + temb*( -r1*v(i,j,k)+r1*v(i,j,k-1) )  &
                         + temc*t23(i,j,nk+1)*(mh(i,j-1,nk)+mh(i,j,nk))*rrv0
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum3(i,j,k)=(cfd-cfa*dum2(i,j,k-1))*tem
          turbz(i,j,k) = (rho(i,j-1,k)+rho(i,j,k))*(dum3(i,j,k)-v(i,j,k))*rdt
          ! explicit piece ... dwdy term
          dum7(i,j,k)=(w(i,j,k)*rgz(i,j)-w(i,j-1,k)*rgz(i,j-1))*rdy*vf(j)          &
                  +0.5*rds(k)*( (zt-sigma(k  ))*(dum9(i,j,k  )+dum9(i,j-1,k  ))    &
                               -(zt-sigma(k-1))*(dum9(i,j,k-1)+dum9(i,j-1,k-1)) )  &
                             *(rgz(i,j)-rgz(i,j-1))*rdy*vf(j)
          dum7(i,j,k)=dum7(i,j,k)*0.25*( kmv(i,j-1,k)+kmv(i,j,k) )                 &
                                      *( gz(i,j-1)*rf(i,j-1,k)+gz(i,j)*rf(i,j,k) )
          turbz(i,j,k)=turbz(i,j,k)+(0.0-dum7(i,j,k))*rdz*0.5*(mh(i,j-1,k)+mh(i,j,k))
        enddo
        enddo
        !--------

        do k=nk-1,1,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=j1,j2
        do i=1,ni
          dum3(i,j,k)=dum1(i,j,k)*dum3(i,j,k+1)+dum2(i,j,k)
          turbz(i,j,k) = (rho(i,j-1,k)+rho(i,j,k))*(dum3(i,j,k)-v(i,j,k))*rdt
          ! explicit piece ... dwdy term
          turbz(i,j,k)=turbz(i,j,k)+(dum7(i,j,k+1)-dum7(i,j,k))*rdz*0.5*(mh(i,j-1,k)+mh(i,j,k))
        enddo
        enddo

        enddo

      ENDIF

  ENDIF  ifimplv

!-----------------------------------------------------------------
!  2nd part of 2-part model:

      IF( dot2p )THEN

        do k=2,ntwk
!!!          tem = 0.5*rdz*mf(1,1,k)
          do j=j1,j2
          do i=1,ni
!!!            dum2(i,j,k) = tem*kmw(k)*(v1b(k)-v1b(k-1))*(rf(i,j-1,k)+rf(i,j,k))
!!!            dum2(i,j,k) = vfw(k)*0.5*(rf(i,j-1,k)+rf(i,j,k))
            dum2(i,j,k) = 0.5*(rf(i,j-1,k)*vfwk(i,j-1,k)+rf(i,j,k)*vfwk(i,j,k))
          enddo
          enddo
        enddo

        do j=j1,j2
        do i=1,ni
          dum2(i,j,1) = 0.0
          dum2(i,j,ntwk+1) = 0.0
        enddo
        enddo

        do k=1,ntwk
          tem = rdz*mh(1,1,k)
          do j=j1,j2
          do i=1,ni
            turbz(i,j,k) = turbz(i,j,k)+tem*(dum2(i,j,k+1)-dum2(i,j,k))
            ! 211207: save 2-pt tendency
            rrv0 = 1.0/(0.5*(rho(i,j-1,k)+rho(i,j,k)))
            v2pt(i,j,k)=tem*(dum2(i,j,k+1)-dum2(i,j,k))*rrv0
          enddo
          enddo
        enddo

      ENDIF

!-----------------------------------------------------------------

      return
      end subroutine turbvz


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC

 
      subroutine turbw(dt,xh,rxh,arh1,arh2,uh,xf,vh,mh,mf,rho,rf,gz,rgzu,rgzv,rds,sigma,   &
                       turbx,turby,turbz,dum1,dum2,dum3,w,wten,t13,t23,t33,t22,kmh,cm0,  &
                       dowbud,wdiag)
      use input
      use constants
      implicit none

      real, intent(in) :: dt
      real, intent(in), dimension(ib:ie) :: xh,rxh,arh1,arh2,uh
      real, intent(in), dimension(ib:ie+1) :: xf
      real, intent(in), dimension(jb:je) :: vh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: rho,rf
      real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgzu,rgzv
      real, intent(in), dimension(kb:ke) :: rds,sigma
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: turbx,turby,turbz,dum1,dum2,dum3
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: w
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: wten
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: t13,t23,t33,t22
      real, intent(in), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmh
      real, intent(in), dimension(ib:ie,jb:je) :: cm0
      logical, intent(in) :: dowbud
      real, intent(inout) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nwdiag) :: wdiag
 
      integer :: i,j,k
      real :: rdt,tema,temb,temc
      real :: tem,r1,r2,rrf
      real :: cfa,cfb,cfc,cfd

!----------------------------------------------------------------

  dohoriz:  &
  IF( dohturb )THEN

  IF(.not.terrain_flag)THEN

    IF(axisymm.eq.0)THEN
      ! Cartesian without terrain:

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=2,nk

        !  x-direction
        !  y-direction
        do j=1,nj
        do i=1,ni
          turbx(i,j,k)=(t13(i+1,j,k)-t13(i,j,k))*rdx*uh(i)
          turby(i,j,k)=(t23(i,j+1,k)-t23(i,j,k))*rdy*vh(j)
        enddo
        enddo

      enddo

    ELSE
      ! axisymmetric:

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=2,nk

        do j=1,nj
        do i=1,ni
          turbx(i,j,k)=(arh2(i)*t13(i+1,j,k)-arh1(i)*t13(i,j,k))*rdx*uh(i)
        enddo
        enddo

        !  y-direction
        do j=1,nj
        do i=1,ni
          turby(i,j,k)=0.0
        enddo
        enddo

      enddo

    ENDIF

!----------------------------------------------------------------

  ELSE
      ! Cartesian with terrain:

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = 0.25*( (t13(i,j,k+1)+t13(i+1,j,k+1)) &
                              +(t13(i,j,k  )+t13(i+1,j,k  )) )
        enddo
        enddo
        do j=1,nj
        do i=1,ni
          dum2(i,j,k) = 0.25*( (t23(i,j,k+1)+t23(i,j+1,k+1)) &
                              +(t23(i,j,k  )+t23(i,j+1,k  )) )
        enddo
        enddo
      enddo


!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=2,nk

        do j=1,nj
        do i=1,ni
          turbx(i,j,k)=gz(i,j)*( t13(i+1,j,k)*rgzu(i+1,j)             &
                                -t13(i  ,j,k)*rgzu(i  ,j) )*rdx*uh(i) &
              +( (zt-sigma(k  ))*dum1(i,j,k  )                        &
                -(zt-sigma(k-1))*dum1(i,j,k-1)                        &
               )*gz(i,j)*(rgzu(i+1,j)-rgzu(i,j))*rdx*uh(i)*rds(k)
        enddo
        enddo

        do j=1,nj
        do i=1,ni
          turby(i,j,k)=gz(i,j)*( t23(i,j+1,k)*rgzv(i,j+1)             &
                                -t23(i,j  ,k)*rgzv(i,j  ) )*rdy*vh(j) &
              +( (zt-sigma(k  ))*dum2(i,j,k  )                        &
                -(zt-sigma(k-1))*dum2(i,j,k-1)                        &
               )*gz(i,j)*(rgzv(i,j+1)-rgzv(i,j))*rdy*vh(j)*rds(k)
        enddo
        enddo

      enddo

  ENDIF  ! endif for terrain check

!-----------------------------------------------------------------
!  open boundary conditions:

    IF( wbc.eq.2 .or. ebc.eq.2 .or. sbc.eq.2 .or. nbc.eq.2 )THEN
!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      DO k=2,nk

        IF( wbc.eq.2 .and. ibw.eq.1 )THEN
          do j=1,nj
            turbx(1,j,k) = 0.0
          enddo
        ENDIF
        IF( ebc.eq.2 .and. ibe.eq.1 )THEN
          do j=1,nj
            turbx(ni,j,k) = 0.0
          enddo
        ENDIF

        IF( sbc.eq.2 .and. ibs.eq.1 )THEN
          do i=1,ni
            turby(i,1,k) = 0.0
          enddo
        ENDIF
        IF( nbc.eq.2 .and. ibn.eq.1 )THEN
          do i=1,ni
            turby(i,nj,k) = 0.0
          enddo
        ENDIF

      ENDDO
    ENDIF

  ELSE  dohoriz

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=2,nk
      do j=1,nj
      do i=1,ni
        turbx(i,j,k)=0.0
        turby(i,j,k)=0.0
      enddo
      enddo
      enddo

  ENDIF  dohoriz

!-----------------------------------------------------------------
!  z-direction

  dovert:  &
  IF( dovturb .or. ( cm1setup.eq.2 .and. ipbl.eq.2 ) )THEN

  ifimplw:  &
  IF( doimpl.eq.0 )THEN
      ! explicit vertical turbulence:

!$omp parallel do default(shared)   &
!$omp private(i,j,k)
      do k=2,nk
      do j=1,nj
      do i=1,ni
        turbz(i,j,k)=(t33(i,j,k)-t33(i,j,k-1))*rdz*mf(i,j,k)
      enddo
      enddo
      enddo

  ELSE

      ! implicit vertical turbulence:

      rdt = 1.0/dt
      tema = -1.0*dt*vialpha*rdz*rdz
      temb =      dt*vibeta*rdz*rdz
      temc = dt*rdz

        k=2
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrf)
        do j=1,nj
        do i=1,ni
          rrf = mf(i,j,k)/rf(i,j,k)
          r2 = (kmh(i,j,k  )+kmh(i,j,k+1))*mh(i,j,k  )*rho(i,j,k  )*rrf
          cfc = tema*r2
          cfb = 1.0 - cfc
          cfd = w(i,j,k) + temb*( r2*w(i,j,k+1)-r2*w(i,j,k) )  &
                         - temc*t33(i,j,k-1)*rrf
          tem = 1.0/cfb
          dum1(i,j,k) = -cfc*tem
          dum2(i,j,k) =  cfd*tem
        enddo
        enddo

        do k=3,(nk-1)

      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrf)
        do j=1,nj
        do i=1,ni
          rrf = mf(i,j,k)/rf(i,j,k)
          r1 = (kmh(i,j,k-1)+kmh(i,j,k  ))*mh(i,j,k-1)*rho(i,j,k-1)*rrf
          r2 = (kmh(i,j,k  )+kmh(i,j,k+1))*mh(i,j,k  )*rho(i,j,k  )*rrf
          cfa = tema*r1
          cfc = tema*r2
          cfb = 1.0 - cfa - cfc
          cfd = w(i,j,k) + temb*(r2*w(i,j,k+1)-(r1+r2)*w(i,j,k)+r1*w(i,j,k-1))
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum1(i,j,k) = -cfc*tem
          dum2(i,j,k) = (cfd-cfa*dum2(i,j,k-1))*tem
        enddo
        enddo

        enddo

      IF( axisymm.eq.0 )THEN
        k = nk
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrf)
        do j=1,nj
        do i=1,ni
          rrf = mf(i,j,k)/rf(i,j,k)
          r1 = (kmh(i,j,k-1)+kmh(i,j,k  ))*mh(i,j,k-1)*rho(i,j,k-1)*rrf
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = w(i,j,k) + temb*( -r1*w(i,j,k)+r1*w(i,j,k-1) )  &
                         + temc*t33(i,j,k)*rrf
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum3(i,j,k) = (cfd-cfa*dum2(i,j,k-1))*tem
          turbz(i,j,k) = rf(i,j,k)*(dum3(i,j,k)-w(i,j,k))*rdt
        enddo
        enddo

        do k=(nk-1),2,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=1,nj
        do i=1,ni
          dum3(i,j,k) = dum1(i,j,k)*dum3(i,j,k+1)+dum2(i,j,k)
          turbz(i,j,k) = rf(i,j,k)*(dum3(i,j,k)-w(i,j,k))*rdt
        enddo
        enddo

        enddo

      ELSE

        k = nk
      !$omp parallel do default(shared)   &
      !$omp private(i,j,r1,r2,cfa,cfb,cfc,cfd,tem,rrf)
        do j=1,nj
        do i=1,ni
          rrf = mf(i,j,k)/rf(i,j,k)
          r1 = (kmh(i,j,k-1)+kmh(i,j,k  ))*mh(i,j,k-1)*rho(i,j,k-1)*rrf
          cfa = tema*r1
          cfb = 1.0 - cfa
          cfd = w(i,j,k) + temb*( -r1*w(i,j,k)+r1*w(i,j,k-1) )  &
                         + temc*t33(i,j,k)*rrf
          tem = 1.0/(cfa*dum1(i,j,k-1)+cfb)
          dum3(i,j,k) = (cfd-cfa*dum2(i,j,k-1))*tem
          turbz(i,j,k) = rf(i,j,k)*(dum3(i,j,k)-w(i,j,k))*rdt
        enddo
        enddo

        do k=(nk-1),2,-1

      !$omp parallel do default(shared)   &
      !$omp private(i,j)
        do j=1,nj
        do i=1,ni
          dum3(i,j,k) = dum1(i,j,k)*dum3(i,j,k+1)+dum2(i,j,k)
          turbz(i,j,k) = rf(i,j,k)*(dum3(i,j,k)-w(i,j,k))*rdt
        enddo
        enddo

        enddo

      ENDIF

  ENDIF  ifimplw

  ELSE  dovert

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=2,nk
      do j=1,nj
      do i=1,ni
        turbz(i,j,k)=0.0
      enddo
      enddo
      enddo

  ENDIF  dovert

!---------------------------------------------------------------------
!  Tendencies:

    IF(axisymm.eq.0)THEN

      IF( cm1setup.eq.4 )THEN
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k)
        do k=2,nk
        do j=1,nj
        do i=1,ni
          if( cm0(i,j) .le. cmemin )then
            ! zero-out turb tendencies outside of LES domain:
            turbx(i,j,k) = 0.0
            turby(i,j,k) = 0.0
            turbz(i,j,k) = 0.0
          endif

          wten(i,j,k)=wten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))/rf(i,j,k)
        enddo
        enddo
        enddo
      ELSE
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k)
        do k=2,nk
        do j=1,nj
        do i=1,ni

          wten(i,j,k)=wten(i,j,k)+((turbx(i,j,k)+turby(i,j,k))+turbz(i,j,k))/rf(i,j,k)
        enddo
        enddo
        enddo
      ENDIF

    ELSE

      !$omp parallel do default(shared)   &
      !$omp private(i,j,k)
      do k=2,nk
      do j=1,nj
      do i=1,ni
        wten(i,j,k)=wten(i,j,k)+(turbx(i,j,k)+turbz(i,j,k))/rf(i,j,k)
      enddo
      enddo
      enddo

    ENDIF

!---------------------------------------------------------------------
!  Diagnostics:

      IF( dowbud )THEN
      if( wd_hturb.ge.1 .and. wd_vturb.ge.1 )then
        if( axisymm.eq.0 )then
          !$omp parallel do default(shared)   &
          !$omp private(i,j,k)
          do k=2,nk
          do j=1,nj
          do i=1,ni
            wdiag(i,j,k,wd_hturb) = (turbx(i,j,k)+turby(i,j,k))/rf(i,j,k)
            wdiag(i,j,k,wd_vturb) = turbz(i,j,k)/rf(i,j,k)
          enddo
          enddo
          enddo
        else
          !$omp parallel do default(shared)   &
          !$omp private(i,j,k)
          do k=2,nk
          do j=1,nj
          do i=1,ni
            wdiag(i,j,k,wd_hturb) = turbx(i,j,k)/rf(i,j,k)
            wdiag(i,j,k,wd_vturb) = turbz(i,j,k)/rf(i,j,k)
          enddo
          enddo
          enddo
        endif
      endif
      ENDIF

!-------------------------------------------------------------------
!  All done

      if(timestats.ge.1) time_ttend=time_ttend+mytime()
 
      return
      end subroutine turbw


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC

  END MODULE turbtend_module
turbnba.F/      1744672191  3193  100   100644  33199     `
  MODULE turbnba_module

  implicit none

  private
  public :: turbnba,turbnba2

      real, parameter :: tke_min         =  1.0e-10
      real, parameter :: nm_min          =  1.0e-6
      real, parameter :: small_len_frac  =  0.001

      real, parameter :: odt = 1.0/3.0

      real, parameter :: nba_cb = 0.36
      real, parameter :: nba_sk = 0.5

  CONTAINS


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbnba(nstep,uh,ruh,uf,ruf,vh,rvh,vf,rvf,mh,rmh,mf,rmf,zf,c1,c2,rho,rf,zntmp,ust,cm0,  &
                         s11 ,s12 ,s13 ,s22 ,s23 ,s33 ,            &
                         r12 ,r13 ,r23  ,lenscl,grdscl,tk  ,cme,   &
                         m11,m12,m13,m22,m23,m33,                  &
                         ua ,va ,wa ,tkea ,nm,                     &
                         kw1,kw2,ke1,ke2,ks1,ks2,kn1,kn2,reqs_s,   &
                         nw1,nw2,ne1,ne2,sw1,sw2,se1,se2)
      use input
      use constants
      use bc_module
      use comm_module
      implicit none

!-----------------------------------------------------------------------

      integer, intent(in) :: nstep
      real, intent(in), dimension(ib:ie) :: uh,ruh
      real, intent(in), dimension(ib:ie+1) :: uf,ruf
      real, intent(in), dimension(jb:je) :: vh,rvh
      real, intent(in), dimension(jb:je+1) :: vf,rvf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh,rmh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf,rmf,zf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: c1,c2,rho,rf
      real, intent(in), dimension(ib:ie,jb:je) :: zntmp,ust,cm0
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: r12,r13,r23
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: lenscl,grdscl,tk
      real, intent(in),    dimension(ibc:iec,jbc:jec,kbc:kec) :: cme
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: s11,s12,s13,s22,s23,s33
      real, intent(inout), dimension(ibnba:ienba,jbnba:jenba,kbnba:kenba) :: m11,m12,m13,m22,m23,m33
      real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: ua
      real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: va
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: wa
      real, intent(inout), dimension(ibt:iet,jbt:jet,kbt:ket) :: tkea
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: nm
      real, intent(inout), dimension(jmp,kmt,4)     :: kw1,kw2,ke1,ke2
      real, intent(inout), dimension(imp,kmt,4)     :: ks1,ks2,kn1,kn2
      integer, intent(inout), dimension(rmp) :: reqs_s
      real, intent(inout), dimension(kmt) :: nw1,nw2,ne1,ne2,sw1,sw2,se1,se2

!-----------------------------------------------------------------------

      integer :: i,j,k
      real :: tem,tem1,tkk
      real :: nba_cs,nba_c1,nba_c2,nba_c3,nba_ce,nba_ck
      real :: nba_a,nba_b,delta,tmp11,tmp22,tmp33,tmp12,tmp13,tmp23,tmr12,tmr13,tmr23,smn

      real, dimension(cmp,jmp) :: west,newwest,east,neweast
      real, dimension(imp,cmp) :: south,newsouth,north,newnorth

!-----------------------------------------------------------------------

        nba_ck = (2.0/3.0)*( (pi*c_m)**(-2.0/3.0) )

        nba_cs = sqrt( ( 8.0*( 1.0+nba_cb ) )/( 27.0*pi*pi ) )  &
                 * cme(1,1,2) / c_m
      if( myid.eq.0 ) print *,'  tem = ',cme(1,1,2) / c_m

        nba_c1 = ( sqrt(960.0)*nba_cb )/( 7.0*( 1.0+nba_cb )*nba_sk )
        nba_c2 = nba_c1
        nba_ce = ( ( 8.0*pi/27.0 )**(1.0/3.0) )*( nba_cs**(4.0/3.0) )
        nba_c3 = ( ( 27.0/( 8.0*pi ) )**(1.0/3.0) )*( nba_cs**(2.0/3.0) )

        if( myid.eq.0 ) print *,'  cs,ce,ck = ',nba_cs,nba_ce,nba_ck
        if( myid.eq.0 ) print *,'  c1,c2,c3 = ',nba_c1,nba_c2,nba_c3

!------------------------------------------------------------------

    DO k=2,nk

    !  get grid scale
    IF(tconfig.eq.1)THEN
      ! single length scale:  appropriate if dx,dy are nearly the same as dz
      do j=1,nj
      do i=1,ni
        grdscl(i,j,k)=( ((dx*ruh(i))*(dy*rvh(j)))*(dz*rmf(i,j,k)) )**0.33333333
        ! cm1r17:  wall condition near surface
        ! cm1r20.1: revisit near-sfc grid scale at a later date
!!!        grdscl(i,j,k) = sqrt(1.0/( 1.0/(grdscl(i,j,k)**2)                                  &
!!!                                  +1.0/((karman*((zf(i,j,k)-zf(i,j,1))+zntmp(i,j))*rcs)**2)  &
!!!                               ) )
      enddo
      enddo
    ELSEIF(tconfig.eq.2)THEN
      ! two length scales:  one for horizontal, one for vertical
      stop 15151
    ENDIF

      ! Get turbulence length scale
      do j=1,nj
      do i=1,ni
        if( tkea(i,j,k).le.tke_min )then
          ! 170718:
          tk(i,j,k) = tke_min
          lenscl(i,j,k) = small_len_frac*grdscl(i,j,k)
        else
          tk(i,j,k)=tkea(i,j,k)
          lenscl(i,j,k)=grdscl(i,j,k)
          if(nm(i,j,k).gt.nm_min)then
            lenscl(i,j,k)=c_l*sqrt(tk(i,j,k)/nm(i,j,k))
            lenscl(i,j,k)=min(lenscl(i,j,k),grdscl(i,j,k))
            lenscl(i,j,k)=max(lenscl(i,j,k),small_len_frac*grdscl(i,j,k))
          endif 
        endif
      enddo
      enddo

    ENDDO

    if( nstep.eq.0 .and. myid.eq.0 )then
      print *
      print *,'  zf,grdscl:'
      i = 1
      j = 1
      do k=2,nk
        print *,k,(zf(i,j,k)-zf(i,j,1)),grdscl(i,j,k)
      enddo
    endif

#ifdef MPI
      call comm_1s_start(lenscl,kw1(1,1,1),kw2(1,1,1),ke1(1,1,1),ke2(1,1,1),  &
                                ks1(1,1,1),ks2(1,1,1),kn1(1,1,1),kn2(1,1,1),reqs_s)
      call comm_1s_end(lenscl,kw1(1,1,1),kw2(1,1,1),ke1(1,1,1),ke2(1,1,1),  &
                              ks1(1,1,1),ks2(1,1,1),kn1(1,1,1),kn2(1,1,1),reqs_s)
      call bcs2(lenscl)
      call getcorner(lenscl,nw1(1),nw2(1),ne1(1),ne2(1),sw1(1),sw2(1),se1(1),se2(1))
#endif

      do j=0,nj+1
      do i=0,ni+1
        lenscl(i,j,1) = karman*zntmp(i,j)*rcs
        lenscl(i,j,nk+1) = lenscl(i,j,nk)
      enddo
      enddo

      if( cm1setup.eq.4 )then
        ! zero-out lenscl in mesoscale-model part of domain:

        DO k=1,nk
        do j=0,nj+1
        do i=0,ni+1
          if( cm0(i,j).le.cmemin ) lenscl(i,j,k) = 0.0
        enddo
        enddo
        ENDDO

      endif

!------------------------------------------------------------------

        DO k=1,nk

          do j=0,nj+2
          do i=0,ni+2
            s11(i,j,k)=(ua(i+1,j,k)-ua(i,j,k))*rdx*uh(i)
            s22(i,j,k)=(va(i,j+1,k)-va(i,j,k))*rdy*vh(j)
            s33(i,j,k)=(wa(i,j,k+1)-wa(i,j,k))*rdz*mh(i,j,k)
            s12(i,j,k)=0.5*( (ua(i,j,k)-ua(i,j-1,k))*rdy*vf(j)   &
                            +(va(i,j,k)-va(i-1,j,k))*rdx*uf(i) )
            s13(i,j,k)=0.5*( (wa(i,j,k)-wa(i-1,j,k))*rdx*uf(i)   &
                            +(ua(i,j,k)-ua(i,j,k-1))*rdz*mf(1,1,k) )
            s23(i,j,k)=0.5*( (wa(i,j,k)-wa(i,j-1,k))*rdy*vf(j)   &
                            +(va(i,j,k)-va(i,j,k-1))*rdz*mf(1,1,k) )
            r12(i,j,k) = 0.5*( (ua(i,j,k)-ua(i,j-1,k))*rdy*vf(j) &
                              -(va(i,j,k)-va(i-1,j,k))*rdx*uf(i) )
            r13(i,j,k) = 0.5*(-(wa(i,j,k)-wa(i-1,j,k))*rdx*uf(i) &
                              +(ua(i,j,k)-ua(i,j,k-1))*rdz*mf(1,1,k) )
            r23(i,j,k) = 0.5*(-(wa(i,j,k)-wa(i,j-1,k))*rdy*vf(j) &
                              +(va(i,j,k)-va(i,j,k-1))*rdz*mf(1,1,k) )
          enddo
          enddo

        ENDDO

      do j=-1,nj+2
      do i=-1,ni+2
        grdscl(i,j,1) = ust(i,j)/(karman*zntmp(i,j))
        grdscl(i,j,2) = sqrt( (0.5*(ua(i,j,1)+ua(i+1,j,1)))**2 &
                             +(0.5*(va(i,j,1)+va(i,j+1,1)))**2 )
      enddo
      enddo

      do k=1,2
        call bc2d(grdscl(ib,jb,k))
#ifdef MPI
        call comm_2d_start(grdscl(ib,jb,k),west,newwest,east,neweast,   &
                                           south,newsouth,north,newnorth,reqs_s)
        call comm_2dew_end(grdscl(ib,jb,k),west,newwest,east,neweast,reqs_s)
        call comm_2dns_end(grdscl(ib,jb,k),south,newsouth,north,newnorth,reqs_s)
        call bcs2_2d(grdscl(ib,jb,k))
        call comm_2d_corner(grdscl(ib,jb,k))
#endif
      enddo

      tem1 = 1.0/(zf(1,1,2)-zf(1,1,1))

      do j=0,nj+2
      do i=0,ni+2
!!!        s13(i,j,1) = 0.5*(dgs3*ua(i,j,3)+dgs2*ua(i,j,2)+dgs1*ua(i,j,1))*tem1
!!!        s23(i,j,1) = 0.5*(dgs3*va(i,j,3)+dgs2*va(i,j,2)+dgs1*va(i,j,1))*tem1
!!!        s13(i,j,1) = (grdscl(i-1,j,1)+grdscl(i,j,1))*ua(i,j,1)/max(0.01,grdscl(i-1,j,2)+grdscl(i,j,2))
!!!        s23(i,j,1) = (grdscl(i,j-1,1)+grdscl(i,j,1))*va(i,j,1)/max(0.01,grdscl(i,j-1,2)+grdscl(i,j,2))
        s13(i,j,1) = 0.0
        s23(i,j,1) = 0.0
        r13(i,j,1) = s13(i,j,1)
        r23(i,j,1) = s23(i,j,1)
        s13(i,j,nk+1) = 0.0
        s23(i,j,nk+1) = 0.0
        r13(i,j,nk+1) = s13(i,j,nk+1)
        r23(i,j,nk+1) = s23(i,j,nk+1)
      enddo
      enddo

#ifdef MPI
      call bct2(tkea)
      call getcornert(tkea,nw1,nw2,ne1,ne2,sw1,sw2,se1,se2)
#endif

  kloop:  DO k=1,nk

    do j=0,nj+1
    do i=0,ni+1

      delta = 0.5*( lenscl(i,j,k  ) &
                   +lenscl(i,j,k+1) )

      nba_a = nba_ce
      nba_b = nba_ce*delta*nba_c3*delta

      tmp11 = s11(i,j,k)**2
      tmp22 = s22(i,j,k)**2
      tmp33 = s33(i,j,k)**2

      tmp12 = 0.25*( ( s12(i,j  ,k)**2 + s12(i+1,j+1,k)**2 ) &
                   + ( s12(i,j+1,k)**2 + s12(i+1,j  ,k)**2 ) )

      tmp13 = 0.25*( ( s13(i,j,k  )**2 + s13(i+1,j,k  )**2 ) &
                   + ( s13(i,j,k+1)**2 + s13(i+1,j,k+1)**2 ) )

      tmp23 = 0.25*( ( s23(i,j,k  )**2 + s23(i,j+1,k  )**2 ) &
                   + ( s23(i,j,k+1)**2 + s23(i,j+1,k+1)**2 ) )

      smn = ( tmp11 + tmp22 ) + tmp33 + 2.0*( tmp12 + ( tmp13 + tmp23 ) )

      tmr12 = 0.25*( ( s12(i,j  ,k)*r12(i,j  ,k) + s12(i+1,j+1,k)*r12(i+1,j+1,k) ) &
                   + ( s12(i,j+1,k)*r12(i,j+1,k) + s12(i+1,j  ,k)*r12(i+1,j  ,k) ) )

      tmr13 = 0.25*( ( s13(i,j,k  )*r13(i,j,k  ) + s13(i+1,j,k  )*r13(i+1,j,k  ) ) &
                   + ( s13(i,j,k+1)*r13(i,j,k+1) + s13(i+1,j,k+1)*r13(i+1,j,k+1) ) )

      tmr23 = 0.25*( ( s23(i,j,k  )*r23(i,j,k  ) + s23(i,j+1,k  )*r23(i,j+1,k  ) ) &
                   + ( s23(i,j,k+1)*r23(i,j,k+1) + s23(i,j+1,k+1)*r23(i,j+1,k+1) ) )

      tkk = 0.5*( lenscl(i,j,k)*sqrt(tkea(i,j,k)) + lenscl(i,j,k+1)*sqrt(tkea(i,j,k+1)) )

      m11(i,j,k) =  rho(i,j,k)*( nba_ce*2.0*tkk*s11(i,j,k)                       &
                   + nba_b*( nba_c1*( ( tmp11 + tmp12 ) + ( tmp13 - smn*odt ) )  &
                           + nba_c2*( -2.0*( tmr12 + tmr13 ) )                   &
                         ) )
      m22(i,j,k) =  rho(i,j,k)*( nba_ce*2.0*tkk*s22(i,j,k)                       &
                   + nba_b*( nba_c1*( ( tmp22 + tmp12 ) + ( tmp23 - smn*odt ) )  &
                           + nba_c2*(  2.0*( tmr12 - tmr23 ) )                   &
                         ) )

      m33(i,j,k) =  rho(i,j,k)*( nba_ce*2.0*tkk*s33(i,j,k)                       &
                   + nba_b*( nba_c1*( ( tmp13 + tmp23 ) + ( tmp33 - smn*odt ) )  &
                           + nba_c2*(  2.0*( tmr13 + tmr23 ) )                   &
                         ) )

!!!      t11(i,j,k) = rho(i,j,k)*nba_a*(   2.0*tkk*s11(i,j,k) )
!!!      t22(i,j,k) = rho(i,j,k)*nba_a*(   2.0*tkk*s22(i,j,k) )
!!!      t33(i,j,k) = rho(i,j,k)*nba_a*(   2.0*tkk*s33(i,j,k) )

    enddo
    enddo

    do j=1,nj+1
    do i=1,ni+1

      delta = 0.125*( ( ( lenscl(i  ,j  ,k  )     &
                         +lenscl(i-1,j-1,k  ) )   &
                       +( lenscl(i-1,j  ,k  )     &
                         +lenscl(i  ,j-1,k  ) ) ) &
                     +( ( lenscl(i  ,j  ,k+1)     &
                         +lenscl(i-1,j-1,k+1) )   &
                       +( lenscl(i-1,j  ,k+1)     &
                         +lenscl(i  ,j-1,k+1) ) ) )

      nba_a = nba_ce
      nba_b = nba_ce*delta*nba_c3*delta

      tmp11 = 0.25*(  (s11(i  ,j,k)+s11(i-1,j-1,k)) &
                     +(s11(i-1,j,k)+s11(i  ,j-1,k)) )
      tmp22 = 0.25*(  (s22(i  ,j,k)+s22(i-1,j-1,k)) &
                     +(s22(i-1,j,k)+s22(i  ,j-1,k)) )
      tmp12 = s12(i,j,k)
      tmp13 = 0.25*( (s13(i,j,k  )+s13(i,j-1,k  )) &
                    +(s13(i,j,k+1)+s13(i,j-1,k+1)) )
      tmp23 = 0.25*( (s23(i,j,k  )+s23(i-1,j,k  )) &
                    +(s23(i,j,k+1)+s23(i-1,j,k+1)) )

      tkk = 0.125*( ( (lenscl(i  ,j,k  )*sqrt(tkea(i  ,j,k  ))+lenscl(i-1,j-1,k  )*sqrt(tkea(i-1,j-1,k  )))   &
                     +(lenscl(i-1,j,k  )*sqrt(tkea(i-1,j,k  ))+lenscl(i  ,j-1,k  )*sqrt(tkea(i  ,j-1,k  ))) ) &
                   +( (lenscl(i  ,j,k+1)*sqrt(tkea(i  ,j,k+1))+lenscl(i-1,j-1,k+1)*sqrt(tkea(i-1,j-1,k+1)))   &
                     +(lenscl(i-1,j,k+1)*sqrt(tkea(i-1,j,k+1))+lenscl(i  ,j-1,k+1)*sqrt(tkea(i  ,j-1,k+1))) ) )

      tmr12 = r12(i,j,k)
      tmr13 = 0.25*( (r13(i,j,k  )+r13(i,j-1,k  )) &
                    +(r13(i,j,k+1)+r13(i,j-1,k+1)) )
      tmr23 = 0.25*( (r23(i,j,k  )+r23(i-1,j,k  )) &
                    +(r23(i,j,k+1)+r23(i-1,j,k+1)) )

      m12(i,j,k) = nba_ce*2.0*tkk*s12(i,j,k)  &
                   + nba_b*( nba_c1*( ( tmp11*tmp12 + tmp12*tmp22 ) + tmp13*tmp23 )  &
                           + nba_c2*( (   tmp11*tmr12 - tmp22*tmr12 )                &
                                     +( - tmp13*tmr23 - tmp23*tmr13 ) )              &
                           )
      m12(i,j,k) = m12(i,j,k)*0.25*( (rho(i-1,j-1,k)+rho(i,j,k))+(rho(i-1,j,k)+rho(i,j-1,k)) )

!!!      t12(i,j,k) = nba_a*(   2.0*tkk*s12(i,j,k) )
!!!      t12(i,j,k) = t12(i,j,k)*0.25*( (rho(i-1,j-1,k)+rho(i,j,k))+(rho(i-1,j,k)+rho(i,j-1,k)) )

    enddo
    enddo

  kcheck:  IF( k.ge.2 )THEN

    do j=1,nj
    do i=1,ni+1

      delta = 0.5*( lenscl(i-1,j,k) &
                   +lenscl(i  ,j,k) )
      nba_a = nba_ce
      nba_b = nba_ce*delta*nba_c3*delta

      tmp11 = 0.5*( c1(1,1,k)*(s11(i-1,j,k-1)+s11(i,j,k-1)) &
                   +c2(1,1,k)*(s11(i-1,j,k  )+s11(i,j,k  )) )
      tmp13 = s13(i,j,k)
      tmp12 = 0.5*( c1(1,1,k)*(s12(i,j+1,k-1)+s12(i,j,k-1)) &
                   +c2(1,1,k)*(s12(i,j+1,k  )+s12(i,j,k  )) )
      tmp23 = 0.25*( (s23(i-1,j+1,k)+s23(i,j  ,k)) &
                    +(s23(i-1,j  ,k)+s23(i,j+1,k)) )
      tmp33 = 0.5*( c1(1,1,k)*(s33(i-1,j,k-1)+s33(i,j,k-1)) &
                   +c2(1,1,k)*(s33(i-1,j,k  )+s33(i,j,k  )) )

      tkk = 0.5*( lenscl(i,j,k)*sqrt(tkea(i,j,k)) + lenscl(i-1,j,k)*sqrt(tkea(i-1,j,k)) )

      tmr13 = r13(i,j,k)
      tmr23 = 0.25*( (r23(i-1,j+1,k)+r23(i,j  ,k)) &
                    +(r23(i-1,j  ,k)+r23(i,j+1,k)) )
      tmr12 = 0.5*( c1(1,1,k)*(r12(i,j+1,k-1)+r12(i,j,k-1)) &
                   +c2(1,1,k)*(r12(i,j+1,k  )+r12(i,j,k  )) )

      m13(i,j,k) = nba_ce*2.0*tkk*s13(i,j,k)  &
                   + nba_b*( nba_c1*( ( tmp11*tmp13 + tmp13*tmp33 ) + tmp12*tmp23 )  &
                           + nba_c2*(   ( tmp11*tmr13 - tmp33*tmr13 )                &
                                      + ( tmp12*tmr23 - tmp23*tmr12 )  )             &
                           )
      m13(i,j,k) = m13(i,j,k)*0.5*( rf(i-1,j,k)+rf(i,j,k) )

!!!      t13(i,j,k) = nba_a*(   2.0*tkk*s13(i,j,k) )
!!!      t13(i,j,k) = t13(i,j,k)*0.5*( rf(i-1,j,k)+rf(i,j,k) )

    enddo
    enddo

    do j=1,nj+1
    do i=1,ni

      delta = 0.5*( lenscl(i,j-1,k) &
                   +lenscl(i,j  ,k) )
      nba_a = nba_ce
      nba_b = nba_ce*delta*nba_c3*delta

      tmp23 = s23(i,j,k)
      tmp12 = 0.5*( c1(1,1,k)*(s12(i,j,k-1)+s12(i+1,j,k-1)) &
                   +c2(1,1,k)*(s12(i,j,k  )+s12(i+1,j,k  )) )
      tmp13 = 0.25*( (s13(i+1,j-1,k)+s13(i,j  ,k)) &
                    +(s13(i+1,j  ,k)+s13(i,j-1,k)) )
      tmp33 = 0.5*( c1(1,1,k)*(s33(i,j,k-1)+s33(i,j-1,k-1)) &
                   +c2(1,1,k)*(s33(i,j,k  )+s33(i,j-1,k  )) )
      tmp22 = 0.5*( c1(1,1,k)*(s22(i,j,k-1)+s22(i,j-1,k-1)) &
                   +c2(1,1,k)*(s22(i,j,k  )+s22(i,j-1,k  )) )

      tkk = 0.5*( lenscl(i,j,k)*sqrt(tkea(i,j,k)) + lenscl(i,j-1,k)*sqrt(tkea(i,j-1,k)) )

      tmr23 = r23(i,j,k)
      tmr13 = 0.25*( (r13(i+1,j-1,k)+r13(i,j  ,k)) &
                    +(r13(i+1,j  ,k)+r13(i,j-1,k)) )
      tmr12 = 0.5*( c1(1,1,k)*(r12(i,j,k-1)+r12(i+1,j,k-1)) &
                   +c2(1,1,k)*(r12(i,j,k  )+r12(i+1,j,k  )) )

      m23(i,j,k) = nba_ce*2.0*tkk*s23(i,j,k)  &
                   + nba_b*( nba_c1*( ( tmp22*tmp23 + tmp23*tmp33 ) + tmp12*tmp13 )  &
                           + nba_c2*(   ( tmp22*tmr23 - tmp33*tmr23 )                &
                                      + ( tmp12*tmr13 + tmp13*tmr12 )  )             &
                           )
      m23(i,j,k) = m23(i,j,k)*0.5*( rf(i,j-1,k)+rf(i,j,k) )

!!!      t23(i,j,k) = nba_a*(   2.0*tkk*s23(i,j,k) )
!!!      t23(i,j,k) = t23(i,j,k)*0.5*( rf(i,j-1,k)+rf(i,j,k) )

    enddo
    enddo

  ENDIF  kcheck

  ENDDO  kloop

!------------------------------------------------------------------

      IF(bbc.eq.1)THEN
        ! free slip:
        do j=1,nj+1
        do i=1,ni+1
          m13(i,j,1) = m13(i,j,2)
          m23(i,j,1) = m23(i,j,2)
        enddo
        enddo
      ELSEIF(bbc.eq.2.or.bbc.eq.3)THEN
        IF(axisymm.eq.0)THEN
!!!          do j=1,nj+1
!!!          do i=1,ni+1
!!!            m13(i,j,1) = t13(i,j,1)
!!!            m23(i,j,1) = t23(i,j,1)
!!!          enddo
!!!          enddo
        ELSE
          stop 1212
        ENDIF
      ELSE
        stop 2222
      ENDIF

!------------------------------------------------------------------

      end subroutine turbnba


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


      subroutine turbnba2(nstep,uh,ruh,uf,ruf,vh,rvh,vf,rvf,mh,rmh,mf,rmf,zf,c1,c2,rho,rf,zntmp,ust,cm0,  &
                         s11 ,s12 ,s13 ,s22 ,s23 ,s33 ,            &
                         r12 ,r13 ,r23  ,lenscl,grdscl,tk  ,cme,   &
                         m11,m12,m13,m22,m23,m33,                  &
                         ua ,va ,wa ,tkea ,nm,                     &
                         kw1,kw2,ke1,ke2,ks1,ks2,kn1,kn2,reqs_s,   &
                         nw1,nw2,ne1,ne2,sw1,sw2,se1,se2)
      use input
      use constants
      use bc_module
      use comm_module
      implicit none

!-----------------------------------------------------------------------

      integer, intent(in) :: nstep
      real, intent(in), dimension(ib:ie) :: uh,ruh
      real, intent(in), dimension(ib:ie+1) :: uf,ruf
      real, intent(in), dimension(jb:je) :: vh,rvh
      real, intent(in), dimension(jb:je+1) :: vf,rvf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: mh,rmh
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: mf,rmf,zf
      real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: c1,c2,rho,rf
      real, intent(in), dimension(ib:ie,jb:je) :: zntmp,ust,cm0
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: r12,r13,r23
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: lenscl,grdscl,tk
      real, intent(in),    dimension(ibc:iec,jbc:jec,kbc:kec) :: cme
      real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: s11,s12,s13,s22,s23,s33
      real, intent(inout), dimension(ibnba:ienba,jbnba:jenba,kbnba:kenba) :: m11,m12,m13,m22,m23,m33
      real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: ua
      real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: va
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: wa
      real, intent(inout), dimension(ibt:iet,jbt:jet,kbt:ket) :: tkea
      real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: nm
      real, intent(inout), dimension(jmp,kmt,4)     :: kw1,kw2,ke1,ke2
      real, intent(inout), dimension(imp,kmt,4)     :: ks1,ks2,kn1,kn2
      integer, intent(inout), dimension(rmp) :: reqs_s
      real, intent(inout), dimension(kmt) :: nw1,nw2,ne1,ne2,sw1,sw2,se1,se2

!-----------------------------------------------------------------------

      integer :: i,j,k
      real :: tem,tem1,tkk
      real :: nba_cs,nba_c1,nba_c2,nba_c3,nba_ce,nba_ck
      real :: nba_a,nba_b,delta,tmp11,tmp22,tmp33,tmp12,tmp13,tmp23,tmr12,tmr13,tmr23,smn

      real, dimension(cmp,jmp) :: west,newwest,east,neweast
      real, dimension(imp,cmp) :: south,newsouth,north,newnorth

!-----------------------------------------------------------------------

        nba_ck = (2.0/3.0)*( (pi*c_m)**(-2.0/3.0) )

        nba_cs = sqrt( ( 8.0*( 1.0+nba_cb ) )/( 27.0*pi*pi ) )  &
                 * cme(1,1,2) / c_m
      if( myid.eq.0 ) print *,'  tem = ',cme(1,1,2) / c_m

        nba_c1 = ( sqrt(960.0)*nba_cb )/( 7.0*( 1.0+nba_cb )*nba_sk )
        nba_c2 = nba_c1
        nba_ce = ( ( 8.0*pi/27.0 )**(1.0/3.0) )*( nba_cs**(4.0/3.0) )
        nba_c3 = ( ( 27.0/( 8.0*pi ) )**(1.0/3.0) )*( nba_cs**(2.0/3.0) )

        if( myid.eq.0 ) print *,'  cs,ce,ck = ',nba_cs,nba_ce,nba_ck
        if( myid.eq.0 ) print *,'  c1,c2,c3 = ',nba_c1,nba_c2,nba_c3

!------------------------------------------------------------------

    DO k=2,nk

    !  get grid scale
    IF(tconfig.eq.1)THEN
      ! single length scale:  appropriate if dx,dy are nearly the same as dz
      do j=1,nj
      do i=1,ni
        grdscl(i,j,k)=( ((dx*ruh(i))*(dy*rvh(j)))*(dz*rmf(i,j,k)) )**0.33333333
        ! cm1r17:  wall condition near surface
        ! cm1r20.1: revisit near-sfc grid scale at a later date
!!!        grdscl(i,j,k) = sqrt(1.0/( 1.0/(grdscl(i,j,k)**2)                                  &
!!!                                  +1.0/((karman*((zf(i,j,k)-zf(i,j,1))+zntmp(i,j))*rcs)**2)  &
!!!                               ) )
      enddo
      enddo
    ELSEIF(tconfig.eq.2)THEN
      ! two length scales:  one for horizontal, one for vertical
      stop 15151
    ENDIF

    ENDDO

    if( nstep.eq.0 .and. myid.eq.0 )then
      print *
      print *,'  zf,grdscl:'
      i = 1
      j = 1
      do k=2,nk
        print *,k,(zf(i,j,k)-zf(i,j,1)),grdscl(i,j,k)
      enddo
    endif

#ifdef MPI
      call comm_1s_start(grdscl,kw1(1,1,1),kw2(1,1,1),ke1(1,1,1),ke2(1,1,1),  &
                                ks1(1,1,1),ks2(1,1,1),kn1(1,1,1),kn2(1,1,1),reqs_s)
      call comm_1s_end(grdscl,kw1(1,1,1),kw2(1,1,1),ke1(1,1,1),ke2(1,1,1),  &
                              ks1(1,1,1),ks2(1,1,1),kn1(1,1,1),kn2(1,1,1),reqs_s)
      call bcs2(grdscl)
      call getcorner(grdscl,nw1(1),nw2(1),ne1(1),ne2(1),sw1(1),sw2(1),se1(1),se2(1))
#endif

      do j=0,nj+1
      do i=0,ni+1
        grdscl(i,j,1) = grdscl(i,j,2)
        grdscl(i,j,nk+1) = grdscl(i,j,nk)
      enddo
      enddo

      if( cm1setup.eq.4 )then
        ! zero-out grdscl in mesoscale-model part of domain:

        DO k=1,nk
        do j=0,nj+1
        do i=0,ni+1
          if( cm0(i,j).le.cmemin ) grdscl(i,j,k) = 0.0
        enddo
        enddo
        ENDDO

      endif

!------------------------------------------------------------------

        DO k=1,nk

          do j=0,nj+2
          do i=0,ni+2
            s11(i,j,k)=(ua(i+1,j,k)-ua(i,j,k))*rdx*uh(i)
            s22(i,j,k)=(va(i,j+1,k)-va(i,j,k))*rdy*vh(j)
            s33(i,j,k)=(wa(i,j,k+1)-wa(i,j,k))*rdz*mh(i,j,k)
            s12(i,j,k)=0.5*( (ua(i,j,k)-ua(i,j-1,k))*rdy*vf(j)   &
                            +(va(i,j,k)-va(i-1,j,k))*rdx*uf(i) )
            s13(i,j,k)=0.5*( (wa(i,j,k)-wa(i-1,j,k))*rdx*uf(i)   &
                            +(ua(i,j,k)-ua(i,j,k-1))*rdz*mf(1,1,k) )
            s23(i,j,k)=0.5*( (wa(i,j,k)-wa(i,j-1,k))*rdy*vf(j)   &
                            +(va(i,j,k)-va(i,j,k-1))*rdz*mf(1,1,k) )
            r12(i,j,k) = 0.5*( (ua(i,j,k)-ua(i,j-1,k))*rdy*vf(j) &
                              -(va(i,j,k)-va(i-1,j,k))*rdx*uf(i) )
            r13(i,j,k) = 0.5*(-(wa(i,j,k)-wa(i-1,j,k))*rdx*uf(i) &
                              +(ua(i,j,k)-ua(i,j,k-1))*rdz*mf(1,1,k) )
            r23(i,j,k) = 0.5*(-(wa(i,j,k)-wa(i,j-1,k))*rdy*vf(j) &
                              +(va(i,j,k)-va(i,j,k-1))*rdz*mf(1,1,k) )
          enddo
          enddo

        ENDDO

      tem1 = 1.0/(zf(1,1,2)-zf(1,1,1))

      do j=0,nj+2
      do i=0,ni+2
!!!        s13(i,j,1) = 0.5*(dgs3*ua(i,j,3)+dgs2*ua(i,j,2)+dgs1*ua(i,j,1))*tem1
!!!        s23(i,j,1) = 0.5*(dgs3*va(i,j,3)+dgs2*va(i,j,2)+dgs1*va(i,j,1))*tem1
        s13(i,j,1) = 0.0
        s23(i,j,1) = 0.0
        r13(i,j,1) = s13(i,j,1)
        r23(i,j,1) = s23(i,j,1)
        s13(i,j,nk+1) = 0.0
        s23(i,j,nk+1) = 0.0
        r13(i,j,nk+1) = s13(i,j,nk+1)
        r23(i,j,nk+1) = s23(i,j,nk+1)
      enddo
      enddo

  kloop:  DO k=1,nk

    do j=0,nj+1
    do i=0,ni+1

      delta = 0.5*( grdscl(i,j,k  ) &
                   +grdscl(i,j,k+1) )

      nba_a = nba_cs*nba_cs*delta*delta

      tmp11 = s11(i,j,k)**2
      tmp22 = s22(i,j,k)**2
      tmp33 = s33(i,j,k)**2

      tmp12 = 0.25*( ( s12(i,j  ,k)**2 + s12(i+1,j+1,k)**2 ) &
                   + ( s12(i,j+1,k)**2 + s12(i+1,j  ,k)**2 ) )

      tmp13 = 0.25*( ( s13(i,j,k  )**2 + s13(i+1,j,k  )**2 ) &
                   + ( s13(i,j,k+1)**2 + s13(i+1,j,k+1)**2 ) )

      tmp23 = 0.25*( ( s23(i,j,k  )**2 + s23(i,j+1,k  )**2 ) &
                   + ( s23(i,j,k+1)**2 + s23(i,j+1,k+1)**2 ) )

      smn = ( tmp11 + tmp22 ) + tmp33 + 2.0*( tmp12 + ( tmp13 + tmp23 ) )

      tmr12 = 0.25*( ( s12(i,j  ,k)*r12(i,j  ,k) + s12(i+1,j+1,k)*r12(i+1,j+1,k) ) &
                   + ( s12(i,j+1,k)*r12(i,j+1,k) + s12(i+1,j  ,k)*r12(i+1,j  ,k) ) )

      tmr13 = 0.25*( ( s13(i,j,k  )*r13(i,j,k  ) + s13(i+1,j,k  )*r13(i+1,j,k  ) ) &
                   + ( s13(i,j,k+1)*r13(i,j,k+1) + s13(i+1,j,k+1)*r13(i+1,j,k+1) ) )

      tmr23 = 0.25*( ( s23(i,j,k  )*r23(i,j,k  ) + s23(i,j+1,k  )*r23(i,j+1,k  ) ) &
                   + ( s23(i,j,k+1)*r23(i,j,k+1) + s23(i,j+1,k+1)*r23(i,j+1,k+1) ) )

      m11(i,j,k) =  rho(i,j,k)*nba_a*( 2.0*sqrt( 2.0*smn )*s11(i,j,k)        &
                   +       ( nba_c1*( ( tmp11 + tmp12 ) + ( tmp13 - smn*odt ) )  &
                           + nba_c2*( -2.0*( tmr12 + tmr13 ) )                   &
                         ) )
      m22(i,j,k) =  rho(i,j,k)*nba_a*( 2.0*sqrt( 2.0*smn )*s22(i,j,k)        &
                   +       ( nba_c1*( ( tmp22 + tmp12 ) + ( tmp23 - smn*odt ) )  &
                           + nba_c2*(  2.0*( tmr12 - tmr23 ) )                   &
                         ) )

      m33(i,j,k) =  rho(i,j,k)*nba_a*( 2.0*sqrt( 2.0*smn )*s33(i,j,k)        &
                   +       ( nba_c1*( ( tmp13 + tmp23 ) + ( tmp33 - smn*odt ) )  &
                           + nba_c2*(  2.0*( tmr13 + tmr23 ) )                   &
                         ) )

!!!      t11(i,j,k) = rho(i,j,k)*nba_a*(   2.0*tkk*s11(i,j,k) )
!!!      t22(i,j,k) = rho(i,j,k)*nba_a*(   2.0*tkk*s22(i,j,k) )
!!!      t33(i,j,k) = rho(i,j,k)*nba_a*(   2.0*tkk*s33(i,j,k) )

    enddo
    enddo

    do j=1,nj+1
    do i=1,ni+1

      delta = 0.125*( ( ( grdscl(i  ,j  ,k  )     &
                         +grdscl(i-1,j-1,k  ) )   &
                       +( grdscl(i-1,j  ,k  )     &
                         +grdscl(i  ,j-1,k  ) ) ) &
                     +( ( grdscl(i  ,j  ,k+1)     &
                         +grdscl(i-1,j-1,k+1) )   &
                       +( grdscl(i-1,j  ,k+1)     &
                         +grdscl(i  ,j-1,k+1) ) ) )

      nba_a = nba_cs*nba_cs*delta*delta

      tmp11 = 0.25*(  (s11(i  ,j,k)+s11(i-1,j-1,k)) &
                     +(s11(i-1,j,k)+s11(i  ,j-1,k)) )
      tmp22 = 0.25*(  (s22(i  ,j,k)+s22(i-1,j-1,k)) &
                     +(s22(i-1,j,k)+s22(i  ,j-1,k)) )
      tmp33 = 0.25*(  (s33(i  ,j,k)+s33(i-1,j-1,k)) &
                     +(s33(i-1,j,k)+s33(i  ,j-1,k)) )
      tmp12 = s12(i,j,k)
      tmp13 = 0.25*( (s13(i,j,k  )+s13(i,j-1,k  )) &
                    +(s13(i,j,k+1)+s13(i,j-1,k+1)) )
      tmp23 = 0.25*( (s23(i,j,k  )+s23(i-1,j,k  )) &
                    +(s23(i,j,k+1)+s23(i-1,j,k+1)) )

      tmr12 = r12(i,j,k)
      tmr13 = 0.25*( (r13(i,j,k  )+r13(i,j-1,k  )) &
                    +(r13(i,j,k+1)+r13(i,j-1,k+1)) )
      tmr23 = 0.25*( (r23(i,j,k  )+r23(i-1,j,k  )) &
                    +(r23(i,j,k+1)+r23(i-1,j,k+1)) )

      smn = ( tmp11*tmp11 + tmp22*tmp22 ) + tmp33*tmp33 + 2.0*( tmp12*tmp12 + ( tmp13*tmp13 + tmp23*tmp23 ) )

      m12(i,j,k) = nba_a*( 2.0*sqrt( 2.0*smn )*s12(i,j,k)  &
                   +       ( nba_c1*( ( tmp11*tmp12 + tmp12*tmp22 ) + tmp13*tmp23 )  &
                           + nba_c2*( (   tmp11*tmr12 - tmp22*tmr12 )                &
                                     +( - tmp13*tmr23 - tmp23*tmr13 ) )              &
                         ) )
      m12(i,j,k) = m12(i,j,k)*0.25*( (rho(i-1,j-1,k)+rho(i,j,k))+(rho(i-1,j,k)+rho(i,j-1,k)) )

!!!      t12(i,j,k) = nba_a*(   2.0*tkk*s12(i,j,k) )
!!!      t12(i,j,k) = t12(i,j,k)*0.25*( (rho(i-1,j-1,k)+rho(i,j,k))+(rho(i-1,j,k)+rho(i,j-1,k)) )

    enddo
    enddo

  kcheck:  IF( k.ge.2 )THEN

    do j=1,nj
    do i=1,ni+1

      delta = 0.5*( grdscl(i-1,j,k) &
                   +grdscl(i  ,j,k) )

      nba_a = nba_cs*nba_cs*delta*delta

      tmp11 = 0.5*( c1(1,1,k)*(s11(i-1,j,k-1)+s11(i,j,k-1)) &
                   +c2(1,1,k)*(s11(i-1,j,k  )+s11(i,j,k  )) )
      tmp22 = 0.5*( c1(1,1,k)*(s22(i-1,j,k-1)+s22(i,j,k-1)) &
                   +c2(1,1,k)*(s22(i-1,j,k  )+s22(i,j,k  )) )
      tmp33 = 0.5*( c1(1,1,k)*(s33(i-1,j,k-1)+s33(i,j,k-1)) &
                   +c2(1,1,k)*(s33(i-1,j,k  )+s33(i,j,k  )) )
      tmp12 = 0.5*( c1(1,1,k)*(s12(i,j+1,k-1)+s12(i,j,k-1)) &
                   +c2(1,1,k)*(s12(i,j+1,k  )+s12(i,j,k  )) )
      tmp13 = s13(i,j,k)
      tmp23 = 0.25*( (s23(i-1,j+1,k)+s23(i,j  ,k)) &
                    +(s23(i-1,j  ,k)+s23(i,j+1,k)) )

      tmr13 = r13(i,j,k)
      tmr23 = 0.25*( (r23(i-1,j+1,k)+r23(i,j  ,k)) &
                    +(r23(i-1,j  ,k)+r23(i,j+1,k)) )
      tmr12 = 0.5*( c1(1,1,k)*(r12(i,j+1,k-1)+r12(i,j,k-1)) &
                   +c2(1,1,k)*(r12(i,j+1,k  )+r12(i,j,k  )) )

      smn = ( tmp11*tmp11 + tmp22*tmp22 ) + tmp33*tmp33 + 2.0*( tmp12*tmp12 + ( tmp13*tmp13 + tmp23*tmp23 ) )

      m13(i,j,k) = nba_a*( 2.0*sqrt( 2.0*smn )*s13(i,j,k)  &
                   +       ( nba_c1*( ( tmp11*tmp13 + tmp13*tmp33 ) + tmp12*tmp23 )  &
                           + nba_c2*(   ( tmp11*tmr13 - tmp33*tmr13 )                &
                                      + ( tmp12*tmr23 - tmp23*tmr12 )  )             &
                         ) )
      m13(i,j,k) = m13(i,j,k)*0.5*( rf(i-1,j,k)+rf(i,j,k) )

!!!      t13(i,j,k) = nba_a*(   2.0*tkk*s13(i,j,k) )
!!!      t13(i,j,k) = t13(i,j,k)*0.5*( rf(i-1,j,k)+rf(i,j,k) )

    enddo
    enddo

    do j=1,nj+1
    do i=1,ni

      delta = 0.5*( grdscl(i,j-1,k) &
                   +grdscl(i,j  ,k) )

      nba_a = nba_cs*nba_cs*delta*delta

      tmp11 = 0.5*( c1(1,1,k)*(s11(i,j,k-1)+s11(i,j-1,k-1)) &
                   +c2(1,1,k)*(s11(i,j,k  )+s11(i,j-1,k  )) )
      tmp22 = 0.5*( c1(1,1,k)*(s22(i,j,k-1)+s22(i,j-1,k-1)) &
                   +c2(1,1,k)*(s22(i,j,k  )+s22(i,j-1,k  )) )
      tmp33 = 0.5*( c1(1,1,k)*(s33(i,j,k-1)+s33(i,j-1,k-1)) &
                   +c2(1,1,k)*(s33(i,j,k  )+s33(i,j-1,k  )) )
      tmp12 = 0.5*( c1(1,1,k)*(s12(i,j,k-1)+s12(i+1,j,k-1)) &
                   +c2(1,1,k)*(s12(i,j,k  )+s12(i+1,j,k  )) )
      tmp13 = 0.25*( (s13(i+1,j-1,k)+s13(i,j  ,k)) &
                    +(s13(i+1,j  ,k)+s13(i,j-1,k)) )
      tmp23 = s23(i,j,k)

      tmr23 = r23(i,j,k)
      tmr13 = 0.25*( (r13(i+1,j-1,k)+r13(i,j  ,k)) &
                    +(r13(i+1,j  ,k)+r13(i,j-1,k)) )
      tmr12 = 0.5*( c1(1,1,k)*(r12(i,j,k-1)+r12(i+1,j,k-1)) &
                   +c2(1,1,k)*(r12(i,j,k  )+r12(i+1,j,k  )) )

      smn = ( tmp11*tmp11 + tmp22*tmp22 ) + tmp33*tmp33 + 2.0*( tmp12*tmp12 + ( tmp13*tmp13 + tmp23*tmp23 ) )

      m23(i,j,k) = nba_a*( 2.0*sqrt( 2.0*smn )*s23(i,j,k)  &
                   +       ( nba_c1*( ( tmp22*tmp23 + tmp23*tmp33 ) + tmp12*tmp13 )  &
                           + nba_c2*(   ( tmp22*tmr23 - tmp33*tmr23 )                &
                                      + ( tmp12*tmr13 + tmp13*tmr12 )  )             &
                         ) )
      m23(i,j,k) = m23(i,j,k)*0.5*( rf(i,j-1,k)+rf(i,j,k) )

!!!      t23(i,j,k) = nba_a*(   2.0*tkk*s23(i,j,k) )
!!!      t23(i,j,k) = t23(i,j,k)*0.5*( rf(i,j-1,k)+rf(i,j,k) )

    enddo
    enddo

  ENDIF  kcheck

  ENDDO  kloop

!------------------------------------------------------------------

      IF(bbc.eq.1)THEN
        ! free slip:
        do j=1,nj+1
        do i=1,ni+1
          m13(i,j,1) = m13(i,j,2)
          m23(i,j,1) = m23(i,j,2)
        enddo
        enddo
      ELSEIF(bbc.eq.2.or.bbc.eq.3)THEN
        IF(axisymm.eq.0)THEN
!!!          do j=1,nj+1
!!!          do i=1,ni+1
!!!            m13(i,j,1) = t13(i,j,1)
!!!            m23(i,j,1) = t23(i,j,1)
!!!          enddo
!!!          enddo
        ELSE
          stop 1212
        ENDIF
      ELSE
        stop 2222
      ENDIF

!------------------------------------------------------------------

      end subroutine turbnba2


!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC
!CCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCCC


  END MODULE turbnba_module

domaindiag.F/   1744672191  3193  100   100644  298050    `
  MODULE domaindiag_module

  implicit none

  private
  public :: domaindiag

  integer, parameter :: varmax = 10000

  integer, parameter :: fnums = 67
  integer, parameter :: fnumw = 68

  integer :: ncid,wloop

  CONTAINS

!-------------------------------------------------------------------------------
!
!  domaindiag:  subroutine to calculate domain-wide diagnostics
!
!       Notes:  - reference profiles are domain-averages at height levels
!               - code currently does not account for terrain
!
!-------------------------------------------------------------------------------

    subroutine domaindiag(nstep,mtime,nwritet,trecs,trecw,qname,qunit,dt,dosfcflx, &
                   xh,rxh,arh1,arh2,uh,ruh,xf,rxf,arf1,arf2,uf,ruf,            &
                   yh,vh,rvh,yf,vf,rvf,                                        &
                   xfref,yfref,rds,sigma,rdsf,sigmaf,                          &
                   wprof,ufrc,vfrc,thfrc,qvfrc,ug,vg,dvdr,                     &
                   uavg,vavg,thavg,pavg,ulspg,vlspg,qavg,cavg,cloudvar,        &
                   tauh,taus,zh,mh,rmh,c1,c2,tauf,zf,mf,rmf,                   &
                   rho0s,pi0s,prs0s,rth0s,                                     &
                   pi0,rho0,prs0,thv0,th0,rth0,qv0,qc0,u0,v0,                  &
                   qi0,rr0,rf0,rrf0,                                           &
                   zs,gz,rgz,gzu,rgzu,gzv,rgzv,dzdx,dzdy,gx,gxu,gy,gyv,        &
                   tsk,znt,ust,stau,tst,qst,z0t,z0q,thflux,qvflux,             &
                   cd,ch,cq,u1,v1,s1,xland,psfc,tlh,prate,ustt,ut,vt,st,       &
                   dum1,dum2,dum3,dum4,dum5,dum6,th  ,ql  ,dum7,               &
                   dum8,rho,rr,rf,prs,t11,t12,t13,t22,t23,t33,                 &
                   m11,m12,m13,m22,m23,m33,                                    &
                   rru,u3d,utk ,utmp ,                                         &
                   rrv,v3d,vtk ,vtmp ,                                         &
                   rrw,w3d,wtk ,wtmp ,                                         &
                   pp3d,sadv,ppten ,qice,th3d,thv  ,thl   ,buoy  ,phi2,        &
                   q3d,qten,kmh,kmv,khh,khv,cme,csm,ce1,ce2,tkea,tke3d,tketen, &
                   nm,defv,defh,lenscl,dissten,epst,epsd1,epsd2,pt3d,          &
                   rain,raincv,hfx,qfx,u10,v10,s10,t2,q2,th2,mznt,             &
                   hpbl,wspd,zol,mol,rmol,br,brcr,phim,phih,psim,psih,         &
                   thpten,qvpten,qcpten,qipten,upten,vpten,qnipten,qncpten,xkzh,xkzq,xkzm, &
                   qsfc,o30,zir,swten,lwten,swtenc,lwtenc,cldfra,              &
                   effc,effi,effs,effr,effg,effis,                             &
                   lwupt,lwuptc,lwdnt,lwdntc,lwupb,lwupbc,lwdnb,lwdnbc,        &
                   swupt,swuptc,swdnt,swdntc,swupb,swupbc,swdnb,swdnbc,        &
                   lwcf,swcf,                                                  &
                   tsq,qsq,cov,sh3d,sm3d,el_pbl,qc_bl,qi_bl,cldfra_bl,         &
                   qWT,qSHEAR,qBUOY,qDISS,dqke,qke_adv,qke,                    &
                   edmf_a,edmf_w,edmf_qt,edmf_thl,edmf_ent,edmf_qc,            &
                   vdfg,maxmf,nupdraft,ktop_plume,                             &
                   thz0,qz0,uz0,vz0,tke_myj,el_myj,                            &
                   tdiag,qdiag,udiag,vdiag,wdiag,kdiag,out2d,out3d,            &
                   getdbz,getvt,                                               &
                   gamk,gamwall,kmw,ufw,vfw,u1b,v1b,l2p,s2p,s2b,t2pm1,t2pm2,t2pm3,t2pm4,kmwk,ufwk,vfwk, &
                   lsnudge_u,lsnudge_v,lsnudge_th,lsnudge_qv,                  &
                   domainlocx,domainlocy,                                      &
                   thcuten,qvcuten,qccuten,qicuten,ucuten,vcuten,              &
                   sw31,sw32,se31,se32,ss31,ss32,sn31,sn32,flag)
        ! end_domaindiag
    use input
    use constants
    use cm1libs , only : rslf,rsif
    use getcape_module
    use sfcphys_module , only : stabil_funcs
    use turb_module , only : getepst
    use simple_phys_module, only : get_avg_uvtq
    use lsnudge_module
#ifdef NETCDF
    use writeout_nc_module, only : writediag_nc
#endif
#ifdef MPI
    use mpi
#endif
    implicit none

    integer, intent(in) :: nstep
    double precision, intent(in) :: mtime
    integer, intent(in) :: nwritet
    integer, intent(inout) :: trecs,trecw
    character(len=3), intent(in), dimension(maxq) :: qname
    character(len=20), intent(in), dimension(maxq) :: qunit
    real, intent(inout) :: dt
    logical, intent(in) :: dosfcflx
    real, intent(in), dimension(ib:ie) :: xh,rxh,arh1,arh2,uh,ruh
    real, intent(in), dimension(ib:ie+1) :: xf,rxf,arf1,arf2,uf,ruf
    real, intent(in), dimension(jb:je) :: yh,vh,rvh
    real, intent(in), dimension(jb:je+1) :: yf,vf,rvf
    real, intent(in), dimension(1-ngxy:nx+ngxy+1) :: xfref
    real, intent(in), dimension(1-ngxy:ny+ngxy+1) :: yfref
    real, intent(in), dimension(kb:ke) :: rds,sigma
    real, intent(in), dimension(kb:ke+1) :: rdsf,sigmaf
    real, intent(inout), dimension(kb:ke) :: wprof,ufrc,vfrc,thfrc,qvfrc,ug,vg,dvdr,  &
                                             uavg,vavg,thavg,pavg,ulspg,vlspg
    real, intent(inout), dimension(kb:ke,numq) :: qavg
    double precision, intent(inout), dimension(kb:ke,3+numq) :: cavg
    logical, intent(in), dimension(maxq) :: cloudvar
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: tauh,taus,zh,mh,rmh,c1,c2
    real, intent(in), dimension(ib:ie,jb:je,kb:ke+1) :: tauf,zf,mf,rmf
    real, intent(in), dimension(ib:ie,jb:je) :: rho0s,pi0s,prs0s,rth0s
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: pi0,rho0,prs0,thv0,th0,rth0,qv0,qc0
    real, intent(in), dimension(ib:ie+1,jb:je,kb:ke) :: u0
    real, intent(in), dimension(ib:ie,jb:je+1,kb:ke) :: v0
    real, intent(in), dimension(ib:ie,jb:je,kb:ke) :: qi0,rr0,rf0,rrf0
    real, intent(in), dimension(ib:ie,jb:je) :: zs
    real, intent(in), dimension(itb:ite,jtb:jte) :: gz,rgz,gzu,rgzu,gzv,rgzv,dzdx,dzdy
    real, intent(in), dimension(itb:ite,jtb:jte,ktb:kte) :: gx,gxu,gy,gyv
    real, intent(in), dimension(ib:ie,jb:je) :: tsk,znt,ust,stau,tst,qst,z0t,z0q,thflux,qvflux,  &
                                                cd,ch,cq,u1,v1,s1,xland,psfc,tlh,prate,ustt,ut,vt,st
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum1,dum2,dum3,dum4,dum5,dum6,th,ql,dum7
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: dum8,rho,rr,rf,prs
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: t11,t12,t13,t22,t23,t33
    real, intent(in), dimension(ibnba:ienba,jbnba:jenba,kbnba:kenba) :: m11,m12,m13,m22,m23,m33
    real, intent(inout), dimension(ib:ie+1,jb:je,kb:ke) :: rru,u3d,utk,utmp
    real, intent(inout), dimension(ib:ie,jb:je+1,kb:ke) :: rrv,v3d,vtk,vtmp
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: rrw,w3d,wtk,wtmp
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: pp3d,sadv,ppten,qice
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: th3d,thv,thl,buoy
    real, intent(in), dimension(ibph:ieph,jbph:jeph,kbph:keph) :: phi2
    real, intent(inout), dimension(ibm:iem,jbm:jem,kbm:kem,numq) :: q3d,qten
    real, intent(inout), dimension(ibc:iec,jbc:jec,kbc:kec) :: kmh,kmv,khh,khv
    real, intent(in),    dimension(ibc:iec,jbc:jec,kbc:kec) :: cme,csm,ce1,ce2
    real, intent(inout), dimension(ibt:iet,jbt:jet,kbt:ket) :: tkea,tke3d,tketen
    real, intent(inout), dimension(ib:ie,jb:je,kb:ke+1) :: nm,defv,defh,lenscl,dissten,epst,epsd1,epsd2
    real, intent(in), dimension(ibp:iep,jbp:jep,kbp:kep,npt) :: pt3d
    real, intent(in), dimension(ib:ie,jb:je,nrain) :: rain,raincv
    real, intent(in), dimension(ibl:iel,jbl:jel) :: hfx,qfx,u10,v10,s10,t2,q2,th2,mznt
    real, intent(in), dimension(ibl:iel,jbl:jel) :: hpbl,wspd,zol,mol,rmol,br,brcr,phim,phih,psim,psih,qsfc
    real, intent(in), dimension(ibb:ieb,jbb:jeb,kbb:keb) :: thpten,qvpten,qcpten,qipten,upten,vpten
    real, intent(in), dimension(ibb:ieb,jbb:jeb,kbb:keb) :: xkzh,xkzq,xkzm
    real, intent(in), dimension(ibr:ier,jbr:jer,kbr:ker) :: o30
    real, intent(in), dimension(ibr:ier,jbr:jer) :: zir
    real, intent(in), dimension(ibr:ier,jbr:jer,kbr:ker) :: swten,lwten,swtenc,lwtenc,cldfra
    real, intent(in), dimension(ibr:ier,jbr:jer,kbr:ker) :: effc,effi,effs,effr,effg,effis
    real, intent(in), dimension(ibr:ier,jbr:jer) :: lwupt,lwuptc,lwdnt,lwdntc,lwupb,lwupbc,lwdnb,lwdnbc
    real, intent(in), dimension(ibr:ier,jbr:jer) :: swupt,swuptc,swdnt,swdntc,swupb,swupbc,swdnb,swdnbc
    real, intent(inout), dimension(ibr:ier,jbr:jer) :: lwcf,swcf
    real, intent(inout), dimension(ibmynn:iemynn,jbmynn:jemynn,kbmynn:kemynn) :: tsq,qsq,cov,sh3d,sm3d,el_pbl,qc_bl,qi_bl,cldfra_bl, &
                                                                qnipten,qncpten,qWT,qSHEAR,qBUOY,qDISS,dqke,qke_adv,qke,  &
                                                                edmf_a,edmf_w,edmf_qt,edmf_thl,edmf_ent,edmf_qc
    real, intent(inout), dimension(ibmynn:iemynn,jbmynn:jemynn) :: vdfg,maxmf
    integer, intent(inout), dimension(ibmynn:iemynn,jbmynn:jemynn) :: nupdraft,ktop_plume
    real, intent(inout), dimension(ibmyj:iemyj,jbmyj:jemyj) :: thz0,qz0,uz0,vz0
    real, intent(inout), dimension(ibmyj:iemyj,jbmyj:jemyj,kbmyj:kemyj) :: tke_myj,el_myj
    logical, intent(in) :: getdbz,getvt
    real, intent(in), dimension(kb:ke) :: gamk,gamwall,kmw,ufw,vfw,u1b,v1b,l2p,s2p,s2b,t2pm1,t2pm2,t2pm3,t2pm4
    real, intent(in), dimension(ib2pt:ie2pt,jb2pt:je2pt,kb2pt:ke2pt) :: kmwk,ufwk,vfwk
    real, intent(inout), dimension(lsnudge_maxlevels,lsnudge_nmax) :: lsnudge_u,lsnudge_v,lsnudge_th,lsnudge_qv
    double precision, intent(in) :: domainlocx,domainlocy
    real, intent(in), dimension(ibcu:iecu,jbcu:jecu,kbcu:kecu) :: thcuten,qvcuten,qccuten,qicuten,ucuten,vcuten
    real, intent(inout), dimension(cmp,jmp,kmp)   :: sw31,sw32,se31,se32
    real, intent(inout), dimension(imp,cmp,kmp)   :: ss31,ss32,sn31,sn32
    logical, intent(inout), dimension(ib:ie,jb:je,kb:ke) :: flag
    real, intent(in) , dimension(ibdt:iedt,jbdt:jedt,kbdt:kedt,ntdiag) :: tdiag
    real, intent(in) , dimension(ibdq:iedq,jbdq:jedq,kbdq:kedq,nqdiag) :: qdiag
    real, intent(in) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nudiag) :: udiag
    real, intent(in) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nvdiag) :: vdiag
    real, intent(in) , dimension(ibdv:iedv,jbdv:jedv,kbdv:kedv,nwdiag) :: wdiag
    real, intent(in) , dimension(ibdk:iedk,jbdk:jedk,kbdk:kedk,nkdiag) :: kdiag
    real, intent(inout), dimension(ib2d:ie2d,jb2d:je2d,nout2d) :: out2d
    real, intent(in) , dimension(ib3d:ie3d,jb3d:je3d,kb3d:ke3d,nout3d) :: out3d

    !---------------------------------------------------------------------------

    integer :: i,j,k,n,nvar,nvar2d,nfile,ncb,nrb,nlb,nct,nrt,nlt,nrk,diffit,nloop,nn,ntmp,wloopmax
    integer :: qflag,pdef,pdefweno
    real :: zi,zimin,zimax,zitb,ziq,dtdz,dqdz,tmax,qmax,ustbar,zntbar,molbar,tem,tem1,nmavg,tk
    real :: qx,px,tx,tlcl,ee,tlast,prinv,tphim,tphih,zeta,tpsim,tpsih
    real, dimension(:), allocatable :: pfoo,tfoo,qfoo
    real :: zlcl, zlfc, zel , psource , tsource , qvsource
    double precision :: savg2d,temd,cwp,rwp,lwp,qcfrac,qrfrac,qlfrac,qifrac,qtfrac,    &
                        zibar,qcb,qrb,qlb,qct,qrt,qlt,weps,thfavg,qvfavg,wstmp,wstar,  &
                        fbmin,zfbmin,bfoo
    double precision, dimension(nk+1) :: ravg,savg,tavg,uub,vvb,wwb,sfr,sfs,sfd,tmass,clw,cli,plw,pli
    double precision, dimension(nk+1) :: ufr,ufs,ufd,vfr,vfs,vfd,ptfr,ptfs,ptfd,qvfr,qvfs,qvfd
    real, dimension(0:nk+1) :: wavg,prsavg,piavg,phiavg,thvavg,thlavg,rhoavg,rfavg,qcrit,  &
                               qvavg,qlavg,qtavg,wsp,wspa,stke,rtke,wvar,temavg,  &
                               u_hturb,u_vturb,u_hadv,u_vadv,u_pgrad,u_lsw,u_cor,u_hidiff,u_vidiff,u_rdamp,     &
                               v_hturb,v_vturb,v_hadv,v_vadv,v_pgrad,v_lsw,v_cor,v_hidiff,v_vidiff,v_rdamp,     &
                               w_hturb,w_vturb,w_hadv,w_vadv,w_pgrad,w_lsw,w_buoy,w_hidiff,w_vidiff,w_rdamp
    real, dimension(0:nk+1,npt) :: ptavg
    character(len=80), dimension(varmax) :: varname,vardesc,varunit
    integer, dimension(varmax) :: varlvls
    character(len=1),  dimension(varmax) :: vargrid
    character(len=80) :: a1,a2
    character(len=16) :: a16
    character(len=8) :: text1
    logical :: saveit,doit,do2

    real :: thvx
    real :: bri,ubar,vbar,thvflux,tmpprt,thf1,thf2,gamfac,ws
    real, dimension(ib:ie,jb:je) :: tmpqsfc,govthv,thvsfc,thv1

    if( myid.eq.0 ) print *
    if( myid.eq.0 ) print *,' ..... begin domaindiag code ..... '
    if( myid.eq.0 ) print *

    uavg = 0.0
    vavg = 0.0
    wavg = 0.0
    prsavg = 0.0
    piavg = 0.0
    thvavg = 0.0
    thlavg = 0.0
    rhoavg = 0.0
    rfavg = 0.0
    qvavg = 0.0
    qlavg = 0.0
    qtavg = 0.0
    wsp = 0.0
    wspa = 0.0
    stke = 0.0
    rtke = 0.0
    wvar = 0.0

    sfr = 0.0
    sfs = 0.0
    sfd = 0.0

    ptfr = 0.0
    ptfs = 0.0
    ptfd = 0.0

    ! by default, assume 3d and scalar levels:
    varlvls = nk
    vargrid = 's'

    thfavg = 0.0
    qvfavg = 0.0
    fbmin = 0.0
    zfbmin = 0.0
    wstar = 0.0

    ustbar = 0.0
    zntbar = 0.0
    molbar = 0.0

    !---------------------------------------------------------------------------
    ! open file:

      if( myid.eq.0 ) print *,'  nwritet = ',nwritet

      IF( output_format.eq.1 )THEN

        ! grads-format

        do i=1,maxstring
          string(i:i) = ' '
        enddo

        if( myid.eq.0 )then

          string = 'cm1out_diag_XXXXXX_s.dat'
          write(string(13:18),151) nwritet
          print *,string
          open(unit=fnums,file=string,form='unformatted',access='direct',recl=4)

          string = 'cm1out_diag_XXXXXX_w.dat'
          write(string(13:18),151) nwritet
          print *,string
          open(unit=fnumw,file=string,form='unformatted',access='direct',recl=4)

        endif

151     format(i6.6)

        wloopmax = 1

      ELSEIF( output_format.eq.2 )THEN

        ! netcdf-format
#ifdef NETCDF

        do i=1,maxstring
          string(i:i) = ' '
        enddo

        string = 'cm1out_diag_XXXXXX.nc'
        write(string(13:18),151) nwritet
        if( myid.eq.0 ) print *,string

        wloopmax = 2

#endif
      ELSE

        print *
        print *,'  output_format = ',output_format
        print *
        print *,'  Invalid value for output_format in domaindiag '
        print *
        call stopcm1

      ENDIF

        trecs = 1
        trecw = 1

    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    ! misc prep:     th  =  potential temperature (theta)
    !                ql  =  total liquid water (usually qc+qr)

    IF( imoist.eq.0 )THEN
      ql = 0.0
      qice = 0.0
    ELSE
      do k=1,nk
        do j=1,nj
        do i=1,ni
          ql(i,j,k) = 0.0
        enddo
        enddo
      IF( nql1.gt.0 )THEN
        do n=nql1,nql2
        do j=1,nj
        do i=1,ni
          ql(i,j,k) = ql(i,j,k)+q3d(i,j,k,n)
        enddo
        enddo
        enddo
      ENDIF
        if( iice.eq.1 )then
          do j=1,nj
          do i=1,ni
            qice(i,j,k) = 0.0
          enddo
          enddo
          do n=nqs1,nqs2
          do j=1,nj
          do i=1,ni
            qice(i,j,k) = qice(i,j,k)+q3d(i,j,k,n)
          enddo
          enddo
          enddo
        endif
      enddo
    ENDIF

    IF( imoist.eq.1 )THEN

      do k=1,nk
      do j=0,nj+1
      do i=0,ni+1
        th(i,j,k) = th0(i,j,k)+th3d(i,j,k)
        thv(i,j,k) = th(i,j,k)*(1.0+repsm1*q3d(i,j,k,nqv)-ql(i,j,k)-qice(i,j,k))
        dum1(i,j,k) = sqrt( (0.5*(u3d(i,j,k)+u3d(i+1,j,k))+umove)**2 &
                           +(0.5*(v3d(i,j,k)+v3d(i,j+1,k))+vmove)**2 )
      enddo
      enddo
      enddo

    ELSE

      do k=1,nk
      do j=0,nj+1
      do i=0,ni+1
        th(i,j,k) = th0(i,j,k)+th3d(i,j,k)
        thv(i,j,k) = th(i,j,k)
        dum1(i,j,k) = sqrt( (0.5*(u3d(i,j,k)+u3d(i+1,j,k))+umove)**2 &
                           +(0.5*(v3d(i,j,k)+v3d(i,j+1,k))+vmove)**2 )
      enddo
      enddo
      enddo

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

      call getavg3d(th,savg)
      do k=1,nk
        thavg(k) = savg(k)
      enddo

      call getavg3d(thv,savg)
      do k=1,nk
        thvavg(k) = savg(k)
      enddo

      call getavg3d(prs,savg)
      do k=1,nk
        pavg(k) = savg(k)
      enddo

      call getavg3d(dum1,savg)
      do k=1,nk
        wsp(k) = savg(k)
      enddo

      !c-c-c-c-c-c-c-c-c-c

  bigwloop:  &
  DO wloop = 1 , wloopmax

      if( myid.eq.0 ) print *,'  wloop = ',wloop

      nvar = 0

    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !ccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
    !  2d variables:

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'mtime'
        vardesc(nvar) = 'model time (since beginning of sim)'
        varunit(nvar) = 's'
        varlvls(nvar) = 0
        vargrid(nvar) = '2'

        savg2d = mtime
        call write2d(savg2d,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'nstep'
        vardesc(nvar) = 'time steps (since beginning of sim)'
        varunit(nvar) = 'unitless'
        varlvls(nvar) = 0
        vargrid(nvar) = '2'

        savg2d = nstep
        call write2d(savg2d,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'umove'
        vardesc(nvar) = 'umove'
        varunit(nvar) = 'm/s'
        varlvls(nvar) = 0
        vargrid(nvar) = '2'

        savg2d = umove
        call write2d(savg2d,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'vmove'
        vardesc(nvar) = 'vmove'
        varunit(nvar) = 'm/s'
        varlvls(nvar) = 0
        vargrid(nvar) = '2'

