      vargrid(nvar) = '2'
      call getavg2d( stau  ,savg2d)
      call write2d(savg2d,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

    IF( sfcmodel.eq.4 )THEN

