        varunit(nvar) = 'm2/s3'
        vargrid(nvar) = 'w'

        call getavg3d(dum8(ib,jb,kb),savg)
        savg(1) = grads_undef
        savg(nk+1) = grads_undef
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

      !c-c-c-c-c-c-c-c-c-c

      IF( idoles .or. cm1setup.eq.3 )THEN

        nvar = nvar+1
        varname(nvar) = 'epsd1'
        vardesc(nvar) = 'epsd1'
        varunit(nvar) = 'm2/s3'
        vargrid(nvar) = 'w'

        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = epsd1(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        savg(1) = grads_undef
        savg(nk+1) = grads_undef
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

