      IF( idoles .or. cm1setup.eq.3 )THEN

        nvar = nvar+1
        varname(nvar) = 'epsd2'
        vardesc(nvar) = 'epsd2'
        varunit(nvar) = 'm2/s3'
        vargrid(nvar) = 'w'

        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = epsd2(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        savg(1) = grads_undef
        savg(nk+1) = grads_undef
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

      !c-c-c-c-c-c-c-c-c-c

      ipbl1:  &
      IF( ipbl.eq.1 )THEN

        nvar = nvar+1
        varname(nvar) = 'xkzh'
        vardesc(nvar) = 'eddy diffusivity for heat (from YSU)'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = xkzh(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

!        nvar = nvar+1
!        varname(nvar) = 'xkzq'
!        vardesc(nvar) = 'eddy diffusivity for moisture (from YSU)'
!        varunit(nvar) = 'm2/s'
!        vargrid(nvar) = 'w'
!        do k=1,nk
!        do j=1,nj
!        do i=1,ni
!          dum1(i,j,k) = xkzq(i,j,k)
!        enddo
!        enddo
!        enddo
!        call getavg3d(dum1,savg)
!        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'xkzm'
        vardesc(nvar) = 'eddy viscosity (from YSU)'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = xkzm(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF  ipbl1

      !c-c-c-c-c-c-c-c-c-c

      ipbl3:  &
      IF( ipbl.eq.3 )THEN

        nvar = nvar+1
        varname(nvar) = 'dkt3d'
        vardesc(nvar) = 'Thermal Diffusivity (from GFSEDMF)'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = xkzh(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'dku3d'
        vardesc(nvar) = 'Momentum Diffusivity (from GFSEDMF)'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = xkzm(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF  ipbl3

      !c-c-c-c-c-c-c-c-c-c

      ipbl4:  &
      IF( ipbl.eq.4 .or. ipbl.eq.5 )THEN

        nvar = nvar+1
        varname(nvar) = 'qke'
        vardesc(nvar) = 'twice TKE from MYNN'
        varunit(nvar) = 'm2/s2'
        call getavg3d(qke,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qwt'
        vardesc(nvar) = 'TKE vertical transport (MYNN)'
        varunit(nvar) = 'm2/s3'
        call getavg3d(qwt,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qshear'
        vardesc(nvar) = 'TKE Production - shear (MYNN)'
        varunit(nvar) = 'm2/s3'
        call getavg3d(qshear,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qbuoy'
        vardesc(nvar) = 'TKE Production - buoyancy (MYNN)'
        varunit(nvar) = 'm2/s3'
        call getavg3d(qbuoy,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qdiss'
        vardesc(nvar) = 'TKE dissipation (MYNN)'
        varunit(nvar) = 'm2/s3'
        call getavg3d(qdiss,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'dqke'
        vardesc(nvar) = 'TKE change (MYNN)'
        varunit(nvar) = 'm2/s3'
        call getavg3d(dqke,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qke_adv'
        vardesc(nvar) = 'advection of twice TKE from MYNN'
        varunit(nvar) = 'm2/s3'
        call getavg3d(qke_adv,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'sh3d'
        vardesc(nvar) = 'Stability function for heat (MYNN)'
        varunit(nvar) = ' '
        call getavg3d(sh3d,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'sm3d'
        vardesc(nvar) = 'Stability function for momentum (MYNN)'
        varunit(nvar) = ' '
        call getavg3d(sm3d,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'tsq'
        vardesc(nvar) = 'liquid water pottemp variance (MYNN)'
        varunit(nvar) = 'K2'
        call getavg3d(tsq,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qsq'
        vardesc(nvar) = 'liquid water variance (MYNN)'
        varunit(nvar) = '(kg/kg)**2'
        call getavg3d(qsq,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'cov'
        vardesc(nvar) = 'liquid water-liquid water pottemp covariance (MYNN)'
        varunit(nvar) = 'K kg/kg'
        call getavg3d(cov,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'exch_h'
        vardesc(nvar) = 'Thermal Diffusivity (from MYNN)'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = xkzh(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'exch_m'
        vardesc(nvar) = 'Momentum Diffusivity (from MYNN)'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = xkzm(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'el_pbl'
        vardesc(nvar) = 'Length scale from PBL'
        varunit(nvar) = 'm'
        vargrid(nvar) = 'w'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = el_pbl(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

   !..................................

      ENDIF  ipbl4

      !c-c-c-c-c-c-c-c-c-c

      ipbl6:  &
      IF( ipbl.eq.6 )THEN

        nvar = nvar+1
        varname(nvar) = 'tke_myj'
        vardesc(nvar) = 'TKE from PBL'
        varunit(nvar) = 'm2/s2'
        vargrid(nvar) = 'w'
        do k=1,nk+1
