        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'el_myj'
        vardesc(nvar) = 'Length scale from PBL'
        varunit(nvar) = 'm'
        vargrid(nvar) = 'w'
        do k=1,nk+1
