      !c-c-c-c-c-c-c-c-c-c

      IF( cm1setup.ge.1 .or. output_def.eq.1 .or. ipbl.ge.1 .or. horizturb.eq.1 )THEN
        nvar = nvar+1
        varname(nvar) = 'defh'
        vardesc(nvar) = 'horizontal deformation'
        varunit(nvar) = 's-2'
        vargrid(nvar) = 'w'

        call getavg3d(defh(ib,jb,kb),savg)
        savg(1) = grads_undef
        savg(nk+1) = grads_undef
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'defv'
        vardesc(nvar) = 'vertical deformation'
        varunit(nvar) = 's-2'
        vargrid(nvar) = 'w'

        call getavg3d(defv(ib,jb,kb),savg)
        savg(1) = grads_undef
        savg(nk+1) = grads_undef
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)
      ENDIF

      !c-c-c-c-c-c-c-c-c-c

    turbcheck:  &
    IF( sgsmodel.ge.1 .or. ipbl.eq.2 )THEN

      if( iusekm.eq.1 )then
        nvar = nvar+1
        varname(nvar) = 'kmh'
        vardesc(nvar) = 'eddy viscosity in horiz direction'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk+1
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = kmh(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)
      endif

      !c-c-c-c-c-c-c-c-c-c

      if( iusekm.eq.1 )then
        nvar = nvar+1
        varname(nvar) = 'kmv'
        vardesc(nvar) = 'eddy viscosity in vert direction'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk+1
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = kmv(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)
      endif

      !c-c-c-c-c-c-c-c-c-c

      if( iusekh.eq.1 )then
        nvar = nvar+1
        varname(nvar) = 'khh'
        vardesc(nvar) = 'eddy diffusivity in horiz direction'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk+1
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = khh(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)
      endif

      !c-c-c-c-c-c-c-c-c-c

      if( iusekh.eq.1 )then
        nvar = nvar+1
        varname(nvar) = 'khv'
        vardesc(nvar) = 'eddy diffusivity in vert direction'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'
        do k=1,nk+1
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = khv(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)
      endif

      !c-c-c-c-c-c-c-c-c-c

      if( iusekh.eq.1 .and. iusekm.eq.1 )then
        nvar = nvar+1
        varname(nvar) = 'pr'
        vardesc(nvar) = 'subgrid Prandtl number'
        varunit(nvar) = 'nondimensional'
        vargrid(nvar) = 'w'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = (1.0e-20+kmv(i,j,k))/(1.0e-20+khv(i,j,k))
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)
      endif

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'rinum'
        vardesc(nvar) = 'Richardson number in subgrid model'
        varunit(nvar) = 'nondimensional'
        vargrid(nvar) = 'w'

        do j=1,nj
        do i=1,ni
          dum1(i,j,1) = 0.0
          dum1(i,j,nk+1) = 0.0
        enddo
        enddo

        IF(tconfig.eq.1)THEN
          do k=2,nk
          do j=1,nj
          do i=1,ni
            prinv = (1.0e-20+khv(i,j,k))/(1.0e-20+kmv(i,j,k))
            dum1(i,j,k) = nm(i,j,k)*prinv/(1.0e-20+defv(i,j,k)+defh(i,j,k))
          enddo
          enddo
          enddo
        ELSEIF(tconfig.eq.2)THEN
          do k=2,nk
          do j=1,nj
          do i=1,ni
            prinv = (1.0e-20+khv(i,j,k))/(1.0e-20+kmv(i,j,k))
            dum1(i,j,k) = nm(i,j,k)*prinv/(1.0e-20+defv(i,j,k))
          enddo
          enddo
          enddo
        ENDIF

        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'grdscl'
        vardesc(nvar) = 'grid scale'
        varunit(nvar) = 'm'
        vargrid(nvar) = 'w'

        dum1 = 0.0

        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = ( ((dx*ruh(i))*(dy*rvh(j)))*(dz*rmf(i,j,k)) )**0.33333333
          ! cm1r17:  wall condition near surface
          dum1(i,j,k) = sqrt(1.0/( 1.0/(dum1(i,j,k)**2)                                  &
                                    +1.0/((karman*((zf(i,j,k)-zf(i,j,1))+znt(i,j))*rcs)**2)  &
                                 ) )
        enddo
        enddo
        enddo

        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

      doit = .true.

      IF( doit .and. idoles .and. iusetke )THEN

        nvar = nvar+1
        varname(nvar) = 'cme'
        vardesc(nvar) = 'cme'
        varunit(nvar) = 'n.d.'
        vargrid(nvar) = 'w'

        call getavg3d(cme,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'csm'
        vardesc(nvar) = 'csm'
        varunit(nvar) = 'n.d.'
        vargrid(nvar) = 'w'

        call getavg3d(csm,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'ce1'
        vardesc(nvar) = 'ce1'
        varunit(nvar) = 'n.d.'
        vargrid(nvar) = 'w'

        call getavg3d(ce1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'ce2'
        vardesc(nvar) = 'ce2'
        varunit(nvar) = 'n.d.'
        vargrid(nvar) = 'w'

        call getavg3d(ce2,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

      !c-c-c-c-c-c-c-c-c-c

      IF( idoles .and. iusetke )THEN

        nvar = nvar+1
        varname(nvar) = 'lenscl'
        vardesc(nvar) = 'length scale in subgrid turbulence model'
        varunit(nvar) = 'm'
        vargrid(nvar) = 'w'

        call getavg3d(lenscl,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

      !c-c-c-c-c-c-c-c-c-c

    ENDIF  turbcheck

      !c-c-c-c-c-c-c-c-c-c

      t2pstuff:  &
      IF( dot2p )THEN

        !-----

        nvar = nvar+1
        varname(nvar) = 'gamk'
        vardesc(nvar) = 'gamk'
        varunit(nvar) = 'unitless'
        vargrid(nvar) = 'w'

        do k=1,nk+1
          savg(k) = gamk(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 'gamwall'
        vardesc(nvar) = 'gamwall'
        varunit(nvar) = 'unitless'
        vargrid(nvar) = 'w'

        do k=1,nk+1
          savg(k) = gamwall(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 'kmw'
        vardesc(nvar) = 'kmw'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'

!        do k=1,nk+1
!          savg(k) = kmw(k)
!        enddo

        dum1 = 0.0
        do k=1,ntwk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = kmwk(i,j,k)
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 'u1b'
        vardesc(nvar) = 'u1b'
        varunit(nvar) = 'm/s'
        vargrid(nvar) = 's'

        do k=1,nk+1
          savg(k) = u1b(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 'v1b'
        vardesc(nvar) = 'v1b'
        varunit(nvar) = 'm/s'
        vargrid(nvar) = 's'

        do k=1,nk+1
          savg(k) = v1b(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 'l2p'
        vardesc(nvar) = 'l2p'
        varunit(nvar) = 'm'
        vargrid(nvar) = 'w'

        do k=1,nk+1
          savg(k) = l2p(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 't2pm1'
        vardesc(nvar) = 't2pm1'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'

        do k=1,nk+1
          savg(k) = t2pm1(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 't2pm2'
        vardesc(nvar) = 't2pm2'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'

        do k=1,nk+1
          savg(k) = t2pm2(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 't2pm3'
        vardesc(nvar) = 't2pm3'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'

        do k=1,nk+1
          savg(k) = t2pm3(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

        nvar = nvar+1
        varname(nvar) = 't2pm4'
        vardesc(nvar) = 't2pm4'
        varunit(nvar) = 'm2/s'
        vargrid(nvar) = 'w'

        do k=1,nk+1
          savg(k) = t2pm4(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        !-----

      ENDIF  t2pstuff

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'wsp'
        vardesc(nvar) = 'horizontal wind speed (ground-relative)'
        varunit(nvar) = 'm/s'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = sqrt( (0.5*(u3d(i,j,k)+u3d(i+1,j,k))+umove)**2 &
                             +(0.5*(v3d(i,j,k)+v3d(i,j+1,k))+vmove)**2 )
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'wspinterp'
        vardesc(nvar) = 'horizontal wind speed (ground-relative)'
        varunit(nvar) = 'm/s'
        vargrid(nvar) = 'w'

        do k=2,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = 0.5*(dum1(i,j,k-1)+dum1(i,j,k))
        enddo
        enddo
        enddo

        call getavg3d(dum1,savg)
        savg(1) = grads_undef
        savg(nk+1) = grads_undef
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'wspan'
        vardesc(nvar) = 'analytic wind speed (neutral)'
        varunit(nvar) = 'm/s'

        do k=1,nk
          savg(k) = (ustbar/karman)*alog( (zh(1,1,k)+zntbar)/zntbar )
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'wspa'
        vardesc(nvar) = 'analytic wind speed'
        varunit(nvar) = 'm/s'

        do k=1,nk
          if( abs(molbar).gt.1.0e-6 )then
            zeta = zh(1,1,k)/molbar
            call stabil_funcs(zeta,tphim,tphih,tpsim,tpsih)
          else
            tpsim = 0.0
          endif
          savg(k) = (ustbar/karman)*( alog(zh(1,1,k)/zntbar) - tpsim )
          wspa(k) = savg(k)
        enddo

        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        nvar = nvar+1
        varname(nvar) = 'sdwsp'
        vardesc(nvar) = 'standard deviation of horizontal wind speed'
        varunit(nvar) = 'm/s'

        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = ( dum1(i,j,k) - wsp(k) )**2
        enddo
        enddo
        enddo

        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

    IF( iptra.eq.1 )THEN

      ptavg = 0.0

      DO n=1,npt

        nvar = nvar+1
        a1 = 'pt                                                                              '
        if(n.le.9)then
          write(a1(3:3),155) n
155       format(i1.1)
        elseif(n.le.99)then
          write(a1(3:4),154) n
154       format(i2.2)
        else
          write(a1(3:5),153) n
153       format(i3.3)
        endif
        varname(nvar) = a1
        vardesc(nvar) = 'passive tracer mixing ratio'
        varunit(nvar) = 'g/g'

        call getavg3d(pt3d(ib,jb,kb,n),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        do k=1,nk
          ptavg(k,n) = savg(k)
        enddo

      ENDDO

    ENDIF

      !c-c-c-c-c-c-c-c-c-c

      IF( radopt.ge.1 )THEN

        nvar = nvar+1
        varname(nvar) = 'o3'
        vardesc(nvar) = 'ozone'
        varunit(nvar) = 'unk'
        call getavg3d(o30(ibr,jbr,kbr),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

      !c-c-c-c-c-c-c-c-c-c

      IF( testcase.eq.4 .or. testcase.eq.5 )THEN

        ! note:  o30 array stores frad

        nvar = nvar+1
        varname(nvar) = 'frad'
        vardesc(nvar) = 'radiative flux'
        varunit(nvar) = 'W/m2'
        call getavg3d(o30(ibr,jbr,kbr),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      !c-c-c-c-c-c-c-c-c-c

        ! note:  o30 array stores frad

        nvar = nvar+1
        varname(nvar) = 'thrad'
        vardesc(nvar) = 'pot temp tendency from radiation scheme'
        varunit(nvar) = 'K/s'

        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = -(o30(i,j,k+1)-o30(i,j,k))*rdz*mh(i,j,k)  &
                         /(cp*rho0(i,j,k))
        enddo
        enddo
        enddo

        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

      !c-c-c-c-c-c-c-c-c-c

      IF( cuparam.ge.1 )THEN

        nvar = nvar+1
        varname(nvar) = 'thcuten'
        vardesc(nvar) = 'thcuten'
        varunit(nvar) = 'K/s'
        call getavg3d(thcuten(ibcu,jbcu,kbcu),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qvcuten'
        vardesc(nvar) = 'qvcuten'
        varunit(nvar) = 'g/g/s'
        call getavg3d(qvcuten(ibcu,jbcu,kbcu),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qccuten'
        vardesc(nvar) = 'qccuten'
        varunit(nvar) = 'g/g/s'
        call getavg3d(qccuten(ibcu,jbcu,kbcu),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'qicuten'
        vardesc(nvar) = 'qicuten'
        varunit(nvar) = 'g/g/s'
        call getavg3d(qicuten(ibcu,jbcu,kbcu),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'ucuten'
        vardesc(nvar) = 'ucuten'
        varunit(nvar) = 'm/s/s'
        call getavg3d(ucuten(ibcu,jbcu,kbcu),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'vcuten'
        vardesc(nvar) = 'vcuten'
        varunit(nvar) = 'm/s/s'
        call getavg3d(vcuten(ibcu,jbcu,kbcu),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

      !c-c-c-c-c-c-c-c-c-c

      IF( radopt.ge.1 )THEN

        nvar = nvar+1
        varname(nvar) = 'swten'
        vardesc(nvar) = 'temperature tendency, sw radiation'
        varunit(nvar) = 'K/s'
        call getavg3d(swten(ibr,jbr,kbr),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'lwten'
        vardesc(nvar) = 'temperature tendency, sw radiation'
        varunit(nvar) = 'K/s'
        call getavg3d(lwten(ibr,jbr,kbr),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'swtenc'
        vardesc(nvar) = 'temperature tendency, sw radiation (clear sky)'
        varunit(nvar) = 'K/s'
        call getavg3d(swtenc(ibr,jbr,kbr),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'lwtenc'
        vardesc(nvar) = 'temperature tendency, sw radiation (clear sky)'
        varunit(nvar) = 'K/s'
        call getavg3d(lwtenc(ibr,jbr,kbr),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

        nvar = nvar+1
        varname(nvar) = 'cldfra'
        vardesc(nvar) = 'cloud fraction from radiation scheme'
        varunit(nvar) = 'nondimensional'
        call getavg3d(cldfra(ibr,jbr,kbr),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

      ENDIF

      !c-c-c-c-c-c-c-c-c-c

      doit = .true.
      IF( doit )THEN
      IF( radopt.ge.1 )THEN

        nvar = nvar+1
        varname(nvar) = 'effc'
        vardesc(nvar) = 'cloud droplet effective radius'
        varunit(nvar) = 'micron'
        call getavg3d(effc(ibr,jbr,kbr),savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

