        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = dum4(i,j,k)**3
        enddo
        enddo
        enddo
        call getavg3d(dum1,savg)
        call write3d(savg,trecs,trecw,vargrid,nvar,varname,vardesc,varunit)

