        vardesc(nvar) = '< v-prime w-prime >'
        varunit(nvar) = 'm2/s2'
        do k=1,nk
        do j=1,nj
        do i=1,ni
          dum1(i,j,k) = dum5(i,j,k)*dum6(i,j,k)
