  if(output_filetype.ge.2)then
    srec=1
    urec=1
    vrec=1
    wrec=1
  endif


!-----------------------------------------------------------------------

      if( output_format.eq.1 )then

        ! write metadata:
        call     write_grads_metadata(nwrite,mrec,nstep,mtime,dt,adt,ndt,domainlocx,domainlocy)

      endif

!-----------------------------------------------------------------------

      IF( imove.eq.1 )THEN
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k)
        do k=1,nk
        do j=jb,je
        do i=ib,ie
          ! get ground-relative winds:
          ugr(i,j,k) = ua(i,j,k)+umove
          vgr(i,j,k) = va(i,j,k)+vmove
        enddo
        enddo
        enddo
      ELSE
        !$omp parallel do default(shared)   &
        !$omp private(i,j,k)
        do k=1,nk
        do j=jb,je
        do i=ib,ie
          ugr(i,j,k) = ua(i,j,k)
          vgr(i,j,k) = va(i,j,k)
        enddo
        enddo
        enddo
      ENDIF


!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc
!cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc

    nmax = 1
    if( output_format.eq.2 ) nmax = 2


    bigloop:  &
    DO nloop = 1 , nmax

      if( myid.eq.0 ) print *,'  nloop = ',nloop

      if( fnum.eq.71 )then
        dointerp = .true.
      else
        dointerp = .false.
      endif

#ifdef NETCDF
      IF(output_format.eq.2)THEN
