              do k=1,nk
              do i=1,ni
                dum1(i,j,1) = dum1(i,j,1) + rho(i,j,k)*qa(i,j,k,nqc)*dz*rmh(i,j,k)
              enddo
              enddo
            endif
          enddo

          !$omp parallel do default(shared)  &
