      real, intent(inout), dimension(ibcu:iecu,jbcu:jecu,kbcu:kecu) :: thcuten,qvcuten,qccuten,qicuten,ucuten,vcuten
      integer, intent(inout), dimension(ibl:iel,jbl:jel) :: lu_index
