  if( myid.eq.0 )then
    if( interp_on_restart )then
      allocate( dumz(0:nzold+1) )
      dumz = 0.0
      IF( restart_format.eq.1 )THEN
        read(50) dumz
#ifdef NETCDF
      ELSEIF( restart_format.eq.2 )THEN
        stop 1111
#endif
      ENDIF
      do k=1,nk
        kk = iz(k)
        ug(k) = (1.0-rz(k))*dumz(kk) + rz(k)*dumz(kk+1)
      enddo
      IF( restart_format.eq.1 )THEN
        read(50) dumz
#ifdef NETCDF
      ELSEIF( restart_format.eq.2 )THEN
#endif
      ENDIF
      do k=1,nk
        kk = iz(k)
        vg(k) = (1.0-rz(k))*dumz(kk) + rz(k)*dumz(kk+1)
      enddo
      deallocate( dumz )
    else
