      0.9568, 0.9568, 0.9567, 0.9565, 0.9562, 0.9557, 0.9548, 0.9533,   &
      0.9510, 0.9477, 0.9428, 0.9355, 0.9250, 0.9106, 0.8921, 0.8700,   &
      0.8452, 0.8171, 0.7839, 0.7443, 0.6986, 0.6486/

