      endif

!print*,"In mynn wrapper, calling mynn_bl_driver"
              CALL  mynn_bl_driver(                                    &
     &        initflag=initflag,restart=restart,cycling=cycling,       &
     &        delt=delt,dz=dz(:,:,j),dx=dx,znt=znt(:,j),               &
